    'id' => 'accidente-trabajo-035',
    'categoria' => 'Accidente de Trabajo',
    'pregunta' => '¿Qué pasa si trabajo para el Estado y me accidento?',
    'respuesta_corta' => 'Los trabajadores del Estado también tienen cobertura por accidentes laborales.',
    'respuesta_completa' => '<p>📌 Si trabajás para el Estado nacional, provincial o municipal, también tenés derecho a la cobertura por accidentes laborales y a las prestaciones que establece la normativa aplicable.</p>
<p>✅ Cobertura: Los trabajadores estatales cuentan con el sistema de cobertura que corresponda según su organismo o jurisdicción.</p>
<p>📌 Prestaciones: Tenés derecho a atención médica, rehabilitación, incapacidad temporaria, incapacidad permanente y demás prestaciones previstas por la ley.</p>
<p>📢 Reclamo: Debés denunciar el accidente y seguir el procedimiento correspondiente si existe algún conflicto con la cobertura.</p>
<p>📌 Asesoramiento: Si rechazaron tu accidente o hubo problemas con la ART o el organismo, podés iniciar el reclamo correspondiente.</p>
<p>📌 Consejo práctico: Denunciá el accidente cuanto antes, conservá toda la documentación médica y laboral y buscá asesoramiento si encontrás obstáculos en el trámite.</p>',
