  38 => 
  array (
    'id' => 'accidente-trabajo-039',
    'categoria' => 'Accidente de Trabajo',
    'pregunta' => '¿Qué pasa si estoy en pasantía y me accidento?',
    'respuesta_corta' => 'Si hay relación de dependencia, tenés derechos. Las pasantías pueden estar cubiertas.',
    'respuesta_completa' => '<p>📌 Si sufrís un accidente durante una pasantía, la cobertura dependerá de las características de esa relación. En muchos casos, si existe una verdadera relación de dependencia, corresponde la cobertura de la ART.</p>
<p>📌  Relación de dependencia: Si cumplís horario, recibís órdenes, percibís una remuneración y trabajás bajo subordinación, la ART puede tener obligación de cubrirte.</p>
<p>📌  Pasantías educativas: Algunas pasantías forman parte de un programa académico y cuentan con un régimen de cobertura diferente.</p>
<p>📌  Determinación del caso: Si existe una discusión sobre la naturaleza de la relación, podrá intervenir la Comisión Médica y, en su caso, la Justicia.</p>
<p>📌  Conservá documentación: Guardá el convenio de pasantía, recibos, comunicaciones y toda prueba que acredite las tareas que realizabas.</p>
<p>📌 Consejo práctico: No asumas que por ser pasante no tenés derechos. Consultá tu situación particular y reuní toda la documentación que demuestre cómo era realmente tu trabajo.</p>
<p>PREGUNTA: ¿Qué es un accidente in itinere?</p>
<p>RESPUESTA_CORTA: Es el accidente que sufrís en el trayecto entre tu casa y el trabajo, o viceversa. Está cubierto por la ART.</p>
<p>Sí. Un accidente in itinere es el que ocurre mientras vas desde tu domicilio al trabajo o regresás a tu casa por el trayecto habitual. La Ley 24.557 lo considera un accidente de trabajo y, por lo tanto, está cubierto por la ART.</p>
<p>📌  Trayecto habitual: La cobertura alcanza el recorrido habitual entre tu casa y el trabajo. No tiene que ser el camino más corto, sino el que normalmente utilizás.</p>
<p>📌  Desvíos justificados: Si hacés una parada necesaria, como dejar a tus hijos en el colegio o comprar medicamentos, la cobertura puede mantenerse.</p>
<p>📌  Carga de la prueba: Si la ART sostiene que hubo un desvío injustificado, debe demostrarlo. No sos vos quien tiene que probar que el accidente fue laboral.</p>
<p>📌 Prestaciones: Si se reconoce el accidente, tenés derecho a atención médica, prestaciones dinerarias e indemnización si corresponde.</p>
<p>📌 Consejo práctico: Denunciá el accidente lo antes posible y guardá fotos, datos de testigos y cualquier prueba que demuestre el recorrido que estabas realizando.</p>
<p>PREGUNTA: ¿Me cubre la ART si me accidento yendo al trabajo en colectivo?</p>
<p>RESPUESTA_CORTA: Sí, si ocurrió durante el trayecto habitual está cubierto por la ART.</p>
<p>Sí. Si te accidentaste viajando en colectivo mientras ibas o volvías del trabajo por tu recorrido habitual, la ART debe brindarte cobertura como accidente in itinere.</p>
<p>📌  Transporte público: La cobertura incluye viajes en colectivo, tren, subte u otro medio que utilices habitualmente para ir o volver del trabajo.</p>
<p>📌  Trayecto completo: También está cubierto el recorrido que hacés caminando desde la parada hasta tu trabajo o domicilio.</p>
<p>📄 Pruebas: Conservá la tarjeta SUBE, boleto, denuncia policial o cualquier elemento que permita acreditar dónde y cuándo ocurrió el accidente.</p>
<p>📢 Denuncia: Si el empleador no realiza la denuncia, podés hacerla directamente ante la ART.</p>
<p>📌 Consejo práctico: Guardá toda la documentación del viaje y del accidente. Puede ser fundamental si la ART cuestiona que ocurrió durante el trayecto laboral.</p>
<p>PREGUNTA: ¿Me cubre la ART si me accidento yendo al trabajo en mi auto?</p>
<p>RESPUESTA_CORTA: Sí, si usabas tu auto en el trayecto habitual, el accidente está cubierto.</p>
<p>Sí. Si el accidente ocurrió mientras ibas o volvías del trabajo por tu recorrido habitual utilizando tu auto, la ART debe cubrirte como accidente in itinere.</p>
<p>📌  Trayecto habitual: La cobertura alcanza el recorrido que normalmente utilizás para ir o regresar del trabajo.</p>
<p>📌 Desvíos: Si realizaste un desvío personal sin una causa justificada, la ART podría discutir la cobertura.</p>
<p>📌  Responsabilidad de terceros: Si otro conductor provocó el accidente, además de la ART, también podés reclamar contra su seguro.</p>
<p>📄 Pruebas: Fotografías, denuncia policial, datos del otro vehículo y testigos pueden ayudarte a demostrar cómo ocurrió el accidente.</p>
<p>📌 Consejo práctico: Hacé la denuncia ante la ART lo antes posible y conservá toda la documentación del siniestro y del seguro.</p>
<p>PREGUNTA: ¿Qué pasa si me desvío del camino habitual y me accidento?</p>
<p>RESPUESTA_CORTA: Si el desvío no tiene justificación, puede no estar cubierto.</p>
<p>Depende del motivo del desvío. No todos los cambios de recorrido hacen perder la cobertura. Si el desvío fue razonable y necesario, el accidente puede seguir siendo considerado in itinere.</p>
<p>📌  Desvíos justificados: Dejar hijos en el colegio, comprar medicamentos o modificar el recorrido por tránsito pueden mantener la cobertura.</p>
<p>📌  Desvíos personales: Si el cambio fue únicamente por un interés personal y sin relación con el trayecto laboral, la ART puede rechazar el accidente.</p>
<p>📌 Evaluación: Cada situación se analiza según las circunstancias concretas y las pruebas disponibles.</p>
<p>📌  Carga de la prueba: Si la ART sostiene que el desvío fue injustificado, debe demostrarlo.</p>
<p>📌 Consejo práctico: Si tuviste que desviarte por una causa válida, guardá tickets, certificados o cualquier prueba que justifique ese recorrido.</p>
<p>PREGUNTA: ¿Qué pasa si me detuve a comprar algo yendo al trabajo?</p>
<p>RESPUESTA_CORTA: Si la compra era una necesidad básica, puede estar cubierto. Si no, puede no estar cubierto.</p>
<p>Una parada durante el trayecto no implica automáticamente perder la cobertura. Lo importante es que la detención haya sido razonable y compatible con el recorrido habitual.</p>
<p>📌  Paradas necesarias: Comprar medicamentos, alimentos o realizar una gestión indispensable puede mantener la cobertura.</p>
<p>📌  Paradas personales: Si la detención fue por un motivo exclusivamente personal, la ART puede cuestionar el accidente.</p>
<p>📌  Análisis del caso: Se evalúan el lugar, el tiempo de la detención y la necesidad de la parada.</p>
<p>📄 Pruebas: Tickets, comprobantes o testigos pueden servir para demostrar el motivo de la detención.</p>
<p>📌 Consejo práctico: Conservá cualquier comprobante de la compra si la ART cuestiona que el accidente ocurrió durante el trayecto habitual.</p>
<p>PREGUNTA: ¿Me cubre la ART si me accidento en bicicleta yendo al trabajo?</p>
<p>RESPUESTA_CORTA: Si la bicicleta es tu medio habitual, el accidente está cubierto.</p>
<p>Sí. Si utilizás la bicicleta como medio habitual para ir o volver del trabajo y sufrís un accidente durante ese trayecto, la ART debe cubrirte como accidente in itinere, conforme al art. 6 inc. a) de la Ley 24.557.</p>
<p>📌  Medio de transporte: La ley no distingue si viajás en bicicleta, auto, moto, colectivo o caminando. Lo importante es que el accidente ocurra en el trayecto habitual entre tu domicilio y el trabajo.</p>
<p>📄 Documentación: Registrá la hora del accidente, el estado de la bicicleta, las condiciones de la calle y cualquier circunstancia que haya influido en el hecho.</p>
<p>📌  Responsabilidad de terceros: Si otro vehículo provocó el accidente, además del reclamo ante la ART, también podés reclamar contra el responsable y su aseguradora.</p>
<p>📌  Carga de la prueba: Si la ART sostiene que la bicicleta no era tu medio habitual, es ella quien debe demostrarlo.</p>
<p>📌 Consejo práctico: Hacé la denuncia cuanto antes y guardá fotos, datos de testigos y toda la documentación que permita acreditar cómo ocurrió el accidente.</p>
<p>PREGUNTA: ¿Qué pasa si no voy directo al trabajo y me accidento?</p>
<p>RESPUESTA_CORTA: Si el recorrido no es el habitual o no tiene una justificación, la ART puede rechazar la cobertura.</p>
<p>No siempre tenés que hacer el camino más corto para estar cubierto. Lo importante es que el recorrido sea el que utilizás habitualmente o que exista una razón válida para modificarlo.</p>
<p>📌  Trayecto habitual: Si normalmente elegís un recorrido distinto por tránsito, seguridad o comodidad, ese camino también puede estar protegido.</p>
<p>📌  Desvíos justificados: Llevar a un hijo al colegio o cambiar la ruta por un corte de tránsito pueden mantener la cobertura.</p>
<p>📌  Desvíos personales: Si te alejaste del recorrido por un motivo exclusivamente personal, la ART puede cuestionar el accidente.</p>
<p>📄 Pruebas: Guardá registros de GPS, mensajes, fotografías o cualquier elemento que demuestre cuál era tu recorrido habitual.</p>
<p>📌 Consejo práctico: Si utilizás siempre un recorrido diferente al más corto, reuní pruebas que acrediten que ese era tu camino habitual antes de iniciar el reclamo.</p>
<p>PREGUNTA: ¿Me cubre la ART si me accidento caminando al trabajo?</p>
<p>RESPUESTA_CORTA: Sí. Si caminabas como parte de tu trayecto habitual, la ART debe cubrirte.</p>
<p>Sí. Si caminabas hacia el trabajo o regresabas a tu domicilio por el recorrido habitual, el accidente está cubierto como in itinere conforme al art. 6 inc. a) de la Ley 24.557.</p>
<p>📌  Trayecto a pie: La cobertura alcanza tanto si hacés todo el recorrido caminando como si caminás un tramo luego de bajar del colectivo, tren o subte.</p>
<p>📌  Responsabilidad de terceros: Si el accidente ocurrió por una vereda en mal estado, además de la ART, podría existir responsabilidad del municipio o del responsable del lugar.</p>
<p>📄 Documentación: Sacá fotos del lugar, anotá la dirección exacta y conseguí los datos de posibles testigos.</p>
<p>📢 Denuncia: Informá el accidente a la ART lo antes posible para evitar demoras en las prestaciones.</p>
<p>📌 Consejo práctico: Conservá el certificado médico y toda la evidencia del lugar donde ocurrió el accidente. Puede servir tanto para el reclamo ante la ART como para otras acciones.</p>
<p>PREGUNTA: ¿Qué pasa si me accidento en la puerta de mi casa saliendo para el trabajo?</p>
<p>RESPUESTA_CORTA: Si ya habías iniciado el trayecto al trabajo, puede ser un accidente in itinere.</p>
<p>Sí. Un accidente ocurrido en la puerta de tu domicilio puede ser considerado in itinere si ya habías comenzado el trayecto habitual hacia el trabajo.</p>
<p>📌  Inicio del recorrido: La hora del accidente y las circunstancias ayudan a demostrar que efectivamente estabas yendo a trabajar.</p>
<p>📌  Lugar del hecho: La cobertura puede alcanzar accidentes ocurridos en la puerta de tu casa, en el ingreso del edificio o al salir del domicilio.</p>
<p>📄 Pruebas: Fotografías, cámaras de seguridad, testigos y cualquier evidencia del lugar pueden resultar determinantes.</p>
<p>📌  Análisis del caso: La ART debe evaluar las circunstancias concretas antes de rechazar la cobertura.</p>
<p>📌 Consejo práctico: Documentá inmediatamente el lugar y el horario del accidente para demostrar que ya habías iniciado tu trayecto laboral.</p>
<p>PREGUNTA: ¿Qué pasa si me accidento llegando al trabajo pero todavía no entré?</p>
<p>RESPUESTA_CORTA: Dependiendo del lugar exacto, puede ser un accidente in itinere o un accidente de trabajo.</p>
<p>La calificación depende del lugar donde ocurrió el accidente. Si todavía estabas realizando el trayecto hacia el trabajo, puede tratarse de un accidente in itinere. Si ya habías ingresado al ámbito laboral, puede ser un accidente de trabajo.</p>
<p>📌  Lugar del accidente: La ubicación exacta es fundamental para determinar cómo debe clasificarse el accidente.</p>
<p>📌  Ámbito laboral: Si el accidente ocurrió dentro del establecimiento o en un sector bajo control del empleador, normalmente será considerado accidente de trabajo.</p>
<p>📄 Documentación: Fotografías, cámaras de seguridad y testimonios ayudan a acreditar dónde ocurrió el hecho.</p>
<p>✅ Cobertura: En cualquiera de los dos casos, la ART debe brindarte las prestaciones que correspondan.</p>
<p>📌 Consejo práctico: Anotá con precisión dónde ocurrió el accidente y reuní pruebas del lugar. Esa información puede ser clave si la ART discute la cobertura.</p>
<p>PREGUNTA: ¿Qué pasa si me accidento yendo a comer fuera del trabajo?</p>
<p>RESPUESTA_CORTA: Depende. Si el almuerzo forma parte de tu jornada laboral, el trayecto puede estar cubierto.</p>
<p>La cobertura depende de las circunstancias. Si el traslado para almorzar forma parte de tu jornada laboral y responde a una modalidad habitual, el accidente puede ser considerado in itinere.</p>
<p>📌  Horario de almuerzo: Si la empresa establece un horario para comer y el traslado forma parte de esa rutina, puede existir cobertura.</p>
<p>📌  Recorrido habitual: El trayecto debe ser razonable y vinculado al lugar donde normalmente almorzás.</p>
<p>📌  Desvíos personales: Si te alejaste del recorrido por un motivo ajeno al almuerzo o realizaste un desvío importante sin justificación, la ART puede rechazar el reclamo.</p>
<p>📄 Pruebas: Tickets, mensajes, testigos o cualquier elemento que demuestre el motivo del traslado pueden resultar útiles.</p>
<p>📌 Consejo práctico: Si sufrís un accidente durante el horario de almuerzo, guardá comprobantes del lugar donde ibas y documentá el recorrido realizado antes de denunciar el hecho ante la ART.</p>
<p>📌 ¿Qué pasa si me voy más temprano del trabajo y me accidento?</p>
<p>📌 Respuesta corta</p>
<p>Si te vas más temprano por una razón justificada, puede estar cubierto como accidente in itinere.</p>
<p>📌 Respuesta completa</p>
<p>Si te retirás antes de tu horario habitual por un motivo justificado (como una cita médica, una emergencia familiar o un permiso del empleador), el accidente puede ser considerado accidente in itinere, siempre que ocurra durante el trayecto habitual entre el trabajo y tu domicilio.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos en el trayecto directo y habitual. Salir antes del trabajo no elimina la cobertura si existía una causa razonable.</p>
<p>📌 Ejemplos de salidas justificadas:</p>
<p> Cita médica.</p>
<p> Emergencia familiar.</p>
<p> Permiso otorgado por el empleador.</p>
<p> Cierre anticipado del establecimiento.</p>
<p> Corte de luz u otra situación que impida continuar la jornada.</p>
<p>📌 Ejemplos que pueden afectar la cobertura:</p>
<p> Ir de compras por motivos personales.</p>
<p> Ir al cine o a un restaurante fuera del recorrido habitual.</p>
<p> Visitar amigos o familiares sin una razón vinculada al trabajo.</p>
<p>📌 Consejo práctico:</p>
<p>Guardá cualquier comprobante que justifique la salida anticipada (certificados médicos, autorización del empleador, mensajes, etc.). Si la ART rechaza la cobertura, podés reclamar ante la Comisión Médica.</p>
<p>📌 ¿Qué pasa si me accidento yendo al trabajo un día de lluvia?</p>
<p>📌 Respuesta corta</p>
<p>La lluvia no elimina la cobertura. Si el accidente ocurrió en el trayecto habitual, sigue siendo un accidente in itinere.</p>
<p>📌 Respuesta completa</p>
<p>Las condiciones climáticas no modifican tu derecho a la cobertura. Si te accidentás mientras ibas o volvías del trabajo durante una lluvia, tormenta, granizo o cualquier otro fenómeno climático, la ART debe brindarte las prestaciones correspondientes.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege el trayecto habitual entre el domicilio y el trabajo, independientemente del clima.</p>
<p>📌 Además:</p>
<p> Si el accidente ocurrió por una vereda rota, un pozo o una calle en mal estado, también puede existir responsabilidad del municipio.</p>
<p> La cobertura de la ART se mantiene aunque el piso estuviera mojado o resbaladizo.</p>
<p>📌 Qué conviene documentar:</p>
<p> Fotos del lugar.</p>
<p> Estado de la calle o vereda.</p>
<p> Pronóstico meteorológico del día.</p>
<p> Datos de testigos.</p>
<p>📌 Consejo práctico:</p>
<p>La ART no puede rechazar el accidente solamente porque &quot;llovía&quot;. Si lo hace, reuní pruebas y reclamá ante la Comisión Médica.</p>
<p>📌 ¿Qué pasa si me roban la moto yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Si sufriste lesiones durante el robo mientras ibas o volvías del trabajo, puede estar cubierto como accidente in itinere.</p>
<p>📌 Respuesta completa</p>
<p>Cuando el robo ocurre durante el trayecto habitual y provoca lesiones físicas, esas lesiones pueden quedar cubiertas por la ART como accidente in itinere.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto laboral habitual.</p>
<p>📌 Es importante distinguir:</p>
<p> El robo del vehículo no lo cubre la ART.</p>
<p> Las lesiones sufridas durante ese hecho sí pueden estar cubiertas.</p>
<p>📌 Qué tenés que hacer:</p>
<p> Hacer la denuncia policial inmediatamente.</p>
<p> Denunciar el accidente ante la ART.</p>
<p> Buscar atención médica y conservar toda la documentación.</p>
<p>📌 Consejo práctico:</p>
<p>Guardá la denuncia policial, certificados médicos y toda prueba del hecho. Si la ART rechaza el caso, consultá con un abogado especializado.</p>
<p>📌 ¿Qué pasa si me accidento llevando a mis hijos al colegio antes del trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Si forma parte de tu recorrido habitual, puede estar cubierto como accidente in itinere.</p>
<p>📌 Respuesta completa</p>
<p>La jurisprudencia reconoce que dejar a los hijos en el colegio antes de ir al trabajo puede integrar el trayecto habitual cuando forma parte de la rutina diaria.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege el trayecto habitual y la jurisprudencia admite determinadas paradas necesarias para cumplir obligaciones familiares.</p>
<p>📌 Para que exista cobertura normalmente se analiza que:</p>
<p> Sea una rutina habitual.</p>
<p> El colegio esté dentro del recorrido razonable.</p>
<p> El accidente ocurra mientras continuabas el trayecto hacia el trabajo.</p>
<p>📌 Qué conviene guardar:</p>
<p> Horarios escolares.</p>
<p> Constancias del establecimiento.</p>
<p> Testigos o cualquier prueba de esa rutina.</p>
<p>📌 Consejo práctico:</p>
<p>Si la ART cuestiona esa parada, reuní pruebas de que llevar a tus hijos forma parte habitual de tu recorrido diario.</p>
<p>📌 ¿Qué pasa si violo una señal de tránsito y me accidento yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Aunque hayas cometido una infracción, el accidente puede seguir estando cubierto por la ART.</p>
<p>📌 Respuesta completa</p>
<p>La existencia de una infracción de tránsito no elimina automáticamente la cobertura del accidente in itinere.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege el accidente ocurrido durante el trayecto habitual. La culpa del trabajador, por sí sola, no excluye la cobertura del sistema.</p>
<p>📌 Esto significa que:</p>
<p> La ART debe brindarte las prestaciones médicas y económicas.</p>
<p> Si causaste daños a terceros, eso podrá discutirse por otra vía civil o de seguros.</p>
<p>⚠️ Importante:</p>
<p> Una infracción puede generar consecuencias de tránsito.</p>
<p> Pero no significa automáticamente perder la cobertura laboral.</p>
<p>📌 Consejo práctico:</p>
<p>Denunciá igualmente el accidente ante la ART. Si intentan rechazarlo únicamente porque cometiste una infracción, reclamá ante la Comisión Médica.</p>
<p>📌 ¿Qué pasa si choco con otro auto yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Está cubierto como accidente in itinere y, además, podés reclamar contra el responsable del choque.</p>
<p>📌 Respuesta completa</p>
<p>Si sufrís un choque mientras ibas o volvías del trabajo por tu recorrido habitual, el accidente está cubierto por la ART, sin importar quién tuvo la culpa.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 considera accidente de trabajo el ocurrido durante el trayecto habitual.</p>
<p>📌 Además de la ART, podés tener otros derechos:</p>
<p> Reclamar al seguro del conductor responsable.</p>
<p> Percibir las prestaciones de la ART mientras continúa el reclamo civil.</p>
<p>📌 Qué conviene hacer:</p>
<p> Sacar fotos del accidente.</p>
<p> Obtener los datos del otro conductor y del seguro.</p>
<p> Hacer la denuncia policial.</p>
<p> Buscar atención médica.</p>
<p>📌 Consejo práctico:</p>
<p>No esperes el resultado del seguro para denunciar el accidente ante la ART. Son reclamos independientes.</p>
<p>📌 ¿Qué pasa si caigo en un pozo yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Está cubierto como accidente in itinere. Además, el municipio puede tener responsabilidad por el mal estado de la vía pública.</p>
<p>📌 Respuesta completa</p>
<p>Si sufriste una caída por un pozo mientras ibas o volvías del trabajo por tu recorrido habitual, el accidente puede ser considerado in itinere y estar cubierto por la ART.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto habitual entre el domicilio y el trabajo.</p>
<p>📌 Además:</p>
<p> La ART debe brindarte todas las prestaciones que correspondan.</p>
<p> Si el pozo era responsabilidad del municipio, también puede existir un reclamo civil por daños.</p>
<p>📌 Qué conviene documentar:</p>
<p> Fotos del pozo.</p>
<p> Dirección exacta.</p>
<p> Hora del accidente.</p>
<p> Datos de testigos.</p>
<p> Certificados médicos.</p>
<p>📌 Consejo práctico:</p>
<p>Denunciá el accidente cuanto antes y conservá todas las pruebas del estado del lugar. Pueden ser importantes tanto para el reclamo ante la ART como para una eventual acción contra el municipio.</p>
<p>📌 ¿Qué pasa si me mordió un perro yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Si fue durante tu trayecto habitual, puede estar cubierto como accidente in itinere.</p>
<p>📌 Respuesta completa</p>
<p>Si un perro te mordió mientras ibas o volvías del trabajo por tu recorrido habitual, el accidente puede ser considerado accidente in itinere y estar cubierto por la ART.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto directo y habitual entre el domicilio y el lugar de trabajo.</p>
<p>📌 Es importante tener en cuenta que:</p>
<p> Si ibas por tu recorrido habitual y el perro te atacó, la cobertura corresponde.</p>
<p> Si te desviaste voluntariamente para acercarte al animal, la ART podría discutir la cobertura.</p>
<p>📌 Qué tenés que hacer:</p>
<p> Buscá atención médica inmediata.</p>
<p> Denunciá el accidente ante la ART.</p>
<p> Si es posible, identificá al dueño del perro y realizá la denuncia correspondiente.</p>
<p> Documentá el lugar y las circunstancias del ataque.</p>
<p>📌 Consejo práctico:</p>
<p>Guardá certificados médicos, fotos y cualquier prueba del hecho. Además de la cobertura de la ART, el dueño del animal puede responder civilmente por los daños ocasionados.</p>
<p>📌 ¿Qué pasa si me atropella un colectivo yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Está cubierto como accidente in itinere. Además, podés reclamar contra la empresa responsable.</p>
<p>📌 Respuesta completa</p>
<p>Si un colectivo te atropella mientras ibas o volvías del trabajo por tu recorrido habitual, el accidente está cubierto por la ART como accidente in itinere.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 considera accidente laboral el ocurrido durante el trayecto directo y habitual entre el domicilio y el trabajo.</p>
<p>📌 Tus derechos incluyen:</p>
<p> Atención médica y rehabilitación por parte de la ART.</p>
<p> Prestaciones económicas si corresponde.</p>
<p> Posibilidad de reclamar daños y perjuicios contra la empresa de transporte.</p>
<p>📌 Qué conviene hacer:</p>
<p> Realizar la denuncia policial.</p>
<p> Obtener datos del colectivo (línea, interno y empresa).</p>
<p> Buscar testigos.</p>
<p> Denunciar el accidente ante la ART.</p>
<p>📌 Consejo práctico:</p>
<p>No firmes acuerdos con la empresa de transporte sin asesoramiento. El reclamo contra la ART y el reclamo civil son independientes y pueden tramitarse simultáneamente.</p>
<p>📌 ¿Qué pasa si me caigo de la bicisenda yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Si ocurrió durante el trayecto habitual, está cubierto como accidente in itinere. Además, el municipio puede ser responsable si la bicisenda estaba en mal estado.</p>
<p>📌 Respuesta completa</p>
<p>Si sufriste una caída mientras circulabas por una bicisenda rumbo al trabajo, el accidente puede estar cubierto por la ART como accidente in itinere.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto habitual entre el domicilio y el trabajo.</p>
<p>📌 Si la bicisenda estaba deteriorada:</p>
<p> El municipio puede responder por el mal estado de la vía pública.</p>
<p> Podés reclamar tanto ante la ART como por la vía civil.</p>
<p>📌 Qué conviene documentar:</p>
<p> Fotos de los baches, grietas u obstáculos.</p>
<p> Dirección exacta del lugar.</p>
<p> Hora del accidente.</p>
<p> Datos de posibles testigos.</p>
<p>📌 Consejo práctico:</p>
<p>Denunciá el accidente ante la ART lo antes posible y conservá toda la evidencia. Si el mal estado de la bicisenda influyó en la caída, consultá con un abogado para evaluar un reclamo adicional.</p>
<p>📌 ¿Qué pasa si me accidento en la vereda yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Si caminabas como parte de tu recorrido habitual, puede estar cubierto como accidente in itinere.</p>
<p>📌 Respuesta completa</p>
<p>Si sufrís una caída o accidente mientras caminás por la vereda durante el trayecto habitual al trabajo, la ART puede reconocerlo como accidente in itinere.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege el trayecto habitual entre el domicilio y el lugar de trabajo.</p>
<p>📌 Si la vereda estaba en mal estado:</p>
<p> La ART debe brindarte las prestaciones correspondientes.</p>
<p> Además, el municipio puede responder por los daños ocasionados por la falta de mantenimiento.</p>
<p>📌 Qué conviene documentar:</p>
<p> Fotos del lugar.</p>
<p> Dirección exacta.</p>
<p> Hora del accidente.</p>
<p> Datos de testigos.</p>
<p> Certificados médicos.</p>
<p>📌 Consejo práctico:</p>
<p>Conservá toda la documentación del accidente. Si la ART rechaza la cobertura o existía un evidente mal estado de la vereda, consultá con un abogado para evaluar las acciones correspondientes.</p>
<p>📌 ¿Qué pasa si me resbalé en una escalera del subte yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Si ocurrió durante el trayecto habitual, puede estar cubierto como accidente in itinere.</p>
<p>📌 Respuesta completa</p>
<p>Si te resbalaste en una escalera del subte mientras ibas o volvías del trabajo, el accidente puede estar cubierto por la ART como accidente in itinere.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto habitual entre el domicilio y el lugar de trabajo.</p>
<p>📌 Además:</p>
<p> Si la escalera estaba mojada, rota o sin señalización adecuada, la empresa concesionaria también podría ser responsable.</p>
<p> Las prestaciones de la ART son independientes de un eventual reclamo civil.</p>
<p>📌 Qué conviene documentar:</p>
<p> Fotos del estado de la escalera.</p>
<p> Lugar exacto del accidente.</p>
<p> Datos de testigos.</p>
<p> Solicitar la conservación de las cámaras de seguridad de la estación.</p>
<p>📌 Consejo práctico:</p>
<p>Denunciá el accidente ante la ART cuanto antes y reuní todas las pruebas posibles. Si hubo deficiencias en el mantenimiento de la estación, consultá con un abogado para analizar un reclamo adicional contra la empresa responsable.</p>
<p>📌 ¿Qué pasa si me detuve a hacer una compra volviendo del trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Si la compra era una necesidad básica, el accidente puede estar cubierto como in itinere.</p>
<p>📌 Respuesta completa</p>
<p>Si te detuviste a hacer una compra cuando volvías del trabajo y sufriste un accidente, puede considerarse un accidente in itinere si la parada fue razonable y necesaria dentro de tu recorrido habitual.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto habitual entre el domicilio y el trabajo. La jurisprudencia admite determinadas paradas necesarias sin perder la cobertura.</p>
<p>📌 Compras que pueden justificar la parada:</p>
<p>  Comprar comida para la cena.</p>
<p>  Comprar medicamentos para vos o un familiar.</p>
<p>  Comprar elementos de higiene personal indispensables.</p>
<p>📌 Compras que normalmente no justifican la parada:</p>
<p>  Comprar ropa, muebles o electrónica.</p>
<p>  Ir a un shopping o comercio alejado del recorrido habitual.</p>
<p>📌 Consejo práctico:</p>
<p>Guardá los tickets de compra, anotá la dirección y el horario del comercio y conservá cualquier comprobante que demuestre que la compra era necesaria.</p>
<p>📌 ¿Qué pasa si el colectivo se fue sin mí y me accidento después?</p>
<p>📌 Respuesta corta</p>
<p>Si tuviste que cambiar el recorrido por ese motivo, el accidente puede seguir estando cubierto.</p>
<p>📌 Respuesta completa</p>
<p>Si el colectivo pasó de largo, el servicio se interrumpió o tuviste que modificar el recorrido para llegar al trabajo, el accidente puede seguir siendo considerado in itinere, siempre que el cambio haya sido necesario y razonable.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege el trayecto habitual. Cuando un cambio de recorrido responde a una causa ajena al trabajador, la cobertura puede mantenerse.</p>
<p>📌 Ejemplos de cambios que pueden estar justificados:</p>
<p>  Caminar hasta otra parada para tomar otro colectivo.</p>
<p>  Cambiar el recorrido por una interrupción del subte.</p>
<p>  Tomar un taxi o remís por la suspensión del tren.</p>
<p>📌 Qué conviene documentar:</p>
<p>  Boletos o comprobantes del transporte.</p>
<p>  Fotos o capturas de la interrupción del servicio.</p>
<p>  Hora y motivo del cambio de recorrido.</p>
<p>📌 Consejo práctico:</p>
<p>Si la ART cuestiona el recorrido, conservá toda la prueba posible que demuestre por qué tuviste que modificar el trayecto.</p>
<p>📌 ¿Qué pasa si me roban el celular yendo al trabajo y me lastimo?</p>
<p>📌 Respuesta corta</p>
<p>Si sufriste lesiones durante el robo, puede estar cubierto como accidente in itinere.</p>
<p>📌 Respuesta completa</p>
<p>Si te robaron el celular mientras ibas al trabajo y durante el hecho sufriste lesiones físicas, el accidente puede estar cubierto por la ART.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto habitual. Lo relevante son las lesiones sufridas durante el hecho.</p>
<p>📌 Qué tenés que hacer:</p>
<p>  Hacer la denuncia policial.</p>
<p>  Buscar atención médica inmediata.</p>
<p>  Denunciar el accidente ante la ART.</p>
<p>  Documentar el lugar, la hora y cómo ocurrió el robo.</p>
<p>📌 Consejo práctico:</p>
<p>Conservá la denuncia policial y todos los certificados médicos. Si el robo te provocó lesiones, la ART debe cubrir las prestaciones correspondientes.</p>
<p>📌 ¿Qué pasa si no recuerdo exactamente dónde fue el accidente?</p>
<p>📌 Respuesta corta</p>
<p>Es más difícil probarlo, pero no significa que pierdas el derecho a reclamar.</p>
<p>📌 Respuesta completa</p>
<p>Si no recordás el lugar exacto donde ocurrió el accidente, igualmente podés demostrar que fue un accidente in itinere mediante otras pruebas que permitan reconstruir el recorrido.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 exige acreditar que el accidente ocurrió durante el trayecto habitual, aunque no siempre sea posible precisar el punto exacto.</p>
<p>📌 Pruebas que pueden ayudarte:</p>
<p>  Testigos.</p>
<p>  Cámaras de seguridad.</p>
<p>  Registros de GPS.</p>
<p>  Certificados médicos.</p>
<p>  Registros de la tarjeta SUBE.</p>
<p>📌 Consejo práctico:</p>
<p>No dejes de denunciar el accidente por no recordar el lugar exacto. Reuní toda la prueba disponible y consultá con un abogado si la ART rechaza el reclamo.</p>
<p>📌 ¿Qué pasa si otro conductor me causa el accidente yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Está cubierto como accidente in itinere. Además, podés reclamar contra el conductor responsable.</p>
<p>📌 Respuesta completa</p>
<p>Si otro conductor provocó el accidente mientras ibas o volvías del trabajo, la ART debe brindarte cobertura, sin importar quién tuvo la culpa del siniestro.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto habitual. El reclamo ante la ART es independiente de cualquier acción civil contra el responsable.</p>
<p>📌 Además de la cobertura de la ART:</p>
<p>  Podés reclamar daños y perjuicios contra el conductor responsable.</p>
<p>  Ambos reclamos pueden tramitarse en forma simultánea.</p>
<p>📌 Qué conviene documentar:</p>
<p>  Fotos del lugar y de los vehículos.</p>
<p>  Denuncia policial.</p>
<p>  Datos del conductor, patente y seguro.</p>
<p>  Datos de los testigos.</p>
<p>📌 Consejo práctico:</p>
<p>No esperes a que termine el reclamo contra el otro conductor para iniciar el trámite ante la ART. Ambos procedimientos son independientes.</p>
<p>📌 ¿Qué pasa si me tropecé con una bicicleta mal estacionada yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Si ocurrió durante tu trayecto habitual, puede estar cubierto como accidente in itinere.</p>
<p>📌 Respuesta completa</p>
<p>Si te tropezaste con una bicicleta mal estacionada mientras ibas al trabajo, el accidente puede estar cubierto por la ART como accidente in itinere, siempre que haya ocurrido durante tu recorrido habitual.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto habitual entre el domicilio y el trabajo.</p>
<p>📌 Si la bicicleta obstaculizaba el paso:</p>
<p>  El dueño puede ser responsable por los daños ocasionados.</p>
<p>  Además de la cobertura de la ART, podrías reclamar por la vía civil.</p>
<p>📌 Qué conviene documentar:</p>
<p>  Fotos de la bicicleta y de cómo obstaculizaba el paso.</p>
<p>  Dirección exacta del accidente.</p>
<p>  Hora del hecho.</p>
<p>  Datos de los testigos, si los hubo.</p>
<p>📌 Consejo práctico:</p>
<p>Denunciá el accidente ante la ART lo antes posible y guardá toda la evidencia. Si la bicicleta estaba mal estacionada y provocó la caída, consultá con un abogado para evaluar un reclamo adicional.</p>
<p>📌 ¿Qué pasa si me dio un mareo yendo al trabajo y me accidento?</p>
<p>📌 Respuesta corta</p>
<p>Si el accidente ocurrió durante el trayecto habitual, puede estar cubierto por la ART.</p>
<p>📌 Respuesta completa</p>
<p>Si sufriste un mareo mientras ibas al trabajo y eso provocó un accidente, el hecho puede ser considerado un accidente in itinere, aunque la ART podría analizar si existía una condición médica previa.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto habitual. La existencia de una enfermedad previa no excluye automáticamente la cobertura.</p>
<p>📌 Si tenías una condición preexistente:</p>
<p>  No significa que pierdas el derecho a la cobertura.</p>
<p>  La ART deberá evaluar si existió relación entre el accidente y el trayecto laboral.</p>
<p>  Si rechaza el caso, deberá fundamentar su decisión.</p>
<p>📌 Qué conviene documentar:</p>
<p>  Atención médica inmediata.</p>
<p>  Hora del mareo y del accidente.</p>
<p>  Medicación que estabas tomando, si corresponde.</p>
<p>  Denuncia ante la ART.</p>
<p>📌 Consejo práctico:</p>
<p>Contale al médico exactamente cómo ocurrió el accidente y conservá toda la documentación. Si la ART rechaza el caso por una enfermedad previa, consultá con un abogado.</p>
<p>📌 ¿Qué pasa si me accidento volviendo del trabajo y me detuve a hacer una compra?</p>
<p>📌 Respuesta corta</p>
<p>Si la compra era una necesidad básica, el accidente puede estar cubierto como in itinere.</p>
<p>📌 Respuesta completa</p>
<p>Si te detuviste a realizar una compra cuando volvías del trabajo y sufriste un accidente, podría seguir siendo considerado un accidente in itinere, siempre que la parada fuera necesaria y razonable.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes durante el trayecto habitual. La jurisprudencia admite determinadas paradas para cubrir necesidades básicas.</p>
<p>📌 Compras que pueden justificar la parada:</p>
<p>  Compra de alimentos.</p>
<p>  Compra de medicamentos.</p>
<p>  Retirar dinero o pagar un servicio esencial.</p>
<p>📌 Compras que normalmente no justifican la parada:</p>
<p>  Comprar ropa o calzado.</p>
<p>  Comprar electrónica o electrodomésticos.</p>
<p>  Ir a locales alejados del recorrido habitual.</p>
<p>📌 Consejo práctico:</p>
<p>Guardá los tickets, anotá la dirección del comercio y conservá cualquier comprobante que demuestre que la compra era necesaria.</p>
<p>📌 ¿Me cubre la ART si me accidento en la estación de tren yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Si la estación forma parte de tu trayecto habitual, puede estar cubierto por la ART.</p>
<p>📌 Respuesta completa</p>
<p>Si sufriste un accidente dentro de la estación de tren mientras ibas o volvías del trabajo, el hecho puede ser considerado un accidente in itinere, ya que la estación integra el recorrido habitual.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto habitual entre el domicilio y el trabajo.</p>
<p>📌 Si la estación estaba en mal estado:</p>
<p>  La empresa concesionaria puede ser responsable.</p>
<p>  Además del reclamo ante la ART, podrías iniciar un reclamo civil.</p>
<p>📌 Qué conviene documentar:</p>
<p>  Fotos del lugar.</p>
<p>  Ubicación exacta dentro de la estación.</p>
<p>  Solicitar las cámaras de seguridad.</p>
<p>  Datos de testigos.</p>
<p>📌 Consejo práctico:</p>
<p>Denunciá el accidente ante la ART y conservá toda la prueba posible. Si hubo fallas en el mantenimiento de la estación, consultá con un abogado.</p>
<p>📌 ¿Qué pasa si me accidento en un parking yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Si el parking forma parte de tu trayecto habitual, puede estar cubierto como accidente in itinere.</p>
<p>📌 Respuesta completa</p>
<p>Si sufriste un accidente en un estacionamiento que utilizás habitualmente para ir al trabajo, el hecho puede estar cubierto por la ART como accidente in itinere.</p>
<p>📌 ¿Qué pasa si me accidento yendo al trabajo pero no recuerdo bien las circunstancias?</p>
<p>📌 Respuesta corta</p>
<p>Es más difícil probarlo, pero no imposible. Buscá pruebas y consultá con un abogado.</p>
<p>📌 Respuesta completa</p>
<p>Si no recordás bien cómo ocurrió el accidente, igual podés reclamar. Lo importante es demostrar que estabas realizando el trayecto habitual entre tu domicilio y el trabajo.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto directo y habitual entre el domicilio y el lugar de trabajo. No exige recordar cada detalle del hecho.</p>
<p>📌 Pruebas que pueden ayudarte:</p>
<p> Testigos que hayan visto el accidente o te hayan asistido.</p>
<p> Cámaras de seguridad de comercios, edificios o del municipio.</p>
<p> Registros de GPS del celular o del vehículo.</p>
<p> Certificados médicos con el horario de atención y las lesiones.</p>
<p> Registros de la tarjeta SUBE, boletos o comprobantes de viaje.</p>
<p>⚠️ Importante:</p>
<p> La ART no puede rechazar automáticamente el reclamo porque no recuerdes exactamente lo sucedido.</p>
<p> Si sostiene que no fue un accidente in itinere, es la ART quien debe probarlo.</p>
<p>📌 Consejo práctico:</p>
<p>Reuní toda la documentación posible, hablá con quienes puedan aportar información y hacé la denuncia cuanto antes. Un abogado puede ayudarte a reconstruir los hechos y fortalecer el reclamo.</p>
<p>📌 ¿Qué pasa si me accidento volviendo del trabajo y el accidente fue por un bache en la ruta?</p>
<p>📌 Respuesta corta</p>
<p>Si ocurrió en tu trayecto habitual, está cubierto como accidente in itinere. Además, el municipio o responsable de la ruta puede responder por el mal estado del camino.</p>
<p>📌 Respuesta completa</p>
<p>Si sufriste un accidente por un bache mientras volvías del trabajo por tu recorrido habitual, el hecho puede estar cubierto por la ART como accidente in itinere.</p>
<p>📌 ¿Qué dice la ley?</p>
<p>El art. 6 inc. a) de la Ley 24.557 protege los accidentes ocurridos durante el trayecto habitual entre el trabajo y el domicilio.</p>
<p>📌 Además del reclamo ante la ART:</p>
<p> Podés iniciar un reclamo civil contra el municipio o quien tenga a cargo el mantenimiento de la ruta.</p>
<p> Ambos reclamos son independientes y pueden realizarse al mismo tiempo.</p>
<p>📌 Qué conviene documentar:</p>
<p> Fotos del bache y del lugar del accidente.</p>
<p> Ubicación exacta (ruta, kilómetro o intersección).</p>
<p> Hora del accidente.</p>
<p> Datos de posibles testigos.</p>
<p> Certificados médicos de las lesiones.</p>
<p>📌 Consejo práctico:</p>
<p>Denunciá el accidente ante la ART lo antes posible y conservá todas las pruebas. Si el mal estado de la ruta fue la causa del siniestro, consultá con un abogado para evaluar también un reclamo por daños y perjuicios.</p>
<p>📌 ¿Qué es la ART?</p>
<p>📌 Respuesta corta</p>
<p>La ART (Aseguradora de Riesgos del Trabajo) es la empresa que tiene que darte cobertura si sufrís un accidente laboral o una enfermedad profesional.</p>
<p>📌 Respuesta completa</p>
<p>Tu empleador está obligado a contratar una ART para cubrir los riesgos del trabajo. Si te accidentás o desarrollás una enfermedad por tu actividad laboral, la ART tiene que hacerse cargo de tu atención médica y de todas las prestaciones que la ley prevé, desde el primer día.</p>
<p>📌 ¿Qué dice la ley? El art. 1 de la Ley 24.557 crea el sistema de Riesgos del Trabajo, con el objetivo de prevenir accidentes y garantizar las prestaciones a los trabajadores que los sufren.</p>
<p>📌 La ART te tiene que dar:</p>
<p>📌  Atención médica integral, sin costo para vos.</p>
<p>📌  Medicamentos, estudios y rehabilitación.</p>
<p>📌  Prestaciones económicas mientras no podés trabajar.</p>
<p>📌  Indemnización si te queda una incapacidad.</p>
<p>📌 Si tu empleador no tiene ART:</p>
<p>📌 Podés reclamar directamente contra el empleador.</p>
<p>📌 No perdés ningún derecho por esa falta.</p>
<p>📌 Consejo práctico: Si tuviste un accidente laboral, pedí siempre el nombre de la ART de tu empleador y hacé la denuncia cuanto antes. Si no tiene ART contratada, consultá con un abogado antes de aceptar cualquier explicación del empleador.</p>
<p>📌 ¿Cómo denuncio un accidente ante la ART?</p>
<p>📌 Respuesta corta</p>
<p>Podés denunciarlo a través de tu empleador o directamente ante la ART.</p>
<p>📌 Respuesta completa</p>
<p>Lo primero es avisarle a tu empleador. Pero si no hace la denuncia, o tarda en hacerla, vos mismo podés presentarla directamente ante la ART. No necesitás esperar a que él actúe.</p>
<p>📌 ¿Qué dice la ley? El art. 31 de la Ley 24.557 obliga al empleador a denunciar el accidente, y a la ART a recibir esa denuncia y brindar las prestaciones que correspondan.</p>
<p>📌 Qué vas a necesitar:</p>
<p>📌  DNI.</p>
<p>📌  Una descripción de cómo ocurrió el accidente.</p>
<p>📌  Datos de testigos, si los hubo.</p>
<p>📌  Certificados médicos, si ya te atendieron.</p>
<p>📌 Si la ART rechaza la denuncia:</p>
<p>📌 Podés iniciar el trámite ante la Comisión Médica.</p>
<p>📌 Podés buscar asesoramiento legal para reclamar.</p>
<p>📌 Consejo práctico: No esperes a que tu empleador se ocupe. Si demora o se niega, hacé la denuncia vos mismo ante la ART y guardá una constancia de todo lo que presentes.</p>
<p>📌 ¿Qué cubre la ART en caso de accidente?</p>
<p>📌 Respuesta corta</p>
<p>La ART tiene que cubrir la atención médica, la rehabilitación, las prestaciones económicas y la indemnización si corresponde.</p>
<p>📌 Respuesta completa</p>
<p>Desde el momento del accidente hasta que te recuperás o hasta que se determina que te queda una incapacidad permanente la ART tiene que brindarte todas las prestaciones necesarias, sin excepciones.</p>
<p>📌 ¿Qué dice la ley? Los arts. 11, 13 y 14 de la Ley 24.557 regulan las prestaciones médicas y económicas que te corresponden como trabajador accidentado.</p>
<p>📌 La cobertura incluye:</p>
<p>📌  Atención médica, estudios y cirugías.</p>
<p>📌  Medicamentos y rehabilitación.</p>
<p>📌  Prótesis y ayudas técnicas, cuando las necesitás.</p>
<p>📌  Reintegro de gastos de traslado.</p>
<p>📌  Prestaciones por incapacidad temporaria o permanente.</p>
<p>📌  Recalificación profesional, en algunos casos.</p>
<p>📌 Consejo práctico: La ART no puede limitar tu tratamiento sin un fundamento médico. Si te niegan una prestación, reclamá de inmediato y guardá toda la documentación: puede ser clave si el caso termina en la Comisión Médica.</p>
<p>📌 ¿La ART me puede rechazar la denuncia del accidente?</p>
<p>📌 Respuesta corta</p>
<p>Sí, pero el rechazo tiene que estar fundamentado, y vos podés impugnarlo.</p>
<p>📌 Respuesta completa</p>
<p>La ART puede considerar que un hecho no es un accidente laboral. Lo que no puede hacer es rechazar tu denuncia sin explicarte con claridad los motivos. Un rechazo sin fundamentos es, en sí mismo, cuestionable.</p>
<p>📌 ¿Qué dice la ley? La Ley 24.557 y la Ley 27.348 habilitan el procedimiento ante la Comisión Médica Jurisdiccional para cuestionar las decisiones de la ART, y después ante la justicia laboral si es necesario.</p>
<p>📌 Si te rechazan el accidente:</p>
<p>📌  Pedí la resolución por escrito.</p>
<p>📌  Reuní toda la documentación médica que tengas.</p>
<p>📌  Buscá testigos o cualquier otra prueba disponible.</p>
<p>📌  Presentá el reclamo ante la Comisión Médica.</p>
<p>📌 Consejo práctico: No aceptes nunca un rechazo por teléfono o de palabra. Exigí siempre la respuesta por escrito y consultá con un abogado antes de definir los próximos pasos.</p>
<p>📌 ¿Qué hago si la ART no me da el tratamiento que necesito?</p>
<p>📌 Respuesta corta</p>
<p>Podés reclamar por escrito para que autorice el tratamiento y, si no responde, ir a la Comisión Médica.</p>
<p>📌 Respuesta completa</p>
<p>La ART tiene la obligación de garantizarte la atención médica necesaria para tu recuperación. Si se niega a autorizar un estudio, una cirugía o un tratamiento, eso es un incumplimiento que podés reclamar.</p>
<p>📌 ¿Qué dice la ley? El art. 20 de la Ley 24.557 establece las prestaciones en especie que la ART tiene que otorgarte mientras dure tu proceso de recuperación.</p>
<p>📌 Qué podés hacer:</p>
<p>📌  Presentar un reclamo por escrito.</p>
<p>📌  Guardar recetas, estudios e informes médicos.</p>
<p>📌  Reclamar ante la Comisión Médica si la ART no responde.</p>
<p>📌  Buscar asesoramiento legal si la negativa persiste.</p>
<p>📌 Consejo práctico: Conservá todas las recetas, órdenes médicas y comunicaciones con la ART. Esa documentación suele ser la prueba decisiva cuando el reclamo llega a la Comisión Médica.</p>
<p>📌 ¿Cuánto tiempo tengo para denunciar un accidente ante la ART?</p>
<p>📌 Respuesta corta</p>
<p>Lo recomendable es denunciarlo de inmediato. El derecho a reclamar prescribe a los 2 años.</p>
<p>📌 Respuesta completa</p>
<p>La ley no fija un plazo específico para hacer la denuncia en sí, pero cuanto antes la hagas, más fácil te va a resultar acreditar cómo ocurrió el accidente y acceder a las prestaciones sin demoras.</p>
<p>📌 ¿Qué dice la ley? El art. 44 de la Ley 24.557 fija en 2 años el plazo de prescripción de las acciones derivadas de un accidente laboral o enfermedad profesional.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌  Avisar el accidente de inmediato.</p>
<p>📌  Exigir que el empleador haga la denuncia formal.</p>
<p>📌  Si no lo hace, denunciar vos mismo ante la ART.</p>
<p>📌  Guardar toda la documentación médica desde el primer día.</p>
<p>📌 Consejo práctico: No esperes a que aparezcan complicaciones para actuar. Cuanto antes denuncies, más simple va a ser reunir la prueba y proteger tu reclamo.</p>
<p>📌 ¿Qué es un accidente de trabajo según la LRT?</p>
<p>📌 Respuesta corta</p>
<p>Es todo hecho súbito y violento ocurrido por causa o en ocasión del trabajo, incluyendo los accidentes in itinere.</p>
<p>📌 Respuesta completa</p>
<p>La Ley de Riesgos del Trabajo considera accidente laboral a todo hecho súbito y violento que ocurre mientras trabajás o como consecuencia del trabajo. También incluye los que ocurren en el trayecto habitual entre tu casa y tu trabajo.</p>
<p>📌 ¿Qué dice la ley? El art. 6 de la Ley 24.557 define el accidente de trabajo e incluye expresamente los ocurridos durante el trayecto directo y habitual entre el domicilio y el lugar de trabajo.</p>
<p>📌 Se consideran accidentes laborales:</p>
<p>📌  Los que ocurren dentro del lugar de trabajo.</p>
<p>📌  Los accidentes in itinere.</p>
<p>📌  Los que se producen cumpliendo tareas ordenadas por el empleador.</p>
<p>📌 Para reclamar:</p>
<p>📌 Denunciá el accidente ante la ART.</p>
<p>📌 Guardá toda la documentación médica.</p>
<p>📌 Conservá cualquier prueba de cómo ocurrió el hecho.</p>
<p>📌 Consejo práctico: Si tenés dudas sobre si tu caso está cubierto, hacé la denuncia igual. Muchas situaciones que la ART rechaza en un primer momento terminan siendo reconocidas por la Comisión Médica o por la justicia.</p>
<p>📌 ¿La ART me cubre si me accidenté yendo al trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Sí. Si el accidente ocurrió en el trayecto habitual entre tu casa y el trabajo, la ART tiene que cubrirte.</p>
<p>📌 Respuesta completa</p>
<p>Los accidentes que ocurren yendo o volviendo del trabajo se llaman accidentes in itinere, y están protegidos por la Ley de Riesgos del Trabajo siempre que hayan sucedido en el recorrido habitual.</p>
<p>📌 ¿Qué dice la ley? El art. 6 inc. a) de la Ley 24.557 considera accidente laboral al que ocurre durante el trayecto directo y habitual entre el domicilio y el lugar de trabajo.</p>
<p>📌 Para que esté cubierto:</p>
<p>📌  Tiene que haber ocurrido en el recorrido habitual.</p>
<p>📌  No puede haber un desvío importante sin justificación.</p>
<p>📌  La ART tiene que darte atención médica y las prestaciones que correspondan.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Informar el accidente cuanto antes.</p>
<p>📌 Guardar pruebas del recorrido (testigos, fotos, GPS, cámaras).</p>
<p>📌 Denunciar ante la ART si el empleador no lo hace.</p>
<p>📌 Consejo práctico: Si la ART rechaza la cobertura alegando un desvío, eso no significa que tenga razón. Un desvío menor una parada breve en un kiosco o una farmacia, por ejemplo no siempre invalida la cobertura. Conservá toda la prueba posible y consultá con un abogado.</p>
<p>📌 ¿Qué es una enfermedad profesional según la ART?</p>
<p>📌 Respuesta corta</p>
<p>Es una enfermedad causada por las tareas que realizás o por los riesgos propios de tu trabajo.</p>
<p>📌 Respuesta completa</p>
<p>No todos los problemas de salud aparecen por un accidente puntual. Cuando una enfermedad se desarrolla como consecuencia directa del trabajo, o de la exposición a determinados agentes laborales, puede ser reconocida como enfermedad profesional y cubierta por la ART.</p>
<p>📌 ¿Qué dice la ley? El art. 6 de la Ley 24.557 incluye entre las contingencias cubiertas a las enfermedades profesionales reconocidas por el listado oficial vigente.</p>
<p>📌 Algunos ejemplos:</p>
<p>📌  Tendinitis por movimientos repetitivos.</p>
<p>📌 </p>
<p>📌 Hernias de columna por levantar peso.</p>
<p>📌  Pérdida auditiva por exposición prolongada al ruido.</p>
<p>📌  Enfermedades provocadas por agentes químicos o biológicos.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Atención médica integral.</p>
<p>📌 Estudios y tratamientos.</p>
<p>📌 Rehabilitación.</p>
<p>📌 Indemnización si te queda una incapacidad.</p>
<p>📌 Consejo práctico: Si sospechás que tu problema de salud tiene relación con tu trabajo, no lo naturalices. Consultá cuanto antes y pedí que se evalúe formalmente como enfermedad profesional.</p>
<p>📌 ¿Qué obligaciones tiene el empleador con la ART?</p>
<p>📌 Respuesta corta</p>
<p>Tiene que contratar una ART, denunciar los accidentes y garantizar que recibas todas las prestaciones.</p>
<p>📌 Respuesta completa</p>
<p>Contratar una ART es solo el punto de partida. Durante toda la relación laboral, tu empleador tiene una serie de obligaciones concretas para prevenir accidentes y responder cuando ocurren.</p>
<p>📌 ¿Qué dice la ley? Los arts. 7 y 8 de la Ley 24.557 obligan al empleador a afiliarse a una ART y a denunciar los accidentes laborales que sufran sus trabajadores.</p>
<p>📌 El empleador tiene que:</p>
<p>📌  Contratar una ART.</p>
<p>📌  Pagar las cuotas correspondientes.</p>
<p>📌  Denunciar el accidente dentro de las 48 horas.</p>
<p>📌  Cumplir las normas de seguridad e higiene.</p>
<p>📌  Colaborar con la investigación del accidente.</p>
<p>📌 Consejo práctico: Si tu empleador no denuncia el accidente, o directamente no tiene ART, igual podés reclamar. Ese incumplimiento suyo no te hace perder ningún derecho.</p>
<p>📌 ¿Me pueden despedir por haberme accidentado en el trabajo?</p>
<p>📌 Respuesta corta</p>
<p>No. Haber sufrido un accidente laboral no es una causa válida de despido.</p>
<p>📌 Respuesta completa</p>
<p>La ley protege al trabajador accidentado frente a represalias. Si tu empleador te despide únicamente por haber tenido un accidente o por haber reclamado tus derechos, ese despido puede tener consecuencias legales para él.</p>
<p>📌 ¿Qué dice la ley? La Ley de Contrato de Trabajo y la Ley 23.592 protegen al trabajador frente a actos discriminatorios o represalias por el ejercicio de sus derechos.</p>
<p>📌 Si te despiden:</p>
<p>📌  Pueden corresponderte indemnizaciones agravadas.</p>
<p>📌  Guardá el telegrama de despido y toda la documentación relacionada.</p>
<p>📌  Conservá las constancias médicas del accidente.</p>
<p>📌  Consultá rápido con un abogado.</p>
<p>📌 Consejo práctico: No firmes acuerdos ni renuncias sin asesoramiento previo. Si el despido llegó justo después del accidente o del reclamo, es un dato que hay que analizar con cuidado.</p>
<p>📌 ¿Qué es la Comisión Médica Jurisdiccional?</p>
<p>📌 Respuesta corta</p>
<p>Es el organismo que resuelve los conflictos entre los trabajadores y la ART.</p>
<p>📌 Respuesta completa</p>
<p>Cuando no estás de acuerdo con una decisión de la ART un rechazo, un alta, un porcentaje de incapacidad, la Comisión Médica interviene para analizar tu caso y determinar qué prestaciones te corresponden.</p>
<p>📌 ¿Qué dice la ley? La Ley 27.348 establece la intervención de las Comisiones Médicas como instancia obligatoria previa para resolver conflictos entre trabajadores y ART.</p>
<p>📌 Interviene, por ejemplo, cuando:</p>
<p>📌  La ART rechaza el accidente.</p>
<p>📌  Te niegan un tratamiento.</p>
<p>📌  Hay discusión sobre el porcentaje de incapacidad.</p>
<p>📌  No estás de acuerdo con el alta médica.</p>
<p>📌 Consejo práctico: El trámite es gratuito y necesita patrocinio letrado. Llevá toda la documentación médica y laboral que tengas para respaldar tu reclamo desde el primer día.</p>
<p>📌 ¿Quién me paga mientras estoy de baja por la ART?</p>
<p>📌 Respuesta corta</p>
<p>Mientras no podés trabajar por el accidente, cobrás una prestación económica que paga la ART.</p>
<p>📌 Respuesta completa</p>
<p>Si el accidente laboral te impide trabajar de manera temporaria, la ART tiene que abonarte esa prestación económica hasta que recibas el alta médica o se determine que te queda una incapacidad permanente.</p>
<p>📌 ¿Qué dice la ley? Los arts. 13 a 16 de la Ley 24.557 regulan las prestaciones dinerarias durante la incapacidad laboral temporaria y permanente.</p>
<p>📌 Durante ese período:</p>
<p>📌  Cobrás la prestación económica prevista por la ley.</p>
<p>📌  La ART sigue a cargo de tu tratamiento médico.</p>
<p>📌  El pago continúa hasta el alta o hasta la determinación de la incapacidad.</p>
<p>📌 Consejo práctico: Controlá que los pagos lleguen en tiempo y forma. Si hay demoras o diferencias, guardá los recibos y reclamá de inmediato: no dejes que se acumulen los meses sin hacer el reclamo formal.</p>
<p>📌 ¿Qué es el Alta Médica de la ART?</p>
<p>📌 Respuesta corta</p>
<p>Es la decisión con la que la ART da por terminado tu tratamiento médico.</p>
<p>📌 Respuesta completa</p>
<p>El alta médica significa que, según la ART, alcanzaste la estabilidad médica y ya no necesitás seguir el tratamiento. Eso no siempre significa que estés totalmente recuperado, y por eso la ley te da una vía para cuestionarla.</p>
<p>📌 ¿Qué dice la ley? La Ley 24.557 y la Resolución SRT N° 5/2026 regulan el procedimiento para impugnar el alta médica cuando el trabajador no está de acuerdo.</p>
<p>📌 Antes de aceptar el alta:</p>
<p>📌  Verificá que realmente estés recuperado.</p>
<p>📌  Pedí copia de todos tus estudios e informes médicos.</p>
<p>📌  Confirmá si corresponde evaluar una incapacidad permanente.</p>
<p>📌 Si no estás de acuerdo:</p>
<p>📌 Podés impugnar el alta ante la Comisión Médica dentro de los plazos legales.</p>
<p>📌 Conservá toda la documentación médica que respalde tu situación.</p>
<p>📌 Consejo práctico: No aceptes un alta si todavía sentís dolor, tenés limitaciones o seguís necesitando tratamiento. Antes de firmar cualquier documento, buscá asesoramiento para proteger tu reclamo.</p>
<p>📌 ¿Puedo elegir el médico que me atiende en la ART?</p>
<p>📌 Respuesta corta</p>
<p>En general, la ART designa al profesional. Si no estás conforme, podés pedir un cambio o reclamar ante la Comisión Médica.</p>
<p>📌 Respuesta completa</p>
<p>La atención médica la brinda la red de prestadores de la ART. Eso no significa que tengas que resignarte a una atención deficiente o a un profesional con el que no te sentís bien atendido.</p>
<p>📌 ¿Qué dice la ley? La Ley 24.557 garantiza el acceso a las prestaciones médicas necesarias para tu recuperación. Si hay diferencias sobre la atención recibida, podés recurrir a la Comisión Médica Jurisdiccional.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Recibir atención médica adecuada y oportuna.</p>
<p>📌 Solicitar el cambio de profesional si hay motivos razonables.</p>
<p>📌 Reclamar si la atención es insuficiente o inadecuada.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Pedí el cambio por escrito ante la ART.</p>
<p>📌 Guardá estudios, recetas e informes médicos.</p>
<p>📌 Si no obtenés respuesta, iniciá el reclamo ante la Comisión Médica.</p>
<p>📌 Consejo práctico: No abandones el tratamiento por tu cuenta aunque no te guste el médico asignado. Reclamá el cambio formalmente, dejando constancia por escrito, para no perder cobertura mientras tanto.</p>
<p>📌 ¿Qué es una enfermedad de trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Es una enfermedad causada por las tareas o por las condiciones en que trabajás.</p>
<p>📌 Respuesta completa</p>
<p>Las enfermedades laborales aparecen como consecuencia de la actividad que realizás o de la exposición sostenida a determinados riesgos en tu puesto de trabajo.</p>
<p>📌 ¿Qué dice la ley? La Ley 24.557 reconoce las enfermedades profesionales cuando existe relación entre la enfermedad y el trabajo desarrollado, conforme al listado de enfermedades profesionales vigente.</p>
<p>📌 Algunos ejemplos:</p>
<p>📌 Tendinitis por movimientos repetitivos.</p>
<p>📌 Hernias por levantar peso.</p>
<p>📌 Síndrome del túnel carpiano.</p>
<p>📌 Hipoacusia por exposición al ruido.</p>
<p>📌 Enfermedades respiratorias por sustancias tóxicas.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Consultar rápido con un médico.</p>
<p>📌 Conservar todos los estudios realizados.</p>
<p>📌 Denunciar la enfermedad ante la ART.</p>
<p>📌 Consejo práctico: Muchas enfermedades profesionales avanzan de forma progresiva. No esperes a que el dolor sea insoportable para iniciar el reclamo: cuanto antes lo hagas, más fácil es demostrar la relación con tu trabajo.</p>
<p>📌 ¿Qué es la SRT?</p>
<p>📌 Respuesta corta</p>
<p>La Superintendencia de Riesgos del Trabajo (SRT) es el organismo que controla a las ART y protege los derechos de los trabajadores.</p>
<p>📌 Respuesta completa</p>
<p>La SRT supervisa que las ART cumplan con sus obligaciones, controla las prestaciones médicas y económicas, y recibe denuncias cuando hay incumplimientos de la aseguradora.</p>
<p>📌 ¿Qué dice la ley? La Superintendencia de Riesgos del Trabajo es la autoridad de aplicación encargada de fiscalizar el sistema de riesgos del trabajo en todo el país.</p>
<p>📌 Podés acudir a la SRT para:</p>
<p>📌 Denunciar incumplimientos de la ART.</p>
<p>📌 Informarte sobre tus derechos.</p>
<p>📌 Reclamar cuando la ART no responde correctamente.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Conservar toda la documentación del expediente.</p>
<p>📌 Registrar los reclamos que le hiciste a la ART.</p>
<p>📌 Presentar la denuncia si la aseguradora incumple sus obligaciones.</p>
<p>📌 Consejo práctico: Antes de resignarte a una negativa de la ART, verificá si corresponde hacer un reclamo ante la SRT o directamente ante la Comisión Médica.</p>
<p>📌 ¿Qué hago si la ART me quiere dar el Alta Médica y no estoy de acuerdo?</p>
<p>📌 Respuesta corta</p>
<p>Podés impugnar el Alta Médica y pedir que tu caso sea revisado por la Comisión Médica.</p>
<p>📌 Respuesta completa</p>
<p>Si todavía necesitás tratamiento, o no estás en condiciones de volver a trabajar, no tenés ninguna obligación de aceptar el alta sin cuestionarla primero.</p>
<p>📌 ¿Qué dice la ley? La Resolución SRT N° 5/2026 regula el procedimiento para presentar la divergencia por alta médica ante la Comisión Médica Jurisdiccional, dentro de los plazos que establece la norma.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Solicitar una nueva evaluación médica.</p>
<p>📌 Presentar estudios e informes de tus propios médicos.</p>
<p>📌 Impugnar el alta cuando la consideres prematura.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 No dejar vencer el plazo para reclamar.</p>
<p>📌 Reunir toda la documentación médica actualizada.</p>
<p>📌 Buscar asesoramiento especializado si persisten las secuelas.</p>
<p>📌 Consejo práctico: El alta médica no siempre significa que estés completamente recuperado. Si todavía tenés dolor, limitaciones, o necesitás seguir el tratamiento, presentá el reclamo antes de que venza el plazo legal.</p>
<p>📌 ¿La ART me cubre si me accidenté fuera de mi horario laboral?</p>
<p>📌 Respuesta corta</p>
<p>Depende. Si el accidente ocurrió mientras hacías tareas vinculadas a tu trabajo, la ART puede tener que cubrirte igual.</p>
<p>📌 Respuesta completa</p>
<p>El horario no es lo único que define la cobertura. Si el accidente ocurrió cumpliendo una tarea laboral, una orden de tu empleador o una actividad relacionada con tu trabajo, puede tratarse de un accidente cubierto por la ART aunque haya sido fuera de tu jornada habitual.</p>
<p>📌 ¿Qué dice la ley? El art. 6 de la Ley 24.557 protege los accidentes ocurridos con motivo o en ocasión del trabajo, aun cuando sucedan fuera del horario habitual.</p>
<p>📌 Puede haber cobertura cuando:</p>
<p>📌 Estabas haciendo horas extra.</p>
<p>📌 Cumplías una tarea pedida por el empleador.</p>
<p>📌 Participabas de una actividad laboral autorizada.</p>
<p>📌 El accidente tuvo relación directa con tu trabajo.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Guardar mensajes o instrucciones del empleador.</p>
<p>📌 Reunir testigos, si los hay.</p>
<p>📌 Denunciar el accidente ante la ART cuanto antes.</p>
<p>📌 Conservar toda la documentación médica.</p>
<p>📌 Consejo práctico: Si la ART rechaza el caso solo por haber ocurrido fuera del horario habitual, eso no significa que tenga razón. Lo que importa es poder demostrar la relación con tu trabajo.</p>
<p>📌 ¿Qué es el baremo de lesiones de la ART?</p>
<p>📌 Respuesta corta</p>
<p>Es la tabla que se usa para determinar el porcentaje de incapacidad y calcular la indemnización.</p>
<p>📌 Respuesta completa</p>
<p>Cuando una lesión te deja secuelas permanentes, la ART tiene que evaluar tu grado de incapacidad usando el baremo oficial vigente. Ese porcentaje es el que después determina el monto de tu indemnización.</p>
<p>📌 ¿Qué dice la ley? El Baremo 2026, aprobado por el Decreto 549/2025 y vigente desde febrero de 2026, junto con su anexo de tabla de evaluación de incapacidades, establece el sistema para determinar el porcentaje de incapacidad laboral permanente.</p>
<p>📌 El baremo sirve para:</p>
<p>📌 Evaluar las secuelas físicas o psíquicas.</p>
<p>📌 Asignar un porcentaje de incapacidad.</p>
<p>📌 Calcular la indemnización correspondiente.</p>
<p>📌 Unificar los criterios de evaluación médica en todo el país.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Solicitar copia de todos los estudios médicos.</p>
<p>📌 Revisar el porcentaje que te asignó la ART.</p>
<p>📌 Pedir una nueva evaluación si no estás de acuerdo.</p>
<p>📌 Impugnar el dictamen ante la Comisión Médica cuando corresponda.</p>
<p>📌 Consejo práctico: Si considerás que el porcentaje fijado por la ART no refleja tus secuelas reales, podés impugnar la evaluación. Un porcentaje mal calculado puede reducir de forma importante la indemnización que te corresponde.</p>
<p>📌 ¿La ART me cubre si me fracturé un dedo en el trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Sí. Si te fracturaste el dedo trabajando, la ART tiene que cubrir el tratamiento completo y las prestaciones que correspondan.</p>
<p>📌 Respuesta completa</p>
<p>Aunque parezca una lesión menor, una fractura ocurrida durante tu jornada laboral o mientras hacías tareas vinculadas a tu trabajo te da derecho a cobertura médica integral y, si corresponde, a las prestaciones económicas de la ley.</p>
<p>📌 ¿Qué dice la ley? El art. 6 de la Ley 24.557 considera accidente de trabajo a todo hecho súbito y violento ocurrido por causa o en ocasión del trabajo.</p>
<p>📌 La ART tiene que cubrir:</p>
<p>📌 Atención médica, estudios y radiografías.</p>
<p>📌 Inmovilización, cirugía si hace falta, y rehabilitación.</p>
<p>📌 Prestaciones económicas mientras dure la incapacidad laboral.</p>
<p>📌 La evaluación de una posible incapacidad permanente al terminar el tratamiento.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Denunciar el accidente ante la ART lo antes posible.</p>
<p>📌 Conservar todos los estudios y certificados médicos.</p>
<p>📌 Cumplir con los controles que te indique la ART.</p>
<p>📌 Consejo práctico: No dejes de denunciar una lesión solo porque parece leve. Una fractura mal consolidada puede generar una incapacidad permanente con derecho a indemnización.</p>
<p>📌 ¿Qué es la contingencia profesional?</p>
<p>📌 Respuesta corta</p>
<p>Es cualquier accidente de trabajo o enfermedad profesional cubierto por la Ley de Riesgos del Trabajo.</p>
<p>📌 Respuesta completa</p>
<p>Una contingencia profesional es toda lesión o enfermedad que tiene relación con tu actividad laboral y que te da derecho a las prestaciones de la ART.</p>
<p>📌 ¿Qué dice la ley? La Ley 24.557 reconoce como contingencias cubiertas a los accidentes de trabajo y a las enfermedades profesionales.</p>
<p>📌 Se consideran contingencias profesionales:</p>
<p>📌 Los accidentes ocurridos durante la jornada laboral.</p>
<p>📌 Los accidentes in itinere.</p>
<p>📌 Las enfermedades profesionales reconocidas por la normativa vigente.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Atención médica integral.</p>
<p>📌 Rehabilitación.</p>
<p>📌 Prestaciones económicas si hay incapacidad.</p>
<p>📌 Indemnización cuando corresponda.</p>
<p>📌 Consejo práctico: Si sufriste una lesión relacionada con tu trabajo, denunciala cuanto antes, aunque tengas dudas sobre si está cubierta. La ART está obligada a analizar el caso igual.</p>
<p>📌 ¿La ART cubre la incapacidad permanente parcial?</p>
<p>📌 Respuesta corta</p>
<p>Sí. Si te queda una incapacidad permanente parcial, la ART tiene que pagarte la indemnización que corresponda.</p>
<p>📌 Respuesta completa</p>
<p>Cuando terminás el tratamiento con una disminución permanente de tu capacidad laboral, la ART tiene que determinar el porcentaje de incapacidad según el baremo y abonarte la indemnización prevista por la ley.</p>
<p>📌 ¿Qué dice la ley? Los arts. 13 a 16 de la Ley 24.557 regulan las prestaciones económicas por incapacidad permanente, y el Baremo 2026 (Decreto 549/2025) determina el porcentaje aplicable a tu caso.</p>
<p>📌 La indemnización depende de:</p>
<p>📌 El porcentaje de incapacidad.</p>
<p>📌 Tu edad al momento del accidente.</p>
<p>📌 Tu remuneración.</p>
<p>📌 El baremo oficial usado para la evaluación.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Revisar el porcentaje de incapacidad que te asignaron.</p>
<p>📌 Pedir el dictamen médico completo.</p>
<p>📌 Consultar si el cálculo de tu remuneración es correcto.</p>
<p>📌 Impugnar ante la Comisión Médica si hay diferencias.</p>
<p>📌 Consejo práctico: No aceptes el porcentaje asignado sin revisarlo. Un punto de diferencia en la incapacidad puede significar una diferencia importante en el monto final.</p>
<p>📌 ¿Qué pasa si no me presento al médico de la ART?</p>
<p>📌 Respuesta corta</p>
<p>Si faltás sin justificación, la ART puede suspender las prestaciones médicas y económicas.</p>
<p>📌 Respuesta completa</p>
<p>Faltar a una consulta médica sin avisar es un riesgo real para tu cobertura. Pero si tenés una razón válida una internación, otra consulta médica, un problema de transporte la ART no debería suspenderte nada, siempre que la avises.</p>
<p>📌 ¿Qué dice la ley? La Ley 24.557 permite a la ART verificar el estado de salud del trabajador durante el tratamiento como condición para mantener las prestaciones.</p>
<p>📌 Qué podés hacer:</p>
<p>📌 Avisar con anticipación si no podés asistir, para que te reprogramen.</p>
<p>📌 Solicitar una explicación por escrito si te suspenden las prestaciones.</p>
<p>📌 Reclamar ante la Comisión Médica si la suspensión te parece injustificada.</p>
<p>📌 Consejo práctico: Nunca ignores una citación médica de la ART. Si surge un imprevisto, comunicalo de inmediato para evitar que te corten la cobertura mientras estás en tratamiento.</p>
<p>📌 ¿Qué es la gran invalidez en la ART?</p>
<p>📌 Respuesta corta</p>
<p>Es la situación de mayor incapacidad: cuando, además de no poder trabajar, necesitás asistencia permanente de otra persona.</p>
<p>📌 Respuesta completa</p>
<p>La gran invalidez es el grado más grave de incapacidad que prevé la Ley de Riesgos del Trabajo. Se da cuando las secuelas del accidente o la enfermedad laboral te dejan sin poder valerte por vos mismo para las actividades básicas de la vida diaria.</p>
<p>📌 ¿Qué dice la ley? La Ley 24.557 contempla prestaciones especiales, económicas y médicas, para los casos de mayor gravedad dentro de la incapacidad permanente.</p>
<p>📌 Puede darse en casos como:</p>
<p>📌 Paraplejia o cuadriplejia.</p>
<p>📌 Pérdida funcional muy severa de miembros.</p>
<p>📌 Ceguera con dependencia permanente.</p>
<p>📌 Otras lesiones que requieran asistencia continua.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Una indemnización mayor.</p>
<p>📌 Cobertura médica de por vida.</p>
<p>📌 Rehabilitación y asistencia según tus necesidades.</p>
<p>📌 Consejo práctico: Si la ART no reconoce la gravedad real de tu situación, pedí una revisión médica y asesorate cuanto antes. En estos casos, la diferencia entre un dictamen correcto y uno incorrecto es enorme.</p>
<p>📌 ¿La ART cubre la incapacidad total y permanente?</p>
<p>📌 Respuesta corta</p>
<p>Sí. Si tu incapacidad es total y permanente, la ART tiene que otorgarte las prestaciones e indemnización que fija la ley.</p>
<p>📌 Respuesta completa</p>
<p>Si un accidente o una enfermedad profesional te dejan con una incapacidad que te impide volver a trabajar, la ART tiene que reconocer esa situación y pagarte la indemnización que corresponde, que en este caso se abona como una prestación mensual, no como un pago único.</p>
<p>📌 ¿Qué dice la ley? La Ley 24.557 establece el régimen de prestaciones para la incapacidad laboral permanente total, calculado según el Baremo 2026 y tu ingreso base.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Cobrar la prestación mensual que corresponda.</p>
<p>📌 Seguir recibiendo las prestaciones médicas necesarias.</p>
<p>📌 Pedir la revisión del porcentaje de incapacidad si no estás de acuerdo.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Guardar toda la documentación médica.</p>
<p>📌 Presentarte a las evaluaciones que te fije la ART o la Comisión Médica.</p>
<p>📌 Buscar asesoramiento si te reconocen un porcentaje menor al real.</p>
<p>📌 Consejo práctico: Si considerás que la incapacidad reconocida no refleja tu limitación real, podés impugnar la decisión ante la Comisión Médica y reclamar lo que realmente te corresponde.</p>
<p>📌 ¿Qué es la asistencia médica obligatoria de la ART?</p>
<p>📌 Respuesta corta</p>
<p>Es el conjunto de prestaciones médicas que la ART tiene que darte sin costo mientras dure tu tratamiento.</p>
<p>📌 Respuesta completa</p>
<p>Desde que sufrís un accidente de trabajo o una enfermedad profesional, la ART tiene la obligación de garantizarte toda la atención médica necesaria hasta que te recuperes o alcances la estabilidad médica.</p>
<p>📌 ¿Qué dice la ley? El art. 20 de la Ley 24.557 obliga a la ART a brindar las prestaciones médicas necesarias derivadas del accidente o enfermedad laboral.</p>
<p>📌 La cobertura incluye:</p>
<p>📌 Consultas médicas.</p>
<p>📌 Estudios y diagnósticos.</p>
<p>📌 Cirugías e internaciones.</p>
<p>📌 Medicamentos.</p>
<p>📌 Prótesis y órtesis.</p>
<p>📌 Rehabilitación y kinesiología.</p>
<p>📌 Traslados, cuando son necesarios.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Guardar todas las órdenes médicas.</p>
<p>📌 Pedir por escrito cualquier prestación que te nieguen.</p>
<p>📌 Reclamar ante la Comisión Médica si la ART demora o rechaza tratamientos.</p>
<p>📌 Consejo práctico: La ART no puede suspender ni limitar tu tratamiento sin un fundamento médico. Si necesitás una prestación y no te la autorizan, reclamá de inmediato y por escrito.</p>
<p>📌 ¿La ART me cubre si me lastimé jugando al fútbol en el trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Depende. Si el partido era parte de una actividad organizada o autorizada por el empleador, puede estar cubierto por la ART.</p>
<p>📌 Respuesta completa</p>
<p>No todo lo que pasa dentro del ámbito laboral es automáticamente un accidente de trabajo. Si la lesión ocurrió en una actividad recreativa organizada, promovida o autorizada por la empresa, es posible que la ART tenga que cubrirla igual.</p>
<p>📌 ¿Qué dice la ley? La cobertura depende de si existía relación entre la actividad y el trabajo, o si tu participación fue autorizada por el empleador, conforme al criterio de &quot;ocasión del trabajo&quot; del art. 6 de la Ley 24.557.</p>
<p>📌 Puede haber cobertura si:</p>
<p>📌 Era una actividad organizada por la empresa.</p>
<p>📌 Formaba parte de un evento laboral.</p>
<p>📌 El empleador promovía o autorizaba la actividad.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Guardar invitaciones o comunicaciones sobre el evento.</p>
<p>📌 Pedir datos de testigos.</p>
<p>📌 Denunciar igual el accidente ante la ART.</p>
<p>📌 Consejo práctico: Aunque la ART rechace el caso en un primer momento, si la actividad tenía un vínculo real con el trabajo, esa decisión se puede revisar ante la Comisión Médica.</p>
<p>📌 ¿Qué es una recaída en la ART?</p>
<p>📌 Respuesta corta</p>
<p>Es cuando vuelven a aparecer los síntomas, o se agrava una lesión, después del Alta Médica.</p>
<p>📌 Respuesta completa</p>
<p>Si después de recibir el alta reaparecen los dolores, las limitaciones o las complicaciones vinculadas al mismo accidente laboral, puede tratarse de una recaída, y la ART tiene que evaluar tu situación de nuevo.</p>
<p>📌 ¿Qué dice la ley? Si existe relación entre los nuevos síntomas y el accidente laboral original, la ART tiene que reabrir el caso y volver a brindar las prestaciones correspondientes.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Pedir la reapertura del caso.</p>
<p>📌 Continuar el tratamiento médico.</p>
<p>📌 Ser evaluado de nuevo si la lesión empeoró.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Consultar al médico apenas reaparezcan los síntomas.</p>
<p>📌 Conservar todos los estudios anteriores.</p>
<p>📌 Informar la situación a la ART de inmediato.</p>
<p>📌 Consejo práctico: No ignores una recaída. Cuanto antes la informes, más fácil va a ser demostrar que está vinculada con el accidente original y no con una situación nueva.</p>
<p>📌 ¿La ART me cubre si me accidenté yendo a comprar algo para el trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Sí. Si estabas cumpliendo una tarea encomendada por tu empleador, el accidente puede estar cubierto por la ART.</p>
<p>📌 Respuesta completa</p>
<p>Si te accidentaste haciendo una compra o gestión relacionada con tu trabajo, por indicación de tu empleador, ese hecho puede considerarse un accidente laboral aunque haya ocurrido fuera del establecimiento.</p>
<p>📌 ¿Qué dice la ley? La Ley 24.557 protege los accidentes ocurridos mientras el trabajador realiza tareas vinculadas con su actividad laboral, incluso fuera de su lugar habitual de trabajo.</p>
<p>📌 Conviene poder demostrar que:</p>
<p>📌 La compra estaba relacionada con el trabajo.</p>
<p>📌 Fue pedida por el empleador.</p>
<p>📌 El accidente ocurrió durante esa gestión.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Guardar mensajes, órdenes o comprobantes de la compra.</p>
<p>📌 Denunciar el accidente ante la ART.</p>
<p>📌 Conservar certificados médicos y datos de testigos.</p>
<p>📌 Consejo práctico: Si la ART rechaza la cobertura alegando que estabas fuera del lugar de trabajo, reuní toda la documentación que demuestre que estabas cumpliendo una tarea laboral en ese momento.</p>
<p>📌 ¿La ART me cubre si tuve un accidente en una obra?</p>
<p>📌 Respuesta corta</p>
<p>Sí. Si sufriste un accidente trabajando en una obra, la ART tiene que darte la cobertura que la ley prevé.</p>
<p>📌 Respuesta completa</p>
<p>Los accidentes en obras de construcción están alcanzados por la cobertura de la ART igual que cualquier otro, siempre que hayan ocurrido durante la prestación de tareas o como consecuencia de ellas.</p>
<p>📌 ¿Qué dice la ley? La Ley 24.557 protege los accidentes ocurridos con motivo o en ocasión del trabajo, sin importar cuál sea la actividad desarrollada.</p>
<p>📌 La cobertura incluye:</p>
<p>📌 Atención médica integral.</p>
<p>📌 Rehabilitación.</p>
<p>📌 Prestaciones económicas, si corresponde.</p>
<p>📌 Indemnización por incapacidad permanente, cuando la haya.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Denunciar el accidente de inmediato.</p>
<p>📌 Buscar atención médica sin demora.</p>
<p>📌 Guardar estudios y certificados.</p>
<p>📌 Pedir los datos de compañeros que hayan presenciado el hecho.</p>
<p>📌 Consejo práctico: Los accidentes en obras suelen dejar lesiones importantes. Conservá toda la documentación desde el primer día para no complicar el reclamo más adelante.</p>
<p>📌 ¿Qué pasa si vuelvo a trabajar y reaparecen los síntomas?</p>
<p>📌 Respuesta corta</p>
<p>Si reaparecen después del alta, podés pedir que la ART vuelva a evaluar tu caso y siga brindando prestaciones.</p>
<p>📌 Respuesta completa</p>
<p>Si volviste a trabajar después del alta médica y te vuelven las molestias relacionadas con el mismo accidente o enfermedad profesional, podés pedir una nueva evaluación en lugar de resignarte a convivir con el dolor.</p>
<p>📌 ¿Qué dice la ley? Cuando hay relación entre los nuevos síntomas y el accidente laboral original, la ART tiene que analizar de nuevo el caso y brindar las prestaciones que correspondan.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Pedir una nueva atención médica.</p>
<p>📌 Solicitar la reapertura del expediente.</p>
<p>📌 Continuar con el tratamiento, si corresponde.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Consultar de inmediato al médico.</p>
<p>📌 Informar la situación a la ART.</p>
<p>📌 Conservar estudios y antecedentes médicos.</p>
<p>📌 Consejo práctico: No minimices una reaparición de síntomas. Cuanto antes la informes, más fácil va a ser acreditar que deriva del accidente original.</p>
<p>📌 ¿La ART cubre los daños estéticos?</p>
<p>📌 Respuesta corta</p>
<p>Las cicatrices y otras secuelas visibles pueden influir en el porcentaje de incapacidad, y en algunos casos dar lugar a otros reclamos.</p>
<p>📌 Respuesta completa</p>
<p>Las cicatrices, deformidades u otras secuelas visibles se pueden tener en cuenta al momento de evaluar las consecuencias permanentes del accidente. Según el caso, también pueden dar lugar a reclamos por otras vías legales.</p>
<p>📌 ¿Qué dice la ley? La incapacidad permanente se determina conforme al Baremo 2026 y a la Ley 24.557, mientras que otros daños se analizan según las circunstancias particulares del caso.</p>
<p>📌 Es importante conservar:</p>
<p>📌 Fotografías de las secuelas.</p>
<p>📌 Informes médicos.</p>
<p>📌 Estudios y certificados.</p>
<p>📌 Toda la documentación del tratamiento.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Pedir la evaluación médica correspondiente.</p>
<p>📌 Guardar evidencia de la evolución de las lesiones.</p>
<p>📌 Consultar con un abogado si las secuelas afectan tu calidad de vida.</p>
<p>📌 Consejo práctico: Las secuelas visibles también pueden tener consecuencias funcionales o psicológicas. Documentá todo desde el inicio del tratamiento, no cuando ya pasó el tiempo.</p>
<p>📌 ¿La ART me cubre si me operaron de la rodilla?</p>
<p>📌 Respuesta corta</p>
<p>Sí. Si la operación fue consecuencia de un accidente de trabajo o una enfermedad profesional, la ART tiene que cubrir todos los gastos y prestaciones.</p>
<p>📌 Respuesta completa</p>
<p>Si te tuvieron que operar la rodilla por una lesión laboral, la ART está obligada a cubrir la cirugía, la internación, los medicamentos, la rehabilitación y todas las prestaciones médicas necesarias hasta tu recuperación.</p>
<p>📌 ¿Qué dice la ley? El art. 6 de la Ley 24.557 establece que los accidentes de trabajo y las enfermedades profesionales están cubiertos por el sistema de riesgos del trabajo.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Cobertura integral de la cirugía y la rehabilitación.</p>
<p>📌 Cobro del subsidio por incapacidad mientras no podés trabajar.</p>
<p>📌 Evaluación de una eventual incapacidad permanente cuando recibas el alta.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Guardar todos los estudios, informes médicos y certificados.</p>
<p>📌 Cumplir con la rehabilitación indicada.</p>
<p>📌 Reclamar ante la Comisión Médica si no estás de acuerdo con el alta o el porcentaje de incapacidad.</p>
<p>📌 Consejo práctico: No aceptes el alta si todavía tenés limitaciones importantes. Una evaluación prematura puede afectar directamente el monto de tu indemnización.</p>
<p>📌 ¿Qué hago si la ART me quiere operar y yo no quiero?</p>
<p>📌 Respuesta corta</p>
<p>Nadie puede obligarte a operarte. Si tenés dudas, podés pedir una segunda opinión médica.</p>
<p>📌 Respuesta completa</p>
<p>Si la ART considera que una cirugía es el tratamiento indicado, la decisión final sigue siendo tuya. Tenés derecho a recibir información clara sobre los riesgos, los beneficios y las alternativas antes de aceptar cualquier intervención.</p>
<p>📌 ¿Qué dice la ley? Toda práctica médica requiere el consentimiento informado del paciente. La Ley 24.557 garantiza la atención médica, pero no habilita a imponerte un tratamiento en contra de tu voluntad.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Pedir toda la información sobre el procedimiento antes de decidir.</p>
<p>📌 Solicitar una segunda opinión médica.</p>
<p>📌 Negarte a una cirugía sin perder por eso tu derecho a otras prestaciones.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Pedir por escrito los fundamentos de la cirugía.</p>
<p>📌 Consultar con otro profesional.</p>
<p>📌 Conservar todos los estudios e informes médicos.</p>
<p>📌 Consejo práctico: Antes de rechazar una cirugía, asesorate con un profesional independiente. En algunos casos, la ART puede discutir si un tratamiento alternativo afecta la evolución de tu lesión y tu porcentaje final de incapacidad.</p>
<p>📌 ¿La ART paga una indemnización si un trabajador fallece?</p>
<p>📌 Respuesta corta</p>
<p>Sí. Si el fallecimiento fue consecuencia de un accidente laboral o una enfermedad profesional, la ART tiene que indemnizar a los derechohabientes.</p>
<p>📌 Respuesta completa</p>
<p>Cuando un trabajador fallece por una contingencia laboral, la ART tiene que pagar la indemnización prevista por la Ley de Riesgos del Trabajo y cubrir los gastos de sepelio.</p>
<p>📌 ¿Qué dice la ley? Los arts. 15 y concordantes de la Ley 24.557 prevén prestaciones económicas para los familiares con derecho a la indemnización.</p>
<p>📌 Los beneficiarios pueden ser:</p>
<p>📌 El cónyuge o conviviente con derecho.</p>
<p>📌 Los hijos menores de 21 años, o hasta los 25 si son estudiantes.</p>
<p>📌 Otros derechohabientes previstos por la ley.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Denunciar el fallecimiento ante la ART.</p>
<p>📌 Reunir la documentación que acredite el vínculo familiar.</p>
<p>📌 Pedir asesoramiento si la ART rechaza el pago.</p>
<p>📌 Consejo práctico: Si hay dudas sobre la causa del fallecimiento, o la ART rechaza la cobertura, es importante consultar rápido con un abogado para proteger los derechos de toda la familia.</p>
<p>📌 ¿Cómo calcula la ART la indemnización por incapacidad?</p>
<p>📌 Respuesta corta</p>
<p>La indemnización se calcula con una fórmula legal que considera, entre otros factores, el porcentaje de incapacidad, la edad y el ingreso base del trabajador.</p>
<p>📌 Respuesta completa</p>
<p>La ART no fija la indemnización a su criterio. El monto surge de la fórmula que establece la Ley de Riesgos del Trabajo, teniendo en cuenta el porcentaje de incapacidad determinado por la Comisión Médica según el Baremo 2026, tu edad y tu ingreso base.</p>
<p>📌 ¿Qué dice la ley? Los arts. 12 a 15 de la Ley 24.557 regulan las prestaciones dinerarias y la forma de calcular las indemnizaciones, con los pisos mínimos que fija periódicamente la SRT.</p>
<p>📌 Para el cálculo se considera:</p>
<p>📌 El porcentaje de incapacidad.</p>
<p>📌 Tu edad al momento del accidente.</p>
<p>📌 El ingreso base previsto por la ley.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Verificar que la ART haya tomado correctamente tu salario.</p>
<p>📌 Revisar el porcentaje de incapacidad asignado.</p>
<p>📌 Reclamar si detectás errores en la liquidación.</p>
<p>📌 Consejo práctico: Un porcentaje de incapacidad mal calculado puede reducir de forma significativa la indemnización. Siempre conviene revisar la liquidación con detalle antes de aceptarla.</p>
<p>📌 ¿Qué pasa si la ART me quiere dar el alta antes de tiempo?</p>
<p>📌 Respuesta corta</p>
<p>Podés impugnar el alta si todavía necesitás tratamiento o no recuperaste tu capacidad laboral.</p>
<p>📌 Respuesta completa</p>
<p>Si la ART pretende darte el alta cuando todavía tenés dolor, limitaciones o necesitás rehabilitación, no estás obligado a aceptar esa decisión sin cuestionarla.</p>
<p>📌 ¿Qué dice la ley? La Resolución SRT N° 5/2026 permite solicitar la intervención de la Comisión Médica cuando hay desacuerdo con el alta otorgada por la ART.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Seguir recibiendo atención médica, si corresponde.</p>
<p>📌 Pedir la revisión del alta.</p>
<p>📌 Reclamar una evaluación correcta de tu incapacidad.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Guardar todos los estudios médicos recientes.</p>
<p>📌 Presentar la impugnación dentro de los plazos legales.</p>
<p>📌 Continuar con los controles médicos mientras tanto.</p>
<p>📌 Consejo práctico: No firmes conformidades si todavía no estás recuperado. Una revisión a tiempo puede evitar que pierdas prestaciones importantes más adelante.</p>
<p>📌 ¿La ART me cubre si me accidento en el comedor de la empresa?</p>
<p>📌 Respuesta corta</p>
<p>Sí. Si el accidente ocurrió dentro del establecimiento y durante tu jornada laboral, puede estar cubierto por la ART.</p>
<p>📌 Respuesta completa</p>
<p>Si sufriste una caída, una quemadura u otro accidente usando el comedor de la empresa durante tu jornada laboral, ese hecho puede considerarse un accidente de trabajo.</p>
<p>📌 ¿Qué dice la ley? El art. 6 de la Ley 24.557 considera accidente laboral al que ocurre con motivo o en ocasión del trabajo.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Atención médica integral por parte de la ART.</p>
<p>📌 Prestaciones económicas si hay incapacidad.</p>
<p>📌 Rehabilitación hasta el alta médica.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Informar el accidente al empleador de inmediato.</p>
<p>📌 Conseguir atención médica.</p>
<p>📌 Buscar testigos y, si podés, sacar fotos del lugar.</p>
<p>📌 Consejo práctico: Si el accidente ocurrió por un desperfecto en el comedor o por falta de medidas de seguridad, además de la cobertura de la ART puede haber otras responsabilidades del empleador para evaluar.</p>
<p>📌 ¿Qué hago si la ART me manda a un médico que no es especialista?</p>
<p>📌 Respuesta corta</p>
<p>Tenés derecho a una atención adecuada. Si el profesional asignado no es el especialista que necesitás, podés reclamar el cambio.</p>
<p>📌 Respuesta completa</p>
<p>La ART tiene que garantizarte una atención médica acorde al tipo de lesión que sufriste. Si el profesional asignado no tiene la especialidad necesaria, podés pedir que te atienda un médico especializado.</p>
<p>📌 ¿Qué dice la ley? La Ley 24.557 garantiza las prestaciones médicas necesarias para la recuperación del trabajador accidentado, lo que incluye una atención acorde a la complejidad de la lesión.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Recibir atención de un profesional idóneo para tu lesión.</p>
<p>📌 Solicitar el cambio de médico si la atención no es adecuada.</p>
<p>📌 Reclamar ante la Comisión Médica si la ART no responde.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Presentar el pedido de cambio por escrito.</p>
<p>📌 Guardar estudios, recetas e informes médicos.</p>
<p>📌 Conservar copia de todos los reclamos que hiciste.</p>
<p>📌 Consejo práctico: No aceptes una atención que pueda perjudicar tu recuperación. Si la ART se niega a darte un especialista, buscá asesoramiento para hacer valer tu derecho.</p>
<p>📌 ¿La ART me cubre si me lastimé en un viaje de trabajo?</p>
<p>📌 Respuesta corta</p>
<p>Sí. Si el accidente ocurrió durante un viaje por motivos laborales, la ART tiene que cubrirte.</p>
<p>📌 Respuesta completa</p>
<p>Los accidentes durante un viaje de trabajo también se consideran accidentes laborales, siempre que exista relación con las tareas que te encomendó tu empleador.</p>
<p>📌 ¿Qué dice la ley? El art. 6 de la Ley 24.557 considera accidente de trabajo al ocurrido con motivo o en ocasión del trabajo, sin importar el lugar donde suceda.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Atención médica completa.</p>
<p>📌 Rehabilitación y medicamentos.</p>
<p>📌 Prestaciones económicas, si corresponde.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Informar el accidente de inmediato.</p>
<p>📌 Guardar pasajes, reservas o comprobantes del viaje.</p>
<p>📌 Conservar certificados médicos y toda la documentación.</p>
<p>📌 Consejo práctico: Si el viaje fue organizado o autorizado por tu empleador, reuní toda la documentación posible para demostrar que estabas cumpliendo tareas laborales.</p>
<p>📌 ¿Qué es la protección al trabajador accidentado?</p>
<p>📌 Respuesta corta</p>
<p>Es el conjunto de derechos que te protege para que no seas perjudicado por haber sufrido un accidente laboral.</p>
<p>📌 Respuesta completa</p>
<p>La legislación laboral protege a quienes sufren accidentes o enfermedades laborales. Haberte accidentado no habilita a tu empleador a discriminarte, reducirte el salario o tomar represalias por haber ejercido tus derechos.</p>
<p>📌 ¿Qué dice la ley? La Ley de Riesgos del Trabajo y la Ley de Contrato de Trabajo protegen al trabajador durante el proceso de recuperación y frente a actos discriminatorios, con base en los principios que reafirmó la Corte Suprema en el fallo &quot;Aquino&quot; (CSJN, 2004).</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Seguir recibiendo las prestaciones de la ART.</p>
<p>📌 No sufrir represalias por haber denunciado un accidente.</p>
<p>📌 Reclamar si hubo un despido o un trato discriminatorio.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Guardar todas las comunicaciones con el empleador.</p>
<p>📌 Conservar certificados médicos y documentación del accidente.</p>
<p>📌 Buscar asesoramiento si sufrís sanciones o un despido.</p>
<p>📌 Consejo práctico: Si después del accidente sufrís un cambio injustificado en tus condiciones laborales, o un despido, consultá cuanto antes con un abogado para evaluar las acciones legales que corresponden.</p>
<p>📌 ¿Cuánto tiempo tengo para reclamar contra la ART?</p>
<p>📌 Respuesta corta</p>
<p>En general, el plazo es de 2 años, aunque puede suspenderse en determinadas situaciones.</p>
<p>📌 Respuesta completa</p>
<p>Si sufriste un accidente laboral o una enfermedad profesional, no dejes pasar el tiempo para iniciar tu reclamo. Las acciones prescriben a los 2 años, aunque ese plazo puede suspenderse mientras la ART siga brindándote prestaciones o tratamiento.</p>
<p>📌 ¿Qué dice la ley? El art. 44 de la Ley 24.557 fija en 2 años el plazo de prescripción para los reclamos derivados de accidentes y enfermedades laborales.</p>
<p>📌 Es importante saber que:</p>
<p>📌 El plazo suele empezar desde el accidente o desde que conocés la enfermedad.</p>
<p>📌 Puede suspenderse mientras recibís prestaciones de la ART.</p>
<p>📌 Si dejás vencer el plazo, podés perder el derecho a reclamar.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Guardar toda la documentación médica.</p>
<p>📌 Conservar constancias de denuncias y tratamientos.</p>
<p>📌 Consultar con un abogado antes de que venza el plazo.</p>
<p>📌 Consejo práctico: No esperes al último momento. Cuanto antes analices tu caso, más fácil va a ser reunir la prueba necesaria y proteger tu reclamo.</p>
<p>📌 ¿Cómo se calcula la indemnización de la ART?</p>
<p>📌 Respuesta corta</p>
<p>La indemnización se calcula según el porcentaje de incapacidad, tu ingreso base y otros factores previstos por la ley.</p>
<p>📌 Respuesta completa</p>
<p>Cuando te queda una incapacidad permanente, la ART tiene que calcular la indemnización aplicando la fórmula de la Ley de Riesgos del Trabajo, tomando en cuenta el porcentaje de incapacidad que determina el Baremo 2026, tu ingreso base y otros factores legales, como tu edad.</p>
<p>📌 ¿Qué dice la ley? Los arts. 13 a 16 de la Ley 24.557 regulan las prestaciones económicas derivadas de las incapacidades laborales, y la Resolución SRT N° 15/2026 fija los pisos mínimos vigentes de esas prestaciones.</p>
<p>📌 Para calcular la indemnización se considera:</p>
<p>📌 El porcentaje de incapacidad.</p>
<p>📌 Tu ingreso base.</p>
<p>📌 Tu edad al momento del accidente.</p>
<p>📌 La normativa vigente aplicable.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Solicitar copia del dictamen médico.</p>
<p>📌 Verificar el porcentaje de incapacidad asignado.</p>
<p>📌 Revisar que el ingreso base utilizado sea correcto.</p>
<p>📌 Consultar si tenés dudas sobre el cálculo.</p>
<p>📌 Consejo práctico: Si considerás que el porcentaje de incapacidad o el monto de la indemnización están mal calculados, podés impugnarlos y pedir una revisión ante la Comisión Médica.</p>
<p>📌 ¿Qué pasa si la ART me paga con demora?</p>
<p>📌 Respuesta corta</p>
<p>Podés reclamar el pago y, según el caso, también los intereses por la demora.</p>
<p>📌 Respuesta completa</p>
<p>Si la ART demora el pago del subsidio o de la indemnización, tenés derecho a exigir que cumpla con sus obligaciones y a reclamar las diferencias que correspondan, incluidos los intereses.</p>
<p>📌 ¿Qué dice la ley? La Ley 24.557 obliga a la ART a brindar en tiempo y forma las prestaciones médicas y económicas previstas.</p>
<p>📌 Tus derechos incluyen:</p>
<p>📌 Cobrar las prestaciones sin demoras injustificadas.</p>
<p>📌 Reclamar intereses cuando corresponda.</p>
<p>📌 Presentar un reclamo ante la Comisión Médica o por la vía judicial.</p>
<p>📌 Qué conviene hacer:</p>
<p>📌 Reclamar por escrito a la ART.</p>
<p>📌 Guardar comprobantes de pagos y comunicaciones.</p>
<p>📌 Registrar las fechas de cada incumplimiento.</p>
<p>📌 Consejo práctico: No aceptes las demoras prolongadas como algo normal. Si la ART incumple sus obligaciones, buscá asesoramiento para reclamar lo que te corresponde, con los intereses incluidos.</p>
<p>PREGUNTA: ¿Cómo calculan la indemnización de la ART?</p>
<p>RESPUESTA_CORTA: El monto depende de tu edad, tu salario y el porcentaje de incapacidad que te dieron. No hay un número fijo: cada caso es distinto.</p>
<p>Entendemos que quieras saber cuánto te corresponde, es lo primero que preguntamos todos. Pero la verdad es que no existe un monto &quot;estándar&quot;: la ley (art. 14, Ley 24.557) establece un método que combina varios factores personales tuyos, así que el resultado cambia caso por caso.</p>
<p>📌 Tu edad: cuanto más joven seas al momento del accidente, mayor suele ser la indemnización, porque la ley compensa más años de capacidad laboral perdida.</p>
<p>📌 Tu ingreso base: se toma tu salario promedio registrado, según el índice RIPTE.</p>
<p>📌 Tu porcentaje de incapacidad: lo fija el baremo de incapacidades vigente (Decreto 549/2025) según tu lesión específica.</p>
<p>📌 Piso mínimo legal: existe un piso que la SRT actualiza periódicamente y que la ART nunca puede pagarte por debajo.</p>
<p>📌 Adicional del 20%: si el accidente ocurrió en tu lugar de trabajo o mientras estabas a disposición del empleador, corresponde un 20% adicional sobre el monto (no aplica a los in itinere).</p>
<p>Como ves, no hay dos casos iguales. Usá nuestra calculadora de indemnizaciones para tener una estimación según tu situación puntual, o escribinos y lo vemos juntos.</p>
<p>PREGUNTA: ¿Qué es el capital de pérdida de capacidad productiva?</p>
<p>RESPUESTA_CORTA: Es el monto principal que te paga la ART por la disminución permanente de tu capacidad para generar ingresos.</p>
<p>El capital por pérdida de capacidad productiva es la indemnización central del sistema: es lo que te paga la ART cuando te queda una incapacidad permanente por un accidente o enfermedad laboral. Es la compensación por esa pérdida definitiva de tu capacidad de trabajar y generar ingresos.</p>
<p>📌 Cómo se determina: la ley combina tu edad, tu ingreso base y tu porcentaje de incapacidad (art. 14, Ley 24.557). No hay un monto fijo: varía en cada caso.</p>
<p>📌 Piso mínimo: existe un piso legal que la SRT actualiza y que la ART nunca puede pagar por debajo, según el Decreto 549/2025.</p>
<p>📌 Adicional del 20%: corresponde si el accidente fue en tu lugar de trabajo o estando a disposición del empleador.</p>
<p>📌 Revisión: si tu estado de salud cambia, podés pedir una revisión del porcentaje ante la Comisión Médica.</p>
<p>Para tener una estimación de lo que te correspondería, usá nuestra calculadora. Y si querés confirmar que la ART te está pagando lo justo, escribinos: lo revisamos con vos.</p>
<p>PREGUNTA: ¿Qué es la carga familiar en la indemnización?</p>
<p>RESPUESTA_CORTA: La carga familiar no existe como concepto en la indemnización por ART. Esa idea viene de otros regímenes (despido, jubilación), no de la Ley de Riesgos del Trabajo.</p>
<p>Es una confusión frecuente, así que vale la pena aclararla: en la indemnización por incapacidad permanente de la ART no se suma nada extra por tener hijos menores, cónyuge u otras cargas de familia.</p>
<p>📌 De dónde viene la confusión: el concepto de carga familiar existe en la indemnización por despido (art. 183, LCT) y en el régimen previsional, pero no en la Ley de Riesgos del Trabajo.</p>
<p>📌 Cómo se calcula realmente: tu indemnización depende de tu edad, tu ingreso base y tu porcentaje de incapacidad, sin adicionales por composición familiar.</p>
<p>📌 Excepción  fallecimiento: si el trabajador fallece a causa del accidente, ahí sí existe un reparto entre los derechohabientes (cónyuge, hijos) que establece la LRT. Es un caso distinto al de la incapacidad permanente.</p>
<p>Si tenés dudas sobre qué te corresponde a vos puntualmente, consultá con nuestro equipo o usá la calculadora para una primera estimación.</p>
<p>PREGUNTA: ¿Cuánto me corresponde por una incapacidad del 10%?</p>
<p>RESPUESTA_CORTA: Depende de tu edad y tu salario. No hay un monto fijo para el 10%: dos personas con la misma incapacidad pueden cobrar montos distintos.</p>
<p>Un 10% de incapacidad suena bajo, pero no subestimes el monto: puede ser significativo según tu salario y tu edad. Lo importante es entender que no hay una cifra &quot;tipo&quot; para el 10%, porque la ley calcula el monto combinando varios factores personales.</p>
<p>📌 Qué influye en el monto: tu edad al momento del accidente, tu ingreso base (salario promedio registrado) y el 10% de incapacidad que te determinaron.</p>
<p>📌 Piso mínimo: si el resultado calculado da por debajo del piso mínimo que fija la SRT, la ART tiene que pagarte ese piso.</p>
<p>📌 ¿No estás de acuerdo con el 10%? Podés impugnar el porcentaje ante la Comisión Médica si tenés razones médicas para reclamar uno mayor.</p>
<p>📌 Revisión futura: si tu estado empeora con el tiempo, podés pedir un aumento del porcentaje.</p>
<p>No aceptes ningún monto sin verificarlo antes. Usá nuestra calculadora para tener una estimación real según tu caso, o escribinos y te ayudamos a revisar la cuenta de la ART.</p>
<p>PREGUNTA: ¿Me corresponde indemnización si tengo una hernia discal por el laburo?</p>
<p>RESPUESTA_CORTA: Sí, si la hernia discal es consecuencia de tu actividad laboral, te corresponde una indemnización.</p>
<p>Si sufriste una hernia discal por tu actividad laboral, te corresponde una indemnización. Es una de las lesiones de columna más comunes en accidentes y enfermedades laborales, sobre todo en trabajos con esfuerzo físico.</p>
<p>📌 Porcentaje según baremo: el Decreto 549/2025 asigna un porcentaje específico a la hernia discal operada. Consultá la tabla de lesiones de columna en nuestro sitio para ver el que corresponde a tu caso.</p>
<p>📄 Documentación: guardá toda la documentación médica: resonancias, informes de cirugía, certificados de kinesiología.</p>
<p>📌 Si la ART no la reconoce: si no te reconocen la hernia como profesional, podés reclamar ante la Comisión Médica.</p>
<p>La hernia discal puede considerarse enfermedad profesional si está relacionada con tu actividad laboral. Escribinos y evaluamos tu caso.</p>
<p>PREGUNTA: ¿Qué documentos necesito para reclamar la indemnización?</p>
<p>RESPUESTA_CORTA: Necesitás tu DNI, parte de accidente, constancias médicas, recibos de sueldo, y toda la documentación que respalde tu reclamo.</p>
<p>Reunir bien la documentación es clave para probar la relación entre tu accidente y tu trabajo.</p>
<p>📌 Documentos personales: DNI vigente, CUIL, composición familiar si corresponde.</p>
<p>📌 Parte de accidente: formulario de denuncia del siniestro ante la ART.</p>
<p>📌 Documentación médica: historia clínica completa, certificados de internación, informes de estudios y tratamientos.</p>
<p>📌 Documentación laboral: recibos de sueldo de los últimos 12 meses, contrato de trabajo, legajo.</p>
<p>📌 Otras pruebas: testimonios de compañeros, fotos del lugar, mensajes, cualquier otra prueba.</p>
<p>📌 Si fue in itinere: demostrá tu recorrido habitual con testimonios, filmaciones u otra prueba.</p>
<p>Guardá siempre los originales y sacá copias de todo. Vamos a necesitar estos documentos para armar tu reclamo.</p>
<p>PREGUNTA: ¿Qué es la tabla de factores de la LRT?</p>
<p>RESPUESTA_CORTA: Es el baremo: asigna un porcentaje de incapacidad a cada lesión y se usa para calcular la indemnización.</p>
<p>El baremo de incapacidades es el documento oficial que fija un porcentaje para cada tipo de lesión. El vigente es el Decreto 549/2025, en vigor desde febrero de 2026.</p>
<p>📌 Estructura: cada lesión tiene un porcentaje asignado según el baremo.</p>
<p>📌 Piso mínimo: existe un piso mínimo que la SRT actualiza periódicamente, y que la ART nunca puede pagarte por debajo.</p>
<p>📌 Impugnación: si no estás de acuerdo con el porcentaje que te asignaron, podés apelar ante la Comisión Médica dentro de los 5 días hábiles.</p>
<p>📌 Adicional del 20%: corresponde si el accidente fue en tu lugar de trabajo o a disposición del empleador.</p>
<p>Consultá la tabla de lesiones en nuestro sitio para ver los porcentajes del nuevo baremo, o usá la calculadora para una primera estimación de tu caso.</p>
<p>PREGUNTA: ¿Puedo reclamar una indemnización mayor a la que me dio la ART?</p>
<p>RESPUESTA_CORTA: Sí, podés reclamar ante la Comisión Médica o la justicia del trabajo si la ART te asignó un porcentaje injusto.</p>
<p>Sí, si considerás que la ART te asignó un porcentaje de incapacidad injusto, tenés dos instancias para reclamar.</p>
<p>📌 Primer paso: apelar ante la Comisión Médica Jurisdiccional dentro de los 5 días hábiles.</p>
<p>📌 Segundo paso: si la Comisión Médica no te da una solución, iniciar un juicio laboral ante la Justicia Federal.</p>
<p>📌 Rubros adicionales: en juicio podés sumar daño moral, daños estéticos, lucro cesante y otros gastos.</p>
<p>⏳ Plazo: tenés 2 años para reclamar (art. 44, LRT). No dejes pasar ese plazo.</p>
<p>📌 Carga de la prueba: la ART debe probar que tu incapacidad es menor a la que reclamás.</p>
<p>No aceptes un porcentaje injusto. Podemos revisar tus informes médicos y ver si respaldan un reclamo mayor.</p>
<p>PREGUNTA: ¿Qué es el régimen de accidentes de trabajo?</p>
<p>RESPUESTA_CORTA: Es el conjunto de leyes que regulan la protección de los trabajadores ante accidentes laborales.</p>
<p>Es el marco legal completo que regula la protección de los trabajadores ante accidentes de trabajo y enfermedades profesionales.</p>
<p>📌 Ley principal: Ley de Riesgos del Trabajo (LRT) N.º 24.557 y sus modificatorias (entre ellas, la Ley 26.773).</p>
<p>📌 Decreto reglamentario: Decreto 170/96 y modificaciones posteriores.</p>
<p>📌 Baremo vigente: Decreto 549/2025.</p>
<p>📌 Obligaciones: de los empleadores (contratar ART, denunciar siniestros), de las ART (asistencia médica, pago de indemnización) y de los trabajadores.</p>
<p>📌 Prestaciones: médicas (tratamiento) y económicas (subsidio, indemnización).</p>
<p>📌 Conflictos: se resuelven ante la Comisión Médica, la Comisión Médica Central y la Justicia Federal.</p>
<p>Conocer el régimen te ayuda a entender mejor tus derechos como trabajador accidentado.</p>
<p>PREGUNTA: ¿Qué es la indemnización por daños y perjuicios?</p>
<p>RESPUESTA_CORTA: Es una compensación que reclamás ante la justicia, más allá del baremo, por todos los perjuicios que te causó el accidente.</p>
<p>Va más allá de la tabla de baremo y te permite reclamar una compensación más completa por lo que te causó el accidente.</p>
<p>📌 Rubros incluidos: daño moral, daños estéticos, lucro cesante, gastos varios y cualquier otro perjuicio demostrable.</p>
<p>📌 Requisito: iniciar una acción judicial ante la justicia del trabajo o civil, según el fundamento del reclamo.</p>
<p>📌 Prueba: informes médicos, testimonios, fotos que acrediten los daños sufridos.</p>
<p>📌 Cálculo: no hay una fórmula fija; el juez lo evalúa caso por caso según la gravedad.</p>
<p>⏳ Plazo: el plazo para reclamar puede variar según el fundamento legal de tu caso (LRT o responsabilidad civil), así que conviene confirmarlo con un abogado apenas tengas los diagnósticos definitivos, para no perder el derecho.</p>
<p>Consultá con nuestro equipo qué rubros te convendría reclamar y cómo armamos la estrategia.</p>
<p>PREGUNTA: ¿Cómo afecta mi salario al monto de la indemnización?</p>
<p>RESPUESTA_CORTA: Tu salario es uno de los factores clave: a mayor ingreso registrado, mayor suele ser la indemnización.</p>
<p>Tu ingreso base (el promedio de tu salario registrado, según el índice RIPTE) es uno de los factores más importantes del cálculo, junto con tu edad y tu porcentaje de incapacidad.</p>
<p>📌 Definición: tu salario promedio registrado de los últimos 12 meses.</p>
<p>📌 Conceptos incluidos: sueldo básico, antigüedad, presentismo, horas extra, comisiones, bonos.</p>
<p>📌 Comisiones variables: si varían mes a mes, se toma un promedio de los últimos 12 meses.</p>
<p>📌 Trabajo no registrado: si estabas en negro, el ingreso base se calcula con los ingresos reales que percibías, no con lo que figuraba en blanco.</p>
<p>📌 Por qué importa: un salario mal calculado puede significar una diferencia enorme en el monto final.</p>
<p>Revisá tus recibos de sueldo y verificá que la ART esté usando el salario correcto. Si tenés dudas, lo revisamos juntos.</p>
<p>PREGUNTA: ¿Qué es la incapacidad laboral temporaria?</p>
<p>RESPUESTA_CORTA: Es la incapacidad temporal que te impide trabajar mientras te recuperás, y la ART te paga un subsidio mientras dura.</p>
<p>La incapacidad laboral temporaria (ILT) es la que te impide trabajar mientras te recuperás del accidente. La ART tiene que pagarte un subsidio equivalente a tu ingreso base desde el primer día hasta el Alta Médica.</p>
<p>📌 Duración: desde el primer día de incapacidad hasta el Alta Médica.</p>
<p>📌 Piso mínimo: no puede ser menor al salario mínimo, vital y móvil vigente.</p>
<p>📌 Pago: la ART debe pagarte de manera regular, generalmente quincenal.</p>
<p>📌 Incumplimiento: si no te pagan o te pagan de menos, reclamá ante la Comisión Médica.</p>
<p>📌 Alta: si te dan el alta y seguís incapacitado, podés impugnarla dentro de los 5 días hábiles.</p>
<p>El subsidio por ILT es un derecho irrenunciable. Si no te lo están pagando bien, escribinos.</p>
<p>PREGUNTA: ¿Qué hago si la ART me ofrece una indemnización poco?</p>
<p>RESPUESTA_CORTA: No la aceptes. Podés reclamar ante la Comisión Médica o iniciar un juicio laboral.</p>
<p>Si te ofrecen una indemnización que consideras injusta, no la aceptes sin más. Tenés mecanismos legales para reclamar un monto mayor.</p>
<p>📌 No firmes: no firmes ningún acuerdo o finiquito sin consultarlo antes con un abogado.</p>
<p>📌 Primer paso: apelá ante la Comisión Médica Jurisdiccional dentro de los 5 días hábiles.</p>
<p>📌 Segundo paso: si no hay solución, iniciá un juicio laboral.</p>
<p>📌 Rubros adicionales: en juicio podés sumar daño moral, daños estéticos, lucro cesante.</p>
<p>📄 Documentación: presentá todos tus informes médicos.</p>
<p>No aceptes nada que no te satisfaga. Muchas veces la primera oferta es más baja de lo que realmente corresponde. Consultanos antes de firmar nada.</p>
<p>PREGUNTA: ¿Qué es la incapacidad permanente total?</p>
<p>RESPUESTA_CORTA: Es cuando tu lesión te impide realizar cualquier tipo de trabajo de manera permanente.</p>
<p>Es la más grave del sistema: tu lesión te impide realizar cualquier actividad laboral de forma definitiva.</p>
<p>📌 Ejemplos: pérdida total de ambas manos, paraplejia, cuadriplejia, ceguera completa.</p>
<p>📌 Indemnización: se calcula considerando el 100% de incapacidad, según tu edad y tu ingreso base.</p>
<p>📌 Adicional del 20%: si el accidente fue en tu lugar de trabajo o a disposición del empleador, corresponde este adicional.</p>
<p>📌 Asistencia médica: la ART debe darte asistencia médica, quirúrgica y farmacéutica de por vida.</p>
<p>📌 Revisión: si tu estado empeora, podés pedir una revisión del porcentaje.</p>
<p>En casos de incapacidad total, contar con un abogado especializado es fundamental. Escribinos y te acompañamos.</p>
<p>PREGUNTA: ¿Me corresponde indemnización si me operaron y la cirugía salió mal?</p>
<p>RESPUESTA_CORTA: Sí, si quedaste con secuelas, te corresponde una indemnización por la incapacidad que te dejó.</p>
<p>Si la cirugía que te hizo la ART salió mal y quedaste con secuelas, la ART tiene que cubrir la incapacidad resultante: limitaciones funcionales, dolor crónico y cualquier otra secuela.</p>
<p>✅ Cobertura: la ART es responsable de las consecuencias del tratamiento médico que te brinda.</p>
<p>📌 Incapacidad: se evalúa la incapacidad resultante de la mala praxis y se calcula la indemnización correspondiente.</p>
<p>📌 Mala praxis: si hubo mala praxis médica, también podés reclamar al médico o al centro de salud, por una vía distinta.</p>
<p>📄 Documentación: guardá informes pre y post quirúrgicos, estudios.</p>
<p>📢 Reclamo: presentalo ante la Comisión Médica y, si hace falta, iniciá un juicio laboral.</p>
<p>La ART no puede desligarse de su responsabilidad diciendo que la cirugía la hizo un profesional externo. Consultanos tu caso.</p>
<p>PREGUNTA: ¿Qué es la compensación por riesgo de trabajo?</p>
<p>RESPUESTA_CORTA: Es la indemnización que recibís cuando quedás con una incapacidad permanente por un accidente de trabajo.</p>
<p>Es la indemnización principal por incapacidad permanente: compensa la pérdida definitiva de tu capacidad para trabajar.</p>
<p>📌 Cómo se calcula: en base a tu edad, tu ingreso base y tu porcentaje de incapacidad determinado por el baremo (Decreto 549/2025).</p>
<p>📌 Piso mínimo: existe un piso legal actualizado periódicamente por la SRT.</p>
<p>📌 Adicional del 20%: si el accidente ocurrió en tu lugar de trabajo o a disposición del empleador.</p>
<p>📌 Diferencia con otros rubros: es distinta del daño moral, los daños estéticos y el lucro cesante, que se reclaman aparte, en juicio.</p>
<p>📌 Plazo de pago: 15 días corridos desde la determinación definitiva de la incapacidad.</p>
<p>Es la base de tu indemnización; los demás rubros se suman si vas a juicio. Usá la calculadora para una estimación o escribinos.</p>
<p>PREGUNTA: ¿Qué es la indemnización por accidente in itinere?</p>
<p>RESPUESTA_CORTA: Tenés derecho a las mismas prestaciones médicas y a la misma indemnización por incapacidad que en un accidente en el trabajo, aunque hay un adicional que no aplica en este caso.</p>
<p>El accidente in itinere (yendo o volviendo del trabajo) te da derecho a las mismas prestaciones médicas y a la misma indemnización por incapacidad permanente que un accidente ocurrido en el lugar de trabajo. Hay, sí, una diferencia importante que conviene conocer.</p>
<p>📌 Igualdad de trato: mismas prestaciones médicas, mismo subsidio, misma indemnización por incapacidad permanente, calculada según tu edad, ingreso base y porcentaje de incapacidad.</p>
<p>📌 La excepción: el adicional del 20% no se aplica a los accidentes in itinere, porque la ley lo reserva para los daños ocurridos en el lugar de trabajo o mientras estás a disposición del empleador.</p>
<p>📌 Trayecto habitual: el accidente tiene que haber ocurrido en tu recorrido habitual entre tu casa y el trabajo.</p>
<p>📌 Desvíos: si te desviaste por motivos personales, puede complicar el reclamo.</p>
<p>📌 Prueba: testimonios, filmaciones, registros de GPS que demuestren que fue in itinere.</p>
<p>Denunciá el accidente ante la ART lo antes posible y guardá toda la documentación de tu recorrido habitual.</p>
<p>PREGUNTA: ¿Qué es la indemnización por gran invalidez?</p>
<p>RESPUESTA_CORTA: Es la indemnización más elevada, cuando la incapacidad te impide trabajar y necesitás asistencia permanente.</p>
<p>Es la más alta del sistema. Se da cuando tu incapacidad te impide trabajar y necesitás ayuda permanente para las tareas básicas de la vida diaria.</p>
<p>📌 Indemnización: se calcula considerando el 100% de incapacidad, según tu edad y tu ingreso base.</p>
<p>📌 Adicional del 20%: corresponde si el accidente fue en tu lugar de trabajo o a disposición del empleador.</p>
<p>📌 Asistencia médica: de por vida, a cargo de la ART.</p>
<p>📌 Asistencia personal: además de la indemnización económica, podés reclamar los gastos de asistencia permanente.</p>
<p>📄 Documentación: informes médicos detallados que demuestren la necesidad de ayuda permanente.</p>
<p>En casos de gran invalidez, tener un abogado especializado es fundamental. Contactanos y te acompañamos en todo el proceso.</p>
<p>PREGUNTA: ¿Qué es la reglamentación de la LRT?</p>
<p>RESPUESTA_CORTA: Son las normas que explican cómo se aplican las disposiciones de la Ley de Riesgos del Trabajo.</p>
<p>Incluye todas las normas que detallan cómo se aplica la ley, con la misma fuerza que ella.</p>
<p>📌 Decreto 170/96: decreto reglamentario de la LRT.</p>
<p>📌 Resoluciones de la SRT: la Superintendencia dicta resoluciones que regulan aspectos específicos.</p>
<p>📌 Baremo vigente: Decreto 549/2025, que fija los porcentajes de incapacidad.</p>
<p>📌 Obligaciones: de empleadores, ART y trabajadores.</p>
<p>📌 Procedimientos: para denunciar accidentes, apelar calificaciones y resolver conflictos.</p>
<p>Conocer la reglamentación te ayuda a entender mejor tus derechos. Mirá nuestra sección de artículos para información actualizada.</p>
<p>PREGUNTA: ¿Qué pasa si acepto la indemnización y después quiero reclamar más?</p>
<p>RESPUESTA_CORTA: Si firmaste un acuerdo, puede ser difícil reclamar más. Por eso, antes de firmar, hacé que alguien lo revise.</p>
<p>Si aceptaste la indemnización y firmaste un acuerdo o finiquito, después puede ser muy difícil reclamar más. Por eso es clave evaluar la oferta antes de firmar.</p>
<p>📌 Acuerdo homologado: si un juez lo homologó, tiene fuerza de sentencia.</p>
<p>📌 Finiquito ante la ART: puede limitar tu derecho a reclamar después.</p>
<p>📌 Antes de firmar: consultá con un abogado para verificar si la oferta es justa.</p>
<p>📌 Si todavía no firmaste: apelá ante la Comisión Médica o iniciá un juicio laboral.</p>
<p>📌 Excepciones: en algunos casos la jurisprudencia admitió reclamos posteriores si se probó engaño o dolo.</p>
<p>No firmes nada sin asesoramiento previo. Escribinos antes de aceptar cualquier oferta.</p>
<p>Ahora la Tanda 3 (026 a 050), cierre del documento:</p>
<p>PREGUNTA: ¿Qué es la prescripción de la indemnización?</p>
<p>RESPUESTA_CORTA: Es el plazo máximo para reclamar: 2 años, según cuándo se cuente desde tu situación particular.</p>
<p>Es el plazo legal para ejercer tu derecho a reclamar. Si lo dejás vencer sin iniciar acciones, perdés el derecho.</p>
<p>📌 Plazo general: 2 años, contados desde la fecha en que la prestación debió pagarse, o desde el cese de la relación laboral (art. 44, LRT).</p>
<p>📌 Enfermedad profesional: el plazo suele contarse desde el diagnóstico o desde que tomaste conocimiento de la relación entre la enfermedad y tu trabajo.</p>
<p>📌 Alta médica: si te dieron el alta y quedaste con incapacidad, el plazo corre desde la determinación definitiva.</p>
<p>📌 Recomendación: no dejes pasar el tiempo. Si estás cerca del vencimiento, iniciá acciones cuanto antes.</p>
<p>Consultanos lo antes posible para confirmar si tu caso está dentro del plazo legal  acá no conviene esperar.</p>
<p>PREGUNTA: ¿Qué es la remuneración imponible para el cálculo?</p>
<p>RESPUESTA_CORTA: Es el salario que toma la ART para calcular tu indemnización, incluyendo todos los conceptos remunerativos.</p>
<p>Tiene que incluir todos los conceptos remunerativos, no solo el sueldo básico.</p>
<p>📌 Conceptos incluidos: sueldo básico, antigüedad, presentismo, horas extra, comisiones, bonos.</p>
<p>📌 Comisiones variables: se toma un promedio de los últimos 12 meses.</p>
<p>📌 No remunerativos: conceptos como viáticos no remunerativos no forman parte del cálculo.</p>
<p>📌 Trabajo no registrado: si estabas en negro, se calcula con los ingresos reales que percibías.</p>
<p>📌 Por qué importa: un salario mal calculado puede representar una diferencia enorme en el monto final.</p>
<p>Revisá tus recibos y verificá que la ART esté usando tu salario real. Podemos chequearlo juntos si tenés dudas.</p>
<p>PREGUNTA: ¿Qué es la indemnización por muerte del trabajador?</p>
<p>RESPUESTA_CORTA: Es la compensación que reciben los familiares del trabajador fallecido por un accidente o enfermedad laboral.</p>
<p>Si el trabajador fallece por causas laborales, sus derechohabientes reciben una indemnización conforme a la LRT.</p>
<p>📌 Derechohabientes: cónyuge o conviviente, hijos menores de 18 años (o hasta 25 si estudian), y otros familiares dependientes según lo previsto por la ley. El reparto exacto entre ellos depende de cuántos derechohabientes haya y de la situación de cada uno.</p>
<p>📌 Gastos de sepelio: también los cubre la ART.</p>
<p>📌 Asistencia médica: la ART debe asistir a los derechohabientes cuando corresponda.</p>
<p>⏳ Plazo: 2 años desde el fallecimiento para reclamar.</p>
<p>📌 Dónde se tramita: ante la Justicia Federal.</p>
<p>Es un momento muy difícil para la familia, y por eso conviene tener acompañamiento legal desde el primer momento. Estamos para ayudarlos.</p>
<p>PREGUNTA: ¿Qué es el daño estético en la indemnización?</p>
<p>RESPUESTA_CORTA: Son las marcas visibles, como cicatrices o deformidades, que podés reclamar como parte de la indemnización.</p>
<p>Incluye lesiones visibles como cicatrices, deformidades, quemaduras o pérdida de miembros que afectan tu apariencia física.</p>
<p>📌 Ejemplos: cicatrices en cara, manos o zonas visibles; quemaduras; deformidades.</p>
<p>📌 Cálculo: no hay una fórmula fija; se evalúa según la ubicación, el tamaño y la visibilidad.</p>
<p>📌 Requisito: fotos y certificados médicos que prueben el daño y su impacto en tu vida.</p>
<p>📌 Dónde se reclama: ante la justicia del trabajo, no ante la Comisión Médica.</p>
<p>📌 Es independiente de la indemnización por incapacidad y del daño moral.</p>
<p>Fotografiá tus lesiones visibles periódicamente para documentar cómo evolucionan. Es una prueba clave si después vas a juicio.</p>
<p>PREGUNTA: ¿Puedo reclamar intereses si la ART tarda en pagarme?</p>
<p>RESPUESTA_CORTA: Sí, si la ART se atrasa, te corresponden intereses sobre lo adeudado.</p>
<p>Si la ART se retrasa en pagarte la indemnización o el subsidio, te corresponden intereses por la demora.</p>
<p>📌 Desde cuándo corren: desde la fecha en que la ART debió pagar (15 días corridos desde la determinación de la incapacidad) hasta el pago efectivo.</p>
<p>📌 Tasa: suele aplicarse la tasa activa del Banco Nación, aunque puede variar según el criterio del juzgado.</p>
<p>📌 Subsidio (ILT): si también se atrasan en pagarlo, corresponden intereses.</p>
<p>📢 Reclamo: ante la Comisión Médica o la justicia, según el caso.</p>
<p>No dejes de reclamar los intereses: son un derecho tuyo. Si la ART te está pagando tarde, avisanos.</p>
<p>PREGUNTA: ¿Qué es la indemnización por incapacidad parcial?</p>
<p>RESPUESTA_CORTA: Es la que te corresponde cuando tu incapacidad es permanente pero no total.</p>
<p>Te compensa cuando tu lesión disminuye tu capacidad de trabajo sin llegar a la totalidad.</p>
<p>📌 Porcentaje: lo fija el baremo de incapacidades (Decreto 549/2025) según tu lesión específica.</p>
<p>📌 Piso mínimo: existe uno que la SRT actualiza y que la ART no puede pagar por debajo.</p>
<p>📌 Adicional del 20%: si el accidente fue en tu lugar de trabajo o a disposición del empleador.</p>
<p>📌 Impugnación: si no estás de acuerdo con el porcentaje, apelá ante la Comisión Médica dentro de los 5 días hábiles.</p>
<p>📌 Revisión: si tu estado empeora, podés pedir un aumento del porcentaje.</p>
<p>Es la más común en los accidentes laborales. Usá la calculadora o consultanos para ver qué te correspondería.</p>
<p>PREGUNTA: ¿Qué pasa si mi accidente fue por culpa del empleador?</p>
<p>RESPUESTA_CORTA: Si fue por negligencia del empleador, podés reclamarle una indemnización adicional por daños y perjuicios, aparte de la de la ART.</p>
<p>Cuando el accidente fue causado por negligencia del empleador, podés reclamarle una indemnización adicional, independiente de la que te paga la ART.</p>
<p>📌 Causas frecuentes: falta de elementos de protección personal, maquinaria sin resguardos, falta de capacitación.</p>
<p>📌 Rubros reclamables: daño moral, daños estéticos, lucro cesante, entre otros.</p>
<p>⚖️ Responsabilidad: según el fundamento del reclamo, la responsabilidad puede ser objetiva (por el riesgo de las cosas o la actividad) o requerir demostrar la culpa del empleador. Conviene que un abogado evalúe cuál aplica a tu caso.</p>
<p>⏳ Plazo: el término para reclamar daños y perjuicios contra el empleador puede variar según el fundamento legal utilizado, así que es importante confirmarlo cuanto antes con asesoramiento profesional.</p>
<p>📌 La ART también puede ser responsable solidaria si conocía los riesgos y no actuó.</p>
<p>Consultá con un abogado laboralista para evaluar la responsabilidad del empleador en tu caso.</p>
<p>PREGUNTA: ¿Qué es el gasto de asistencia médica en la indemnización?</p>
<p>RESPUESTA_CORTA: Son los gastos que la ART debe cubrir por tu tratamiento: consultas, estudios y medicamentos.</p>
<p>Todos los costos médicos que genera el accidente o la enfermedad laboral, y que la ART está obligada a cubrir.</p>
<p>✅ Cobertura: consultas, estudios diagnósticos, cirugías, internaciones, medicamentos, prótesis, rehabilitación y traslados.</p>
<p>📌 Red de prestadores: la ART puede indicarte una red, pero si necesitás un especialista fuera de ella, tiene que autorizártelo.</p>
<p>📌 Tratamiento: debe darte todo lo necesario hasta tu estabilidad médica.</p>
<p>📌 Incumplimiento: si te niegan un tratamiento necesario, reclamá ante la Comisión Médica.</p>
<p>📌 Prótesis: la ART debe proveerlas y renovarlas cuando haga falta.</p>
<p>No aceptes que te nieguen un tratamiento que tu médico considera necesario. Si te está pasando, contanos.</p>
<p>PREGUNTA: ¿Qué es la indemnización por agravación de la lesión?</p>
<p>RESPUESTA_CORTA: Es la compensación que recibís si tu lesión empeora con el tiempo.</p>
<p>Si tu lesión se agrava después de haber sido calificada la incapacidad, podés reclamar una indemnización adicional.</p>
<p>📌 Requisito: demostrar que la lesión empeoró y que ese empeoramiento está relacionado con el accidente original.</p>
<p>📢 Reclamo: ante la Comisión Médica, con documentación médica actualizada.</p>
<p>📌 Nueva evaluación: la Comisión ordenará una nueva pericia.</p>
<p>📌 Indemnización: si se reconoce, se recalcula con el nuevo porcentaje.</p>
<p>⏳ Plazo: no hay un límite de tiempo fijo para pedir esta revisión.</p>
<p>Si notás que tu lesión empeoró, no esperes: presentá el reclamo con toda la documentación médica.</p>
<p>PREGUNTA: ¿Qué es la indemnización por muerte en accidente in itinere?</p>
<p>RESPUESTA_CORTA: Si el trabajador muere yendo o volviendo del trabajo, sus familiares reciben la indemnización por fallecimiento, igual que en un accidente en el lugar de trabajo.</p>
<p>Los derechohabientes de un trabajador fallecido en un accidente in itinere reciben la misma indemnización por muerte que si el fallecimiento hubiera sido en el lugar de trabajo.</p>
<p>📌 Derechohabientes: cónyuge o conviviente, hijos menores de 18 (o hasta 25 si estudian) y otros familiares dependientes según la ley. El reparto exacto depende de la situación de cada familia.</p>
<p>📌 Gastos de sepelio: también cubiertos por la ART.</p>
<p>📌 Prueba: hay que demostrar que el fallecimiento ocurrió durante el trayecto habitual.</p>
<p>⏳ Plazo: 2 años desde el fallecimiento para reclamar.</p>
<p>Es fundamental que la familia tenga acompañamiento legal desde el primer momento. Estamos para ayudarlos a gestionar el reclamo.</p>
<p>PREGUNTA: ¿Qué es la indemnización por lesiones permanentes?</p>
<p>RESPUESTA_CORTA: Es la compensación que recibís cuando tu incapacidad ya no va a mejorar.</p>
<p>Te compensa cuando llegás a la estabilidad médica: el momento en que tu estado de salud deja de mejorar o empeorar de forma significativa.</p>
<p>📌 Qué determina el monto: tu porcentaje de incapacidad, tu edad y tu ingreso base.</p>
<p>📌 Piso mínimo: existe uno actualizado periódicamente por la SRT.</p>
<p>📌 Revisión: si tu estado empeora después de la estabilidad, podés pedir una revisión.</p>
<p>📌 Asesoramiento: conviene confirmar con un abogado que la indemnización sea la que corresponde antes de aceptarla.</p>
<p>No aceptes nada sin verificar primero que el porcentaje de incapacidad sea el correcto. Podemos revisarlo con vos.</p>
<p>PREGUNTA: ¿Puedo reclamar daño psicológico en la indemnización?</p>
<p>RESPUESTA_CORTA: Sí, si el accidente te causó daño psicológico, podés reclamar una indemnización por ese concepto.</p>
<p>Si el accidente te generó depresión, ansiedad o estrés postraumático, podés reclamar una indemnización adicional por ese daño.</p>
<p>📌 Tipos frecuentes: depresión reactiva, trastorno de ansiedad, estrés postraumático, fobias.</p>
<p>📌 Requisito: un informe psicológico o psiquiátrico que certifique el daño y su relación con el accidente.</p>
<p>📌 Cálculo: no hay una fórmula fija; se evalúa según la gravedad.</p>
<p>📌 Dónde se reclama: ante la justicia del trabajo, como parte de la indemnización integral.</p>
<p>📌 Tratamiento: la ART debe cubrir el tratamiento psicológico o psiquiátrico.</p>
<p>No minimices el daño psicológico: es un rubro indemnizable y puede representar un monto significativo. Consultanos tu caso.</p>
<p>PREGUNTA: ¿Qué es la indemnización por pérdida de una extremidad?</p>
<p>RESPUESTA_CORTA: Es la compensación que recibís cuando perdés total o parcialmente una extremidad a causa del accidente.</p>
<p>La pérdida total o parcial de una extremidad tiene un porcentaje de incapacidad asignado en el baremo vigente (Decreto 549/2025).</p>
<p>📌 Tabla de lesiones: consultá la de mano, brazo, pierna o pie en nuestro sitio para ver el porcentaje que aplica a tu caso.</p>
<p>📌 Pérdida total vs. parcial: la pérdida total tiene un porcentaje mayor que la parcial.</p>
<p>📌 Prótesis: la ART debe proveerlas y renovarlas cuando sea necesario.</p>
<p>📌 Revisión: si tu estado empeora, podés pedir un aumento del porcentaje.</p>
<p>Consultá la tabla de lesiones en nuestro sitio, o escribinos directamente para revisar tu caso puntual.</p>
<p>PREGUNTA: ¿Qué es la indemnización por pérdida de visión?</p>
<p>RESPUESTA_CORTA: Es la compensación que recibís cuando perdés visión total o parcialmente a causa del accidente.</p>
<p>Si perdés visión total o parcialmente por un accidente de trabajo, te corresponde una indemnización según el baremo vigente (Decreto 549/2025).</p>
<p>📌 Baremo: consultá la tabla de lesiones de vista en nuestro sitio para ver los porcentajes.</p>
<p>📌 Ceguera total: tiene un porcentaje muy alto dentro del baremo.</p>
<p>📌 Pérdida parcial: se evalúa según el porcentaje de visión perdida en cada ojo.</p>
<p>📌 Tratamiento: la ART debe darte el tratamiento oftalmológico necesario.</p>
<p>📢 Reclamo: si no te reconocen la pérdida como profesional, reclamá ante la Comisión Médica.</p>
<p>Es una de las lesiones más graves del sistema. Consultanos para evaluar tu caso.</p>
<p>PREGUNTA: ¿Qué es la indemnización por pérdida de audición?</p>
<p>RESPUESTA_CORTA: Es la compensación que recibís cuando perdés audición total o parcialmente a causa del accidente.</p>
<p>Si perdés audición por un accidente o por tu actividad laboral, te corresponde una indemnización según el baremo vigente.</p>
<p>📌 Causas comunes: exposición prolongada a ruidos intensos en fábricas, obras o ambientes industriales.</p>
<p>📌 Evaluación: se hace mediante una audiometría para determinar el porcentaje de pérdida.</p>
<p>📌 Tratamiento: la ART debe darte tratamiento audiológico y proveerte audífonos si corresponde.</p>
<p>📢 Reclamo: si no te reconocen la pérdida como profesional, reclamá ante la Comisión Médica.</p>
<p>Puede considerarse enfermedad profesional si está relacionada con tu trabajo. Consultanos tu caso.</p>
<p>PREGUNTA: ¿Qué pasa si la ART no reconoce mi enfermedad como profesional?</p>
<p>RESPUESTA_CORTA: Reclamá ante la Comisión Médica o la justicia.</p>
<p>Si la ART rechaza el reconocimiento de tu enfermedad como profesional, tenés derecho a apelar ante la Comisión Médica Jurisdiccional.</p>
<p>📌 Recurso: presentá el reclamo dentro de los plazos establecidos.</p>
<p>📌 Prueba: necesitás demostrar la relación entre la enfermedad y tu actividad laboral.</p>
<p>📌 Evaluación: la comisión evaluará tu caso y puede ordenarle a la ART que te dé las prestaciones.</p>
<p>⏳ Plazo: no dejes pasar los 2 años para reclamar (art. 44, LRT).</p>
<p>La ART no puede rechazar tu enfermedad sin fundamento médico. Consultá con nuestro equipo.</p>
<p>PREGUNTA: ¿Qué es la indemnización por incapacidad del 5%?</p>
<p>RESPUESTA_CORTA: Es una indemnización baja en porcentaje, pero te corresponde igual si tu lesión te dejó ese grado de incapacidad.</p>
<p>Un 5% parece poco, pero no lo subestimes: el monto final depende de tu edad y tu salario, así que puede ser un importe relevante.</p>
<p>📌 Piso mínimo: si el resultado calculado da por debajo del piso mínimo vigente, la ART tiene que pagarte ese piso.</p>
<p>📌 Impugnación: si considerás que tu incapacidad real es mayor, podés apelar ante la Comisión Médica.</p>
<p>📌 Revisión: si tu estado empeora, podés pedir un aumento del porcentaje.</p>
<p>No subestimes un 5%: cada porcentaje genera una indemnización. Usá nuestra calculadora para tener una estimación de tu caso.</p>
<p>PREGUNTA: ¿Qué es la indemnización por incapacidad del 50%?</p>
<p>RESPUESTA_CORTA: Es una indemnización significativa, porque implica una pérdida importante de tu capacidad de trabajo.</p>
<p>Un 50% de incapacidad implica una pérdida significativa de tu capacidad productiva.</p>
<p>📌 Cómo se calcula: en base a tu edad, tu ingreso base y ese porcentaje de incapacidad.</p>
<p>📌 Adicional del 20%: corresponde si el accidente fue en tu lugar de trabajo o a disposición del empleador (no es automático por el solo hecho de llegar al 50%).</p>
<p>📌 Piso mínimo: existe uno actualizado por la SRT.</p>
<p>📌 Impugnación: si no estás de acuerdo con el porcentaje, apelá ante la Comisión Médica.</p>
<p>📌 Impacto: una incapacidad del 50% puede limitar mucho tu capacidad de seguir trabajando.</p>
<p>Es un umbral clave en el sistema. Usá la calculadora para una estimación, o consultanos directamente.</p>
<p>PREGUNTA: ¿Qué es la indemnización por incapacidad del 100%?</p>
<p>RESPUESTA_CORTA: Es la máxima indemnización, cuando tu incapacidad te impide trabajar de manera permanente.</p>
<p>Se da cuando tu lesión te impide realizar cualquier actividad laboral de forma permanente.</p>
<p>📌 Cómo se calcula: considerando el 100% de incapacidad, tu edad y tu ingreso base.</p>
<p>📌 Adicional del 20%: corresponde si el accidente fue en tu lugar de trabajo o a disposición del empleador.</p>
<p>📌 Asistencia médica: de por vida, a cargo de la ART.</p>
<p>📌 Asistencia personal: si necesitás ayuda permanente, podés reclamar esos gastos aparte.</p>
<p>📄 Documentación: informes médicos detallados que demuestren la gravedad.</p>
<p>En casos de incapacidad total, contar con un abogado especializado es fundamental. Escribinos y te acompañamos en todo el proceso.</p>
<p>PREGUNTA: ¿Qué es la diferencia entre incapacidad parcial y total?</p>
<p>RESPUESTA_CORTA: La parcial te limita, pero podés trabajar en algo. La total te impide trabajar en cualquier ocupación.</p>
<p>La diferencia principal está en cuánto te limita la lesión para trabajar.</p>
<p>📌 Incapacidad parcial: tu lesión limita tu capacidad, pero podés desempeñarte en algunas tareas. Se calcula según el porcentaje específico que te asignaron.</p>
<p>📌 Incapacidad total: tu lesión te impide realizar cualquier actividad laboral de manera permanente; se considera el 100% de incapacidad.</p>
<p>📌 Adicional del 20%: en ambos casos, corresponde si el accidente fue en tu lugar de trabajo o a disposición del empleador.</p>
<p>📌 Ambas son permanentes cuando ya no van a mejorar.</p>
<p>📌 Revisión: las dos pueden revisarse si tu estado de salud cambia.</p>
<p>El porcentaje de incapacidad es la clave para saber cuánto te corresponde. Usá nuestra calculadora o escribinos para calcularlo juntos.</p>
<p>PREGUNTA: ¿Qué es la incapacidad según la ART?</p>
<p>RESPUESTA_CORTA: Es la disminución permanente de tu capacidad para trabajar, causada por un accidente o enfermedad laboral.</p>
<p>Es la disminución total o parcial de tu capacidad para trabajar a causa de un accidente de trabajo o una enfermedad profesional. Puede ser temporaria (mientras te recuperás) o permanente. La permanente se clasifica en parcial (te limita, pero podés trabajar en algo) o total (te impide trabajar en cualquier ocupación).</p>
<p>📌 Marco legal: la Ley de Riesgos del Trabajo (Ley 24.557) regula todas las contingencias vinculadas a la incapacidad laboral. El art. 6 define las contingencias cubiertas, y los arts. 13 a 16 establecen las prestaciones según el tipo de incapacidad.</p>
<p>📌 Baremo vigente: desde febrero de 2026 rige el Decreto 549/2025, que asigna un porcentaje fijo por cada secuela específica (ya no rangos como el baremo anterior).</p>
<p>📌 Topes por miembro: por ejemplo, en el miembro superior, la suma de secuelas en mano y muñeca no puede superar el 50%; sumando antebrazo, el 55%; con codo y brazo, el 60%; y con toda la cintura escapular, el 66%. En el miembro inferior, el tope de pie y tobillo es 35%, con pierna 40%, con rodilla 55%, y con muslo/cadera/hemipelvis, 70%.</p>
<p>📌 Factores adicionales: al porcentaje de la lesión se le suma un factor por tu edad y otro por la dificultad que te genera para tus tareas habituales (o la necesidad de reubicación laboral).</p>
<p>Si querés saber qué porcentaje te correspondería según tu lesión puntual, contanos el diagnóstico y te lo confirmamos con la tabla vigente.</p>
<p>PREGUNTA: ¿Qué es el baremo de lesiones?</p>
<p>RESPUESTA_CORTA: Es la tabla oficial que asigna un porcentaje fijo de incapacidad a cada tipo de lesión, y se usa para calcular la indemnización.</p>
<p>El baremo fija cómo se valora cada lesión permanente derivada de un accidente o enfermedad laboral. El porcentaje que asigna es la base para calcular tu indemnización.</p>
<p>📌 Baremo vigente: Decreto 549/2025, en vigor desde febrero de 2026, que reemplazó al Decreto 659/96.</p>
<p>📌 Organización: por capítulos según el sistema afectado  piel, osteoarticular, cabeza y rostro, oftalmología, otorrinolaringología, sistema respiratorio, cardiovascular, digestivo, nefro-urológico, aparato genital, sistema hematopoyético, sistema nervioso, psiquiatría, infectología, oncología y toxicología.</p>
<p>📌 Qué cambió: ya no hay rangos donde el médico elige un número entre un piso y un techo  cada secuela tiene un valor fijo.</p>
<p>📌 Si tu lesión no está contemplada exactamente: se puede recurrir a las tablas de limitación funcional (goniometría) del sector afectado, o la Comisión Médica evalúa por analogía.</p>
<p>Contanos tu diagnóstico específico y te decimos qué porcentaje corresponde según la tabla vigente.</p>
<p>PREGUNTA: ¿Cómo se determina el porcentaje de incapacidad?</p>
<p>RESPUESTA_CORTA: La ART o la Comisión Médica evalúan tu lesión y aplican el porcentaje fijo que le corresponde según el baremo vigente.</p>
<p>La ART hace una evaluación médica y te asigna el porcentaje que corresponde a tu diagnóstico. Si no estás de acuerdo, podés apelar ante la Comisión Médica Jurisdiccional, que designa un médico para reevaluarte.</p>
<p>📌 Metodología: el Decreto 549/2025 fija un valor único por secuela, sin rangos.</p>
<p>📌 Capacidad restante: cuando hay más de una secuela por el mismo accidente, en general se aplica el método de &quot;capacidad restante&quot; (se evalúa cada lesión sobre lo que queda de capacidad después de la anterior), salvo que la tabla indique expresamente sumarlas de forma aritmética  como ocurre, por ejemplo, con las lesiones de columna.</p>
<p>📌 Factores de ponderación: se suma un porcentaje según tu edad y la dificultad que la lesión te genera para tus tareas habituales.</p>
<p>Traenos tu diagnóstico y te confirmamos el porcentaje que corresponde según la tabla actual.</p>
<p>PREGUNTA: ¿Qué es la incapacidad permanente parcial?</p>
<p>RESPUESTA_CORTA: Es cuando tu lesión disminuye permanentemente tu capacidad para trabajar sin llegar a la total.</p>
<p>Reduce tu capacidad para trabajar de manera definitiva, sin impedirte completamente. Podés seguir trabajando en algunas tareas, pero con limitaciones. El porcentaje depende de la secuela exacta que te quedó, según la tabla vigente.</p>
<p>📌 Ejemplo real del baremo: una hernia de disco operada tiene fijado un 5% de incapacidad (Decreto 549/2025).</p>
<p>📌 Se indemniza según ese porcentaje, tu edad y tu salario.</p>
<p>📌 Factores adicionales: se suma un porcentaje por edad y por la dificultad para tus tareas habituales.</p>
<p>Contanos tu diagnóstico y te decimos el porcentaje exacto que le corresponde según la tabla vigente.</p>
<p>PREGUNTA: ¿Qué es la incapacidad permanente total?</p>
<p>RESPUESTA_CORTA: Es cuando tu lesión te impide realizar cualquier tipo de trabajo de manera definitiva.</p>
<p>Te impide realizar cualquier actividad laboral de forma permanente y definitiva. El baremo fija porcentajes altos para este tipo de secuelas.</p>
<p>📌 Ejemplos con porcentaje fijo: desarticulación coxofemoral (70%), amputación interescapulotorácica (66%), amputación de muslo en tercio proximal (70%), entre otras lesiones graves.</p>
<p>📌 Prestaciones: la ART debe brindarte asistencia médica de por vida.</p>
<p>📌 Factores adicionales: cuando la suma de factores de ponderación llevaría el porcentaje a más del 100%, el valor máximo se limita al 100%.</p>
<p>En casos de incapacidad total, contar con un abogado especializado es clave. Escribinos y te acompañamos.</p>
<p>PREGUNTA: ¿Qué es la gran invalidez?</p>
<p>RESPUESTA_CORTA: Es la incapacidad más grave: te impide trabajar y necesitás asistencia permanente de otra persona.</p>
<p>Se da cuando tu incapacidad te impide realizar cualquier actividad laboral y, además, necesitás ayuda de otra persona para las tareas cotidianas.</p>
<p>📌 Ejemplos: paraplejia, cuadriplejia, pérdida de ambas manos combinada con ceguera, amputación de ambas piernas.</p>
<p>📌 Indemnización: es la más alta que puede otorgar la ART.</p>
<p>📌 Prestaciones: asistencia médica de por vida, y podés reclamar además los gastos de asistencia personal.</p>
<p>Si tu caso encuadra en gran invalidez, contactanos: es fundamental el acompañamiento legal desde el principio.</p>
<p>PREGUNTA: ¿Qué porcentaje de incapacidad me pueden dar por una hernia discal lumbar?</p>
<p>RESPUESTA_CORTA: El baremo vigente fija un 5% para la hernia de disco operada. Si no fue operada, se evalúa por la limitación funcional que te haya quedado en la columna.</p>
<p>El nuevo baremo (Decreto 549/2025) ya no maneja rangos para esta lesión: fija un porcentaje único.</p>
<p>📌 Hernia de disco operada: 5% de incapacidad.</p>
<p>📌 Si no fue operada: se evalúa según la limitación funcional de columna dorsolumbar que hayas conservado (movilidad de flexión, extensión, rotación e inclinación), no por un porcentaje fijo propio.</p>
<p>📌 Tope del sector: la suma de todas las secuelas de columna dorsolumbar no puede superar el 60%.</p>
<p>📌 Si tenés otras secuelas de columna asociadas (por ejemplo, una fractura vertebral), se suman de forma aritmética.</p>
<p>Este es uno de los ejemplos donde más bajó el porcentaje respecto del baremo anterior, así que si te dictaminaron antes de febrero de 2026 puede corresponder otra valoración. Consultanos tu caso puntual.</p>
<p>PREGUNTA: ¿Qué porcentaje de incapacidad me pueden dar por una lesión de hombro?</p>
<p>RESPUESTA_CORTA: Depende de la lesión específica: hay valores fijos para luxaciones, roturas musculares y prótesis, y las lesiones no nombradas se evalúan por la movilidad que te quedó.</p>
<p>El baremo vigente (Decreto 549/2025) fija porcentajes según el diagnóstico exacto de hombro, no según su gravedad general.</p>
<p>📌 Luxación acromioclavicular o esternoclavicular: 2%.</p>
<p>📌 Luxación glenohumeral: 4% sin recidiva documentada, 12% si es recidivante.</p>
<p>📌 Inestabilidad de hombro por pérdida de partes blandas u óseas: 30%.</p>
<p>📌 Ruptura completa de deltoides: 6% sin secuelas, 12% con secuelas.</p>
<p>📌 Prótesis de hombro: 15% sin secuelas, 30% con secuelas.</p>
<p>📌 Lesiones no nombradas específicamente (como una rotura de manguito rotador sin cirugía protésica): se evalúan según la limitación funcional de hombro que te quedó (grados de movilidad en abducción, elevación, rotación).</p>
<p>Contanos tu diagnóstico exacto y la cirugía que tuviste (si la hubo) para darte el porcentaje que corresponde.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por perder un dedo?</p>
<p>RESPUESTA_CORTA: Depende de qué dedo sea y a qué altura se amputó. La pérdida del pulgar es la que más incapacidad genera: hasta 40% a nivel de la articulación trapeciometacarpiana.</p>
<p>El baremo vigente (Decreto 549/2025) fija un porcentaje fijo sin rangos según el dedo y el nivel exacto de la amputación.</p>
<p>Pulgar:</p>
<p>📌 A nivel de la articulación trapeciometacarpiana: 40% (el valor más alto)</p>
<p>📌 A nivel del metacarpiano: 35%</p>
<p>📌 A nivel de la articulación metacarpofalángica: 30%</p>
<p>📌 A nivel de la falange proximal: 25%</p>
<p>📌 A nivel de la interfalángica: 15%</p>
<p>📌 A nivel de la falange distal: 8%</p>
<p>📌 A nivel del pulpejo (sin lesión ósea): 2%</p>
<p>📌 Con transferencia de rayo: 37%</p>
<p>Índice, mayor, anular o meñique:</p>
<p>📌 A nivel del carpo: 15%</p>
<p>📌 A nivel del metacarpiano: 11%</p>
<p>📌 A nivel de la articulación metacarpofalángica: 10%</p>
<p>📌 A nivel de la falange proximal: 9%</p>
<p>📌 A nivel de la interfalángica proximal: 8%</p>
<p>📌 A nivel de la falange media: 7%</p>
<p>📌 A nivel de la interfalángica distal: 6%</p>
<p>📌 A nivel de la falange distal: 3%</p>
<p>📌 A nivel del pulpejo (sin lesión ósea): 1%</p>
<p>📌 Con transferencia de rayo: 12%</p>
<p>Amputaciones múltiples:</p>
<p>📌 Los cinco dedos, a nivel del carpo o metacarpofalángico: 50% (equivale a la pérdida funcional de la mano)</p>
<p>📌 Los cuatro dedos sin el pulgar a nivel metacarpofalángico: 40%</p>
<p>Contanos exactamente qué dedo y a qué altura fue la amputación, y te confirmamos el porcentaje preciso.</p>
<p>PREGUNTA: ¿Qué es la estabilidad médica?</p>
<p>RESPUESTA_CORTA: Es el momento en que tu estado de salud ya no va a mejorar ni empeorar de forma significativa.</p>
<p>Es cuando tu cuadro clínico se estabiliza y ya no se espera una mejora significativa con más tratamiento. En ese momento la ART determina tu incapacidad permanente y te da el Alta Médica.</p>
<p>📌 Si no estás de acuerdo con que te hayan declarado la estabilidad médica, podés apelar ante la Comisión Médica.</p>
<p>📌 Por qué importa el momento exacto: el porcentaje de incapacidad se fija según tu estado en ese punto, así que conviene no aceptar un alta apurada si sentís que tu cuadro todavía puede evolucionar.</p>
<p>Si te dieron el alta y no estás de acuerdo, escribinos antes de que venza el plazo para impugnarla.</p>
<p>PREGUNTA: ¿Qué es la tabla de factores de incapacidad?</p>
<p>RESPUESTA_CORTA: Es la tabla oficial que asigna un porcentaje fijo a cada lesión, más los factores de ponderación por edad y dificultad para trabajar.</p>
<p>El baremo vigente (Decreto 549/2025) establece dos componentes:</p>
<p>📌 El valor de la secuela: un porcentaje fijo según tu diagnóstico exacto, organizado por capítulos según el sistema afectado.</p>
<p>📌 Los factores de ponderación: se suman un porcentaje por tu edad (que va del 2% al 5% según el rango etario) y otro según qué tan difícil te resulta desempeñar tus tareas habituales o si necesitás reubicación laboral (5%, 10% o 20% según el grado).</p>
<p>📌 Lesiones no contempladas: la jurisprudencia admitió que puedan indemnizarse por analogía con lesiones similares.</p>
<p>Consultá con nuestro equipo el porcentaje específico que corresponde a tu lesión.</p>
<p>PREGUNTA: ¿Qué es la incapacidad temporaria?</p>
<p>RESPUESTA_CORTA: Es la incapacidad temporal que te impide trabajar mientras te recuperás del accidente.</p>
<p>Te impide trabajar de manera temporal mientras te recuperás. Durante ese período, la ART te paga un subsidio equivalente a tu ingreso base. Cuando alcanzás la estabilidad médica, se determina si quedaste con una incapacidad permanente.</p>
<p>📌 Si no te dan el alta y sentís que necesitás más tiempo de tratamiento, podés reclamar.</p>
<p>📌 Duración máxima: la ley prevé un plazo límite para esta situación, transcurrido el cual se define tu situación definitiva.</p>
<p>Si la ART te quiere dar el alta antes de tiempo, contactanos para evaluarlo.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por una fractura de muñeca?</p>
<p>RESPUESTA_CORTA: Depende del hueso específico y si quedó con secuelas: los valores van del 1% al 15%.</p>
<p>El baremo distingue entre los distintos huesos del carpo, y entre fractura sin secuelas, con secuelas, y con pseudoartrosis.</p>
<p>📌 Fractura de escafoides: 5% sin secuelas, 10% con secuelas, 15% con pseudoartrosis.</p>
<p>📌 Fractura de semilunar: los mismos valores (5% / 10% / 15%).</p>
<p>📌 Fractura de otro hueso del carpo: 1% / 2% / 3% si es un solo hueso; 3% / 6% / 9% si son varios.</p>
<p>📌 Fractura de radio (incluye estiloides radial): 4% / 8% / 12%.</p>
<p>📌 Fractura de estiloides cubital: 1% / 2% / 3%.</p>
<p>📌 &quot;Con secuelas&quot; significa que hay angulación, deseje, necrosis, artrosis, incongruencia articular u otras complicaciones documentadas.</p>
<p>Contanos qué hueso se fracturó y si te quedaron secuelas, y te confirmamos el porcentaje exacto.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por una lesión de rodilla?</p>
<p>RESPUESTA_CORTA: Depende de la lesión específica: una meniscectomía operada tiene fijado un 4%, una rotura de cruzado anterior un 7%.</p>
<p>El baremo vigente fija un valor único para cada tipo de lesión de rodilla, sin importar tanto la gravedad como el diagnóstico exacto.</p>
<p>📌 Lesión meniscal operada (meniscectomía, meniscoplastia o sutura): 4%.</p>
<p>📌 Lesión meniscal no operada con hipotrofia muscular, hidrartrosis o bloqueo: 8%.</p>
<p>📌 Ruptura completa del ligamento cruzado anterior: 7%.</p>
<p>📌 Ruptura completa del ligamento cruzado posterior: 4%.</p>
<p>📌 Ruptura de ligamento lateral interno o externo: 3% cada uno.</p>
<p>📌 Luxación de rótula: 1%.</p>
<p>📌 Fractura de rótula: 3% sin secuelas, 4% con secuelas, 6% con pseudoartrosis.</p>
<p>📌 Prótesis de rodilla: 20% sin secuelas, 40% con secuelas.</p>
<p>Contanos tu diagnóstico exacto (con o sin cirugía) y te confirmamos el porcentaje que corresponde.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por una lesión de columna cervical?</p>
<p>RESPUESTA_CORTA: Depende de la lesión: una fractura simple puede ser un 4%, y el conjunto de secuelas cervicales nunca puede superar el 40%.</p>
<p>El baremo fija valores específicos por tipo de fractura y nivel vertebral, y todas las secuelas de un mismo sector se suman de forma aritmética.</p>
<p>📌 Fractura de apófisis odontoides: 5% sin secuelas, 10% con secuelas, 15% con pseudoartrosis.</p>
<p>📌 Fractura o luxofractura cervical C1-C2: 6% / 12% / 18%.</p>
<p>📌 Fractura o luxofractura cervical C3-C7: 4% / 8% / 12%.</p>
<p>📌 Tope del sector: la suma de todas las secuelas del sector cervical no puede superar el 40%, sin importar cuántas fracturas o lesiones tengas ahí.</p>
<p>📌 Hernia de disco operada: 5% (mismo valor en cualquier sector de columna).</p>
<p>Contanos el diagnóstico exacto (qué vértebras y con qué secuelas) para confirmarte el porcentaje.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por una amputación?</p>
<p>RESPUESTA_CORTA: Depende del nivel exacto: la mano completa tiene fijado un 50%, el brazo un 60%, y la pierna a la altura del muslo, entre 60% y 70%.</p>
<p>El baremo tiene una tabla específica con el valor exacto para cada nivel de amputación.</p>
<p>Miembro superior:</p>
<p>📌 Amputación interescapulotorácica o a nivel de la cintura escapular: 66%.</p>
<p>📌 A nivel del brazo o desarticulación de codo: 60%.</p>
<p>📌 A nivel del antebrazo: 55%.</p>
<p>📌 Mano a nivel de la muñeca, o los cinco dedos a nivel del carpo: 50%.</p>
<p>📌 Los cuatro dedos (menos el pulgar): 40%.</p>
<p>Miembro inferior:</p>
<p>📌 Desarticulación coxofemoral, o muslo en tercio proximal: 70%.</p>
<p>📌 Muslo en tercio medio o distal: 60%.</p>
<p>📌 Desarticulación de rodilla: 55%.</p>
<p>📌 A nivel de la pierna: 40%.</p>
<p>📌 Amputación de Syme (tobillo): 35%.</p>
<p>Contanos el nivel exacto de tu amputación y te confirmamos el porcentaje que corresponde según la tabla.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por una cicatriz?</p>
<p>RESPUESTA_CORTA: Depende de la ubicación, el tamaño y si fue por una quemadura: en cabeza y cuello hay una tabla específica según la longitud.</p>
<p>El baremo evalúa las cicatrices de manera distinta según dónde estén y su origen.</p>
<p>📌 Cicatrices en cuero cabelludo: 1% si mide hasta 10 cm, 2% si supera los 10 cm.</p>
<p>📌 Cicatrices en rostro o cuello: 2% hasta 2 cm, 4% de 2 a 4 cm, 10% de 4 a 10 cm, 12% si supera los 10 cm.</p>
<p>📌 Cicatrices por quemadura en cualquier parte del cuerpo: se calculan según el porcentaje de superficie corporal afectada (con la &quot;regla de los nueve&quot;), y si además están en cabeza o rostro, se suma un 20% adicional por el compromiso estético.</p>
<p>📌 No se evalúan hasta que pasaron al menos 4 meses desde la lesión, para dar tiempo a que cicatrice.</p>
<p>Contanos la ubicación, el tamaño y si fue por quemadura, y te confirmamos el porcentaje.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por una lesión de codo?</p>
<p>RESPUESTA_CORTA: Depende de la lesión: una fractura de húmero puede ser un 8%, una prótesis de codo entre 10% y 20%.</p>
<p>El baremo fija valores según el diagnóstico exacto de codo.</p>
<p>📌 Fractura de húmero: 8% sin secuelas, 16% con secuelas, 24% con pseudoartrosis.</p>
<p>📌 Prótesis de codo: 10% sin secuelas, 20% con secuelas.</p>
<p>📌 Inestabilidad de codo por pérdida de partes blandas u óseas: 20%.</p>
<p>📌 Epicondilitis (codo de tenista) u otras lesiones que no tengan un valor fijo propio en la tabla: se evalúan según la limitación funcional que te haya quedado en la movilidad del codo (flexión, extensión, pronación, supinación).</p>
<p>Contanos tu diagnóstico exacto y si requirió cirugía o prótesis, y te confirmamos el porcentaje.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por una lesión de tobillo?</p>
<p>RESPUESTA_CORTA: Depende de la lesión: una fractura de maléolo puede ser un 3%, una prótesis de tobillo entre 10% y 20%.</p>
<p>El baremo fija porcentajes exactos para las lesiones óseas de tobillo.</p>
<p>📌 Fractura de maléolo (peroneo, tibial medial o tibial posterior): 3% sin secuelas, 6% con secuelas, 9% con pseudoartrosis (cada uno).</p>
<p>📌 Fractura de astrágalo o de calcáneo: 6% / 12% / 18%.</p>
<p>📌 Prótesis de tobillo: 10% sin secuelas, 20% con secuelas.</p>
<p>📌 Amputación de Syme: 35%.</p>
<p>📌 Un esguince sin secuela ósea documentada no tiene, en general, un valor fijo propio: se evalúa según la limitación funcional que haya quedado en la movilidad del tobillo, si la hay.</p>
<p>Contanos tu diagnóstico exacto para confirmarte el porcentaje.</p>
<p>PREGUNTA: ¿Qué es la incapacidad por pérdida de dientes?</p>
<p>RESPUESTA_CORTA: Cada pieza dentaria perdida (y no reemplazada) tiene un porcentaje fijo, que va del 0,50% al 2% según el diente.</p>
<p>El baremo fija un valor específico por cada pieza dentaria, siempre que la pérdida no haya sido reemplazada por una prótesis fija (puente o implante).</p>
<p>📌 Incisivo central, incisivo lateral o canino: 2% cada uno.</p>
<p>📌 Primer o segundo premolar: 1% cada uno.</p>
<p>📌 Primer o segundo molar: 1% cada uno.</p>
<p>📌 Tercer molar: 0,50%.</p>
<p>📌 Si perdés más de una pieza: los porcentajes se suman de forma aritmética.</p>
<p>📌 Si la pérdida fue reemplazada por prótesis fija: no corresponde este porcentaje.</p>
<p>Contanos cuántas piezas perdiste y cuáles, y te confirmamos el porcentaje total.</p>
<p>PREGUNTA: ¿Qué es la incapacidad por daño cerebral?</p>
<p>RESPUESTA_CORTA: El daño cerebral puede generar una incapacidad muy alta, dependiendo de las secuelas neurológicas y psíquicas concretas que te haya dejado.</p>
<p>El porcentaje depende de qué secuelas específicas te quedaron: pueden ser motoras, sensitivas, cognitivas o psíquicas, y cada una se evalúa según el capítulo correspondiente del baremo (sistema nervioso, psiquiatría).</p>
<p>📌 Puede incluir: problemas de memoria, concentración, lenguaje, coordinación motriz, cambios de personalidad y limitaciones motoras.</p>
<p>📌 Cómo se evalúa: cada secuela concreta (por ejemplo, una lesión de un nervio o par craneal específico, o un cuadro psiquiátrico determinado) tiene su propio valor en el baremo, y se combinan según la metodología de capacidad restante.</p>
<p>📌 Tratamiento: la ART debe cubrir rehabilitación neurológica y neuropsicológica.</p>
<p>Este tipo de casos requiere una evaluación médica muy puntual. Contanos el diagnóstico y las secuelas concretas para orientarte mejor.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por una lesión de pie?</p>
<p>RESPUESTA_CORTA: Depende de la lesión: la pérdida del dedo gordo puede ser un 12%, una fractura de metatarsiano del 1% al 6%.</p>
<p>El baremo fija un valor exacto según el hueso y el tipo de lesión.</p>
<p>📌 Amputación del primer dedo: 12% a nivel de la falange proximal, 6% a nivel de la falange distal.</p>
<p>📌 Amputación del 2º, 3º, 4º o 5º dedo: 3% a nivel de la falange proximal, 2% en la falange media, 1% en la falange distal.</p>
<p>📌 Fractura de metatarsiano: el 1º tiene 2% / 4% / 6% (sin secuelas / con secuelas / pseudoartrosis); el 2º, 3º o 4º, 1% / 2% / 3%; el 5º, 2% / 4% / 6%.</p>
<p>📌 Fractura de astrágalo o calcáneo: 6% / 12% / 18%.</p>
<p>📌 Fractura de escafoides (pie): 4% / 8% / 12%.</p>
<p>Contanos qué hueso o dedo se afectó y qué secuelas te quedaron, y te confirmamos el porcentaje exacto.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por una fractura de tibia y peroné?</p>
<p>RESPUESTA_CORTA: La fractura de tibia va del 10% al 30% según las secuelas; la de peroné, del 2% al 6%.</p>
<p>El baremo distingue entre ambos huesos y entre fractura sin secuelas, con secuelas, y con pseudoartrosis.</p>
<p>📌 Fractura de tibia (incluye el pilón tibial): 10% sin secuelas, 20% con secuelas, 30% con pseudoartrosis.</p>
<p>📌 Fractura de peroné: 2% / 4% / 6%.</p>
<p>📌 Si tenés ambas fracturas de la misma pierna, se suman de forma aritmética por tratarse del mismo miembro y lateralidad.</p>
<p>📌 &quot;Con secuelas&quot; incluye angulación, deseje, necrosis, artrosis, incongruencia articular u otras complicaciones documentadas.</p>
<p>Contanos qué hueso se fracturó y si te quedaron secuelas, y te confirmamos el porcentaje total.</p>
<p>PREGUNTA: ¿Qué es la incapacidad por síndrome del túnel carpiano?</p>
<p>RESPUESTA_CORTA: Es una lesión común en trabajos con movimientos repetitivos, y su porcentaje se evalúa según el compromiso del nervio mediano que te haya dejado.</p>
<p>No tiene un valor fijo propio y único en la tabla del baremo: se evalúa como una lesión del nervio periférico afectado (el nervio mediano), según el grado de compromiso motor y sensitivo que presentes.</p>
<p>📌 Evaluación: se mide con escalas específicas de función motora y sensitiva del nervio comprometido.</p>
<p>📌 Si afecta ambas manos: los porcentajes se suman.</p>
<p>📌 Tratamiento: la ART debe cubrir el tratamiento y la rehabilitación, incluida la cirugía si corresponde.</p>
<p>Este es un caso donde conviene una evaluación médica puntual para determinar el porcentaje exacto. Contanos tu diagnóstico (con o sin cirugía) y te orientamos.</p>
<p>PREGUNTA: ¿Qué es la incapacidad por quemaduras?</p>
<p>RESPUESTA_CORTA: Se calcula según la superficie corporal afectada y la profundidad de la quemadura, con un adicional si dejó marcas en cabeza o rostro.</p>
<p>El baremo tiene una metodología específica de cálculo, basada en la extensión y la profundidad de la cicatriz por quemadura.</p>
<p>📌 Extensión: se mide con la &quot;regla de los nueve de Wallace&quot; (la palma de tu mano equivale al 1% de tu superficie corporal total).</p>
<p>📌 Profundidad tipo AB (epidermis y dermis): se asigna el 100% del porcentaje de esa extensión.</p>
<p>📌 Profundidad tipo B (hasta hueso o aponeurosis): se asigna el 200% del porcentaje de esa extensión.</p>
<p>📌 Si la quemadura está en cabeza o rostro: se suma un 20% adicional por el compromiso estético.</p>
<p>📌 Compromiso funcional (por ejemplo, si limita el movimiento de una articulación): se evalúa aparte, según el capítulo de la zona afectada.</p>
<p>Contanos la extensión, la profundidad y la ubicación de tus quemaduras, y te ayudamos a calcular el porcentaje.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por una lesión de cadera?</p>
<p>RESPUESTA_CORTA: Una fractura de fémur/cadera va del 10% al 30% según las secuelas; una prótesis de cadera, del 20% al 40%.</p>
<p>El baremo agrupa la fractura de cadera dentro de la fractura de fémur.</p>
<p>📌 Fractura de fémur (incluye cadera): 10% sin secuelas, 20% con secuelas, 30% con pseudoartrosis.</p>
<p>📌 Prótesis parcial o total de cadera: 20% sin secuelas, 40% con secuelas.</p>
<p>📌 Desarticulación coxofemoral: 70% (el valor más alto de esta zona).</p>
<p>📌 &quot;Con secuelas&quot; incluye angulación, deseje, incongruencia articular u otras complicaciones documentadas.</p>
<p>Contanos si tuviste fractura, prótesis o algo más grave, y te confirmamos el porcentaje que corresponde.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por una lesión de fémur?</p>
<p>RESPUESTA_CORTA: La fractura de fémur va del 10% al 30% según las secuelas; una amputación a la altura del muslo, entre 60% y 70%.</p>
<p>El baremo fija estos valores para las lesiones de fémur:</p>
<p>📌 Fractura de fémur (incluye cadera): 10% sin secuelas, 20% con secuelas, 30% con pseudoartrosis.</p>
<p>📌 Amputación de muslo en tercio proximal: 70%.</p>
<p>📌 Amputación de muslo en tercio medio o distal: 60%.</p>
<p>📌 Prótesis de cadera: 20% sin secuelas, 40% con secuelas.</p>
<p>Contanos el tipo exacto de lesión (fractura, amputación o prótesis) y te confirmamos el porcentaje.</p>
<p>PREGUNTA: ¿Qué es la incapacidad por estrés post traumático?</p>
<p>RESPUESTA_CORTA: Puede reconocerse si es consecuencia de un accidente de trabajo grave, y el porcentaje se determina según la evaluación psiquiátrica de tu cuadro.</p>
<p>Si el estrés postraumático es consecuencia de un accidente de trabajo grave, la ART debe reconocerlo y darte el tratamiento correspondiente.</p>
<p>📌 Puede generar: limitaciones en la concentración, las relaciones interpersonales y la capacidad laboral.</p>
<p>📌 Tratamiento: la ART debe cubrir el abordaje psicológico y psiquiátrico necesario.</p>
<p>📌 Porcentaje: se determina según la evaluación psiquiátrica de tu cuadro específico, conforme al capítulo correspondiente del baremo vigente.</p>
<p>Este tipo de casos necesita informes psiquiátricos que certifiquen el cuadro y su relación con el accidente. Consultanos para evaluar tu situación.</p>
<p>PREGUNTA: ¿Qué es la reincorporación laboral después de una incapacidad?</p>
<p>RESPUESTA_CORTA: Es volver a trabajar después de una incapacidad; tu empleador debe adaptar tu puesto si hace falta.</p>
<p>Tu empleador tiene la obligación de reincorporarte y, si es necesario, adaptar tu puesto a tu nueva condición.</p>
<p>📌 Si tu incapacidad impide que vuelvas a tu puesto anterior: la ART debe brindarte capacitación para otra ocupación.</p>
<p>📌 Si tu empleador se niega a reincorporarte: podés reclamar ante la justicia del trabajo.</p>
<p>Si te están complicando la vuelta al trabajo, consultanos: hay herramientas legales para exigir tus derechos.</p>
<p>PREGUNTA: ¿Qué es la rehabilitación laboral de la ART?</p>
<p>RESPUESTA_CORTA: Es un programa que la ART debe brindarte para que puedas volver a trabajar después de una incapacidad.</p>
<p>Incluye capacitación, orientación vocacional y adaptación a nuevas tareas. Si tu incapacidad te impide volver a tu ocupación anterior, la ART tiene que brindarte formación para otra actividad. Es un derecho contemplado en la LRT.</p>
<p>Si la ART no te está ofreciendo este programa, escribinos y lo reclamamos.</p>
<p>PREGUNTA: ¿Qué porcentaje me dan por una fractura de columna?</p>
<p>RESPUESTA_CORTA: Depende del nivel y del tipo de fractura, con valores que van del 1% al 24%, y con un tope según el sector.</p>
<p>El baremo fija un valor por cada nivel vertebral, y distingue entre fractura sin secuelas, con secuelas y con pseudoartrosis.</p>
<p>📌 Apófisis odontoides: 5% / 10% / 15%.</p>
<p>📌 Cervical C1-C2: 6% / 12% / 18%. C3-C7: 4% / 8% / 12%.</p>
<p>📌 Dorsal D1-D10: 5% / 10% / 15%. D11-D12: 8% / 16% / 24%.</p>
<p>📌 Lumbar L1: 8% / 16% / 24%. L2-L5: 5% / 10% / 15%.</p>
<p>📌 Sacro: 3% / 6% / 9%. Coxis: 2% / 4% / 6%.</p>
<p>📌 Topes por sector: el sector cervical no puede superar el 40% en total, y el dorsolumbar no puede superar el 60%, sin importar cuántas fracturas tengas en ese sector.</p>
<p>Contanos qué vértebra se fracturó y con qué secuelas, y te confirmamos el porcentaje.</p>
<p>PREGUNTA: ¿Qué es la incapacidad por pérdida renal?</p>
<p>RESPUESTA_CORTA: La insuficiencia renal crónica se evalúa combinando dos estudios de laboratorio, con porcentajes que van del 5% al 70%.</p>
<p>El baremo cruza dos valores de laboratorio (la tasa de filtrado glomerular y la relación albúmina/creatinina en orina) para determinar el porcentaje.</p>
<p>📌 Rango de resultados: desde 5% (función renal levemente reducida) hasta 70% (función muy comprometida).</p>
<p>📌 Nefrectomía bilateral con diálisis crónica actual, hemodiálisis o diálisis peritoneal: 70%.</p>
<p>📌 Trasplante renal: 40%.</p>
<p>📌 Si necesitás diálisis o trasplante, la ART debe cubrir el tratamiento completo.</p>
<p>Contanos tus últimos estudios (filtrado glomerular y relación albúmina/creatinina) y te orientamos sobre el porcentaje.</p>
<p>PREGUNTA: ¿Qué es la incapacidad por pérdida de un riñón?</p>
<p>RESPUESTA_CORTA: La nefrectomía (extirpación) de un riñón tiene fijado un 10% si fue parcial, y un 20% si fue total.</p>
<p>El baremo distingue entre extirpación parcial y total de un riñón.</p>
<p>📌 Nefrectomía unilateral parcial: 10%.</p>
<p>📌 Nefrectomía unilateral total: 20%.</p>
<p>📌 Si además tenés otras afectaciones (infección urinaria recurrente, pérdida de función renal general), se suman por la metodología de capacidad restante.</p>
<p>Si perdiste un riñón por un accidente de trabajo, la ART debe cubrir el tratamiento y la indemnización correspondiente. Consultanos tu caso.</p>
<p>PREGUNTA: ¿Qué es la revisión de la incapacidad?</p>
<p>RESPUESTA_CORTA: Es el proceso donde se vuelve a evaluar tu incapacidad si tu estado de salud cambia.</p>
<p>Si tu estado de salud cambia (mejora o empeora), podés solicitar que se revise tu porcentaje de incapacidad.</p>
<p>📌 Si empeorás: podés pedir una revisión para que te aumenten el porcentaje.</p>
<p>📌 Si mejorás: la ART podría pedir una revisión para disminuirlo.</p>
<p>📌 Dónde se tramita: ante la Comisión Médica Jurisdiccional. Es un derecho del trabajador.</p>
<p>Si notás cambios en tu estado de salud, no esperes: consultanos para iniciar la revisión.</p>
<p>01. ¿Qué es la Comisión Médica?</p>
<p>RESPUESTA CORTA: Es el organismo de la SRT que resuelve los conflictos entre vos y la ART sobre tu incapacidad.</p>
<p>RESPUESTA COMPLETA</p>
<p>La Comisión Médica Jurisdiccional es el organismo de la Superintendencia de Riesgos del Trabajo (SRT) que interviene cuando vos y la ART no se ponen de acuerdo sobre tu incapacidad. Es la instancia administrativa previa y obligatoria antes de poder ir a juicio (art. 1, Ley 27.348).</p>
<p>📌 Competencia: Resuelve controversias sobre la calificación de tu incapacidad, el porcentaje según el baremo vigente (Decreto 549/2025) y las prestaciones médicas que te corresponden.</p>
<p>📌  Cómo se inicia: Con un reclamo presentado en la SRT, completando el formulario correspondiente y adjuntando tu documentación médica.</p>
<p>⏳ Plazo: Tiene 60 días hábiles administrativos para resolver, prorrogables por única vez hasta 30 días hábiles más si hace falta producir prueba (art. 3, Ley 27.348 y Resolución SRT 5/2026).</p>
<p>📌 Dictamen: Emite un dictamen que es vinculante para las partes, salvo que lo apeles a tiempo.</p>
<p>📌 Apelación: Si no estás de acuerdo, podés apelar ante la Comisión Médica Central dentro de los 5 días hábiles de notificado.</p>
<p>📌 Gratuidad: El trámite es completamente gratuito para vos.</p>
<p>📌 Consejo práctico: Antes de presentar el reclamo, reuní toda tu documentación médica. Cuanto más completa esté, más rápido y mejor se resuelve tu caso.</p>
<p>02. ¿Cómo se presenta un reclamo ante la Comisión Médica?</p>
<p>RESPUESTA CORTA: Completás el formulario de la SRT y lo presentás en la comisión médica de tu jurisdicción, con toda tu documentación médica.</p>
<p>RESPUESTA COMPLETA</p>
<p>Para presentar un reclamo ante la Comisión Médica tenés que seguir estos pasos:</p>
<p>📌 Formulario: Completá el formulario de solicitud de la SRT, que podés descargar del sitio web del organismo o pedir en la comisión médica de tu jurisdicción.</p>
<p>📄 Documentación: Adjuntá copia de tu historia clínica completa, certificados médicos, informes de estudios (radiografías, resonancias) y las resoluciones de la ART.</p>
<p>📌 Presentación: Entregá todo en la comisión médica jurisdiccional que te corresponde según tu domicilio o el lugar donde trabajás, personalmente o por apoderado.</p>
<p>📌  Plazo especial para el alta: Si vas a impugnar un alta médica, el plazo es de solo 5 días hábiles desde la notificación fehaciente (Resolución SRT 5/2026). Para otros reclamos no hay un plazo mínimo, pero conviene actuar cuanto antes.</p>
<p>📌 </p>
<p>📌 Notificación a la ART: La comisión le da traslado del reclamo a la ART para que presente su posición en el plazo que se le fije.</p>
<p>📌 Audiencia: Puede citarte a una junta médica donde un perito oficial va a examinar tu lesión.</p>
<p>📌 Consejo práctico: Guardá copia de todo lo que presentes y hacé seguimiento constante del expediente. Eso te va a ayudar a conocer el estado real de tu reclamo.</p>
<p>03. ¿Cuánto tiempo tengo para apelar la calificación de incapacidad?</p>
<p>CATEGORÍA: Comisión Médica</p>
<p>RESPUESTA CORTA: Tenés 5 días hábiles desde que te notifican el dictamen de la Comisión Médica para apelar ante la Comisión Médica Central.</p>
<p>RESPUESTA COMPLETA</p>
<p>El plazo para apelar el dictamen de la Comisión Médica Jurisdiccional es de 5 días hábiles desde que te lo notifican. Es un plazo perentorio: si no apelás dentro de ese término, el dictamen queda firme y ya no lo podés cuestionar por vía administrativa.</p>
<p>⚠️ Importante: Si dejás pasar los 5 días hábiles, el dictamen queda firme. Podés seguir teniendo la opción de ir directamente a la justicia laboral, pero ya no vas a poder apelar dentro del sistema administrativo.</p>
<p>📌 Forma: Se apela presentando un escrito fundado ante la Comisión Médica Central, o directamente ante la justicia laboral ordinaria de tu provincia, a tu elección (art. 2, Ley 27.348).</p>
<p>📄 Documentación: Tenés que adjuntar los fundamentos de tu disconformidad y toda la documentación médica que respalde tu reclamo.</p>
<p>📌  Patrocinio letrado: Para apelar, el patrocinio de un abogado es obligatorio en la mayoría de las provincias adheridas a la Ley 27.348.</p>
<p>📌  Comisión Médica Central: Es quien resuelve la apelación: puede confirmar, modificar o revocar el dictamen original.</p>
<p>📌 Consejo práctico: No dejes pasar el plazo de 5 días hábiles. Consultá con un abogado apenas te notifiquen el dictamen que no te cierra.</p>
<p>04. ¿Qué es el porcentaje de incapacidad?</p>
<p>CATEGORÍA: Comisión Médica</p>
<p>RESPUESTA CORTA: Es la evaluación médica que determina cuánto te afectó la lesión para trabajar y define el monto de tu indemnización.</p>
<p>RESPUESTA COMPLETA</p>
<p>El porcentaje de incapacidad es la calificación médica que expresa cuánto te afectó la lesión o enfermedad para trabajar y para tu vida diaria. Es el número que, junto con tu edad y tu salario, determina cuánto vas a cobrar.</p>
<p>📌 Escala: Va del 0% al 100%, según el baremo vigente: el Anexo del Decreto 549/2025, obligatorio en todo el país desde el 1° de febrero de 2026.</p>
<p>📌  Porcentaje fijo: A diferencia del baremo anterior (Decreto 659/96), que usaba rangos, ahora cada lesión tiene un porcentaje único, sin margen de discrecionalidad para el perito.</p>
<p>📌  Factor de ponderación: Al porcentaje base de la tabla se le suma un incremento según tu edad (entre 2% y 5%) y según cómo afecta la lesión a tus tareas habituales (5%, 10% o 20%). Ese incremento se aplica como porcentaje sobre el valor de la lesión, no como puntos fijos.</p>
<p>📌 Impacto: Determina el monto de tu indemnización. Cada punto porcentual representa una diferencia real de dinero.</p>
<p>📌 Revisión: Puede modificarse si tu estado de salud cambia, para mejor o para peor.</p>
<p>📌 Impugnación: Si no estás de acuerdo, podés apelar ante la Comisión Médica Central dentro de los 5 días hábiles de notificado.</p>
<p>📌 Consejo práctico: No aceptes un porcentaje sin que lo revise un abogado. Verificá que respete al pie de la letra el baremo vigente, incluido el factor de ponderación por edad y actividad.</p>
<p>05. ¿La ART me puede rechazar el reclamo si no voy a la pericia médica?</p>
<p>RESPUESTA CORTA: Sí, si faltás a la pericia médica sin justificar tu ausencia, la ART puede rechazar tu reclamo de incapacidad.</p>
<p>RESPUESTA COMPLETA</p>
<p>Asistir a las citaciones médicas es obligatorio. Si no te presentás a la pericia sin justificación, la ART puede tomar decisiones que perjudiquen seriamente tu reclamo.</p>
<p>📌 Rechazo: La ART puede rechazar tu solicitud de incapacidad si faltás a la pericia sin justificar.</p>
<p>📌 Consecuencias: No vas a cobrar la indemnización que te corresponde y podés perder el derecho a reclamar por esa vía.</p>
<p>📌 Reprogramación: Podés pedir una nueva fecha, siempre que justifiques la inasistencia con documentación médica (certificado de internación, licencia médica, etc.).</p>
<p>📌 Desistimiento: Si faltás sin ninguna justificación, se considera que desististe de tu reclamo.</p>
<p>📌 Reposición: Si tenés justificación, podés pedir la reposición del trámite dentro de un plazo razonable.</p>
<p>📌 Consejo práctico: Si no podés asistir a una citación, avisá a la comisión médica con anticipación y mandá la documentación que justifique tu ausencia.</p>
<p>06. ¿Qué es la revisión de la incapacidad?</p>
<p>RESPUESTA CORTA: Es el trámite para volver a evaluarte cuando tu estado de salud cambia respecto del porcentaje que te asignaron.</p>
<p>RESPUESTA COMPLETA</p>
<p>La revisión de la incapacidad es un derecho tuyo como trabajador cuando tu condición médica cambia. Si tu estado mejora o empeora, podés pedir una nueva evaluación.</p>
<p>📌 Empeoramiento: Si empeoraste, podés pedir una nueva evaluación para que te aumenten el porcentaje.</p>
<p>📌 Mejoría: Si mejoraste, la ART también puede solicitar que se ajuste el porcentaje a la baja.</p>
<p>⏳ Plazo: No hay límite de tiempo para pedir la revisión. Podés hacerlo en cualquier momento.</p>
<p>📌 Proceso: Se presenta ante la Comisión Médica con documentación médica actualizada que demuestre el cambio en tu estado.</p>
<p>📌  Nueva pericia: La comisión va a ordenar una nueva evaluación médica.</p>
<p>📌 Indemnización: Si el porcentaje cambia, se recalcula el monto de tu indemnización.</p>
<p>📌 Consejo práctico: Si tu estado de salud cambió, no esperes. Pedí la revisión con toda la documentación médica que respalde el cambio.</p>
<p>07. ¿Qué pasa si no estoy de acuerdo con la calificación de la ART?</p>
<p>RESPUESTA CORTA: Tenés derecho a apelar ante la Comisión Médica Central dentro de los 5 días hábiles de notificado.</p>
<p>RESPUESTA COMPLETA</p>
<p>Si no estás de acuerdo con la calificación que te dio la ART, tenés derecho a impugnarla. El proceso tiene pasos claros que hay que respetar dentro de los plazos.</p>
<p>📌 Derecho: Podés impugnar la resolución si considerás que tu incapacidad real es mayor a la que te asignaron.</p>
<p>⏳ Plazo: Contás con 5 días hábiles para apelar desde que te notifican la resolución.</p>
<p>📌 Trámite: Presentás un escrito con los fundamentos de tu apelación y la documentación médica que respalde tu reclamo.</p>
<p>📌  Comisión Médica Central: Es el organismo que resuelve la apelación. También podés optar por ir directamente a la justicia laboral.</p>
<p>📌  Nueva pericia: Podés solicitar una nueva evaluación médica en esta instancia.</p>
<p>📌 Consejo práctico: No dejes pasar el plazo de 5 días hábiles. Consultá con un abogado para que evalúe tu caso cuanto antes.</p>
<p>08. ¿Cuánto cuesta ir a la Comisión Médica?</p>
<p>RESPUESTA CORTA: El trámite ante la Comisión Médica es gratuito para el trabajador, no tenés que pagar aranceles.</p>
<p>RESPUESTA COMPLETA</p>
<p>El trámite ante la Comisión Médica es completamente gratuito para vos. La ley establece que no se pueden cobrar aranceles ni tasas por este servicio.</p>
<p>📌  Sin costos: No pagás aranceles, tasas ni ningún tipo de cargo por presentar tu reclamo.</p>
<p>📌  Asesoramiento legal: Podés contar con un abogado. En la mayoría de los estudios laboralistas cobra honorarios solo si ganás el reclamo, generalmente entre el 15% y el 25% de lo obtenido.</p>
<p>📄 Documentación: Sacar copias de expedientes o certificados puede tener un costo mínimo, pero es la excepción.</p>
<p>📌  Un derecho protegido: La gratuidad es un derecho del trabajador accidentado que la ley resguarda expresamente.</p>
<p>📌 Consejo práctico: La gratuidad del trámite asegura que puedas defender tus derechos sin importar tu situación económica. Aprovechá esa herramienta.</p>
<p>09. ¿Qué documentos necesito para la Comisión Médica?</p>
<p>RESPUESTA CORTA: Necesitás el formulario de la SRT, tu historia clínica, certificados médicos y tu DNI.</p>
<p>RESPUESTA COMPLETA</p>
<p>Para iniciar el trámite ante la Comisión Médica tenés que reunir la siguiente documentación:</p>
<p>📌 Formulario: El formulario de solicitud de la SRT, que conseguís en el sitio web del organismo.</p>
<p>📌  Documentos personales: DNI y CUIL vigentes.</p>
<p>📌  Historia clínica: Copia de toda tu documentación médica: historia clínica completa, informes de estudios, certificados de internación.</p>
<p>📌 Certificados: Certificados de la ART sobre la calificación de incapacidad y de tu médico tratante.</p>
<p>📌 Resoluciones: Copia de todas las resoluciones que emitió la ART sobre tu caso.</p>
<p>📌  Documentación laboral: Recibos de sueldo y contrato de trabajo, si son necesarios para calcular tu indemnización.</p>
<p>📌 Consejo práctico: Guardá los originales y sacá copias de todo. La documentación médica es la prueba más importante para respaldar tu reclamo.</p>
<p>10. ¿Cómo funciona la pericia médica?</p>
<p>RESPUESTA CORTA: Es la evaluación donde un médico especialista examina tu lesión y determina tu porcentaje de incapacidad según el baremo vigente.</p>
<p>RESPUESTA COMPLETA</p>
<p>La pericia médica es la evaluación que realiza un médico designado por la comisión para determinar tu incapacidad. Es el paso más importante del trámite.</p>
<p>📌 Examen: El médico evalúa tus lesiones y limitaciones funcionales, y realiza las pruebas clínicas necesarias.</p>
<p>📄 Documentación: Revisa tu historia clínica completa, tus estudios diagnósticos y los informes de tratamientos.</p>
<p>📌 Dictamen: Emite un informe con el porcentaje de incapacidad según el baremo vigente (Decreto 549/2025).</p>
<p>📌 Importancia: Es la base para calcular tu indemnización. El porcentaje que fije el perito define cuánto dinero vas a recibir.</p>
<p>📌 Impugnación: Si no estás de acuerdo con el dictamen, podés apelar dentro de los 5 días hábiles.</p>
<p>📌  Perito de parte: Podés llevar un médico perito propio para que emita un informe alternativo.</p>
<p>📌 Consejo práctico: Asistí a la pericia con toda tu documentación médica y describí con honestidad tus síntomas y limitaciones.</p>
<p>11. ¿Puedo elegir el médico que me evalúa?</p>
<p>RESPUESTA CORTA: No, el médico perito lo designa la Comisión Médica, vos no podés elegirlo.</p>
<p>RESPUESTA COMPLETA</p>
<p>En el sistema de la SRT, el médico perito lo designa la Comisión Médica. Vos no lo elegís directamente, pero sí tenés derechos que podés ejercer.</p>
<p>📌 Designación: La comisión nombra al médico especialista según el tipo de lesión que tenés.</p>
<p>📌 Imparcialidad: Se busca que el perito sea neutral. No puede tener vínculos con la ART ni con vos.</p>
<p>📌 Recurso: Si no estás de acuerdo con el dictamen, podés apelar ante la Comisión Médica Central.</p>
<p>📌  Perito de parte: Podés contratar un médico perito propio que emita un dictamen alternativo para respaldar tu reclamo.</p>
<p>📌 Recusación: Si el perito tiene algún vínculo con la ART, podés pedir que lo aparten del caso.</p>
<p>📌 Consejo práctico: Aunque no podés elegir al perito, tenés herramientas para garantizar que la evaluación sea imparcial. Usalas.</p>
<p>12. ¿Qué es la Comisión Médica Central?</p>
<p>RESPUESTA CORTA: Es el organismo de la SRT que revisa las decisiones de la Comisión Médica Jurisdiccional cuando apelás un dictamen.</p>
<p>RESPUESTA COMPLETA</p>
<p>La Comisión Médica Central es el organismo de la SRT que revisa las decisiones de las comisiones médicas jurisdiccionales cuando no estás de acuerdo con el dictamen. Es la última instancia administrativa antes de la vía judicial.</p>
<p>📌 Función: Revisa el dictamen de la Comisión Médica Jurisdiccional y puede confirmarlo, modificarlo o revocarlo.</p>
<p>⏳ Plazo: Tenés 5 días hábiles para apelar ante la Comisión Médica Central desde que te notifican el dictamen.</p>
<p>📌 Proceso: Se presenta un escrito con los fundamentos de la apelación y la documentación médica correspondiente.</p>
<p>📌  Nueva pericia: Puede ordenar una nueva evaluación médica si los fundamentos lo justifican.</p>
<p>📌 Resolución: Su decisión es la última instancia administrativa. Después, cualquiera de las partes puede recurrir ante la justicia.</p>
<p>📌 Alternativa: En lugar de apelar ante la Comisión Médica Central, podés optar por ir directamente a la justicia laboral ordinaria (art. 2, Ley 27.348).</p>
<p>📌 Consejo práctico: La apelación ante la Comisión Médica Central es una oportunidad real de mejorar la calificación de tu incapacidad. No la dejes pasar.</p>
<p>13. ¿Qué es la incapacidad permanente?</p>
<p>RESPUESTA CORTA: Es la que queda después de que terminaste el tratamiento y tu estado ya no mejora ni empeora.</p>
<p>RESPUESTA COMPLETA</p>
<p>La incapacidad permanente es la que queda una vez que alcanzaste la estabilidad médica y tu tratamiento terminó. Es la base para calcular tu indemnización.</p>
<p>📌 Definición: Es la pérdida definitiva de capacidad para trabajar después de alcanzar la estabilidad médica.</p>
<p>📌 Calificación: Se determina con un porcentaje según el baremo vigente (Decreto 549/2025).</p>
<p>📌  Cómo se calcula la indemnización: Con la fórmula del art. 14 de la Ley 24.557: 53 x Ingreso Base Mensual (actualizado por RIPTE) x % de incapacidad x (65/tu edad).</p>
<p>📌  Piso mínimo: El resultado nunca puede ser menor al piso mínimo que fija la SRT, actualizado semestralmente por RIPTE.</p>
<p>📌  Adicionales por incapacidad alta: Si tu incapacidad es igual o mayor al 50%, corresponde además una Compensación Adicional de Pago Único con un monto fijo que también actualiza la SRT.</p>
<p>📌 Revisión: Puede modificarse si tu condición cambia, para mejor o para peor.</p>
<p>📌 Consejo práctico: La incapacidad permanente es el momento clave que define cuánto dinero vas a recibir. Asegurate de que el porcentaje y el cálculo sean correctos antes de firmar cualquier acuerdo.</p>
<p>14. ¿Cuánto tarda la Comisión Médica en resolver?</p>
<p>RESPUESTA CORTA: El trámite puede tardar entre 4 y 6 meses en la práctica, aunque la ley fija un plazo de 60 días hábiles.</p>
<p>RESPUESTA COMPLETA</p>
<p>Los tiempos de la Comisión Médica varían según la jurisdicción y la carga de expedientes. La ley establece plazos que deberían respetarse.</p>
<p>📌  Plazo legal: La Comisión Médica debe resolver en 60 días hábiles administrativos, prorrogables por única vez hasta 30 días hábiles más cuando hace falta producir prueba (art. 3, Ley 27.348 y Resolución SRT 5/2026).</p>
<p>📌  Plazo real: En la práctica, el trámite puede tomar de 3 a 6 meses según la jurisdicción y la carga de trabajo de cada comisión.</p>
<p>📌 Factores: La congestión de expedientes, la disponibilidad de médicos peritos y la complejidad del caso pueden demorar la resolución.</p>
<p>📌 Seguimiento: Es importante hacer seguimiento constante del expediente para conocer su estado real.</p>
<p>📌  Si se vence el plazo: Si la Comisión Médica no resuelve en el plazo legal, podés apelar o llevar el caso a la justicia laboral.</p>
<p>📌 Consejo práctico: No te desanimes si el trámite tarda. Es clave mantener el seguimiento del expediente y la documentación al día.</p>
<p>15. ¿Puedo ir a la Comisión Médica sin abogado?</p>
<p>CATEGORÍA: Comisión Médica</p>
<p>RESPUESTA CORTA: Para la impugnación inicial del alta podés ir solo, pero para el reclamo de incapacidad y las apelaciones el patrocinio letrado es obligatorio.</p>
<p>RESPUESTA COMPLETA</p>
<p>Depende de la etapa del trámite. Para la presentación inicial de una divergencia en el alta, en los primeros 5 días hábiles, la normativa no exige de manera obligatoria contar con abogado. Pero para el reclamo de determinación de incapacidad y para las apelaciones, el patrocinio letrado es obligatorio en las provincias adheridas a la Ley 27.348, que hoy son la gran mayoría.</p>
<p>📌  Cuándo es obligatorio: En las provincias adheridas a la Ley 27.348 (entre ellas CABA, Buenos Aires, Córdoba, Santa Fe, Neuquén, Entre Ríos y Río Negro), necesitás patrocinio letrado desde el reclamo de incapacidad.</p>
<p>📌  Honorarios a cargo de la ART: Si no tenés abogado, podés pedir que te asignen uno: sus honorarios están a cargo de la ART (art. 37, Res. SRT 298/2017).</p>
<p>📌  Riesgo de ir sin asesoramiento: Sin experiencia en el sistema de riesgos del trabajo, podés perder derechos o no saber cómo fundamentar correctamente tu reclamo.</p>
<p>⏳ Plazos: Un abogado se asegura de que no pierdas plazos clave, como los 5 días hábiles para apelar un dictamen o un alta.</p>
<p>📄 Documentación: Un abogado sabe exactamente qué documentación presentar y cómo fundamentar tu reclamo frente a la ART.</p>
<p>📌 Consejo práctico: Aunque en algunos pasos no sea obligatorio, el asesoramiento legal aumenta significativamente tus posibilidades de que el porcentaje que te asignen sea justo.</p>
<p>16. ¿Qué es el dictamen de la Comisión Médica?</p>
<p>RESPUESTA CORTA: Es la resolución oficial donde determinan tu porcentaje de incapacidad y los derechos que te corresponden.</p>
<p>RESPUESTA COMPLETA</p>
<p>El dictamen de la Comisión Médica es la resolución oficial donde se fija tu porcentaje de incapacidad y la indemnización que te corresponde.</p>
<p>📌 Contenido: Establece el porcentaje de incapacidad que te asignan según la evaluación médica realizada.</p>
<p>📌 Derechos: Determina la indemnización que te corresponde según la fórmula del art. 14 de la Ley 24.557.</p>
<p>📌 Notificación: Tienen que notificarte formalmente del dictamen para que puedas ejercer tu derecho a apelar.</p>
<p>📌 Apelación: Si no estás conforme, podés apelar ante la Comisión Médica Central dentro de los 5 días hábiles.</p>
<p>📌 Vinculante: El dictamen es vinculante para las partes, salvo que sea apelado dentro del plazo.</p>
<p>📌 Efectos: Una vez firme, y homologado el acuerdo o la resolución, la ART tiene que depositarte la indemnización dentro de los 5 días hábiles siguientes a la notificación de la homologación.</p>
<p>📌 Consejo práctico: Revisá cuidadosamente el dictamen y verificá que el porcentaje respete el baremo vigente. Si no es así, apelá dentro del plazo.</p>
<p>27. ¿Cuánto me pagan por un 10% de incapacidad?</p>
<p>CATEGORÍA: Comisión Médica</p>
<p>RESPUESTA CORTA: Depende de tu salario y tu edad, pero la ley garantiza un piso mínimo que hoy equivale a $9.750.242 para un 10% de incapacidad.</p>
<p>RESPUESTA COMPLETA</p>
<p>El monto de la indemnización por un 10% de incapacidad varía según tu ingreso base y tu edad. Se calcula con la fórmula del art. 14 de la Ley 24.557, pero nunca puede ser inferior al piso mínimo que fija la SRT.</p>
<p>📌 Fórmula: 53 x Ingreso Base Mensual (actualizado por RIPTE) x % de incapacidad x (65/tu edad).</p>
<p>📌  Piso mínimo vigente: Para contingencias entre el 1° de marzo y el 31 de agosto de 2026, el piso es de $97.502.420 por el grado de incapacidad (Resolución SRT 15/2026). Para un 10%, eso equivale a $9.750.242, y la ART tiene que pagarte ese monto si es mayor al que da la fórmula.</p>
<p>📌  Adicional del 20%: Si se trata de un accidente de trabajo o enfermedad profesional (no in itinere), se suma un 20% adicional sobre el resultado de la fórmula o el piso, el que sea mayor (art. 3, Ley 26.773).</p>
<p>📌  Actualización semestral: Tanto el piso mínimo como el ingreso base se actualizan por RIPTE, así que el monto exacto depende de la fecha de tu accidente.</p>
<p>📌 Impugnación: Si considerás que tu incapacidad real es mayor al 10%, podés apelar ante la Comisión Médica Central.</p>
<p>📌 Consejo práctico: Usá una calculadora actualizada o consultá con un abogado para obtener el cálculo preciso de lo que te corresponde, considerando el piso mínimo vigente al momento de tu accidente.</p>
<p>18. ¿Qué hago si la ART no me da el tratamiento que necesito?</p>
<p>CATEGORÍA: Comisión Médica</p>
<p>RESPUESTA CORTA: Podés reclamar ante la Comisión Médica para que ordene a la ART que te dé el tratamiento.</p>
<p>RESPUESTA COMPLETA</p>
<p>Si la ART te niega un tratamiento necesario, tenés derecho a reclamar ante la Comisión Médica para que la obligue a brindarte la atención que necesitás.</p>
<p>📌 Derecho: Tenés derecho a recibir todo tratamiento médico, quirúrgico y de rehabilitación que indique tu médico tratante.</p>
<p>📢 Reclamo: Presentá el reclamo ante la Comisión Médica Jurisdiccional con los informes médicos que justifiquen la necesidad del tratamiento.</p>
<p>📄 Documentación: Adjuntá los informes de tu médico tratante, de especialistas y cualquier otro respaldo de la necesidad del tratamiento.</p>
<p>📌  Medida urgente: En casos urgentes, podés pedir que se resuelva de manera prioritaria para que el tratamiento se inicie de inmediato.</p>
<p>📌 Incumplimiento: Si la ART no cumple con lo ordenado, la SRT puede sancionarla.</p>
<p>📌 Consejo práctico: No dejes que la ART te niegue un tratamiento necesario. Reclamá ante la Comisión Médica con toda la documentación médica que tengas.</p>
<p>19. ¿Qué es la ART y cómo me afecta?</p>
<p>RESPUESTA CORTA: La ART es la Aseguradora de Riesgos del Trabajo que tiene que cubrir tus gastos médicos y pagarte la indemnización por incapacidad.</p>
<p>RESPUESTA COMPLETA</p>
<p>La ART es la aseguradora que tu empleador contrató para cubrirte contra accidentes laborales y enfermedades profesionales.</p>
<p>📌 Función: Tiene que cubrir tu tratamiento médico y pagarte la indemnización por incapacidad permanente.</p>
<p>📌 Obligaciones: Brindarte asistencia médica completa, pagarte el subsidio por incapacidad temporaria, y depositarte la indemnización dentro de los 5 días hábiles siguientes a la homologación del acuerdo o resolución.</p>
<p>📌 Derechos: Podés reclamar si la ART no cumple con sus obligaciones, ante la Comisión Médica o ante la justicia.</p>
<p>📌 Control: La SRT (Superintendencia de Riesgos del Trabajo) supervisa a las ART y puede sancionarlas.</p>
<p>📌 Solidaridad: Tu empleador es responsable solidario si la ART no cumple con sus obligaciones.</p>
<p>📌 Consejo práctico: Si la ART no cumple con sus obligaciones, no dudes en reclamar. La SRT y la Comisión Médica están para ayudarte.</p>
<p>20. ¿Puedo cambiar de médico tratante?</p>
<p>RESPUESTA CORTA: Sí, podés pedir el cambio de médico tratante ante la ART, pero tiene que estar justificado.</p>
<p>RESPUESTA COMPLETA</p>
<p>Tenés derecho a solicitar el cambio de médico tratante ante la ART si tenés motivos justificados para hacerlo.</p>
<p>📌 Derecho: Podés pedir el cambio si el médico actual no te brinda una atención adecuada, no confiás en su diagnóstico, o hay un conflicto de intereses.</p>
<p>📌 Solicitud: Presentá el pedido ante la ART por escrito, explicando los motivos del cambio.</p>
<p>📌 Evaluación: La ART va a evaluar tu solicitud y debe responder en un plazo razonable.</p>
<p>📌  Si te lo rechazan: Si la ART te niega el cambio sin justificación, podés reclamar ante la Comisión Médica.</p>
<p>📌  Segunda opinión: Podés pedir una segunda opinión médica si no estás conforme con el diagnóstico.</p>
<p>📌 Consejo práctico: El cambio de médico tratante es un derecho tuyo. Si no te sentís bien atendido, reclamá.</p>
<p>21. ¿Qué hago si la ART me da de alta sin estar curado?</p>
<p>RESPUESTA CORTA: No aceptes el alta: presentá la divergencia ante la Comisión Médica dentro de los 5 días hábiles, con tus informes médicos.</p>
<p>RESPUESTA COMPLETA</p>
<p>Si la ART te da el alta y seguís con dolor o limitaciones, no la aceptes: presentá el trámite de divergencia con toda tu documentación médica.</p>
<p>📌  No la aceptes: El alta no es definitiva mientras esté dentro de plazo para impugnarla.</p>
<p>📌  Plazo perentorio: Tenés 5 días hábiles para impugnar el alta ante la Comisión Médica (Resolución SRT 5/2026), contados desde la notificación fehaciente.</p>
<p>📢 Reclamo: Presentá el trámite de divergencia ante la Comisión Médica Jurisdiccional con todos tus informes médicos.</p>
<p>📄 Documentación: Adjuntá informes de tu médico tratante, especialistas y estudios que demuestren que seguís con secuelas.</p>
<p>📌  Mientras se resuelve: Si presentás la divergencia dentro del plazo, el alta queda en suspenso y seguís cobrando el subsidio por incapacidad temporaria.</p>
<p>📌 Asesoramiento: Consultá con un abogado especialista para que te acompañe en el trámite.</p>
<p>📌 Consejo práctico: El alta médica no es definitiva si la impugnás dentro del plazo. No dejes pasar los 5 días hábiles.</p>
<p>22. ¿Qué es la incapacidad total y permanente?</p>
<p>RESPUESTA CORTA: Es la más grave del sistema: se da cuando tu incapacidad alcanza o supera el 66% y te impide trabajar.</p>
<p>RESPUESTA COMPLETA</p>
<p>La incapacidad laboral permanente total (ILPT) es la más grave del sistema. Se configura cuando el propio baremo clasifica tu lesión como Total y el porcentaje alcanza o supera el 66%.</p>
<p>📌 Porcentaje: Se da cuando el daño alcanza o supera el 66%, siempre que la tabla del Decreto 549/2025 clasifique esa lesión específica como Total. Si tu lesión está clasificada como Parcial, el porcentaje queda topado en 65,99% aunque los factores de ponderación por edad y actividad sumen más.</p>
<p>📌 Consecuencia: Te incapacita para toda actividad laboral, sin posibilidad de reincorporación.</p>
<p>📌 Indemnización: Se calcula con la fórmula del art. 14 de la Ley 24.557 al 100%, más el piso mínimo vigente ($97.502.420 para contingencias entre marzo y agosto de 2026), más la Compensación Adicional de Pago Único correspondiente a incapacidad total.</p>
<p>📌  Renta mensual: Además de la indemnización de pago único, corresponde una prestación de pago mensual mientras dure la incapacidad.</p>
<p>📌  Asistencia médica: La ART tiene que brindarte asistencia médica de por vida.</p>
<p>📌  Gran invalidez: Si necesitás ayuda de otra persona para tus actos elementales de la vida diaria, corresponde una prestación adicional por gran invalidez.</p>
<p>📌 Consejo práctico: En casos de incapacidad total, es fundamental contar con un abogado especializado que gestione todos los reclamos y verifique cada ítem de la liquidación.</p>
<p>23. ¿Cómo se calcula la incapacidad?</p>
<p>RESPUESTA CORTA: Según la tabla oficial de la SRT, tomando en cuenta tu lesión, tu edad y cómo afecta tu actividad laboral.</p>
<p>RESPUESTA COMPLETA</p>
<p>El cálculo de tu incapacidad considera varios factores que influyen en el porcentaje final que te asignan.</p>
<p>📌  Tabla oficial: Se usa el Anexo del Decreto 549/2025 (Baremo 2026) como referencia principal, organizado por capítulos según cada órgano o sistema del cuerpo.</p>
<p>📌 Lesión: Se evalúa la lesión específica: tipo, gravedad, ubicación y secuelas, con un valor fijo para cada una.</p>
<p>📌 Edad: Influye como factor de ponderación (entre 2% y 5% según tu tramo etario) que se suma al porcentaje de la lesión, y también en el cálculo de la indemnización mediante el coeficiente 65/edad.</p>
<p>📌 Actividad: El impacto de la lesión en tus tareas habituales suma un factor de ponderación de 5%, 10% o 20% según el grado de dificultad.</p>
<p>📌 Ganancia: Tu salario se usa para calcular el monto de la indemnización, no el porcentaje de incapacidad.</p>
<p>📌  Estabilidad médica: Se evalúa cuándo tu estado de salud dejó de cambiar significativamente, momento en que se fija el porcentaje definitivo.</p>
<p>📌 Consejo práctico: Cada caso es único. Un abogado puede ayudarte a que el porcentaje refleje correctamente tu situación real, incluidos los factores de ponderación.</p>
<p>24. ¿Qué pasa si no me presento a la Comisión Médica?</p>
<p>RESPUESTA CORTA: Se considera que desististe de tu reclamo y la ART queda liberada de pagar, salvo que justifiques la ausencia.</p>
<p>RESPUESTA COMPLETA</p>
<p>Si no te presentás a la Comisión Médica sin justificación, se considera que desististe de tu reclamo de incapacidad.</p>
<p>📌 Consecuencia: Se entiende que desististe de tu reclamo de incapacidad.</p>
<p>📌 ART: La aseguradora queda liberada de pagar la indemnización por incapacidad permanente mientras dure ese desistimiento.</p>
<p>📌 Reposición: Podés pedir la reposición del trámite si tenés justificación (enfermedad, emergencia, etc.).</p>
<p>⏳ Plazo: La reposición hay que pedirla dentro de un plazo razonable después de la inasistencia.</p>
<p>📄 Documentación: Necesitás presentar pruebas que justifiquen tu ausencia.</p>
<p>📌 Consejo práctico: Si no podés asistir a una citación, notificá a la comisión médica con anticipación y justificá tu inasistencia.</p>
<p>25. ¿Puedo pedir una segunda opinión médica?</p>
<p>RESPUESTA CORTA: Sí, podés solicitar una revisión médica o llevar un perito propio si no confiás en el dictamen.</p>
<p>RESPUESTA COMPLETA</p>
<p>Tenés derecho a buscar una segunda opinión médica si no confiás en el diagnóstico de la ART o en el dictamen de la Comisión Médica.</p>
<p>📌 Derecho: Podés pedir una revisión ante la Comisión Médica Jurisdiccional si no estás conforme con el diagnóstico o la calificación.</p>
<p>📌 Proceso: Se presenta un nuevo reclamo con documentación médica que fundamente tu disconformidad.</p>
<p>📌 Evaluación: Un nuevo médico perito te va a evaluar y va a emitir un dictamen.</p>
<p>📌 Importancia: Es un mecanismo de protección que ayuda a asegurar la imparcialidad del diagnóstico.</p>
<p>📌  Perito de parte: También podés contratar un médico perito propio para que emita su propio informe.</p>
<p>📌 Apelación: Si la segunda opinión te favorece, podés usarla como fundamento para apelar el dictamen original.</p>
<p>📌 Consejo práctico: No dudes en pedir una segunda opinión si no estás conforme con el diagnóstico. Es tu derecho.</p>
<p>26. ¿Qué hago si la ART no me paga la indemnización?</p>
<p>RESPUESTA CORTA: Presentá el reclamo ante la Comisión Médica y, si no resuelven, podés ir a juicio.</p>
<p>RESPUESTA COMPLETA</p>
<p>Si la ART no te paga la indemnización que te corresponde, tenés varias opciones legales para reclamar.</p>
<p>📢 Reclamo: Presentá el reclamo ante la Comisión Médica Jurisdiccional documentando el incumplimiento.</p>
<p>⏳ Plazo: La Comisión Médica debe resolver en 60 días hábiles.</p>
<p>📌 Escalada: Si no resuelven a tu favor, podés apelar ante la Comisión Médica Central dentro de los 5 días hábiles.</p>
<p>📌 Juicio: Como último recurso, podés iniciar un juicio ante la justicia laboral.</p>
<p>📌 Intereses: Te corresponden intereses sobre la indemnización adeudada desde la fecha en que debió pagarse.</p>
<p>📌  Medida cautelar: Tu abogado puede pedir una medida cautelar para que el juez ordene el pago inmediato en casos urgentes.</p>
<p>📌 Consejo práctico: No dejes que la ART ignore tu reclamo. Actuá con un abogado para hacer valer tus derechos.</p>
<p>27. ¿Qué es la prescripción en los accidentes de trabajo?</p>
<p>RESPUESTA CORTA: Es el tiempo que tenés para reclamar: 2 años desde el accidente o desde el diagnóstico.</p>
<p>RESPUESTA COMPLETA</p>
<p>La prescripción es el plazo que tenés para ejercer tu derecho a reclamar. Si lo dejás vencer sin iniciar acciones, perdés el derecho.</p>
<p>⏳ Plazo: 2 años desde el accidente de trabajo o desde que tomaste conocimiento de la enfermedad profesional (art. 44, Ley 24.557).</p>
<p>📌 Inicio: Se cuenta desde la fecha del accidente o desde el momento en que pudiste ejercer el derecho, por ejemplo, al conocer el diagnóstico.</p>
<p>📌 Suspensión: El plazo se suspende mientras la ART te esté pagando prestaciones o mientras estés bajo tratamiento.</p>
<p>📌 Importancia: Si el plazo vence, perdés el derecho a reclamar la indemnización.</p>
<p>📌 Recomendación: Reclamá lo antes posible. No dejes que el tiempo pase sin actuar.</p>
<p>📌 Consejo práctico: Consultá con un abogado lo antes posible para que evalúe si tu caso todavía está dentro del plazo legal.</p>
<p>28. ¿Qué es el cese de la relación laboral y cómo afecta mi reclamo?</p>
<p>RESPUESTA CORTA: Es cuando termina tu vínculo de trabajo, pero no perdés el derecho a la indemnización por incapacidad.</p>
<p>RESPUESTA COMPLETA</p>
<p>El cese de la relación laboral es la finalización del contrato de trabajo, pero no implica la pérdida de tus derechos a reclamar la indemnización.</p>
<p>📌 Definición: Es la terminación del vínculo laboral por cualquier causa (despido, renuncia, fin de contrato, etc.).</p>
<p>📌 Derechos: No perdés el derecho a la indemnización por incapacidad permanente, incluso si ya no trabajás para esa empresa.</p>
<p>⏳ Plazo: Tenés 2 años para reclamar desde el alta médica definitiva o desde la resolución que fija tu incapacidad.</p>
<p>📄 Documentación: Es fundamental documentar todo: constancia de la baja, recibos de sueldo, certificados médicos.</p>
<p>📌  No lo confundas: El cese de la relación laboral y la prescripción son conceptos distintos.</p>
<p>📌 Consejo práctico: El cese de la relación laboral no extingue tus derechos como trabajador accidentado. Consultá con un abogado para que evalúe tu caso.</p>
<p>29. ¿Qué hago si la ART me rechaza la cobertura?</p>
<p>RESPUESTA CORTA: Podés llevar el caso a la Comisión Médica Jurisdiccional para que determine si el accidente es laboral.</p>
<p>RESPUESTA COMPLETA</p>
<p>Si la ART rechaza tu accidente o enfermedad, tenés derecho a que la Comisión Médica Jurisdiccional revise si corresponde considerarlo una contingencia laboral.</p>
<p>📌 Trámite: El rechazo o el silencio de la ART habilita el trámite ante la Comisión Médica Jurisdiccional para que determine la naturaleza laboral del hecho.</p>
<p>📌  Plazo de la comisión: Tiene 60 días hábiles administrativos para resolver, prorrogables hasta 30 días hábiles más si hace falta producir prueba.</p>
<p>📄 Documentación: Adjuntá todos los respaldos médicos que demuestren la relación entre tu lesión y tu actividad laboral.</p>
<p>📌 Asesoramiento: Consultá con un abogado especialista para que presente tu caso correctamente.</p>
<p>📌  Si te siguen rechazando: Podés apelar ante la Comisión Médica Central dentro de los 5 días hábiles del dictamen, o ir directamente a la justicia laboral.</p>
<p>📌 Consejo práctico: No aceptes un rechazo sin cuestionarlo. Muchas veces la Comisión Médica termina reconociendo el carácter laboral del accidente.</p>
<p>30. ¿Qué es la tabla de incapacidades de la SRT?</p>
<p>RESPUESTA CORTA: Es el documento oficial (Baremo 2026) que establece el porcentaje de incapacidad para cada tipo de lesión.</p>
<p>RESPUESTA COMPLETA</p>
<p>La tabla de incapacidades, o baremo, es el documento oficial que establece el porcentaje de incapacidad para cada tipo de lesión. Es la referencia obligatoria para calcular tu indemnización.</p>
<p>📌 Contenido: Establece porcentajes fijos para cada tipo de lesión: columna, hombro, rodilla, mano y muchas otras, organizados por capítulos según cada sistema del cuerpo.</p>
<p>📌 Uso: La usan las Comisiones Médicas y los juzgados laborales de todo el país para calificar tu incapacidad.</p>
<p>📌  Norma vigente: Desde el 1° de febrero de 2026 rige el baremo del Anexo del Decreto 549/2025, que reemplazó al que estaba vigente desde 1996.</p>
<p>📌  Porcentaje único: Cada lesión tiene un valor fijo, sin los rangos variables que existían antes.</p>
<p>📌  Factor de ponderación: A ese porcentaje se le suma un incremento por edad y por el impacto en tu actividad laboral.</p>
<p>📌 Consulta: Podés consultar la tabla actualizada en nuestro sitio para ver el porcentaje que corresponde a tu lesión.</p>
<p>📌 Consejo práctico: La tabla de incapacidades es la base para determinar cuánto dinero recibís. Verificá que el porcentaje que te asignaron sea el correcto según el baremo vigente.</p>
<p>31. ¿Puedo seguir trabajando mientras estoy en tratamiento con la ART?</p>
<p>RESPUESTA CORTA: Depende de tu estado médico. Si te autorizan a trabajar, podés hacerlo, respetando las indicaciones médicas.</p>
<p>RESPUESTA COMPLETA</p>
<p>La posibilidad de trabajar mientras estás en tratamiento con la ART depende de tu estado médico y de las indicaciones de tu médico tratante.</p>
<p>📌 Evaluación: El médico es quien determina si podés trabajar y en qué condiciones.</p>
<p>📌 Restricciones: Pueden indicarte tareas livianas, prohibición de levantar peso o jornada reducida.</p>
<p>📌 Autorización: Tienen que autorizarte formalmente antes de que retomes tus tareas.</p>
<p>📌 Importancia: Respetá las indicaciones médicas. Trabajar en contra de lo indicado puede empeorar tu lesión.</p>
<p>📌  Si te presionan: Si la ART o tu empleador te obligan a trabajar antes de tiempo, reclamá ante la Comisión Médica.</p>
<p>📌 Consejo práctico: No retomes tus tareas sin autorización médica. Si te sentís presionado, consultá con un abogado.</p>
<p>32. ¿Qué es la estabilización de la lesión?</p>
<p>RESPUESTA CORTA: Es cuando tu estado de salud ya no mejora ni empeora y se considera definitivo.</p>
<p>RESPUESTA COMPLETA</p>
<p>La estabilización de la lesión, o consolidación médica, es el momento clave en que tu estado de salud se considera definitivo. Ahí se fija el porcentaje de incapacidad permanente.</p>
<p>📌 Definición: Tu estado de salud deja de mejorar o empeorar de forma significativa.</p>
<p>📌 Calificación: Se fija el porcentaje de incapacidad permanente según el baremo vigente.</p>
<p>📌 Indemnización: Se calcula el monto de la indemnización con el porcentaje definitivo.</p>
<p>📌 Revisión: Si empeorás después de la estabilidad, podés pedir una revisión ante la Comisión Médica.</p>
<p>⏳ Tiempo: No hay un plazo fijo para alcanzar la estabilidad médica. Depende de tu lesión y tu tratamiento.</p>
<p>📌 Consejo práctico: La estabilización es el momento más importante del proceso. Asegurate de que el porcentaje que te asignen en ese momento sea justo.</p>
<p>33. ¿Qué es la SRT y qué controla?</p>
<p>RESPUESTA CORTA: Es la Superintendencia de Riesgos del Trabajo, que supervisa a las ART y protege a los trabajadores accidentados.</p>
<p>RESPUESTA COMPLETA</p>
<p>La SRT es la Superintendencia de Riesgos del Trabajo, el organismo que regula todo el sistema de seguridad social por accidentes y enfermedades laborales en Argentina.</p>
<p>📌 Función: Supervisa a las ART para que cumplan con sus obligaciones legales.</p>
<p>📌 Control: Verifica que las ART brinden asistencia médica, paguen las indemnizaciones y cumplan con la normativa vigente, incluido el baremo del Decreto 549/2025.</p>
<p>📌 Protección: Vela por los derechos de los trabajadores accidentados en todo el país.</p>
<p>📌  Organismos a su cargo: Regula a las Comisiones Médicas Jurisdiccionales y a la Comisión Médica Central.</p>
<p>📌 Sanciones: Puede imponer sanciones a las ART que no cumplan con sus obligaciones.</p>
<p>📌 Normativa: Dicta resoluciones que actualizan periódicamente los pisos mínimos, las compensaciones adicionales y otros aspectos del sistema.</p>
<p>📌 Consejo práctico: La SRT es tu aliada en la defensa de tus derechos. Si la ART no cumple, podés reclamar ante la superintendencia.</p>
<p>Fuentes normativas utilizadas</p>
<p>CIRUGÍA ART</p>
<p>1 ¿La ART me cubre una cirugía?</p>
<p>En síntesis: Sí, la ART tiene que cubrir todas las cirugías necesarias para tratar tu lesión laboral.</p>
<p>Sí. La ART tiene la obligación legal de cubrir todas las cirugías necesarias para tratar tu accidente de trabajo o enfermedad profesional. Esto está en el artículo 11 de la Ley 24.557 (LRT), que establece las prestaciones en especie, incluida la asistencia quirúrgica completa.</p>
<p>📌 Cobertura total: La ART tiene que pagar la cirugía, la anestesia, la internación, los honorarios médicos, el material de osteosíntesis y todo lo que la intervención requiera.</p>
<p>📌 Autorización previa: Necesitás la autorización escrita de la ART antes de operarte. Tu médico tratante la solicita con los informes correspondientes.</p>
<p>📌 Designación médica: Generalmente la ART designa al cirujano y la clínica. Si no autoriza, podés reclamar ante la Comisión Médica.</p>
<p>📌 Urgencia: Si hay riesgo para tu salud, podés operarte sin esperar la autorización y reclamar la cobertura después.</p>
<p>📌 Consejo práctico: No te quedes sin la cirugía que necesitás por un trámite administrativo. Si la ART demora o niega la autorización, presentá el reclamo ante la Comisión Médica Jurisdiccional y consultá con un abogado.</p>
<p>CIRUGÍA ART</p>
<p>2 ¿Necesito autorización de la ART para operarme?</p>
<p>En síntesis: Sí, salvo urgencia, la ART tiene que autorizar la cirugía antes de que te operes.</p>
<p>Sí, la autorización previa de la ART es obligatoria para cualquier cirugía dentro del sistema de riesgos del trabajo. Este requisito surge del artículo 11 de la LRT y de las normas de procedimiento de la SRT.</p>
<p>📌 Solicitud: Tu médico tratante pide la autorización por escrito, con informes médicos, estudios complementarios y la justificación de la cirugía.</p>
<p>📌 Respuesta de la ART: La ART tiene que responder en un plazo razonable y con un dictamen fundado. Si demora en exceso o no responde, podés reclamar ante la Comisión Médica.</p>
<p>📌 Urgencia: Si tu vida o tu integridad física están en riesgo, podés operarte sin esperar la autorización. Guardá todos los comprobantes.</p>
<p>📌 Negativa injustificada: Si la ART niega la cirugía sin fundamento médico, podés impugnar esa decisión.</p>
<p>📌 Consejo práctico: No te operes sin autorización salvo que sea una urgencia real: sin ese respaldo, tu reclamo posterior se complica. Si la ART no responde o niega sin justificación, reclamá ante la Comisión Médica.</p>
<p>CIRUGÍA ART</p>
<p>3 ¿Qué pasa si la ART no autoriza la cirugía?</p>
<p>En síntesis: Podés reclamar ante la Comisión Médica Jurisdiccional para que ordene la autorización.</p>
<p>Si la ART no autoriza la cirugía que indicó tu médico, tenés herramientas concretas para revertirlo. La ART no puede negar un tratamiento quirúrgico necesario y eficaz para tu recuperación sin fundamento médico.</p>
<p>📌 Reclamo ante la Comisión Médica: Es la instancia previa y obligatoria (Ley 27.348). Presentá el reclamo cuanto antes, con todos los informes médicos que justifiquen la cirugía.</p>
<p>📌 Documentación completa: Sumá radiografías, resonancias, electromiografías, informes del médico tratante y cualquier otro estudio relevante.</p>
<p>📌 Urgencia: Si la cirugía es urgente y la ART no autoriza, operate y reclamá la cobertura después. No arriesgues tu salud por un trámite.</p>
<p>📌   Asesoramiento legal: Un abogado especialista en accidentes de trabajo puede acelerar el reclamo y, si hace falta, iniciar acciones judiciales.</p>
<p>📌 Consejo práctico: La Comisión Médica puede ordenarle a la ART que autorice la cirugía, y si esa decisión tampoco te favorece, podés apelar ante la Justicia Federal. No te quedes de brazos cruzados: tenés 2 años de plazo para reclamar (art. 44, Ley 24.557).</p>
<p>CIRUGÍA ART</p>
<p>4 ¿Puedo elegir el cirujano?</p>
<p>En síntesis: Generalmente la ART designa al cirujano y la clínica, pero podés pedir un cambio con motivos justificados.</p>
<p>En el sistema de ART, lo habitual es que la aseguradora designe al cirujano y la clínica donde te vas a operar, buscando controlar costos. Pero esa designación nunca puede perjudicar la calidad de tu atención médica.</p>
<p>📌 Designación por la ART: Es la regla general, pero no es absoluta: si hay motivos válidos, podés cuestionarla.</p>
<p>📌 Solicitud de cambio: Si el cirujano no te genera confianza, hay conflicto de interés o la clínica no tiene el equipamiento necesario, pedí el cambio por escrito.</p>
<p>📌 Revisión ante la Comisión Médica: Si la ART niega el cambio, podés reclamar ante la Comisión Médica, que evalúa si tu pedido es razonable.</p>
<p>📌 Casos complejos: En lesiones de alta complejidad donde la ART no tiene un especialista adecuado, tu médico puede pedir un cirujano específico.</p>
<p>📌 Consejo práctico: Tu derecho a una atención médica de calidad está por encima de las consideraciones económicas de la ART. Si el cirujano asignado no es especialista en tu tipo de lesión, reclamá un profesional idóneo.</p>
<p>CIRUGÍA ART</p>
<p>5 ¿Cuánto tarda la ART en autorizar una cirugía?</p>
<p>En síntesis: No hay un plazo fijo en la ley para la autorización quirúrgica, pero la ART tiene que responder en tiempo razonable y sin dilaciones injustificadas.</p>
<p>La LRT no fija un número de días puntual para autorizar una cirugía, pero exige que la ART cumpla con las prestaciones en especie de forma oportuna (art. 11, LRT). Una demora irrazonable es en sí misma un incumplimiento que podés reclamar.</p>
<p>📌 Sin excusas administrativas: La ART no puede demorar la autorización por cuestiones de trámite interno mientras tu salud se sigue deteriorando.</p>
<p>📌 Casos urgentes: Si hay riesgo para tu salud o integridad, la respuesta tiene que ser inmediata.</p>
<p>📌 Seguimiento constante: Hacé seguimiento de tu solicitud: llamá, mandá mails y guardá constancia de cada comunicación con fecha y hora.</p>
<p>📌 Reclamo por demora: Si la ART se toma un tiempo irrazonable, presentá el reclamo ante la Comisión Médica Jurisdiccional.</p>
<p>📌 Consejo práctico: No dejes que la demora sea la forma que encuentra la ART para no cubrir tu cirugía. Documentá cada gestión: esa prueba es clave si después tenés que reclamar.</p>
<p>CIRUGÍA ART</p>
<p>6 ¿Qué cirugías cubre la ART?</p>
<p>En síntesis: Todas las que sean médicamente necesarias para tratar tu lesión laboral, desde reconstructivas hasta prótesis.</p>
<p>La ART cubre todo tipo de cirugía que esté médicamente indicada para tratar tu accidente de trabajo o enfermedad profesional. Están contempladas en el artículo 11 de la LRT como prestaciones obligatorias.</p>
<p>📌 Reconstructivas: Para huesos, articulaciones, tendones, ligamentos y tejidos blandos: osteosíntesis, suturas tendinosas, reconstrucciones ligamentosas.</p>
<p>📌 Protésicas: Colocación de prótesis de cadera, rodilla, hombro, mano u otras articulaciones, de buena calidad.</p>
<p>📌 Rehabilitadoras: Liberaciones de tendones, artroscopias, descompresiones nerviosas, para recuperar la funcionalidad perdida.</p>
<p>📌 Reconstructivas estéticas: En cicatrices visibles resultado del accidente que afectan tu imagen.</p>
<p>📌 Consejo práctico: La ART no puede negar ninguna cirugía que sea médicamente necesaria. Si tu médico la indica, tiene que autorizarla; si no lo hace, es un caso claro para reclamar.</p>
<p>CIRUGÍA ART</p>
<p>7 ¿Puedo operarme en una clínica privada?</p>
<p>En síntesis: Generalmente la ART te deriva a una clínica conveniada, pero en algunos casos podés pedir otra.</p>
<p>Lo habitual es que la ART te derive a un centro de su cartilla de prestadores. Sin embargo, existen situaciones donde podés pedir operarte en otro lugar sin perder la cobertura.</p>
<p>📌 Cartilla de la ART: La ART trabaja con clínicas y sanatorios con los que tiene convenio, y normalmente te asigna uno de esos centros.</p>
<p>📌 Solicitud de cambio: Si la clínica asignada no tiene el equipamiento adecuado, no cuenta con el especialista que necesitás o queda muy lejos, podés pedir el cambio.</p>
<p>📌 Centro no conveniado: Si la ART no tiene opciones adecuadas en tu zona, podés operarte en un centro no conveniado; la ART debería cubrir el costo, aunque esto puede generar discusiones.</p>
<p>📢 Reclamo: Si la clínica no es adecuada, presentá el reclamo por escrito ante la ART y, si no responde, ante la Comisión Médica.</p>
<p>📌 Consejo práctico: Lo importante es que la clínica tenga el equipo médico idóneo para tu cirugía. No aceptes un centro que no cumpla esos requisitos solo porque a la ART le resulta más barato.</p>
<p>CIRUGÍA ART</p>
<p>8 ¿Qué pasa si la cirugía sale mal?</p>
<p>En síntesis: La ART debe cubrir el tratamiento correctivo, y si hubo mala praxis, podés reclamar daños y perjuicios.</p>
<p>Si tu cirugía presenta complicaciones, la ART sigue teniendo obligaciones concretas con vos. No es un capítulo cerrado: es parte del mismo tratamiento que la ART tiene que garantizar.</p>
<p>📌 Tratamiento correctivo: La ART tiene que cubrir cualquier cirugía correctiva, rehabilitación adicional o tratamiento derivado de la complicación.</p>
<p>📌 Responsabilidad médica: Si la complicación se debió a mala praxis del cirujano designado por la ART, podés iniciar una acción por daños, y la ART puede ser corresponsable por haberlo designado.</p>
<p>📄 Documentación: Guardá todos los informes médicos, informes de la complicación, estudios posteriores y facturas: son tu prueba principal.</p>
<p>📌 Seguimiento post-operatorio: La ART tiene que garantizar el seguimiento y cubrir todos los tratamientos necesarios para resolver la complicación.</p>
<p>📌 Consejo práctico: Consultá con un abogado especialista lo antes posible: las acciones por daños tienen plazo de prescripción. No firmes nada con la ART sin asesorarte primero.</p>
<p>CIRUGÍA ART</p>
<p>9 ¿La ART cubre la rehabilitación después de la cirugía?</p>
<p>En síntesis: Sí, la ART tiene que cubrir toda la rehabilitación necesaria después de la cirugía.</p>
<p>Sí. La rehabilitación post-operatoria es parte inseparable de la cobertura quirúrgica. Según el artículo 11 de la LRT, la ART tiene que cubrir todo el proceso de recuperación después de una cirugía.</p>
<p>📌 Kinesiología post-operatoria: Sesiones para recuperar movilidad, fuerza y funcionalidad de la zona operada.</p>
<p>📌 Fisioterapia: Tratamientos con agentes físicos para reducir inflamación, dolor y acelerar la cicatrización.</p>
<p>📌 Duración: Todo el tiempo que tu médico indique como necesario: no hay un número fijo de sesiones en la ley.</p>
<p>📌 Frecuencia: Según la prescripción médica: puede ser diaria, varias veces por semana o semanal.</p>
<p>📌 Consejo práctico: El alta quirúrgica no es el fin del tratamiento: es el inicio de la rehabilitación. Si tu médico indica que seguís necesitando kinesiología, la ART tiene que seguir cubriéndola.</p>
<p>CIRUGÍA ART</p>
<p>10 ¿Puedo pedir una segunda opinión antes de la cirugía?</p>
<p>En síntesis: Sí, podés pedir que la Comisión Médica designe un nuevo médico para que revise tu caso.</p>
<p>Tenés derecho a una segunda opinión médica antes de una cirugía. Es un mecanismo que la ley te da para asegurar que el tratamiento propuesto sea el adecuado para tu lesión.</p>
<p>📌 Derecho a la revisión: Podés solicitar que la Comisión Médica designe un nuevo médico para evaluar tu caso y emitir un segundo dictamen.</p>
<p>📌 Evaluación independiente: Un médico no vinculado a la ART revisa tu situación y puede confirmar, modificar o descartar la cirugía propuesta.</p>
<p>📌 Impacto: La segunda opinión puede confirmar la cirugía, proponer alternativas o determinar que no es necesaria.</p>
<p>📌 Trámite: Solicitala por escrito ante la ART o directamente ante la Comisión Médica Jurisdiccional.</p>
<p>📌 Consejo práctico: Es especialmente importante en cirugías de alto riesgo o que puedan dejar secuelas permanentes. No dudes en pedirla: es tu derecho y puede evitarte una intervención innecesaria.</p>
<p>CIRUGÍA ART</p>
<p>11 ¿Qué es la artroscopia de hombro y la cubre la ART?</p>
<p>En síntesis: Es una cirugía mínimamente invasiva del hombro que la ART debe cubrir si el origen es un accidente laboral.</p>
<p>La artroscopia de hombro se realiza a través de pequeñas incisiones, insertando una cámara y los instrumentos quirúrgicos. Se usa para tratar roturas del manguito rotador, lesiones del labrum, pinzamiento subacromial y cuerpos libres intraarticulares.</p>
<p>✅ Cobertura: La ART la cubre si la lesión es por accidente laboral o enfermedad profesional, según el artículo 11 de la LRT.</p>
<p>📌 Ventajas: Recuperación más rápida que la cirugía abierta, menos dolor post-operatorio y menor riesgo de infección.</p>
<p>📌 Rehabilitación: Necesitás un programa de kinesiología post-operatoria para recuperar movilidad y fuerza.</p>
<p>📌 Tiempo de recuperación: Generalmente entre 4 y 12 semanas, aunque puede ser más largo en lesiones del manguito rotador.</p>
<p>📌 Consejo práctico: Si la artroscopia es viable, no aceptes una cirugía abierta sin motivo: es menos agresiva y tu recuperación suele ser mejor.</p>
<p>CIRUGÍA ART</p>
<p>12 ¿La ART cubre la colocación de placas y tornillos?</p>
<p>En síntesis: Sí, la ART tiene que cubrir todo el material de osteosíntesis que tu cirugía requiera.</p>
<p>La ART debe cubrir todo el material de osteosíntesis necesario para tu cirugía, con la calidad adecuada a tu tipo de fractura. Está contemplado en el artículo 11 de la LRT como parte del tratamiento quirúrgico completo.</p>
<p>📌 Material incluido: Placas de titanio o acero, tornillos, clavos intramedulares, tensores y alfileres de Kirschner según la cirugía.</p>
<p>📌 Insumos complementarios: Toda la sutura y el material que la intervención requiera.</p>
<p>📌 Calidad: El material tiene que ser de primera línea, no genérico ni de menor duración.</p>
<p>📌 Retiro de material: Si hace falta una segunda cirugía para retirarlo (por ejemplo, placas en fracturas de mano), la ART también debe cubrirla.</p>
<p>📌 Consejo práctico: Guardá los comprobantes y autorizaciones. Si la ART intenta cobrarte el material o te ofrece uno de mala calidad, reclamá ante la Comisión Médica.</p>
<p>CIRUGÍA ART</p>
<p>13 ¿Qué es una cirugía de columna y la cubre la ART?</p>
<p>En síntesis: Es cualquier procedimiento quirúrgico en la columna, y la ART lo cubre si es por accidente laboral.</p>
<p>La cirugía de columna engloba distintos procedimientos para tratar lesiones vertebrales causadas por accidentes de trabajo. La ART la cubre cuando la lesión es consecuencia del siniestro laboral o la enfermedad profesional.</p>
<p>📌 Hernia discal: Discectomía o microdiscectomía para retirar el disco que comprime un nervio.</p>
<p>📌 Fusión vertebral: Artrodesis para estabilizar vértebras inestables.</p>
<p>📌 Descompresión: Laminectomía para aliviar la presión sobre la médula o los nervios.</p>
<p>📌 Prótesis de disco: Reemplazo del disco dañado por una prótesis artificial.</p>
<p>📌 Consejo práctico: Las cirugías de columna tienen alto impacto en tu calidad de vida. Asegurate de que el cirujano sea especialista y que la clínica tenga el equipamiento necesario; si la ART no autoriza, reclamá ante la Comisión Médica con todos tus informes.</p>
<p>CIRUGÍA ART</p>
<p>14 ¿Puedo operarme sin autorización de la ART?</p>
<p>En síntesis: En casos de urgencia sí, pero después tenés que reclamar la cobertura con toda la documentación.</p>
<p>En situaciones de urgencia médica, con riesgo inmediato para tu vida, tu integridad física o tu salud, podés operarte sin esperar la autorización previa de la ART. Tu bienestar está antes que el trámite administrativo.</p>
<p>📄 Documentación: Guardá todos los comprobantes: informes de emergencia, facturas, recetas, constancia de internación.</p>
<p>📌 Reclamo posterior: Después de la cirugía, tenés que reclamar la cobertura a la ART presentando toda esa documentación respaldatoria.</p>
<p>📌 Complejidad del reclamo: Sin autorización previa, el reclamo puede ser más difícil. Por eso es fundamental la documentación que demuestre la urgencia.</p>
<p>📌   Asesoramiento legal: Un abogado puede ayudarte a presentar el reclamo correctamente ante la ART y, si hace falta, ante la Comisión Médica.</p>
<p>📌 Consejo práctico: No dejes que la falta de autorización te impida recibir atención urgente. Una vez estabilizado, actuá rápido para documentar todo y reclamar.</p>
<p>CIRUGÍA ART</p>
<p>15 ¿La ART cubre cirugías estéticas por cicatrices?</p>
<p>En síntesis: Sí, si la cicatriz es consecuencia directa de un accidente laboral y afecta tu imagen.</p>
<p>La ART puede cubrir cirugías reconstructivas estéticas cuando la cicatriz es resultado directo de un accidente laboral y afecta significativamente tu imagen o tu calidad de vida. Está contemplado como prestación en el artículo 11 de la LRT.</p>
<p>📌 Origen laboral: La cicatriz tiene que ser consecuencia directa del accidente de trabajo o la enfermedad profesional.</p>
<p>📌 Afectación demostrada: Tiene que afectar tu imagen, tu vida social o tu capacidad laboral, por ejemplo si trabajás cara al público.</p>
<p>📌 Autorización médica: Un cirujano plástico tiene que determinar que la cirugía es necesaria y viable.</p>
<p>📌 Evaluación de la ART: La ART tiene que evaluar la solicitud y autorizar si se cumplen los requisitos.</p>
<p>📌 Consejo práctico: Si la ART niega la cobertura, reclamá ante la Comisión Médica con los informes del cirujano plástico. No minimices el impacto psicológico de una cicatriz visible: la ley lo reconoce como un daño real.</p>
<p>CIRUGÍA ART</p>
<p>16 ¿Qué es la cirugía de rodilla y la cubre la ART?</p>
<p>En síntesis: Es cualquier procedimiento quirúrgico en la rodilla, y la ART lo cubre si es por accidente laboral.</p>
<p>La cirugía de rodilla engloba distintos procedimientos para tratar lesiones articulares causadas por accidentes laborales. La ART la cubre cuando la lesión es consecuencia del siniestro, con autorización previa salvo urgencia.</p>
<p>📌 Meniscectomía: Retiro o reparación del menisco dañado.</p>
<p>📌 Reconstrucción de ligamentos: Reconstrucción del ligamento cruzado anterior o posterior con injerto.</p>
<p>📌 Artroplastia: Reemplazo total o parcial de la rodilla con prótesis.</p>
<p>📌 Artroscopia: Cirugía mínimamente invasiva para diagnóstico y tratamiento.</p>
<p>📌 Consejo práctico: La rodilla soporta todo el peso corporal, y la calidad de la cirugía y la rehabilitación definen buena parte de tu recuperación. Asegurate de que te opere un especialista en rodilla.</p>
<p>CIRUGÍA ART</p>
<p>17 ¿La ART cubre las prótesis de cadera?</p>
<p>En síntesis: Sí, la ART debe cubrir la colocación de una prótesis de cadera si la lesión es por accidente laboral.</p>
<p>La ART tiene que cubrir la colocación de una prótesis de cadera cuando la lesión es consecuencia de un accidente laboral, por ejemplo tras fracturas graves, necrosis avascular o artrosis severa causada por el trabajo.</p>
<p>📌 Cobertura completa: Incluye la cirugía, la prótesis, la internación, la anestesia y los honorarios médicos.</p>
<p>📌 Calidad de la prótesis: La ART tiene que proveer una prótesis de buena calidad y adecuada a tu caso; no aceptes implantes genéricos.</p>
<p>📌 Rehabilitación: Necesitás un programa post-operatorio con kinesiología, fisioterapia y terapia ocupacional, que puede durar de 3 a 6 meses.</p>
<p>📌 Seguimiento: La ART tiene que hacer controles periódicos para verificar el funcionamiento de la prótesis.</p>
<p>📌 Consejo práctico: Si la ART ofrece una prótesis de mala calidad o se niega a cubrir una mejor, reclamá: la calidad del implante impacta directamente en tu calidad de vida a largo plazo.</p>
<p>CIRUGÍA ART</p>
<p>18 ¿Qué pasa si me rechazan la autorización para operarme?</p>
<p>En síntesis: Podés apelar ante la Comisión Médica, y si es urgente, operarte y reclamar después.</p>
<p>Si la ART te rechaza la autorización para operarte, tenés opciones concretas para revertir esa decisión y no depender solo de la buena voluntad de la aseguradora.</p>
<p>📌 Apelación ante la Comisión Médica: Presentá el reclamo con todos los informes médicos que respalden la necesidad de la cirugía; es la instancia previa obligatoria (Ley 27.348).</p>
<p>📌 Urgencia: Si la cirugía es urgente y la ART no autoriza, operate y reclamá después. No arriesgues tu salud.</p>
<p>📄 Documentación: Adjuntá informes médicos, estudios complementarios, imágenes diagnósticas y la solicitud original ante la ART.</p>
<p>📌   Asesoramiento legal: Un abogado especialista te ayuda a preparar el caso correctamente.</p>
<p>📌 Consejo práctico: La Comisión Médica puede ordenarle a la ART que autorice la cirugía, y si esa decisión tampoco te favorece, podés apelar ante la Justicia. La clave es actuar rápido y con buena documentación.</p>
<p>CIRUGÍA ART</p>
<p>19 ¿La ART cubre la anestesia en la cirugía?</p>
<p>En síntesis: Sí, la ART tiene que cubrir todos los costos de la cirugía, incluida la anestesia.</p>
<p>La anestesia es una parte obligatoria de la cobertura quirúrgica. La ART tiene que cubrir todos los costos asociados, sin que tengas que pagar nada de tu bolsillo.</p>
<p>📌 Tipo de anestesia: General, regional (peridural, raquídea) o local, según la complejidad de la cirugía y la indicación del anestesiólogo.</p>
<p>📌 Cobertura completa: Incluye honorarios del anestesiólogo, medicamentos, monitoreo durante la cirugía y cuidado post-anestésico.</p>
<p>📌 Sin costos adicionales: No te pueden cobrar un adicional por la anestesia: está incluida en la prestación quirúrgica.</p>
<p>⚖️ Responsabilidad: La ART tiene que garantizar que la anestesia la administre un profesional habilitado en un centro con el equipamiento adecuado.</p>
<p>📌 Consejo práctico: Si la ART intenta descontarte el costo de la anestesia o te pide que pagues una diferencia, reclamá: no es un componente opcional de la cirugía.</p>
<p>CIRUGÍA ART</p>
<p>20 ¿Cuánto tiempo de recuperación tengo después de una cirugía?</p>
<p>En síntesis: Depende del tipo de cirugía, pero la ART tiene que cubrir todo el tiempo que tu recuperación necesite.</p>
<p>El tiempo de recuperación varía según el tipo de intervención, tu edad, tu estado general de salud y tu respuesta al tratamiento. La ART tiene que cubrir todo el tiempo necesario hasta tu recuperación completa.</p>
<p>📌 Factores que influyen: El tipo de cirugía (una artroscopia se recupera antes que una prótesis), tu edad, tu condición física previa y la complejidad de la lesión.</p>
<p>📌 Licencia médica: Tenés derecho a licencia médica pagada según el artículo 13 de la LRT: 100% del ingreso base, primero a cargo del empleador y luego de la ART.</p>
<p>📌 Rehabilitación: El tiempo de recuperación incluye la rehabilitación post-operatoria, que puede extenderse semanas o meses.</p>
<p>📌 Seguimiento: La ART tiene que hacer controles periódicos para verificar tu evolución.</p>
<p>📌 Consejo práctico: No te apures a volver antes de tiempo: una reincorporación prematura puede causar recaídas. Seguí las indicaciones de tu médico; la ART no puede presionarte para que vuelvas antes.</p>
<p>CIRUGÍA ART</p>
<p>21 ¿Puedo operarme en mi obra social en vez de la ART?</p>
<p>En síntesis: No: si es por accidente laboral, la ART es la responsable de cubrir la cirugía.</p>
<p>Si la lesión es consecuencia de un accidente de trabajo o una enfermedad profesional, la ART es la responsable de cubrir la cirugía y todo el tratamiento. Tu obra social no está obligada a atender contingencias laborales.</p>
<p>📌 Responsabilidad exclusiva de la ART: Cubre accidentes laborales y enfermedades profesionales desde la contingencia hasta el alta médica.</p>
<p>📌 No mezclar sistemas: Usar tu obra social para un tratamiento que corresponde a la ART puede complicar tu reclamo y generar conflictos entre instituciones.</p>
<p>📌 Excepción: Si la ART rechaza el tratamiento y necesitás atención urgente, podés recurrir a tu obra social como medida temporal y después reclamarle a la ART.</p>
<p>📌 Importancia: Mantené siempre en claro qué sistema te cubre cada tratamiento: para accidentes laborales, siempre es la ART.</p>
<p>📌 Consejo práctico: Lo mejor es que la ART asuma su responsabilidad desde el inicio. Si hay conflicto entre la ART y la obra social, consultá con un abogado.</p>
<p>CIRUGÍA ART</p>
<p>22 ¿La ART cubre cirugías de mano por túnel carpiano?</p>
<p>En síntesis: Sí, si el túnel carpiano fue causado por el trabajo, la ART debe cubrir la cirugía.</p>
<p>El síndrome del túnel carpiano es una de las enfermedades profesionales más comunes. La ART tiene que cubrir la cirugía de liberación del nervio mediano si se demuestra que su origen es laboral.</p>
<p>✅ Cobertura: Si el túnel carpiano fue causado por movimientos repetitivos, posturas forzadas o vibración en el trabajo, la ART lo cubre como enfermedad profesional.</p>
<p>📌 Diagnóstico: Se diagnostica mediante electromiografía, que la ART tiene que cubrir, y evaluación clínica de un especialista.</p>
<p>📌 Autorización: Necesitás la autorización previa de la ART para la cirugía.</p>
<p>📌 Tratamiento completo: Incluye la cirugía, la rehabilitación post-operatoria y el seguimiento.</p>
<p>📌 Consejo práctico: No esperes a que empeore: si sentís adormecimiento, hormigueo o debilidad en la mano, consultá con un médico. La ART no puede negar la cobertura diciendo que &#039;es algo común&#039;.</p>
<p>CIRUGÍA ART</p>
<p>23 ¿Qué es la cirugía de hombro con prótesis?</p>
<p>En síntesis: Es cuando se reemplaza la articulación del hombro dañada por una prótesis, y la ART la cubre si es por accidente laboral.</p>
<p>La artroplastia de hombro reemplaza la articulación dañada por una prótesis artificial. Se indica en fracturas complejas, artrosis severa, necrosis avascular o roturas masivas e irrecuperables del manguito rotador.</p>
<p>✅ Cobertura: La ART la cubre si la lesión es por accidente laboral: incluye la cirugía, la prótesis, la internación y la anestesia.</p>
<p>📌 Calidad del implante: La ART tiene que proveer una prótesis adecuada a tu caso, parcial o total según la indicación médica.</p>
<p>📌 Recuperación: Requiere una rehabilitación intensiva de 3 a 6 meses; la kinesiología es clave para recuperar la movilidad.</p>
<p>📌 Resultados: Generalmente son buenos, y permiten recuperar la función del brazo para actividades cotidianas y laborales.</p>
<p>📌 Consejo práctico: Si la ART no autoriza la prótesis o te ofrece una de inferior calidad, reclamá ante la Comisión Médica: tu calidad de vida depende en gran parte del implante.</p>
<p>CIRUGÍA ART</p>
<p>24 ¿La ART cubre la cirugía de hernia discal?</p>
<p>En síntesis: Sí, si la hernia discal fue causada por el trabajo, la ART debe cubrir la cirugía.</p>
<p>La hernia discal puede estar cubierta por la ART si se demuestra que su origen es laboral (esfuerzos repetitivos, levantamiento de cargas, posturas forzadas). La cobertura incluye tanto el tratamiento conservador como el quirúrgico cuando hace falta.</p>
<p>✅ Cobertura: Si la hernia discal es contingencia profesional, la ART cubre todo el tratamiento.</p>
<p>📌 Diagnóstico: Se diagnostica mediante resonancia magnética y evaluación clínica.</p>
<p>📌 Tratamiento conservador primero: Generalmente se intenta primero con medicación, infiltraciones, fisioterapia y kinesiología; la cirugía se indica cuando eso no alcanza.</p>
<p>📌 Autorización quirúrgica: Si hace falta operar, la ART tiene que autorizarla: discectomía, microdiscectomía o artrodesis, según el caso.</p>
<p>📌 Consejo práctico: Si la ART niega la cobertura diciendo que &#039;no es por el trabajo&#039;, reclamá con informes médicos que establezcan el nexo causal. Con buenos informes, ese vínculo es demostrable.</p>
<p>CIRUGÍA ART</p>
<p>25 ¿Qué pasa si me opero y la ART no paga?</p>
<p>En síntesis: Podés reclamar ante la Comisión Médica y, si hace falta, iniciar un juicio.</p>
<p>Si la ART no paga una cirugía que ya te realizaste o se niega a cubrirla, tenés vías claras de reclamo, tanto administrativas como judiciales.</p>
<p>📌 Reclamo ante la Comisión Médica: Presentá el reclamo cuanto antes, con todos los comprobantes: facturas, informes médicos, autorizaciones y comunicaciones con la ART.</p>
<p>📌 Documentación completa: Sumá el informe quirúrgico, los honorarios médicos, el costo del material, la internación y cualquier gasto asociado.</p>
<p>📌 Escalada: Si la Comisión Médica no resuelve a tu favor, podés apelar ante la Justicia Federal.</p>
<p>📌 Juicio: Como último recurso, podés iniciar un juicio ordinario reclamando la cobertura, más intereses y costas.</p>
<p>📌 Consejo práctico: La ART no puede dejarte de lado después de una cirugía. Mientras se resuelve el reclamo, guardá todos los comprobantes de pago: si pagaste de tu bolsillo, tenés derecho al reintegro completo más intereses.</p>
<p>CIRUGÍA ART</p>
<p>26 ¿La ART cubre cirugías de tobillo y pie?</p>
<p>En síntesis: Sí, la ART cubre cirugías de tobillo y pie si son consecuencia de un accidente laboral.</p>
<p>Las cirugías de tobillo y pie están cubiertas por la ART cuando son consecuencia de un accidente laboral. Son lesiones frecuentes en caídas de altura, aplastamientos o esfuerzos repetitivos.</p>
<p>📌 Tipos de cirugías: Síntesis de fracturas, reparación de tendones (aquiles, tibial), artroscopia de tobillo, artroplastia, corrección de deformidades.</p>
<p>✅ Cobertura: La ART cubre la cirugía completa, incluido el material de osteosíntesis, la internación y la anestesia.</p>
<p>📌 Autorización previa: Necesitás la autorización de la ART antes de operarte, salvo urgencia.</p>
<p>📌 Rehabilitación: Es clave para recuperar la marcha y el equilibrio; puede requerir muletas, bota ortopédica y kinesiología prolongada.</p>
<p>📌 Consejo práctico: Las lesiones de tobillo y pie pueden dejar secuelas importantes si no se tratan bien. Asegurate de que te opere un especialista en pie y tobillo.</p>
<p>CIRUGÍA ART</p>
<p>27 ¿Qué es la cirugía de codo y la cubre la ART?</p>
<p>En síntesis: Es cualquier procedimiento quirúrgico en el codo, y la ART lo cubre si es por accidente laboral.</p>
<p>La cirugía de codo engloba distintos procedimientos para tratar lesiones articulares causadas por accidentes laborales. La ART la cubre cuando la lesión es consecuencia del siniestro, con autorización previa.</p>
<p>📌 Artroscopia de codo: Cirugía mínimamente invasiva para tratar cuerpos libres, contracturas, pinzamiento y lesiones del cartílago.</p>
<p>📌 Reconstrucción: Reparación de ligamentos, tendones y articulaciones dañadas por traumatismos.</p>
<p>📌 Prótesis de codo: Reemplazo articular en casos de artrosis severa o fracturas complejas.</p>
<p>📌 Descompresión del nervio cubital: Para tratar la neuropatía por compresión, frecuente en trabajadores.</p>
<p>📌 Consejo práctico: El codo se usa constantemente en el trabajo y en la vida diaria. Una buena cirugía con buena rehabilitación puede devolver la funcionalidad completa; la ART no puede escatimar en calidad.</p>
<p>CIRUGÍA ART</p>
<p>28 ¿La ART cubre la cirugía de amputación?</p>
<p>En síntesis: Sí, la ART debe cubrir la cirugía de amputación y la prótesis si es consecuencia de un accidente laboral.</p>
<p>La ART tiene que cubrir la cirugía de amputación cuando es necesaria por un accidente laboral grave, y además la prótesis y la rehabilitación posterior.</p>
<p>📌 Cirugía de amputación: El procedimiento en sí, realizado por un cirujano especialista.</p>
<p>📌 Prótesis funcional: Colocación y adaptación de una prótesis que te permita recuperar la mayor funcionalidad posible.</p>
<p>📌 Rehabilitación: Un programa intensivo para aprender a usar la prótesis y adaptarte a las nuevas condiciones.</p>
<p>📌 Indemnización: Además de la cobertura médica, te corresponde una indemnización por incapacidad, que en amputaciones suele ser un porcentaje alto según el Baremo 2026 (Decreto 549/2025).</p>
<p>📌 Consejo práctico: Según la Resolución SRT 15/2026, la indemnización por incapacidad no puede ser inferior a $97.502.420 multiplicado por tu porcentaje de incapacidad, un piso mínimo que la SRT actualiza semestralmente por RIPTE. No firmes nada sin que un abogado evalúe tu indemnización.</p>
<p>CIRUGÍA ART</p>
<p>29 ¿Puedo pedir un cambio de clínica para la cirugía?</p>
<p>En síntesis: Sí, podés solicitar un cambio si tenés motivos justificados ante la ART.</p>
<p>Podés pedir un cambio de clínica para tu cirugía si tenés motivos justificados. La ART no puede obligarte a operarte en un centro que no cumpla los requisitos necesarios para tu tratamiento.</p>
<p>📌 Solicitud escrita: Presentá el pedido ante la ART explicando los motivos del cambio.</p>
<p>📌 Motivos válidos: Falta de equipamiento, ausencia del especialista requerido, distancia excesiva, problemas de higiene o seguridad, o razones de confianza médica.</p>
<p>📌 Evaluación: La ART tiene que evaluar tu solicitud y responder en un plazo razonable.</p>
<p>📌 Si te rechazan: Podés reclamar ante la Comisión Médica, que puede ordenar el cambio si los motivos son legítimos.</p>
<p>📌 Consejo práctico: Tu seguridad y la calidad de la cirugía son lo primero. Documentá tu solicitud y la respuesta de la ART; eso te protege si el reclamo avanza.</p>
<p>CIRUGÍA ART</p>
<p>30 ¿Qué documentos necesito para la cirugía con la ART?</p>
<p>En síntesis: Necesitás la autorización de la ART, informes médicos y tu documentación personal.</p>
<p>Para que tu cirugía sea autorizada y realizada a través de la ART, tenés que reunir cierta documentación clave que respalde el pedido y te proteja ante cualquier conflicto posterior.</p>
<p>📌 Autorización de la ART: El documento oficial donde autoriza la cirugía, con el cirujano, la clínica y la fecha.</p>
<p>📌 Informes médicos: El informe de tu médico tratante que justifique la cirugía, con diagnóstico y plan quirúrgico.</p>
<p>📌 Estudios complementarios: Radiografías, resonancias, electromiografías, análisis y todo estudio que respalde la necesidad de la cirugía.</p>
<p>📌 Documentos personales: DNI, CUIL y carnet de la ART.</p>
<p>📌 Consejo práctico: Armá una carpeta con copias de todo, presentá originales y quedate con las copias, y enviá documentación por mail con acuse de recibo. Esa organización es tu mejor herramienta si surge un conflicto.</p>
<p>JUICIO ART</p>
<p>1 ¿Cuándo puedo hacer un juicio a la ART?</p>
<p>En síntesis: Cuando agotaste la instancia ante la Comisión Médica y la ART no te dio una solución justa.</p>
<p>Podés iniciar un juicio contra la ART cuando se cumplen ciertos requisitos que fija la ley. En general, primero tenés que pasar por la Comisión Médica Jurisdiccional, que es la instancia administrativa previa y obligatoria (art. 1, Ley 27.348). Sin ese paso, el juez puede rechazar tu demanda.</p>
<p>📌 Instancia previa: Tenés que haber pasado por la Comisión Médica Jurisdiccional y, si no estás conforme, haber apelado ante la Comisión Médica Central o la vía judicial que prevé la ley.</p>
<p>📌 Rechazo o disconformidad: La ART rechazó tu reclamo, te dio un porcentaje de incapacidad que considerás injusto, o no te brindó el tratamiento que necesitás.</p>
<p>📌 Plazo de prescripción: Tenés 2 años desde que conociste la resolución de la ART o desde el alta médica definitiva para iniciar acciones legales (art. 44, LRT).</p>
<p>📌 Competencia: Los juicios contra ART se tramitan ante la Justicia Federal en todo el país (arts. 49 y 50, LRT).</p>
<p>📌 Consejo práctico: Si la ART incumplió sus obligaciones de darte asistencia médica o pagarte el subsidio, también podés iniciar un juicio sin pasar antes por la Comisión Médica. Consultá con un abogado para evaluar tu caso puntual.</p>
<p>JUICIO ART</p>
<p>2 ¿Cuánto cuesta hacer un juicio a la ART?</p>
<p>En síntesis: Generalmente los abogados cobran solo si ganás, así que no tenés que pagar por adelantado.</p>
<p>El costo de un juicio contra la ART no debería frenarte para reclamar tus derechos. La mayoría de los abogados laboralistas trabajan a honorarios de éxito: solo cobran si ganás el juicio.</p>
<p>📌 Honorarios del abogado: Se pagan solo si ganás, generalmente entre el 15% y el 25% de lo obtenido, según la complejidad del caso.</p>
<p>📌 Gastos judiciales: No tenés que pagar por adelantado. En los juicios laborales, la parte vencida (generalmente la ART) paga las costas.</p>
<p>📌 Gastos de pericias: Puede haber gastos menores de pericias médicas, que generalmente anticipa tu abogado.</p>
<p>📌 Consulta inicial: Suele ser gratuita y sin compromiso.</p>
<p>📌 Consejo práctico: No firmes acuerdos directos con la ART sin asesorarte: muchas veces las indemnizaciones que ofrecen son menores a las que podés obtener en un juicio.</p>
<p>JUICIO ART</p>
<p>3 ¿Cuánto tarda un juicio contra la ART?</p>
<p>En síntesis: En promedio, entre 1 y 3 años en primera instancia, y puede extenderse más si hay apelación.</p>
<p>Los tiempos judiciales varían según múltiples factores: la complejidad médica del caso, la jurisdicción y la carga de trabajo del juzgado influyen directamente en los plazos.</p>
<p>📌 Primera instancia: Entre 1 y 3 años, desde la presentación de la demanda hasta la sentencia.</p>
<p>📌 Factores que influyen: La complejidad médica del caso, la jurisdicción y la cantidad de pruebas a producir.</p>
<p>📌 Apelaciones: Si la ART apela la sentencia, el proceso puede extenderse 1 o 2 años más ante la Cámara Federal.</p>
<p>📌 Medidas cautelares: Mientras dura el juicio, tu abogado puede pedir que la ART continúe brindándote tratamiento médico o pagándote el subsidio.</p>
<p>📌 Consejo práctico: Aunque el juicio sea largo, no dejes de reclamar tus derechos: los intereses que se acumulan desde el accidente hasta la sentencia pueden ser un monto significativo.</p>
<p>JUICIO ART</p>
<p>4 ¿Qué documentos necesito para iniciar un juicio?</p>
<p>En síntesis: Necesitás toda la documentación médica, laboral y las resoluciones de la Comisión Médica.</p>
<p>Para iniciar un juicio contra la ART, tenés que reunir la documentación que respalde tu reclamo: es la base para probar la relación entre tu accidente y tu actividad laboral, y para calcular la indemnización que te corresponde.</p>
<p>📌 Documentación médica: Historia clínica completa, certificados de internación, estudios (radiografías, resonancias, electromiografías), informes de tratamientos y de kinesiología.</p>
<p>📌 Documentación laboral: Contrato de trabajo, recibos de sueldo de los últimos 12 meses (que demuestran tu ingreso base), legajo y certificado de trabajo.</p>
<p>📌 Documentación administrativa: Resoluciones de la Comisión Médica Jurisdiccional, formularios SRT de denuncia del siniestro y toda resolución de la ART sobre tu caso.</p>
<p>📌 Documentación personal: DNI vigente, CUIL y composición familiar, si corresponde.</p>
<p>📌 Consejo práctico: Guardá siempre los originales y hacé copias de todo. Tu abogado va a necesitar esta documentación para calcular tu indemnización con la fórmula del art. 14 de la LRT: 53 × Ingreso Base × % de incapacidad × (65/edad).</p>
<p>JUICIO ART</p>
<p>5 ¿Puedo seguir cobrando el subsidio mientras hago el juicio?</p>
<p>En síntesis: Sí, mientras tengas licencia médica, seguís cobrando el subsidio por incapacidad temporaria.</p>
<p>Sí, podés seguir cobrando el subsidio por incapacidad laboral temporaria mientras tramita tu juicio. Equivale al 100% de tu ingreso base mensual y se paga desde el primer día de la incapacidad hasta el alta médica. Son trámites independientes.</p>
<p>📌 Licencia médica: Mientras tengas licencia otorgada por el médico tratante de la ART, seguís cobrando el subsidio diario.</p>
<p>📌 Obligación de la ART: Tiene que pagar el subsidio durante toda la incapacidad temporaria, sin que el juicio influya en ese pago.</p>
<p>📌 Trámites independientes: El juicio por incapacidad permanente no interrumpe el pago del subsidio por incapacidad temporaria.</p>
<p>📌 Si no pagan: Si la ART se niega a pagarte, tu abogado puede pedir una medida cautelar para que el juez ordene el pago inmediato.</p>
<p>📌 Consejo práctico: Si la ART te da el alta y seguís incapacitado, podés impugnarla ante la Comisión Médica dentro de los 5 días hábiles que fija la Resolución SRT N.° 5/2026, para seguir cobrando mientras se resuelve tu caso.</p>
<p>JUICIO ART</p>
<p>6 ¿Qué es la pericia médica en un juicio?</p>
<p>En síntesis: Es la evaluación de un médico designado por el juez para determinar tu incapacidad.</p>
<p>La pericia médica es una de las pruebas más importantes del juicio. La realiza un perito designado por el juez, que determina el porcentaje de incapacidad que te dejó la lesión o enfermedad profesional, y es la base sobre la que el juez fija tu indemnización.</p>
<p>📌 Designación del perito: El juez nombra al médico perito, que tiene que ser especialista e imparcial. Vos y la ART también pueden proponer un perito de parte.</p>
<p>📌 Evaluación: Examina tus lesiones, revisa tu historia clínica, analiza los estudios complementarios y evalúa tus limitaciones funcionales.</p>
<p>📌 Dictamen: Emite un informe con el porcentaje de incapacidad, fundamentado en el Baremo 2026 (Decreto 549/2025) y en su criterio médico.</p>
<p>📌 Importancia: No es vinculante para el juez, pero en la práctica pesa mucho en la decisión final. Si no estás de acuerdo, tu abogado puede pedir un nuevo peritaje o impugnar el dictamen.</p>
<p>📌 Consejo práctico: Es fundamental que asistas a la pericia con toda tu documentación médica y seas honesto sobre tus limitaciones: no las minimices ni las exageres.</p>
<p>JUICIO ART</p>
<p>7  ¿Puedo hacer un juicio si estoy en negro?</p>
<p>En síntesis: Sí, e incluso podés reclamar más porque el empleador no te registró.</p>
<p>Podés hacer juicio aunque trabajes en negro. El trabajo no registrado no te quita ningún derecho a reclamar por un accidente o enfermedad laboral; de hecho, puede sumar reclamos adicionales porque tu empleador incumplió la ley al no registrarte.</p>
<p>📌 Derecho a reclamar: La ART tiene que cubrirte igual, porque la obligación de contratar una ART es del empleador, sin importar tu registración.</p>
<p>📌 Reclamo adicional: Podés reclamarle a tu empleador la registración laboral, las diferencias salariales y una indemnización por trabajo no registrado según la LCT.</p>
<p>📌 Misma indemnización: Te corresponde la misma indemnización por incapacidad que a un empleado en blanco, con la fórmula: 53 × Ingreso Base × % incapacidad × (65/edad).</p>
<p>📌 Prueba: Necesitás demostrar la relación laboral con cualquier medio: testimonios, transferencias, mensajes, fotos.</p>
<p>📌 Consejo práctico: Recordá que tenés 2 años para reclamar (art. 44, LRT), así que no dejes pasar el tiempo. Consultá con un abogado laboralista lo antes posible para que te asesore sobre cómo probar la relación laboral.</p>
<p>JUICIO ART</p>
<p>8 ¿Qué pasa si pierdo el juicio?</p>
<p>En síntesis: Generalmente no tenés que pagar las costas, pero es clave tener un buen abogado.</p>
<p>Si perdés el juicio contra la ART, la situación no es tan grave como parece. En los juicios laborales argentinos rige el principio protectorio: en general, el trabajador que pierde no queda obligado a pagar las costas.</p>
<p>📌 Costas: Generalmente no se te imponen si perdés, salvo que el juez determine que actuaste con temeridad o mala fe.</p>
<p>📌 Honorarios del abogado: Si trabajaste con honorarios de éxito, no le debés nada si perdiste. Si firmaste un contrato de honorarios fijos, sí podrías deberle.</p>
<p>📌 Apelación: Tenés derecho a apelar la sentencia ante la Cámara Federal; tu abogado evalúa si hay fundamento.</p>
<p>📌 Acuerdo: Muchas veces, antes de la sentencia, se puede llegar a un acuerdo con la ART más favorable que el resultado incierto de un juicio.</p>
<p>📌 Consejo práctico: No te desanimes si la primera instancia no fue favorable: muchos juicios se ganan en la apelación. Consultá con tu abogado sobre las posibilidades reales antes de decidir cómo seguir.</p>
<p>JUICIO ART</p>
<p>9 ¿Cuánto puedo sacar en un juicio a la ART?</p>
<p>En síntesis: Depende de tu incapacidad, tu salario y tu edad; a eso se le pueden sumar otros rubros que la ART no paga administrativamente.</p>
<p>El monto depende de varios factores. La indemnización por incapacidad permanente se calcula con la fórmula del art. 14 de la LRT: 53 × Ingreso Base Mensual × % de incapacidad × (65/edad). A eso se le pueden sumar otros rubros que solo se reclaman en juicio.</p>
<p>📌 Incapacidad: A mayor porcentaje, mayor indemnización. Si la incapacidad llega o supera el 66%, corresponde el régimen de incapacidad total (art. 15, LRT) más el adicional del art. 3 de la Ley 26.773.</p>
<p>📌 Salario: Se toma tu remuneración promedio de los últimos 12 meses, incluyendo todos los conceptos remunerativos.</p>
<p>📌 Edad: El coeficiente (65/edad) reduce el monto cuanto mayor seas: un trabajador joven recibe más que uno mayor con la misma incapacidad y salario.</p>
<p>📌 Rubros adicionales: En juicio podés reclamar daño moral, daños estéticos y otros perjuicios que puedas demostrar, además de los intereses desde la fecha del accidente.</p>
<p>📌 Consejo práctico: Existe un piso mínimo que la SRT actualiza cada semestre por RIPTE (actualmente $97.502.420 según la Resolución SRT 15/2026), que la ART nunca puede pagar de menos. Un abogado puede calcular con precisión el monto que te corresponde.</p>
<p>JUICIO ART</p>
<p>10 ¿Qué es la conciliación en un juicio?</p>
<p>En síntesis: Es cuando intentan llegar a un acuerdo antes o durante el juicio, y puede ahorrarte tiempo.</p>
<p>La conciliación es un mecanismo alternativo de resolución de conflictos: vos y la ART intentan llegar a un acuerdo con la ayuda de un mediador, sin que un juez tenga que decidir el caso.</p>
<p>📌 Objetivo: Llegar a un acuerdo sobre el monto y las condiciones de pago, evitando un juicio largo y costoso.</p>
<p>📌 Ahorro de tiempo: Un juicio puede durar entre 1 y 3 años; un acuerdo se puede lograr en semanas o meses.</p>
<p>📌 Mediación: Un mediador neutral ayuda a las partes a negociar. En el fuero federal, es una instancia obligatoria antes del juicio.</p>
<p>📌 Homologación: Si se llega a un acuerdo, se formaliza ante el juez, que lo homologa dándole fuerza de sentencia.</p>
<p>📌 Consejo práctico: No estás obligado a aceptar la primera oferta de la ART. Contá siempre con la asesoría de tu abogado antes de firmar cualquier acuerdo.</p>
<p>JUICIO ART</p>
<p>11 ¿Puedo hacer juicio si ya pasaron muchos años del accidente?</p>
<p>En síntesis: El plazo general es de 2 años, pero hay excepciones que pueden extenderlo, así que conviene consultar igual.</p>
<p>El plazo de prescripción para reclamar indemnización por accidente o enfermedad laboral es de 2 años, conforme al art. 44 de la LRT. Sin embargo, existen excepciones que pueden modificar ese plazo.</p>
<p>📌 Plazo general: 2 años desde la fecha del accidente o desde el alta médica definitiva.</p>
<p>📌 Enfermedad profesional: El plazo corre desde el diagnóstico o desde que supiste que la enfermedad estaba relacionada con tu trabajo.</p>
<p>📌 Suspensión del plazo: Se suspende mientras la ART te esté pagando prestaciones dinerarias o mientras estés en tratamiento médico o en trámite ante la Comisión Médica.</p>
<p>📌 Daños y perjuicios: Si reclamás daño moral u otros daños ante la Justicia ordinaria, el plazo de prescripción es de 3 años (art. 2561, Código Civil y Comercial).</p>
<p>📌 Consejo práctico: No dejes pasar el tiempo. Si creés que podés tener derecho a reclamar, consultá con un abogado: muchas veces hay argumentos para evitar la prescripción.</p>
<p>JUICIO ART</p>
<p>12 ¿Qué es la ejecución de sentencia?</p>
<p>En síntesis: Es el trámite que obliga a la ART a pagar lo que dictó el juez, si no lo hace voluntariamente.</p>
<p>Una vez que la sentencia queda firme, la ART tiene que cumplir lo ordenado. Si no paga voluntariamente, se inicia la ejecución de sentencia para obligarla a hacerlo.</p>
<p>📌 Definición: Es el proceso judicial que obliga a la ART a cumplir la sentencia firme, pagando el monto que fijó el juez.</p>
<p>⏳ Plazo: La ART tiene que cumplir dentro del plazo que fije el juez, generalmente unos días para el pago.</p>
<p>📌 Embargo: Si no paga, el juez puede ordenar embargos sobre las cuentas o bienes de la ART para garantizar el cobro.</p>
<p>📌 Multas: Si sigue sin cumplir, el juez puede imponer multas diarias hasta que se haga efectivo el pago.</p>
<p>📌 Consejo práctico: Tu abogado gestiona la ejecución de sentencia. No bajes la guardia después de ganar el juicio: la ART a veces demora en cumplir.</p>
<p>JUICIO ART</p>
<p>13 ¿Puedo hacer juicio si estoy jubilado?</p>
<p>En síntesis: Sí, podés reclamar por la incapacidad que te dejó el accidente laboral, sin importar tu jubilación.</p>
<p>La jubilación no impide reclamar por incapacidad laboral. Si un accidente de trabajo o una enfermedad profesional te dejó una incapacidad permanente, tenés derecho a la indemnización correspondiente, sin importar tu situación previsional.</p>
<p>📌 Derecho: Podés reclamar la indemnización por incapacidad permanente: es un derecho que no se pierde con la jubilación.</p>
<p>⏳ Plazo: Tenés 2 años desde el alta médica definitiva o la resolución de la ART para iniciar acciones (art. 44, LRT).</p>
<p>📌 Cálculo: Se aplica la fórmula: 53 × Ingreso Base × % incapacidad × (65/edad). Al estar jubilado, el coeficiente puede reducir el monto, pero no elimina el derecho.</p>
<p>📌 Justicia competente: Los juicios se tramitan ante la Justicia Federal (arts. 49-50, LRT), igual que los de trabajadores activos.</p>
<p>📌 Consejo práctico: No confundas la jubilación con la indemnización por incapacidad laboral: son prestaciones distintas, con distinto origen jurídico. Consultá con un abogado especialista para evaluar tu caso.</p>
<p>JUICIO ART</p>
<p>14 ¿Qué es el daño moral en un juicio?</p>
<p>En síntesis: Es la compensación por el sufrimiento físico y psicológico que te causó el accidente o la enfermedad laboral.</p>
<p>Aunque la LRT no contempla expresamente este rubro, la jurisprudencia de los tribunales argentinos reconoce de manera reiterada el derecho del trabajador a reclamar daño moral en un juicio contra la ART.</p>
<p>📌 Definición: Es la compensación económica por el sufrimiento, la angustia y la afectación de tu calidad de vida que causó el accidente o la enfermedad.</p>
<p>📌 Cálculo: No hay una fórmula fija: se evalúa según la gravedad de la lesión, el tiempo de recuperación y el impacto en tu vida personal y familiar.</p>
<p>📌 Requisito: Tenés que demostrar el sufrimiento con informes psicológicos o psiquiátricos, testimonios y la documentación médica correspondiente.</p>
<p>📢 Reclamo: Se reclama ante la Justicia del Trabajo, no ante la Comisión Médica: es un rubro que la ART no paga administrativamente.</p>
<p>📌 Consejo práctico: El daño moral es independiente de la indemnización por incapacidad permanente. Si tu accidente te causó sufrimiento significativo, asegurate de incluir este rubro en tu juicio.</p>
<p>JUICIO ART</p>
<p>15 ¿Cuánto cobro si gano el juicio?</p>
<p>En síntesis: Depende de tu caso, pero generalmente es bastante más de lo que te ofrecieron por vía administrativa.</p>
<p>Si ganás el juicio, el monto que recibís suele ser mayor a lo que la ART ofrece administrativamente, porque en juicio podés reclamar rubros que la ART no paga por esa vía.</p>
<p>📌 Incapacidad permanente: Se calcula con la fórmula del art. 14 LRT: 53 × Ingreso Base × % incapacidad × (65/edad), fijado por el juez según la pericia médica.</p>
<p>📌 Intereses: Se acumulan desde la fecha del accidente hasta la sentencia, y pueden representar un monto considerable en juicios largos.</p>
<p>📌 Daño moral y daños estéticos: Compensación por sufrimiento psicológico y físico, o por cicatrices y marcas visibles: no los paga la ART administrativamente.</p>
<p>📌 Honorarios y costas: La ART tiene que pagar los honorarios de tu abogado (generalmente entre 15% y 25%) y todos los gastos del juicio si lo perdió.</p>
<p>📌 Consejo práctico: El monto final puede ser bastante superior a lo que la ART te ofreció inicialmente. Por eso conviene no aceptar ofertas bajas y consultar con un abogado antes de firmar cualquier acuerdo.</p>
<p>JUICIO ART</p>
<p>16 ¿Qué es la apelación en un juicio?</p>
<p>En síntesis: Es el recurso para pedir que un tribunal superior revise la sentencia con la que no estás de acuerdo.</p>
<p>La apelación es el recurso que tenés cuando no estás conforme con la sentencia de primera instancia. Un tribunal superior, la Cámara Federal, revisa la decisión y puede confirmarla, modificarla o revocarla.</p>
<p>📌 Derecho: Tanto vos como la ART pueden apelar la sentencia si no están conformes con el porcentaje de incapacidad o el monto de la indemnización.</p>
<p>⏳ Plazo: Existe un plazo breve, de pocos días hábiles desde la notificación de la sentencia, para interponer el recurso.</p>
<p>📌 Tribunal: La Cámara Federal evalúa si el juez aplicó correctamente la ley y si la prueba fue valorada de forma adecuada.</p>
<p>📌 Posibilidad de mejora: La apelación puede mejorar la sentencia si el juez de primera instancia se equivocó en la valoración de la prueba o en la aplicación de la ley.</p>
<p>📌 Consejo práctico: Tu abogado es quien evalúa si conviene apelar, según las posibilidades reales de éxito. Tené en cuenta que una apelación puede extender el juicio entre 1 y 2 años más.</p>
<p>JUICIO ART</p>
<p>17 ¿Puedo hacer juicio si me dieron el alta?</p>
<p>En síntesis: Sí, el alta no cierra tu derecho a reclamar la incapacidad que te dejó la lesión.</p>
<p>El alta médica solo significa que la ART considera que tu tratamiento terminó. Si te quedó una incapacidad permanente, seguís teniendo derecho a reclamar la indemnización correspondiente.</p>
<p>📌 Derecho: El alta no extingue tu derecho a reclamar la incapacidad permanente que te dejó la lesión o la enfermedad.</p>
<p>⏳ Plazo: Tenés 2 años desde el alta médica definitiva para iniciar acciones legales (art. 44, LRT).</p>
<p>📌 Porcentaje de incapacidad: Se evalúa la incapacidad residual según el Baremo 2026 (Decreto 549/2025).</p>
<p>📌 Impugnación del alta: Si el alta te parece prematura, podés impugnarla ante la Comisión Médica dentro de los 5 días hábiles desde la notificación (Resolución SRT N.° 5/2026).</p>
<p>📌 Consejo práctico: El momento del alta es clave para actuar. Si no la impugnás en el plazo legal, podrías perder el derecho a seguir cobrando el subsidio mientras se resuelve tu caso; consultá con un abogado para evaluar si el porcentaje que te asignaron es justo.</p>
<p>JUICIO ART</p>
<p>18 ¿Qué es la medida cautelar en un juicio?</p>
<p>En síntesis: Es una orden del juez que obliga a la ART a darte tratamiento o a pagarte mientras dura el juicio.</p>
<p>La medida cautelar protege tus derechos mientras tramita el juicio contra la ART, sin esperar a la sentencia final.</p>
<p>📌 Objetivo: Protegerte mientras se resuelve el juicio, asegurando el tratamiento médico y el pago del subsidio.</p>
<p>📌 Contenido: El juez puede ordenarle a la ART que continúe el tratamiento, pague el subsidio o realice estudios diagnósticos.</p>
<p>📌 Solicitud: Tu abogado presenta el pedido argumentando la urgencia y la necesidad de la medida.</p>
<p>⏳ Plazo: El juez suele resolver en pocos días, dado el carácter urgente de estas medidas.</p>
<p>📌 Consejo práctico: Si la ART dejó de cumplir con sus obligaciones, no esperes: pedile a tu abogado que solicite una medida cautelar cuanto antes.</p>
<p>JUICIO ART</p>
<p>19 ¿Puedo hacer juicio si la ART me dio una incapacidad del 5%?</p>
<p>En síntesis: Sí, podés reclamar si considerás que tu incapacidad real es mayor.</p>
<p>Podés hacer juicio aunque la ART te haya asignado un 5% de incapacidad. Ese porcentaje no es definitivo y puede ser revisado por un juez si no refleja tu incapacidad real.</p>
<p>📌 Derecho: Podés impugnar la calificación de la ART si considerás que está por debajo de tu incapacidad real.</p>
<p>📌 Evaluación judicial: Un juez, con la asistencia de un perito médico, puede fijar un porcentaje mayor al que determinó la ART.</p>
<p>📌 Pruebas médicas: Tus informes médicos, estudios complementarios y testimonios son clave para demostrar que tu incapacidad es mayor.</p>
<p>📌 Piso mínimo: Si el resultado del cálculo es inferior al piso mínimo que fija la SRT, la ART tiene que pagar el piso.</p>
<p>📌 Consejo práctico: No subestimes un 5% de incapacidad: con la fórmula del art. 14 LRT, incluso ese porcentaje puede quedar por debajo del piso mínimo vigente ($97.502.420 según la Resolución SRT 15/2026), y en ese caso la ART está obligada a pagarte el piso completo. Consultá con un abogado antes de aceptar el número que te dieron.</p>
<p>JUICIO ART</p>
<p>20¿Qué es la audiencia de prueba?</p>
<p>En síntesis: Es la instancia donde se presentan las pruebas y los testigos ante el juez.</p>
<p>La audiencia de prueba es una de las etapas más importantes del juicio: es el momento donde se producen todas las pruebas ofrecidas por las partes, testimonios, pericias médicas e interrogatorios.</p>
<p>📌 Objetivo: Producir las pruebas que fundamentan tu reclamo: es el momento donde se demuestra la relación entre tu accidente y tu incapacidad.</p>
<p>📌 Participación: Tu abogado presenta tu caso, interroga a testigos y peritos, y objeta las preguntas del abogado de la ART si son impertinentes.</p>
<p>📌 Testigos: Pueden declarar compañeros de trabajo, supervisores, médicos tratantes y cualquier persona que conozca las circunstancias del accidente.</p>
<p>📌 Perito médico: Presenta su dictamen y puede ser interrogado por ambas partes sobre sus conclusiones.</p>
<p>📌 Consejo práctico: Asistí con toda tu documentación médica y actuá con naturalidad y honestidad: el juez también evalúa tu credibilidad.</p>
<p>JUICIO ART</p>
<p>21¿Qué es la sentencia en un juicio?</p>
<p>En síntesis: Es la decisión final del juez, que determina cuánto te tiene que pagar la ART.</p>
<p>La sentencia es el documento donde el juez analiza todas las pruebas producidas, aplica la ley y determina si la ART tiene que pagarte una indemnización, y de cuánto.</p>
<p>📌 Contenido: Establece el porcentaje de incapacidad, calcula la indemnización con la fórmula del art. 14 LRT (53 × Ingreso Base × % incapacidad × 65/edad) y define otros rubros que corresponda pagar.</p>
<p>📌 Recurso: Vos y la ART pueden apelarla ante la Cámara Federal si no están conformes con el monto o la incapacidad fijada.</p>
<p>📌 Efecto: Una vez firme, la ART tiene que cumplirla obligatoriamente.</p>
<p>📌 Intereses: Puede incluir el cálculo de intereses desde la fecha del accidente hasta la fecha de la sentencia.</p>
<p>📌 Consejo práctico: La sentencia es el resultado del trabajo de tu abogado y de toda la prueba producida durante el juicio: por eso conviene elegir bien a quién te representa desde el inicio.</p>
<p>JUICIO ART</p>
<p>22¿Puedo hacer juicio si me despidieron?</p>
<p>En síntesis: Sí, lel despido no te impide reclamar por la incapacidad que te dejó el accidente.</p>
<p>El hecho de que hayas dejado de trabajar en la empresa no extingue tu derecho a reclamar la indemnización por la incapacidad permanente que te dejó el accidente o la enfermedad laboral.</p>
<p>📌 Derecho: Podés reclamar la incapacidad permanente sin importar si seguís trabajando o no en la empresa donde te accidentaste.</p>
<p>⏳ Plazo: Tenés 2 años desde el alta médica definitiva o la resolución de la ART (art. 44, LRT).</p>
<p>📌 Indemnización: Te corresponde la compensación calculada con la fórmula: 53 × Ingreso Base × % incapacidad × (65/edad).</p>
<p>📄 Documentación: Guardá toda la documentación laboral (recibos, contrato, carta de baja) y médica (historia clínica, certificados).</p>
<p>📌 Consejo práctico: No confundas la baja laboral con la pérdida de derechos: tus derechos como trabajador accidentado se mantienen aunque hayas dejado la empresa. Consultá con un abogado para evaluar el mejor momento para iniciar el juicio.</p>
<p>JUICIO ART</p>
<p>23 ¿Qué es la liquidación en un juicio?</p>
<p>En síntesis: Es el cálculo final de cuánto te debe la ART, incluyendo intereses y gastos.</p>
<p>La liquidación es el paso final del juicio: el cálculo detallado de todo el monto que la ART tiene que pagarte, incluido el capital de la incapacidad, los intereses y cualquier otro rubro que haya establecido el juez.</p>
<p>📌 Objetivo: Calcular el monto total que la ART tiene que pagarte, desglosando cada componente de la indemnización.</p>
<p>📌 Contenido: El capital de la incapacidad (fórmula del art. 14 LRT), los intereses desde el accidente hasta la sentencia, y el daño moral o los daños estéticos si fueron otorgados.</p>
<p>📌 Proceso: Tu abogado presenta una liquidación detallada; la ART puede cuestionarla y el juez resuelve las diferencias.</p>
<p>📌 Intereses: Se calculan con la tasa que fije el juez, generalmente la tasa activa del Banco Nación o la que aplique la jurisprudencia de tu jurisdicción.</p>
<p>📌 Consejo práctico: Una buena liquidación puede representar una diferencia significativa en el monto final que recibís. Es un trámite técnico: tu abogado lo gestiona con la experiencia y el conocimiento de la jurisprudencia vigente.</p>
<p>001. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué hago si la ART no me quiere cubrir?</p>
<p>En resumen: Tenés derecho a reclamar. Podés denunciar ante la SRT e iniciar el trámite ante la Comisión Médica con el acompañamiento de un abogado.Si la ART se niega a cubrirte, no es el final del camino: tenés herramientas concretas para defender lo que te corresponde. Lo primero es no quedarte de brazos cruzados.</p>
<p>📌 Denuncia ante la SRT: podés hacerla llamando al 0800-666-6778 o a través de la página oficial de la Superintendencia de Riesgos del Trabajo.</p>
<p>📌 Comisión Médica Jurisdiccional: es el paso obligatorio para que se revise el rechazo. Desde febrero de 2026, por la Resolución SRT 5/2026, el trámite debe iniciarse con los formularios oficiales aprobados por la SRT, completados y firmados junto con tu abogado.</p>
<p>📌 Abogado: el patrocinio letrado es obligatorio en este trámite (art. 1, Ley 27.348). Un abogado especializado te acompaña desde la denuncia y, si hace falta, puede llevar el caso ante la Justicia Laboral.</p>
<p>📄 Documentación: reuní toda la prueba médica y testimonial que tengas, porque con la Resolución SRT 5/2026 ahora hay que presentar toda la prueba junto con el escrito inicial, no después.</p>
<p>⏳ Plazos: la prescripción general para reclamar es de 2 años (art. 44, Ley 24.557). No dejes pasar el tiempo.</p>
<p>📌 Sin ART por culpa del empleador: si te quedaste sin cobertura porque tu empleador no contrató una ART, podés recurrir al Fondo de Garantía (FGLP) para asistencia médica urgente.</p>
<p>No aceptes una negativa sin pelearla. Estamos para acompañarte en cada paso: escribinos y vemos juntos cómo seguir.</p>
<p>002. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué es el accidente de trabajo y cómo lo demuestro?</p>
<p>En resumen: Es todo accidente que sufrís durante o a causa de tu trabajo, incluido el trayecto. Se demuestra con testigos, partes médicos y documentación.El accidente de trabajo está definido por el art. 6 de la Ley 24.557 como todo suceso repentino que ocurre en ocasión o como consecuencia del trabajo. También incluye el accidente in itinere (en el trayecto entre tu casa y el trabajo).</p>
<p>📌 Qué reunir: partes médicos con diagnóstico, testimonios de compañeros, fotos del lugar y las condiciones, comunicaciones con tu jefe sobre el hecho, y el parte de ART que tu empleador debe presentar.</p>
<p>📢 Denuncia: avisale a tu empleador apenas puedas, idealmente por escrito y con constancia de recepción. Cuanto antes lo hagas, más fácil es probar la relación con el trabajo.</p>
<p>📌 Si la ART no te lo reconoce: podés iniciar el trámite de rechazo ante la Comisión Médica Jurisdiccional, paso obligatorio antes de cualquier instancia judicial (Ley 27.348).</p>
<p>📌 Enfermedad profesional: también está cubierta la enfermedad causada directamente por el trabajo (art. 6, LRT).</p>
<p>📌 Presunción a tu favor: si el hecho ocurrió en el lugar y horario de trabajo, se presume que es accidente laboral.</p>
<p>Documentá todo desde el primer momento: las pruebas son la base de un reclamo sólido. Si necesitás ayuda para armar el expediente, contactanos.</p>
<p>003. DERECHOS DEL TRABAJADOR</p>
<p>¿Cuánto tiempo tengo para denunciar un accidente laboral?</p>
<p>En resumen: Avisale a tu empleador lo antes posible. Cuanto más tardes, más difícil puede ser probar la relación entre el accidente y tu trabajo.La ley no te da un margen infinito: hay que denunciar el accidente sin demora ante tu empleador, porque el paso del tiempo puede complicar la prueba del hecho.</p>
<p>📌 Cómo denunciar: por escrito, con constancia de recepción si es posible, para tener prueba de que fue presentada.</p>
<p>📌 Tu empleador también tiene una obligación: debe comunicar el accidente a la ART sin demora. Si no lo hace, comete una falta grave que podés denunciar ante la SRT.</p>
<p>📌 Si no pudiste avisar a tiempo: por ejemplo, porque estabas internado o inconsciente, un abogado puede ayudarte a explicar la demora y sostener igual tu reclamo.</p>
<p>📌 Consecuencias de la demora: puede dificultar el reconocimiento, pero no lo impide automáticamente. Cada caso se evalúa con su propia prueba.</p>
<p>📄 Pruebas: testimonios de compañeros, fotos, partes médicos y cualquier documentación que respalde cuándo y cómo ocurrió.</p>
<p>Si ya pasó un tiempo desde el accidente, no te quedes con la duda: consultanos y vemos cómo encarar tu reclamo.</p>
<p>004. DERECHOS DEL TRABAJADOR</p>
<p>¿La ART me puede dar el alta médica sin que esté bien?</p>
<p>En resumen: Puede pasar. Si no estás de acuerdo, podés cuestionar esa decisión ante la Comisión Médica Jurisdiccional.La ART puede darte el alta antes de que sientas que estás completamente recuperado, pero eso no significa que tengas que aceptarla sin más.</p>
<p>📌 Qué hacer: si no estás de acuerdo, podés iniciar el trámite de divergencia ante la Comisión Médica Jurisdiccional de tu zona. Cuanto antes lo hagas después de la notificación del alta, mejor: no dejes pasar el tiempo.</p>
<p>📌 Perito independiente: la Comisión Médica designa un profesional que evalúa tu estado sin injerencia de la ART.</p>
<p>📌 Tenés derecho al tratamiento completo: hasta alcanzar la estabilidad médica, según lo que indique tu diagnóstico (art. 11, LRT).</p>
<p>📌 Mientras se resuelve la divergencia: en general la ART debe seguir cubriendo tu tratamiento y tu incapacidad temporaria mientras el trámite está en curso (art. 13, LRT).</p>
<p>📄 Documentación: reuní todos tus informes médicos, estudios y certificados que respalden que no estás en condiciones de volver.</p>
<p>No te quedes sin reclamar si el alta te parece injusta. Contanos tu caso y evaluamos juntos los pasos a seguir.</p>
<p>005. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué prestaciones me corresponden si me accidento?</p>
<p>En resumen: Asistencia médica completa, indemnización por incapacidad si te quedan secuelas, traslados, prótesis y más, según tu caso particular.Si sufrís un accidente laboral, la Ley 24.557 te garantiza un conjunto de prestaciones en especie y en dinero que la ART debe brindarte.</p>
<p>📌 Asistencia médica total: consultas, cirugías, internación, medicación, kinesiología y rehabilitación (art. 11, LRT).</p>
<p>📌 Incapacidad temporaria: mientras no puedas trabajar, seguís cobrando tu salario a través de la ART (art. 13, LRT).</p>
<p>📌 Incapacidad permanente: si te quedan secuelas, corresponde una indemnización que se calcula según la fórmula del art. 14 de la LRT, tomando en cuenta tu edad, tu salario y el porcentaje de incapacidad que te asignen (según el baremo vigente, actualizado por el Decreto 549/2025). El monto final varía en cada caso: usá nuestra calculadora para tener una primera referencia.</p>
<p>📌 Gastos de traslado: la ART debe cubrir el transporte para tus consultas médicas.</p>
<p>📌 Prótesis y ayudas técnicas: si las necesitás, la ART está obligada a proporcionártelas.</p>
<p>📌 Renta mensual: si tu incapacidad supera cierto umbral, podés acceder a una renta mensual en lugar de un pago único.</p>
<p>Conocer tus prestaciones es el primer paso para no quedarte corto en tu reclamo. Si la ART te niega alguna, escribinos.</p>
<p>006. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué pasa si me despiden mientras estoy con licencia médica?</p>
<p>En resumen: Es un despido que puede considerarse injustificado y discriminatorio. Podés reclamar la reincorporación o una indemnización agravada.Si te despiden estando con licencia médica por un accidente laboral, hay razones fuertes para pensar que ese despido es injustificado.</p>
<p>📌 Protección legal: la ley protege al trabajador accidentado frente al despido durante el período de incapacidad (art. 1 y art. 20, LRT).</p>
<p>📌 Estabilidad laboral: si tenés incapacidad permanente parcial, tu empleador debe mantenerte en tu puesto o reubicarte durante un tiempo determinado por ley.</p>
<p>📌 Opciones: según el caso, podés elegir entre reclamar tu reincorporación con los salarios caídos, o una indemnización agravada.</p>
<p>⏳ Plazo: la prescripción general es de 2 años (art. 44, LRT), pero cuanto antes actúes, mejor se conserva la prueba.</p>
<p>📄 Pruebas: guardá el telegrama de despido, las comunicaciones con tu empleador y los certificados médicos.</p>
<p>📌 Vía judicial: si no se resuelve por las buenas, la acción se tramita ante la Justicia Laboral que corresponda a tu domicilio.</p>
<p>No aceptes un despido así sin consultar. Tus derechos están protegidos y hay caminos concretos para reclamar.</p>
<p>007. DERECHOS DEL TRABAJADOR</p>
<p>¿Puedo elegir médico con la ART?</p>
<p>En resumen: Sí, en el primer nivel de atención. La ART debe ofrecerte más de un profesional entre los cuales elegir.Tenés derecho a elegir tu médico en el primer nivel de atención cuando la ART te brinda cobertura por un accidente laboral.</p>
<p>📌 Primer nivel: la ART debe ofrecerte distintas opciones de profesionales para la atención inicial, no imponerte uno solo sin alternativa.</p>
<p>📌 Especialista: si necesitás uno, la ART puede derivarte, pero siempre buscando tu conformidad.</p>
<p>📌 Cambio de médico: si el profesional no te genera confianza o no te atiende bien, podés pedir un cambio por escrito a la ART.</p>
<p>📌 Si no te dan opciones adecuadas: podés quejarte ante la SRT al 0800-666-6778.</p>
<p>📌 Calidad de atención: tenés derecho a recibir atención médica de calidad y profesional. No tenés por qué aceptar maltratos ni negligencias.</p>
<p>📌 Segunda opinión: en cualquier momento podés buscar una segunda opinión médica independiente.</p>
<p>Tu médico tratante es clave para tu recuperación. Elegí uno en quien confíes, y si algo no funciona, no dudes en pedir el cambio.</p>
<p>008. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué es la Comisión Médica y para qué sirve?</p>
<p>En resumen: Es el organismo de la SRT que interviene, con carácter obligatorio, cuando hay un conflicto con la ART sobre tu incapacidad o tu alta médica.La Comisión Médica Jurisdiccional es el organismo de la SRT que actúa como instancia de revisión, previa y obligatoria, cuando hay un conflicto entre vos y la ART (Ley 27.348).</p>
<p>📌 Funciones: evalúa a los trabajadores accidentados, determina el grado de incapacidad y resuelve las divergencias sobre el alta médica.</p>
<p>📌 Cómo se inicia: desde febrero de 2026, por la Resolución SRT 5/2026, el trámite debe iniciarse con los formularios oficiales aprobados por la SRT, completados a computadora y firmados por vos y tu abogado (el patrocinio letrado es obligatorio, art. 1, Ley 27.348).</p>
<p>📌 Perito independiente: la Comisión designa un profesional que evalúa tu caso sin injerencia de la ART.</p>
<p>⏳ Plazos: la Comisión tiene 60 días hábiles administrativos para resolver, contados desde la primera presentación completa (art. 3, Ley 27.348). La Resolución SRT 5/2026 permite prorrogar ese plazo por 30 días hábiles más en casos que requieran más prueba. Toda la prueba, además, tiene que presentarse junto con el escrito inicial: no se puede ir sumando después.</p>
<p>📌 Si no resuelve a tiempo: podés optar por acudir directamente a la Justicia Laboral Ordinaria de tu provincia o de CABA (Ley 27.348, art. 2), en lugar de esperar indefinidamente.</p>
<p>📌 Independencia: la Comisión Médica es independiente de la ART, lo que apunta a una evaluación más objetiva.</p>
<p>La Comisión Médica es tu principal aliada cuando la ART toma decisiones que no te parecen justas. Si tenés que iniciar un trámite ahí, te acompañamos con el patrocinio letrado desde el primer formulario.</p>
<p>009. DERECHOS DEL TRABAJADOR</p>
<p>¿Cómo me calculan la indemnización por incapacidad?</p>
<p>En resumen: Se basa en tu edad, tu salario y el porcentaje de incapacidad que te asignen. El monto final varía en cada caso: usá nuestra calculadora para un estimado.El cálculo de la indemnización por incapacidad permanente sigue la fórmula del art. 14 de la Ley 24.557, que combina tres variables: tu ingreso base, el porcentaje de incapacidad y tu edad al momento del accidente.</p>
<p>📌 Edad: cuanto mayor seas, menor será el resultado de la fórmula, porque el factor vinculado a tu edad disminuye con los años.</p>
<p>📌 Baremo y piso mínimo: el porcentaje de incapacidad se determina con la tabla de evaluación vigente, actualizada por el Decreto 549/2025. Además, existen pisos mínimos indemnizatorios que se actualizan periódicamente según el RIPTE (Remuneración Imponible Promedio de los Trabajadores Estables). No damos cifras fijas en pesos porque cambian con cada actualización oficial y dependen de la fecha de tu accidente: lo que corresponde en tu caso concreto se calcula con los valores vigentes al momento del siniestro.</p>
<p>📌 Renta: si tu incapacidad supera cierto porcentaje, podés optar por una renta mensual en lugar de un pago único.</p>
<p>📌 Verificación: usá nuestra calculadora de accidentes laborales para tener un primer estimado orientativo de tu caso.</p>
<p>📌 Abogado: siempre conviene que un profesional verifique el cálculo antes de que aceptes un monto que te ofrezca la ART.</p>
<p>No aceptes una indemnización sin chequear si el cálculo es correcto. Un error en la cuenta puede costarte una parte importante de lo que te corresponde.</p>
<p>010. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué es la incapacidad laboral y cómo se mide?</p>
<p>En resumen: Es la reducción permanente de tu capacidad de trabajar. Se mide en porcentaje, según la tabla de incapacidades vigente.La incapacidad laboral es la reducción permanente de tu capacidad de trabajo como consecuencia de un accidente o una enfermedad profesional.</p>
<p>📌 Baremo: la tabla oficial que asigna porcentajes según cada lesión fue actualizada por el Decreto 549/2025. La ART la usa junto con tu edad y tu profesión para calcular el porcentaje que te corresponde.</p>
<p>📌 Parcial permanente: cuando la incapacidad no supera cierto umbral, corresponde una indemnización en un solo pago, calculada según la fórmula del art. 14 de la LRT.</p>
<p>📌 Total permanente: cuando supera ese umbral, podés optar por una renta mensual en lugar del pago único.</p>
<p>📌 Gran invalidez: si necesitás asistencia permanente de otra persona para tus actividades cotidianas, se considera gran invalidez y las prestaciones son mayores.</p>
<p>📌 Si no estás de acuerdo con el porcentaje: podés cuestionarlo ante la Comisión Médica Jurisdiccional. Cuanto antes lo hagas después de recibir el dictamen, mejor.</p>
<p>📌 Revisión: la incapacidad puede revisarse si tu estado empeora o mejora significativamente con el tiempo.</p>
<p>El porcentaje que te asignen determina buena parte de lo que vas a recibir. Antes de aceptarlo, hacé que un abogado lo revise con vos.</p>
<p>011. DERECHOS DEL TRABAJADOR</p>
<p>¿Puedo trabajar mientras estoy con licencia por accidente?</p>
<p>En resumen: Depende de tu estado. Si tu médico o la ART te autorizaron a volver, sí. Si no, lo mejor es esperar el alta.Mientras estás con licencia médica por un accidente laboral, hay reglas claras sobre tu actividad.</p>
<p>📌 Sin autorización: no conviene volver a trabajar sin el aval de la ART o de tu médico tratante. Si lo hacés, la ART puede cuestionar o suspender las prestaciones.</p>
<p>📌 Con autorización: si tu médico habilita el retorno, podés volver, respetando las condiciones que se indiquen.</p>
<p>📌 Tu empleador no puede forzarte: si tu médico no te dio el alta, tu empleador no puede obligarte a trabajar. Si lo hace, es una irregularidad que podés denunciar.</p>
<p>📌 Riesgo de volver antes de tiempo: si trabajás sin autorización y tu lesión empeora, puede ser más difícil sostener el reclamo ante la ART.</p>
<p>📌 Salud primero: lo más importante es que tu recuperación no corra riesgo.</p>
<p>📄 Documentación: guardá todos los certificados médicos que indiquen que no estás en condiciones de trabajar.</p>
<p>Tu recuperación es lo primero. No vuelvas antes de que tu médico lo autorice y la ART lo confirme.</p>
<p>012. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué es el accidente in itinere?</p>
<p>En resumen: Es el accidente que sufrís yendo o volviendo del trabajo. La ART lo cubre igual que un accidente dentro de la empresa.El accidente in itinere es el que sufrís en el trayecto entre tu domicilio y tu lugar de trabajo, o viceversa. La ART lo cubre igual.</p>
<p>✅ Cobertura: según el art. 6 de la LRT, el accidente in itinere está expresamente incluido entre las contingencias cubiertas.</p>
<p>📌 Trayecto habitual: lo importante es que el recorrido sea el que hacés normalmente para ir a trabajar.</p>
<p>📌 Desvíos: si hiciste paradas o cambios de recorrido sin justificación, la ART puede cuestionar la cobertura, aunque muchas paradas razonables (como llevar a un hijo a la escuela) están contempladas.</p>
<p>📄 Pruebas: testimonios, datos de la ruta, horarios habituales y cualquier evidencia del recorrido ayudan a tu reclamo.</p>
<p>📢 Denuncia: avisá cuanto antes a tu empleador y a la ART.</p>
<p>📌 Si te rechazan la cobertura: podés iniciar el trámite ante la Comisión Médica Jurisdiccional para que se revise.</p>
<p>No subestimes esta protección: si te accidentás yendo o viniendo del trabajo, estás cubierto igual.</p>
<p>013. DERECHOS DEL TRABAJADOR</p>
<p>¿Puedo pedir una segunda opinión médica con la ART?</p>
<p>En resumen: Sí, podés pedir la intervención de un perito independiente a través de la Comisión Médica Jurisdiccional.Tenés derecho a buscar una segunda opinión médica cuando no estás conforme con la evaluación de la ART.</p>
<p>📌 Cómo pedirla: solicitando que la Comisión Médica Jurisdiccional revise tu caso con un perito independiente, sin relación con la ART.</p>
<p>📌 Si tampoco estás conforme: podés recurrir ante la Comisión Médica Central o, directamente, ante la Justicia Laboral Ordinaria de tu provincia o de CABA (Ley 27.348, art. 2).</p>
<p>📌 Importancia: nunca te conformes con una sola opinión si sentís que no refleja tu estado real.</p>
<p>📄 Documentación: reuní todos los informes médicos de ambas evaluaciones para poder compararlos.</p>
<p>⏳ Tiempos: no hay que demorar demasiado en pedir la revisión; cuanto antes lo hagas después del dictamen que cuestionás, mejor se conserva tu derecho.</p>
<p>Tu salud y tus derechos merecen la mejor evaluación posible. Si necesitás ayuda para pedir esa segunda opinión, escribinos.</p>
<p>014. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué obligaciones tiene mi empleador conmigo?</p>
<p>En resumen: Contratar una ART, darte elementos de protección, capacitarte y mantener un lugar de trabajo seguro son sus obligaciones principales.Tu empleador tiene obligaciones legales claras para garantizar tu seguridad y salud en el trabajo.</p>
<p>📌 Contratar una ART: es obligatorio (art. 1, LRT).</p>
<p>📌 Elementos de protección: cascos, guantes, lentes, calzado de seguridad, según la tarea.</p>
<p>📌 Capacitación: debe informarte sobre los riesgos laborales y las medidas de prevención.</p>
<p>📌 Lugar de trabajo seguro: limpio, ordenado y en condiciones.</p>
<p>📌 Denunciar accidentes: debe comunicarlos a la ART sin demora.</p>
<p>📌 Si no cumple: podés denunciarlo ante la SRT, la AFIP, y en algunos casos demandarlo.</p>
<p>📌 Sin ART: si tu empleador no tiene una contratada, las prestaciones las debe pagar él directamente.</p>
<p>Tu empleador tiene obligaciones, y vos tenés derechos. No dejes que se salga con la suya: contanos si algo no se está cumpliendo.</p>
<p>015. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué es la renta por incapacidad?</p>
<p>En resumen: Es un pago mensual que te da la ART cuando tu incapacidad supera un porcentaje elevado, en lugar de un pago único.La renta por incapacidad es un pago mensual que la ART otorga a trabajadores con un porcentaje de incapacidad alto.</p>
<p>📌 Requisito: tu incapacidad tiene que superar el umbral que fija la ley. Por debajo de ese umbral, corresponde una indemnización en un solo pago.</p>
<p>📌 Cálculo: se calcula sobre tu salario promedio y se actualiza periódicamente. El monto exacto depende de tu situación particular: nuestra calculadora te da una primera referencia.</p>
<p>📌 Incapacidad total (100%): recibís el monto completo previsto para la renta.</p>
<p>📌 Actualización: se actualiza para no perder poder adquisitivo con el tiempo.</p>
<p>📌 Alternativa: en algunos casos podés elegir entre la renta mensual o una indemnización en un solo pago.</p>
<p>📌 Asesoramiento: consultá con un abogado para saber qué opción te conviene más según tu situación.</p>
<p>La renta por incapacidad es una protección clave para trabajadores con lesiones graves. Si tenés dudas sobre cuál opción elegir, hablemos.</p>
<p>016. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué hago si la ART no me da los medicamentos que necesito?</p>
<p>En resumen: Reclamá por escrito adjuntando la receta. Si no responden, podés denunciar ante la SRT y, en casos urgentes, pedir intervención judicial.Si la ART no te da los medicamentos que tu médico recetó, tenés herramientas para reclamar.</p>
<p>📌 Paso 1: reclamá por escrito adjuntando la receta médica y los informes que justifiquen la medicación.</p>
<p>📌 Paso 2: si no responden en un plazo razonable, denunciá ante la SRT (0800-666-6778).</p>
<p>📌 Urgencia: si la negativa pone en riesgo tu salud, un abogado puede pedir una medida urgente ante la Justicia.</p>
<p>📌 Obligación de la ART: no puede negarte tratamientos necesarios; está obligada por ley (art. 11, LRT).</p>
<p>📌 Secuelas: incluso después del alta, la ART debe seguir cubriendo la medicación vinculada a las secuelas del accidente.</p>
<p>📌 Alternativa: si no te la dan, podés comprarla vos y reclamar el reembolso con los comprobantes.</p>
<p>No te quedes sin tu medicación por la negativa de la ART. Tus derechos están protegidos: contanos qué está pasando.</p>
<p>017. DERECHOS DEL TRABAJADOR</p>
<p>¿Puedo hacer el reclamo a la ART sin abogado?</p>
<p>En resumen: Para el trámite ante la Comisión Médica, el patrocinio letrado es obligatorio por ley. Un abogado te protege de errores que te pueden costar caro.El trámite ante la Comisión Médica Jurisdiccional exige patrocinio letrado obligatorio (art. 1, Ley 27.348): sin abogado, ni siquiera se puede iniciar el expediente. Es una garantía para vos, no un trámite burocrático de más.</p>
<p>📌 Complejidad: los trámites tienen plazos estrictos y, desde la Resolución SRT 5/2026, formularios específicos y reglas más rígidas sobre la prueba.</p>
<p>📌 La ART está preparada: tiene sus propios abogados. Vos necesitás alguien que trabaje exclusivamente para vos.</p>
<p>📌 Monto justo: un abogado revisa que el cálculo de tu indemnización sea correcto antes de que aceptes nada.</p>
<p>📌 Honorarios: los honorarios profesionales los paga el trabajador (no la ART), generalmente un porcentaje sobre lo que se obtiene en el reclamo, habitualmente en torno al 20%. Muchos estudios, incluido el nuestro, no cobran nada por adelantado: se cobra solo si hay resultado.</p>
<p>📌 Alternativas si no podés pagar: podés recurrir a la Defensoría del Pueblo o a organizaciones de derechos laborales para orientación inicial.</p>
<p>El costo de no tener abogado suele ser mayor que el de contratar uno: perder derechos por un error de trámite o aceptar un monto menor al que te corresponde. Si tenés dudas, conversemos sin compromiso.</p>
<p>018. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué es la estabilidad laboral del accidentado?</p>
<p>En resumen: Es la protección que impide que te despidan sin justa causa mientras tenés una incapacidad por accidente de trabajo.La estabilidad laboral del accidentado es una protección legal que limita la posibilidad de que tu empleador te despida durante el período de incapacidad.</p>
<p>📌 Incapacidad parcial permanente: tu empleador debe mantenerte en tu puesto, o reubicarte si tus limitaciones lo requieren, durante el plazo que fija la ley.</p>
<p>📌 Incapacidad total permanente y gran invalidez: la protección es más extensa según el caso.</p>
<p>📌 Adecuación del puesto: durante ese período, el empleador debe adecuar tu puesto a tus limitaciones o reubicarte en otro compatible.</p>
<p>📌 Despido durante la protección: si te despiden en ese lapso sin causa justificada, podés reclamar reinstalación o una indemnización agravada, según tu situación.</p>
<p>📄 Documentación: guardá certificados médicos, comunicaciones con el empleador y telegramas de despido.</p>
<p>Tu empleador no puede despedirte por el accidente. Si lo hace, no te quedes con la duda: consultanos y evaluamos tu caso.</p>
<p>019 . DERECHOS DEL TRABAJADOR</p>
<p>¿Cómo funciona el baremo de lesiones de la ART?</p>
<p>En resumen: Es la tabla oficial que asigna un porcentaje de incapacidad según cada lesión. Se actualizó con el Decreto 549/2025.El baremo de lesiones es la tabla oficial que asigna un porcentaje de incapacidad según el tipo y la gravedad de la lesión que sufriste.</p>
<p>📌 Actualización: el baremo vigente fue actualizado por el Decreto 549/2025, que reemplazó y ajustó la tabla anterior. Es importante verificar qué versión del baremo corresponde a tu caso según la fecha de tu accidente.</p>
<p>📌 Cómo se usa: la ART combina el porcentaje del baremo con tu edad y tu salario para calcular la indemnización, según la fórmula del art. 14 de la LRT. No damos montos fijos en pesos porque dependen de la fecha del siniestro y de los valores vigentes en ese momento: usá nuestra calculadora para tener una referencia orientativa.</p>
<p>📌 Flexibilidad: el baremo es una guía técnica; un juez puede apartarse del porcentaje asignado si tu caso tiene particularidades que lo justifiquen.</p>
<p>📌 Si el porcentaje no te parece justo: podés cuestionarlo ante la Comisión Médica Jurisdiccional, con el acompañamiento de tu abogado.</p>
<p>Conocer el baremo te da una idea de qué porcentaje podría corresponderte, pero no reemplaza una revisión profesional de tu caso. No aceptes un porcentaje sin que un abogado lo verifique.</p>
<p>020. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué documentos necesito para hacer el reclamo?</p>
<p>En resumen: DNI, certificado de trabajo, parte médico y toda la documentación que respalde tu lesión y la relación con el trabajo.Para iniciar un reclamo ante la ART, conviene reunir cierta documentación de entrada.</p>
<p>📌 Documentos esenciales: DNI vigente, recibo de sueldo o certificado de trabajo, parte médico con diagnóstico, fecha del accidente y nombre de la ART.</p>
<p>📌 Pruebas adicionales: testimonios de compañeros, fotos del lugar, comunicaciones con tu jefe.</p>
<p>📌 Organización: guardá copias de todo en un lugar seguro. La documentación es tu mejor herramienta.</p>
<p>📌 Parte de ART: tu empleador debe haber presentado el parte de accidente ante la ART. Pedí una copia.</p>
<p>📌 Con la Resolución SRT 5/2026: toda la prueba de la que quieras valerte hay que presentarla junto con el escrito inicial del trámite ante la Comisión Médica, no después. Por eso conviene reunir todo antes de arrancar.</p>
<p>No subestimes la importancia de la documentación: sin pruebas, tu reclamo se debilita. Si querés que te ayudemos a armar el expediente, escribinos.</p>
<p>021. DERECHOS DEL TRABAJADOR</p>
<p>¿Puedo reclamar si el accidente fue culpa mía?</p>
<p>En resumen: Sí, la ART te cubre igual. Que hayas tenido un descuido no te quita el derecho a las prestaciones.La ART te cubre aunque el accidente haya sido, en parte, por un descuido tuyo. El sistema de la Ley 24.557 tiene naturaleza objetiva.</p>
<p>📌 Naturaleza objetiva: mientras el accidente haya ocurrido en ocasión del trabajo, tenés derecho a las prestaciones sin que se discuta la culpa.</p>
<p>📌 Excepción: la principal excepción es que el accidente haya sido intencional (dolo del propio trabajador).</p>
<p>📌 Un descuido no te excluye: si te lastimaste por un error o una maniobra imprudente, la ART igual te cubre.</p>
<p>📌 Tus obligaciones: aun así, tenés que denunciar el accidente cuanto antes y asistir al tratamiento (art. 21, LRT).</p>
<p>📄 Documentación: juntá testimonios, fotos y pruebas de cómo ocurrieron las cosas, sin miedo a contar lo que pasó.</p>
<p>No tengas miedo de reclamar por vergüenza. La ley te protege aunque hayas tenido algo de responsabilidad en el accidente.</p>
<p>022. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué es la SRT y para qué sirve?</p>
<p>En resumen: Es la Superintendencia de Riesgos del Trabajo. Controla a las ART y es el primer lugar al que recurrir si no te tratan bien.La Superintendencia de Riesgos del Trabajo (SRT) es el organismo nacional que controla todo el sistema de ART en Argentina.</p>
<p>📌 Funciones principales: controlar a las ART, recibir denuncias, fiscalizar el cumplimiento de la Ley 24.557, coordinar las Comisiones Médicas Jurisdiccionales y dictar normas de prevención.</p>
<p>📌 Contacto: podés comunicarte al 0800-666-6778 (línea gratuita) o a través de su página web oficial.</p>
<p>📢 Denuncias: si tenés problemas con tu ART, la SRT es el primer lugar al que acudir.</p>
<p>📌 Poder de sanción: puede sancionar a las ART que no cumplan con sus obligaciones.</p>
<p>📌 Asesoramiento: también brinda información a trabajadores sobre sus derechos.</p>
<p>La SRT está para protegerte. No dudes en recurrir a ella si tu ART no te trata correctamente, y si necesitás que un abogado lleve adelante el reclamo, contanos.</p>
<p>023. DERECHOS DEL TRABAJADOR</p>
<p>¿Cuánto tarda la ART en aceptar mi caso?</p>
<p>En resumen: Tiene un plazo breve para aceptar o rechazar tu denuncia. Si no responde a tiempo, el silencio juega a tu favor.La ART tiene plazos legales acotados para responder a tu siniestro.</p>
<p>📌 Plazo inicial: la ART debe expedirse en un plazo breve desde que recibe la denuncia del accidente, con posibilidad de una prórroga corta si justifica que necesita más tiempo.</p>
<p>📌 Silencio de la ART: si no responde dentro del plazo que corresponde, en general se entiende que aceptó tácitamente la cobertura del hecho.</p>
<p>📌 Si te rechaza: podés iniciar el trámite de rechazo ante la Comisión Médica Jurisdiccional. Si esa instancia tampoco resuelve en los plazos que fija la Ley 27.348 (60 días hábiles, prorrogables por 30 días hábiles más según la Resolución SRT 5/2026), podés optar por ir directamente a la Justicia Laboral Ordinaria de tu provincia o de CABA.</p>
<p>📄 Documentación: guardá todos los comprobantes de presentación, con fecha y número de expediente.</p>
<p>📌 Seguimiento: hacé seguimiento constante del estado de tu trámite. No esperes pasivamente.</p>
<p>Los plazos son importantes. Si la ART no responde, eso puede jugar a tu favor: consultanos para confirmar exactamente cómo aplica a tu caso.</p>
<p>024. DERECHOS DEL TRABAJADOR</p>
<p>¿Puedo cobrar la indemnización y seguir trabajando?</p>
<p>En resumen: Depende del tipo de incapacidad. Con incapacidad parcial generalmente sí; con incapacidad total, suele corresponder una renta mensual.La relación entre cobrar la indemnización y seguir trabajando depende del tipo de incapacidad que tengas.</p>
<p>📌 Incapacidad parcial permanente (por debajo del umbral que fija la ley): podés recibir una indemnización en un solo pago y, en general, seguir trabajando.</p>
<p>📌 Incapacidad total permanente (por encima de ese umbral): generalmente corresponde una renta mensual. Podés seguir trabajando si tu empleador te mantiene en un puesto compatible.</p>
<p>📌 Gran invalidez: si necesitás asistencia permanente de otra persona, en general implica que no podés seguir trabajando.</p>
<p>📌 Tu empleador: puede mantenerte en tu puesto si tu tarea es compatible con tu estado.</p>
<p>📌 Cada caso es distinto: consultá con un abogado para entender cómo afecta tu incapacidad concreta a tu situación laboral y económica.</p>
<p>La incapacidad no significa necesariamente que tengas que dejar de trabajar. Conversemos tu caso puntual.</p>
<p>025. DERECHOS DEL TRABAJADOR</p>
<p>¿Me cubren si me accidento yendo al baño del trabajo?</p>
<p>En resumen: Sí, mientras sea dentro de tu jornada laboral y en el ámbito de la empresa, está cubierto.Los accidentes dentro del lugar de trabajo, durante la jornada laboral, están cubiertos por la ART.</p>
<p>📌 Ámbito cubierto: baños, comedores, salas de descanso, pasillos, estacionamientos de la empresa.</p>
<p>📌 Jornada laboral: lo importante es que ocurra durante tu jornada, o en un lapso razonable antes o después.</p>
<p>📄 Pruebas: testimonios, cámaras de seguridad, registros de entrada y salida.</p>
<p>📢 Denuncia: avisá a tu empleador cuanto antes.</p>
<p>📌 Cobertura completa: te corresponden todas las prestaciones: asistencia médica, incapacidad temporaria y permanente si aplica.</p>
<p>📌 Si te rechazan la cobertura: podés iniciar el trámite ante la Comisión Médica Jurisdiccional.</p>
<p>No importa exactamente dónde dentro de la empresa te accidentaste, mientras sea durante tu jornada: estás cubierto.</p>
<p>026. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué pasa si me niego a hacer un trabajo peligroso?</p>
<p>En resumen: Podés negarte sin que te sancionen. Tu empleador tiene la obligación de garantizar tu seguridad.Tenés derecho a negarte a realizar tareas que pongan en riesgo tu vida o tu salud.</p>
<p>📌 Protección: tu empleador no puede sancionarte ni despedirte válidamente por esa decisión, si las condiciones eran efectivamente inseguras.</p>
<p>📌 Condiciones inseguras: si el lugar no es seguro, no te dan los elementos de protección necesarios o las condiciones son de riesgo, tenés fundamento para negarte.</p>
<p>📢 Denuncia: podés denunciar las condiciones inseguras ante la SRT.</p>
<p>📄 Documentación: registrá las condiciones con fotos, videos y testimonios.</p>
<p>📌 Seguridad primero: es un derecho, no un privilegio que dependa de la buena voluntad del empleador.</p>
<p>📌 Si te presionan: buscá asesoramiento legal antes de tomar una decisión.</p>
<p>No pongas tu vida en riesgo por miedo a represalias. Si tu empleador te presiona en una situación así, consultanos.</p>
<p>027. DERECHOS DEL TRABAJADOR</p>
<p>¿La ART cubre los gastos de rehabilitación?</p>
<p>En resumen: Sí, kinesiología, terapia ocupacional y los tratamientos que necesites están cubiertos hasta tu estabilidad médica.La ART tiene la obligación legal de cubrir los gastos de rehabilitación que necesites.</p>
<p>📌 Tratamientos cubiertos: kinesiología, terapia ocupacional, fisioterapia, prótesis, órtesis y rehabilitación integral.</p>
<p>📌 Hasta cuándo: debe cubrir estos tratamientos hasta que alcances la estabilidad médica (art. 11, LRT).</p>
<p>📌 Secuelas: incluso después del alta, la ART sigue cubriendo los tratamientos necesarios para las secuelas del accidente.</p>
<p>📌 Si la ART se niega: podés reclamar ante la Comisión Médica Jurisdiccional.</p>
<p>📌 Calidad: tenés derecho a recibir tratamientos de calidad, no atención incompleta o deficiente.</p>
<p>Tu rehabilitación es fundamental para tu recuperación. No aceptes tratamientos incompletos: la ART debe cubrir todo lo que tu médico indique como necesario.</p>
<p>028. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué es la ART y por qué me la asignan?</p>
<p>En resumen: Es la Aseguradora de Riesgos del Trabajo. Tu empleador está obligado a contratarla para cubrir accidentes laborales.La Aseguradora de Riesgos del Trabajo (ART) es la empresa de seguros que tu empleador está obligado por ley a contratar.</p>
<p>📌 Obligación: según el art. 1 de la Ley 24.557, toda empresa está obligada a contratar una ART (o autoasegurarse, si cumple los requisitos para eso).</p>
<p>📌 Quién la elige: la ART la elige el empleador, no vos. No podés elegirla ni cambiarla por tu cuenta.</p>
<p>✅ Cobertura: debe brindarte asistencia médica integral, incapacidad temporaria y permanente, y las demás prestaciones de la ley.</p>
<p>📌 Sin ART: si tu empleador no tiene una contratada, las prestaciones las paga él directamente.</p>
<p>📌 Cambios de ART: si tu empleador cambia de aseguradora, vos pasás a estar cubierto por la nueva automáticamente.</p>
<p>📢 Reclamos: si tu ART no te trata bien, podés denunciar ante la SRT al 0800-666-6778.</p>
<p>La ART es tu cobertura obligatoria frente a un accidente. Conocé tus derechos y no aceptes maltratos.</p>
<p>029 . DERECHOS DEL TRABAJADOR</p>
<p>¿Puedo cambiarme de ART?</p>
<p>En resumen: No, la elige tu empleador. Pero podés reclamar ante la SRT si no te tratan bien.No podés elegir ni cambiar tu ART por tu cuenta: la selecciona tu empleador. Aun así, tenés opciones si no te tratan bien.</p>
<p>📢 Denuncia: si tu ART no te trata adecuadamente, denunciá ante la SRT.</p>
<p>📌 Comisión Médica y Justicia: si el conflicto es sobre tu incapacidad o el alta, podés recurrir a la Comisión Médica Jurisdiccional y, si hace falta, a la Justicia Laboral.</p>
<p>📌 Abogado: buscá un abogado especialista que pueda evaluar tu situación puntual.</p>
<p>📌 Derechos: aunque no puedas cambiar la ART, tenés derecho a recibir atención de calidad.</p>
<p>📄 Documentación: guardá todas las quejas y comunicaciones con la ART.</p>
<p>No podés elegir la ART, pero sí podés reclamar si no cumple con sus obligaciones. Contanos qué está pasando.</p>
<p>030. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué es la enfermedad profesional y cómo la pruebo?</p>
<p>En resumen: Es una enfermedad causada directamente por las condiciones de tu trabajo. Se prueba con certificados médicos y evidencia de exposición al riesgo.La enfermedad profesional es la que se origina directamente en las condiciones de tu trabajo. A diferencia del accidente, suele desarrollarse de forma gradual.</p>
<p>📌 Definición: toda enfermedad que surge como consecuencia del trabajo habitual, en condiciones específicas de exposición (art. 6, LRT).</p>
<p>📌 Cómo probarla: con un certificado médico que vincule la enfermedad con el trabajo, evidencia de la exposición al riesgo, y tu historial laboral.</p>
<p>📌 Ejemplos: problemas de columna por carga de peso, lesiones por movimientos repetitivos, enfermedades respiratorias por exposición a polvo o químicos.</p>
<p>✅ Cobertura: la ART debe cubrirla con las mismas prestaciones que un accidente de trabajo.</p>
<p>📌 Prescripción: el plazo general es de 2 años, contados desde que se diagnosticó la enfermedad o desde que dejaste de estar expuesto al riesgo.</p>
<p>Si tu enfermedad está vinculada a tu trabajo, tenés derecho a la cobertura de la ART. Consultanos para que te ayudemos a reunir las pruebas.</p>
<p>031. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué pasa si la ART no me manda a un especialista?</p>
<p>En resumen: Reclamá por escrito. Si no te derivan, podés pedir la intervención de la Comisión Médica.Si la ART no te deriva a un especialista que necesitás, tenés opciones para reclamar esa atención.</p>
<p>📌 Pedido formal: solicitá la derivación por escrito.</p>
<p>📌 Si te la niegan: denunciá ante la SRT. La ART está obligada a brindarte atención especializada si tu caso lo requiere (art. 11, LRT).</p>
<p>📌 Comisión Médica: podés pedir que evalúe tu caso y determine si necesitás un especialista.</p>
<p>📌 Abogado: si hace falta llegar a una instancia judicial, un abogado puede acompañarte.</p>
<p>📄 Documentación: guardá todos los pedidos y respuestas de la ART.</p>
<p>No aceptes una atención médica incompleta. Si necesitás un especialista y no te lo dan, escribinos.</p>
<p>032. DERECHOS DEL TRABAJADOR</p>
<p>¿Me cubren si me accidento fuera de horario pero en la empresa?</p>
<p>En resumen: Si estabas haciendo tareas laborales, sí. Si no tenía relación con tu trabajo, puede que la ART cuestione la cobertura.La cobertura depende de si el accidente ocurrió en ocasión del trabajo, no estrictamente del horario formal.</p>
<p>📌 Fuera de horario pero trabajando: si estabas haciendo tareas vinculadas a tu trabajo, la ART te cubre igual.</p>
<p>📌 Sin relación con el trabajo: si el momento no tenía nada que ver con tus tareas, es más probable que la ART cuestione la cobertura.</p>
<p>📌 Prueba: necesitás demostrar que estabas realizando trabajo en ese momento: testimonios, comunicaciones con tu jefe, registros.</p>
<p>📢 Denuncia: avisá el accidente cuanto antes y dejá que la ART lo evalúe.</p>
<p>📌 Si te rechazan la cobertura: podés impugnar ante la Comisión Médica Jurisdiccional.</p>
<p>La cobertura no depende solo del horario, sino de si estabas efectivamente trabajando. Evaluemos tu caso puntual.</p>
<p>033. DERECHOS DEL TRABAJADOR</p>
<p>¿Puedo reclamar si el accidente fue por un defecto de una máquina?</p>
<p>En resumen: Sí, hay varios frentes posibles: tu empleador, el fabricante y el distribuidor, además de la cobertura de la ART.Si el accidente fue por el defecto de una máquina, hay más de un camino posible para tu reclamo.</p>
<p>📌 Tu empleador: por no mantener la máquina en condiciones seguras.</p>
<p>📌 El fabricante: por responsabilidad frente a un producto defectuoso.</p>
<p>📌 El distribuidor: en algunos casos, también puede ser responsable.</p>
<p>📌 Guardá la máquina: no dejes que se destruya ni se modifique; es una prueba clave para tu caso.</p>
<p>📌 ART: mientras tanto, la ART debe cubrirte con todas las prestaciones de la LRT, sin importar de quién sea la culpa.</p>
<p>📌 Sobre reclamar además por daños y perjuicios: hay que evaluar con cuidado la &quot;opción excluyente&quot; de la Ley 26.773 entre el sistema ART y la vía civil, para no perder derechos por elegir mal el camino.</p>
<p>📌 Abogado: consultá para evaluar todos los frentes de reclamo disponibles en tu caso concreto.</p>
<p>Un defecto de máquina puede abrir varios caminos de reclamo. Evaluemos juntos cuál te conviene antes de dar el primer paso.</p>
<p>034. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué derechos tengo si sufro un accidente grave?</p>
<p>En resumen: Asistencia médica total, indemnización si te quedan secuelas.Si sufrís un accidente grave, la ley te garantiza un conjunto amplio de prestaciones para tu recuperación y tu subsistencia.</p>
<p>📌 Asistencia médica total: consultas, tratamientos, cirugías, internación y medicación.</p>
<p>📌 Internación: si hace falta, la ART cubre todos los gastos.</p>
<p>📌 Medicamentos: toda la medicación que indique tu médico.</p>
<p>📌 Indemnización: por incapacidad permanente, si te quedan secuelas.</p>
<p>📌 Renta mensual: si tu incapacidad supera el umbral que fija la ley, podés acceder a una renta en lugar de un pago único.</p>
<p>📌 Ayudas técnicas: prótesis, sillas de ruedas, bastones y lo que necesites según tu caso.</p>
<p>📌 Capacitación: para tu reinserción laboral si es necesario.</p>
<p>📌 Asistencia psicológica: para acompañar el impacto emocional del accidente.</p>
<p>En un accidente grave, conocer todas tus prestaciones es fundamental. Estamos para acompañarte en cada una de ellas.</p>
<p>035. DERECHOS DEL TRABAJADOR</p>
<p>¿Puedo reclamar si soy empleado doméstico?</p>
<p>En resumen: Sí, si estás registrado tenés los mismos derechos laborales que cualquier trabajador, incluida la cobertura de la ART.Si sos empleado o empleada doméstica registrada, tenés los mismos derechos laborales que cualquier otro trabajador, incluida la cobertura de la ART.</p>
<p>📌 Cobertura de la ART: tu empleador debe contratarte una ART igual que a cualquier otro trabajador.</p>
<p>📌 Licencia por enfermedad: tenés derecho a licencia paga cuando estás enfermo.</p>
<p>📌 Aguinaldo y vacaciones: te corresponden como a cualquier trabajador.</p>
<p>📌 Indemnización por despido: si te despiden sin causa, te corresponde la indemnización que fija la ley.</p>
<p>📌 Registro: tu empleador tiene la obligación de registrarte.</p>
<p>📌 Si no te registró o no te dio ART: podés denunciar ante la SRT y la AFIP.</p>
<p>Ser empleado doméstico no te quita derechos: si estás registrada o registrado, tenés la misma protección que cualquier trabajador. Consultanos tu caso.</p>
<p>036. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué pasa si la ART me da un porcentaje de incapacidad bajo?</p>
<p>En resumen: Podés cuestionarlo ante la Comisión Médica Jurisdiccional. Un abogado puede pedir una revisión con un perito independiente.Si te dieron un porcentaje de incapacidad que sentís que no refleja tu realidad, tenés opciones para reclamar uno más justo.</p>
<p>📌 Trámite ante la Comisión Médica Jurisdiccional: presentá un pedido explicando por qué el porcentaje no refleja tu situación, con el acompañamiento de tu abogado (patrocinio letrado obligatorio).</p>
<p>📌 Revisión con perito independiente: podés pedir que un perito, sin relación con la ART, evalúe tu caso.</p>
<p>📌 Acción judicial: si esa instancia no resuelve conforme a derecho, podés recurrir ante la Comisión Médica Central o directamente ante la Justicia Laboral Ordinaria de tu provincia o de CABA (Ley 27.348).</p>
<p>📌 Pruebas médicas: reuní informes detallados que reflejen la verdadera magnitud de tus limitaciones.</p>
<p>📌 Baremo vigente: verificá que el porcentaje asignado sea consistente con la tabla de incapacidades actualizada por el Decreto 549/2025.</p>
<p>📌 Con la Resolución SRT 5/2026: toda la prueba que quieras aportar tiene que presentarse junto con el pedido inicial, así que conviene reunirla antes de arrancar el trámite.</p>
<p>No aceptes un porcentaje bajo sin cuestionarlo. Tenés derecho a que refleje tu incapacidad real: conversemos tu caso.</p>
<p>037. DERECHOS DEL TRABAJADOR</p>
<p>¿Qué recursos legales tengo si la ART no me respeta mis derechos?</p>
<p>En resumen: SRT, Comisión Médica Jurisdiccional y, si hace falta, la Justicia Laboral están a tu disposición.Si la ART no respeta tus derechos, tenés más de un recurso legal disponible.</p>
<p>📌 Denuncia ante la SRT: es el primer paso. La SRT puede sancionar a la ART.</p>
<p>📌 Comisión Médica Jurisdiccional: para cuestiones médicas, de incapacidad o de rechazo de cobertura, con patrocinio letrado obligatorio.</p>
<p>📌 Justicia Laboral Ordinaria: si la Comisión Médica no resuelve o si no estás de acuerdo con su dictamen, podés recurrir a la Justicia Laboral de tu provincia o de CABA (Ley 27.348), y ya no a la justicia federal como se exigía antes de la reforma de 2017.</p>
<p>📌 Amparo: si la ART niega un tratamiento urgente, en casos graves un abogado puede pedir una medida urgente ante la Justicia.</p>
<p>📌 Defensa del consumidor: en ciertos aspectos, la ART también está alcanzada por normas de protección al usuario de servicios.</p>
<p>⏳ Plazos: la prescripción general es de 2 años (art. 44, LRT). No pierdas ese plazo.</p>
<p>Tenés varios caminos para hacer valer tus derechos frente a la ART. No te quedes sin reclamar: estamos para acompañarte en el que corresponda a tu caso.</p>
<p>REHABILITACIÓN  ·</p>
<p>rehabilitacion-001</p>
<p>¿Qué es la rehabilitación y por qué es tan importante después de un accidente laboral?</p>
<p>En resumen: Es el conjunto de tratamientos para recuperar tus capacidades físicas y psicológicas. La ART está obligada a dártela sin costo hasta que te recuperes.La rehabilitación es el conjunto de tratamientos kinesiología, fisioterapia, terapia ocupacional, apoyo psicológico que buscan devolverte las capacidades físicas, mentales y sociales que perdiste por el accidente o la enfermedad profesional. No es un beneficio opcional: según el artículo 11 de la Ley 24.557 (LRT), es una de las prestaciones en especie que la ART tiene la obligación legal de brindarte sin costo alguno, y debe sostenerse hasta que logres la curación completa o hasta que tu cuadro se estabilice en una secuela definitiva.</p>
<p>📌 Prestación obligatoria: la ART no puede cobrarte ni derivarte a tu obra social para esto.</p>
<p>📌 Integral: incluye recuperación física y también psicológica, porque el impacto emocional también forma parte del daño.</p>
<p>📌 Sin plazo fijo de antemano: dura lo que tu lesión necesite, según lo determine tu médico tratante.</p>
<p>📌 Reclamable: si te la niegan o te la cortan antes de tiempo, podés denunciar ante la SRT o acudir a la Comisión Médica.</p>
<p>📌 Consejo práctico: Guardá cada informe, turno y constancia desde el primer día. Esa documentación es tu principal respaldo si más adelante la ART intenta discutir tu tratamiento o el porcentaje de incapacidad que te asignen.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-002</p>
<p>¿Qué tipo de tratamientos de rehabilitación me puede dar la ART?</p>
<p>En resumen: Kinesiología, fisioterapia, terapia ocupacional, hidroterapia, psicoterapia y todo lo que tu lesión requiera.La ART debe brindarte una amplia gama de tratamientos según tu diagnóstico: kinesiología, fisioterapia, terapia ocupacional, hidroterapia, masajes terapéuticos, reeducación postural y asistencia psicológica o psiquiátrica cuando corresponda. Todos están comprendidos en el artículo 11 de la Ley 24.557 como prestaciones en especie de carácter obligatorio, y es tu médico tratante no la ART quien decide cuáles necesitás según el tipo y la gravedad de tu lesión.</p>
<p>📌 El criterio médico manda: la ART no puede recortar un tratamiento indicado sin una justificación médica fundada por escrito.</p>
<p>📌 Se ajusta a tu lesión: una lesión de columna no se trata igual que una de mano, y el plan debe reflejarlo.</p>
<p>📌 Todo por escrito: pedí que cada indicación y cada rechazo queden documentados.</p>
<p>📌 Vía de reclamo: ante una negativa sin fundamento, podés acudir a la Comisión Médica dentro de los 60 días hábiles administrativos (art. 3, Ley 27.348).</p>
<p>📌 Consejo práctico: Si te ofrecen menos sesiones o menos tratamientos de los que indicó tu médico, no lo dejes pasar: pedí la justificación por escrito el mismo día. Esa negativa documentada vale como prueba después.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-003</p>
<p>¿Cuánto dura el proceso de rehabilitación?</p>
<p>En resumen: Depende de tu lesión y tu evolución. No hay un plazo fijo, y la ART no puede cortarlo antes de tiempo.No existe un plazo único: la duración depende del tipo de lesión, tu edad, tu estado de salud general y tu respuesta al tratamiento. Cada caso lo evalúa tu médico tratante, y mientras él indique que necesitás seguir en rehabilitación, la ART está obligada a cubrirla conforme al artículo 11 de la LRT.</p>
<p>📌 No hay techo legal: puede ser de semanas o extenderse por meses e incluso años en lesiones graves.</p>
<p>📌 La ART no decide sola: no puede dar de alta ni cortar el tratamiento solo porque &quot;ya pasó tiempo&quot;.</p>
<p>📌 Plazo para impugnar el alta: si te dan de alta antes de tiempo, tenés 5 días hábiles para presentar la disconformidad ante la Comisión Médica, según la Resolución SRT N.º 5/2026.</p>
<p>📌 Documentar cada etapa: informes, estudios y evaluaciones periódicas sostienen tu reclamo si hay discusión.</p>
<p>📌 Consejo práctico: Si sentís que te están apurando para cerrar el tratamiento, pedí una segunda opinión médica antes de firmar nada. El alta no se negocia contra reloj: si no estás de acuerdo, tenés herramientas legales para frenarla.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-004</p>
<p>¿Qué es la kinesiología y cómo me ayuda en la rehabilitación?</p>
<p>En resumen: Usa ejercicios y técnicas manuales para recuperar movilidad y fuerza. La ART debe cubrirla sin límite de sesiones mientras tu médico la indique.La kinesiología es una de las herramientas centrales de la rehabilitación laboral: usa ejercicios terapéuticos, terapia manual, movilizaciones articulares y reeducación postural para recuperar fuerza muscular, mejorar el rango de movimiento y reducir el dolor. Está contemplada en el artículo 11 de la Ley 24.557 como prestación obligatoria, sin un tope de sesiones fijado por ley: el límite lo marca tu evolución clínica, no un número administrativo.</p>
<p>📌 Objetivo funcional: recuperar fuerza, movilidad y la capacidad de volver a tus tareas.</p>
<p>📌 Incluye ejercicios en casa: como complemento de las sesiones presenciales, nunca como reemplazo.</p>
<p>📌 Seguimiento periódico: el kinesiólogo debe reevaluar tu progreso y ajustar el plan.</p>
<p>📌 Cambio de profesional: si no estás conforme, tenés derecho a pedir otro kinesiólogo.</p>
<p>📌 Consejo práctico: Si después de varias semanas no notás avances, no esperes al final del tratamiento para decirlo. Consultá con tu médico tratante para que reevalúe el plan a tiempo.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-005</p>
<p>¿Qué pasa si la ART no me da las sesiones de kinesiología que necesito?</p>
<p>En resumen: Reclamá por escrito y, si no responden, denunciá ante la SRT o pedí la intervención de la Comisión Médica.Si la ART no te otorga las sesiones que tu médico indicó, está incumpliendo una obligación legal expresa del artículo 11 de la Ley 24.557. No es una molestia menor: es una violación de tus derechos como trabajador accidentado, y tenés un camino concreto para revertirlo.</p>
<p>1?? Pedí por escrito la cantidad de sesiones autorizadas y la justificación si es menor a lo indicado por tu médico.</p>
<p>2?? Si no responden en un plazo razonable o la respuesta es negativa, denunciá ante la SRT por su línea de atención o portal web.</p>
<p>3?? Solicitá la intervención de la Comisión Médica: el trámite tiene un plazo de resolución de 60 días hábiles administrativos (art. 3, Ley 27.348).</p>
<p>4?? Consultá con un abogado especialista en accidentes de trabajo si la situación no se resuelve.</p>
<p>📌 Consejo práctico: Mientras reclamás, seguí asistiendo a las sesiones que sí tenés autorizadas. Faltar a los turnos que te dieron puede usarse en tu contra, aunque el reclamo sea justo.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-006</p>
<p>¿Qué es la terapia ocupacional y para qué sirve?</p>
<p>En resumen: Te ayuda a recuperar habilidades para las tareas diarias y laborales, como la destreza manual. Es una prestación obligatoria.La terapia ocupacional te ayuda a recuperar habilidades para tu vida cotidiana y laboral: destreza manual, adaptación de herramientas, entrenamiento en actividades diarias y reeducación de movimientos específicos. Es especialmente relevante en lesiones de mano y muñeca, aunque también se aplica a columna, miembros inferiores y cualquier condición que limite tu capacidad funcional. Está incluida en el artículo 11 de la LRT como prestación obligatoria.</p>
<p>📌 Clave en lesiones de mano y muñeca: donde la pérdida de destreza afecta directamente tu trabajo.</p>
<p>📌 Se adapta a tu oficio: si trabajás con las manos (electricista, mecánico, gastronomía), el enfoque debe considerarlo.</p>
<p>📌 Plan personalizado: el terapeuta debe evaluar tu capacidad funcional específica.</p>
<p>📌 Obligación de la ART: no puede negarla si tu médico la indica.</p>
<p>📌 Consejo práctico: Si tu trabajo depende de la destreza manual, pedí explícitamente que la terapia ocupacional se incluya en tu plan desde el inicio, no como algo que se agrega después ante un reclamo.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-007</p>
<p>¿Puedo elegir a mi kinesiólogo?</p>
<p>En resumen: Sí, entre las opciones que te da la ART. Si no te convencen, podés pedir otras.Tenés derecho a elegir tu kinesiólogo dentro de las opciones que te ofrece la ART, que debe presentarte más de una alternativa entre las cuales elegir. Esto forma parte de tus derechos como paciente y del deber de calidad prestacional que la normativa de la SRT le impone a las aseguradoras.</p>
<p>📌 Pedí la lista completa de profesionales conveniados disponibles, por escrito.</p>
<p>📌 Elegí según ubicación, disponibilidad horaria o confianza.</p>
<p>📌 Si ninguno te convence, pedí otras opciones: la ART no puede limitarte a un único prestador.</p>
<p>📌 Si no te dan alternativas suficientes, podés denunciar ante la SRT.</p>
<p>📌 Consejo práctico: La relación con el profesional influye directamente en tu recuperación. Si ya estás en tratamiento y no estás conforme, podés pedir un cambio en cualquier momento, no solo al inicio.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-008</p>
<p>¿Qué ejercicios debo hacer en casa durante la rehabilitación?</p>
<p>En resumen: Solo los que te indique tu kinesiólogo. No improvises ni te automediques con ejercicios por tu cuenta.Los ejercicios domiciliarios son los que tu kinesiólogo te indicó expresamente, con series, repeticiones y frecuencia concretas. Hacer ejercicios por tu cuenta, sin esa indicación, puede empeorar la lesión y complicar tu recuperación además de darle a la ART un argumento para cuestionar tu evolución.</p>
<p>📌 Cumplí el plan tal cual te lo indicaron, sin sumar ni restar ejercicios.</p>
<p>📌 Si sentís dolor intenso, parás y consultás, no forzás.</p>
<p>📌 No reemplazan las sesiones presenciales: son un complemento, no un sustituto.</p>
<p>📌 Reportá cualquier molestia inusual en la próxima sesión.</p>
<p>📌 Consejo práctico: Si la ART te da de alta pero tu médico indica que necesitás seguir con ejercicios supervisados, la ART debe seguir cubriendo las sesiones presenciales necesarias: el alta administrativa no cierra automáticamente el tratamiento médico indicado.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-009</p>
<p>¿Qué es la fisioterapia y cómo se diferencia de la kinesiología?</p>
<p>En resumen: La fisioterapia usa agentes físicos como calor, frío o electricidad. La kinesiología se centra en el ejercicio terapéutico. Son complementarias.La fisioterapia trabaja con agentes físicos calor, frío, electricidad, ultrasonido, láser, corrientes terapéuticas para reducir el dolor, mejorar la circulación y acelerar la cicatrización. La kinesiología, en cambio, se apoya más en el movimiento y el ejercicio terapéutico. No compiten entre sí: muchas veces un plan de rehabilitación combina ambas.</p>
<p>📌 Útil para el dolor agudo y crónico y la inflamación.</p>
<p>📌 Mejora la circulación y acelera la cicatrización de tejidos.</p>
<p>📌 Se complementan: no es raro que tu plan incluya las dos.</p>
<p>📌 Ambas están cubiertas por el artículo 11 de la LRT sin límite mientras tu médico las indique.</p>
<p>📌 Consejo práctico: Si la ART te da una pero no la otra, y tu médico indicó ambas, reclamá puntualmente por la que falta: no des por hecho que una reemplaza a la otra.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-010</p>
<p>¿Puedo recibir rehabilitación mientras estoy con licencia médica?</p>
<p>En resumen: Sí, y es lo recomendable: cuanto antes empiece, mejor es la recuperación.Es fundamental recibir rehabilitación desde el inicio de tu licencia médica: cuanto antes arranque el tratamiento, mejor suele ser el pronóstico. El artículo 11 de la LRT obliga a la ART a brindar rehabilitación desde el momento del accidente o del diagnóstico de la enfermedad profesional, sin esperar a que termine la etapa de reposo.</p>
<p>📌 Mientras estás con Incapacidad Laboral Temporaria (ILT), cobrás tu ingreso base conforme al artículo 13 de la LRT: los primeros 10 días los paga el empleador y el resto, la ART.</p>
<p>📌 No hay que esperar el alta: la rehabilitación debe ser continua desde el diagnóstico.</p>
<p>📌 La ART no puede postergarla por trámites administrativos internos.</p>
<p>📌 Demoras injustificadas en turnos son denunciables ante la SRT.</p>
<p>📌 Consejo práctico: Guardá constancia de cada llamado, mail o gestión con la ART para pedir turnos. Si hay demoras, esa documentación te sirve para el reclamo.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-011</p>
<p>¿Qué es la hidroterapia y cuándo me sirve?</p>
<p>En resumen: Son ejercicios terapéuticos en agua climatizada. Útil en lesiones de columna, rodilla y cuando el peso corporal dificulta el ejercicio en seco.La hidroterapia consiste en ejercicios realizados en agua climatizada, generalmente entre 33 y 36 grados. Es especialmente útil en lesiones de columna, lesiones de rodilla, artritis, rehabilitación postquirúrgica y en casos donde el peso corporal dificulta el ejercicio convencional, porque el agua reduce el impacto articular y facilita el movimiento.</p>
<p>📌 Menor impacto articular: el agua reduce el peso que soportan tus articulaciones.</p>
<p>📌 Resistencia natural que fortalece sin sobrecargar.</p>
<p>📌 El calor terapéutico relaja la musculatura y reduce el dolor.</p>
<p>📌 Cubierta por el artículo 11 de la LRT si tu médico la indica.</p>
<p>📌 Consejo práctico: No la subestimes como tratamiento &quot;secundario&quot;: si tenés limitaciones que te impiden el ejercicio en seco, puede ser clave para tu recuperación. Pedí turnos regulares y no faltes a las sesiones.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-012</p>
<p>¿Cómo sé si estoy mejorando con la rehabilitación?</p>
<p>En resumen: Menos dolor, más movimiento y fuerza, y evaluaciones objetivas de tu kinesiólogo que documenten el avance.Los signos de mejora incluyen menos dolor al mover la zona afectada, mayor rango de movimiento, más fuerza muscular y mejor capacidad para tus actividades diarias. Tu kinesiólogo debe medir tu progreso periódicamente con herramientas objetivas goniometría, test funcionales, evaluación de fuerza y esos informes son clave si más adelante la ART discute tu porcentaje de incapacidad.</p>
<p>📌 Menos dolor al mover la zona lesionada.</p>
<p>📌 Mayor rango de movimiento: girás, flexionás o extendés más que antes.</p>
<p>📌 Más fuerza para sostener, levantar o empujar.</p>
<p>📌 Mejor capacidad funcional para caminar, subir escaleras o trabajar.</p>
<p>📌 Consejo práctico: Si después de varias semanas no ves cambios, no lo minimices: puede ser señal de que el plan necesita ajustarse. Consultá con tu médico antes de que la ART lo use como argumento para el alta.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-013</p>
<p>¿Qué pasa si me salteo sesiones de kinesiología?</p>
<p>En resumen: Perdés continuidad en el tratamiento y la ART puede usarlo como excusa para un alta anticipada.Saltear sesiones tiene un doble costo: perdés el progreso ya logrado, porque la rehabilitación requiere continuidad, y le das a la ART un argumento aunque sea injusto para sostener que ya no necesitás más tratamiento. Si no podés asistir por un motivo justificado, avisá con antelación y por escrito, y pedí que reprogramen la sesión.</p>
<p>📌 Perdés progreso: la continuidad es parte del tratamiento.</p>
<p>📌 Podés agravar la lesión: contracturas y rigidez pueden aumentar.</p>
<p>📌 Riesgo de alta anticipada: la ART puede argumentar falta de necesidad.</p>
<p>📌 Avisá siempre por escrito si hay una inasistencia justificada.</p>
<p>📌 Consejo práctico: Si el problema es que la ART te da turnos en horarios imposibles de cumplir, el problema es de ellos, no tuyo. Denunciá ante la SRT si te dificultan el acceso al tratamiento.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-014</p>
<p>¿La ART me paga los viáticos para ir al kinesiólogo?</p>
<p>En resumen: Sí, debe cubrir el traslado si el centro de tratamiento queda lejos de tu domicilio o de tu trabajo.La ART debe cubrir los gastos de traslado cuando el lugar de tratamiento está alejado de tu domicilio o de tu lugar de trabajo. Esto incluye transporte público, transporte privado cuando no hay alternativa adecuada, y peajes si necesitás usar autopista para llegar. Este derecho surge de las normas de la SRT sobre prestaciones en especie.</p>
<p>📌 Transporte público: colectivo, subte, tren.</p>
<p>📌 Transporte privado: taxi o remís si no hay opción de transporte público razonable.</p>
<p>📌 Peajes si el trayecto los requiere.</p>
<p>📌 Guardá todos los comprobantes para pedir el reintegro.</p>
<p>📌 Consejo práctico: Si te asignan un centro que queda a horas de distancia sin ofrecerte cobertura del traslado, reclamá: podés pedir que te acerquen a un centro más cercano o que cubran el gasto adicional.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-015</p>
<p>¿Qué es la rehabilitación neurológica y cuándo se usa?</p>
<p>En resumen: Es un tratamiento especializado para lesiones del sistema nervioso, como traumatismos de cráneo o de médula.La rehabilitación neurológica está dirigida a lesiones del sistema nervioso: traumatismos craneoencefálicos, accidentes cerebrovasculares, lesiones de médula espinal y daños neurológicos derivados de accidentes laborales. Combina varias disciplinas y suele requerir un abordaje prolongado y multidisciplinario, todo cubierto por el artículo 11 de la LRT.</p>
<p>📌 Terapia del lenguaje para recuperar el habla y la deglución.</p>
<p>📌 Terapia cognitiva para memoria, atención y funciones ejecutivas.</p>
<p>📌 Fisioterapia neurológica para marcha, equilibrio y coordinación.</p>
<p>📌 Terapia ocupacional para reintegrarte a las actividades diarias.</p>
<p>📌 Consejo práctico: Las lesiones neurológicas exigen seguimiento por un equipo especializado. Si la ART te ofrece un abordaje aislado o incompleto, pedí que se conforme un equipo interdisciplinario acorde a la gravedad del cuadro.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-016</p>
<p>¿Qué es la psicoterapia y por qué la necesito después del accidente?</p>
<p>En resumen: Es terapia psicológica. Muchos trabajadores accidentados atraviesan estrés, ansiedad o depresión, y es una prestación obligatoria.Un accidente laboral no solo lesiona el cuerpo: también puede generar estrés postraumático, depresión, ansiedad, insomnio o miedo a volver al trabajo. La asistencia psicológica y psiquiátrica es una prestación obligatoria según el artículo 11 de la Ley 24.557, porque la rehabilitación debe ser integral, no solo física.</p>
<p>📌 Es habitual sentir tristeza, irritabilidad o pesadillas después de un accidente: no es un signo de debilidad.</p>
<p>📌 La ART debe cubrir el tratamiento psicológico si tu médico lo indica.</p>
<p>📌 No puede negarla ni derivarte a tu obra social como excusa.</p>
<p>📌 Si te la niegan, podés reclamar ante la Comisión Médica.</p>
<p>📌 Consejo práctico: Si tenés miedo de volver al lugar del accidente, dificultad para concentrarte o cambios de ánimo sostenidos, pedí atención psicológica cuanto antes: es parte legítima de tu recuperación, no un trámite aparte.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-017</p>
<p>¿Qué es la reeducación postural y cómo me ayuda?</p>
<p>En resumen: Te enseña a moverte y sostener buena postura para prevenir nuevas lesiones y reducir el dolor.La reeducación postural te enseña a mantener una buena postura en tus actividades cotidianas y laborales, con el objetivo de prevenir nuevas lesiones y reducir el dolor existente. Es especialmente útil en lesiones de columna lumbalgia, cervicalgia, hernias discales y también en hombro, rodilla y cadera. Está comprendida en el artículo 11 de la LRT.</p>
<p>📌 Fortalecimiento del core, espalda y cuello.</p>
<p>📌 Estiramientos para mejorar flexibilidad y reducir tensión muscular.</p>
<p>📌 Consejos prácticos para sentarte, dormir y usar dispositivos correctamente.</p>
<p>📌 Técnicas seguras para levantar peso y hacer esfuerzos en el trabajo.</p>
<p>📌 Consejo práctico: Si tu lesión se originó por malas posturas en tu puesto de trabajo, la reeducación postural es clave para evitar que se repita. Pedí que se incluya expresamente en tu plan si tu médico lo considera necesario.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-018</p>
<p>¿Puedo trabajar mientras hago rehabilitación?</p>
<p>En resumen: Depende de lo que autorice tu médico: puede habilitar tareas livianas, jornada reducida o un puesto adaptado.Depende de tu estado médico. Tu médico tratante puede autorizar tareas livianas, jornada reducida o un puesto adaptado mientras seguís en rehabilitación. Mientras dure la Incapacidad Laboral Temporaria percibís el 100% de tu ingreso base según el artículo 13 de la LRT, y si el médico habilita tareas parciales, la prestación puede ajustarse en función del grado de actividad autorizado.</p>
<p>📌 Tareas livianas si tu lesión lo permite, sin comprometer la zona afectada.</p>
<p>📌 Jornada reducida como alternativa mientras te recuperás.</p>
<p>📌 Puesto adaptado: el empleador debe ajustarlo para que trabajes sin riesgo de agravar la lesión.</p>
<p>📌 Todo debe surgir de un certificado médico claro sobre qué podés y qué no podés hacer.</p>
<p>📌 Consejo práctico: Ni tu empleador puede obligarte a volver sin autorización médica, ni vos podés negarte si el médico habilita tareas con ciertas condiciones. Lo que te protege siempre es que quede documentado por escrito.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-019</p>
<p>¿Qué es la medicina del dolor y cuándo se usa?</p>
<p>En resumen: Es una especialidad para tratar dolores crónicos que no mejoran con tratamientos convencionales.La medicina del dolor trata dolores crónicos que no ceden con analgésicos comunes o kinesiología básica, y se vuelve fundamental cuando el dolor persistente se convierte en un obstáculo para tu rehabilitación. Es importante tener en cuenta que, desde el Baremo 2026 (Decreto 549/2025), el dolor dejó de tener un puntaje autónomo dentro de la tabla de incapacidades, por su carácter subjetivo. Eso hace todavía más importante que tu dolor esté respaldado por estudios objetivos resonancias, electromiogramas, informes de especialista que documenten la limitación funcional real que te genera.</p>
<p>📌 Se usa en dolor lumbar crónico, dolor postquirúrgico, dolor neuropático y cefaleas por lesiones cervicales, entre otros.</p>
<p>📌 Incluye bloqueos nerviosos, infiltraciones, neuromodulación y terapia conductual del dolor.</p>
<p>📌 Objetivar el dolor: pedí que cada limitación funcional quede documentada con estudios, no solo con tu relato.</p>
<p>📌 Está cubierta por la ART según el artículo 11 de la LRT.</p>
<p>📌 Consejo práctico: Si tu dolor crónico no está siendo tratado en serio, pedí la derivación a un especialista en dolor y no dejes de generar estudios que respalden objetivamente tu limitación: eso pesa más que el relato del dolor en sí.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-020</p>
<p>¿Qué son las órtesis y prótesis y cuándo las necesito?</p>
<p>En resumen: Son dispositivos que apoyan o reemplazan partes del cuerpo. La ART está obligada a proveértelas sin costo.Las órtesis son dispositivos que apoyan, inmovilizan o corrigen partes del cuerpo férulas, corsés lumbares, collarines, rodilleras, muñequeras. Las prótesis reemplazan partes del cuerpo perdidas o dañadas, como una mano, un brazo o una pierna. Ambas son prestaciones obligatorias según el artículo 11 de la Ley 24.557, y la ART debe proveértelas sin que tengas que pagar nada.</p>
<p>📌 Provisión inicial cuando tu lesión lo requiere.</p>
<p>📌 Reposición cuando el dispositivo se desgasta o deja de funcionar.</p>
<p>📌 Actualización si aparece tecnología que beneficie tu recuperación.</p>
<p>📌 Pedí que la marca y el modelo del dispositivo consten en tu expediente.</p>
<p>📌 Consejo práctico: No aceptes un dispositivo de mala calidad o que no se adapta bien a vos. Reclamá antes de recibirlo si notás que no cumple con lo que tu lesión necesita.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-021</p>
<p>¿Cómo puedo acelerar mi recuperación?</p>
<p>En resumen: Cumplí las indicaciones médicas al pie de la letra, sostené los ejercicios en casa y documentá tu evolución.Tu recuperación depende en gran parte de la constancia: cumplir las indicaciones de tu médico y kinesiólogo, sostener los ejercicios domiciliarios con la frecuencia indicada, descansar lo suficiente y evitar hábitos que retrasan la cicatrización, como fumar. Pero también depende de que documentes el proceso, porque esa documentación es la que te protege si la ART intenta apurar el alta.</p>
<p>📌 Cumplí al pie de la letra las indicaciones médicas y de kinesiología.</p>
<p>📌 Sostené los ejercicios en casa con la frecuencia correcta.</p>
<p>📌 Descansá lo suficiente: el cuerpo se repara mientras dormís.</p>
<p>📌 Evitá el tabaco: retrasa la cicatrización y afecta la circulación.</p>
<p>📌 Consejo práctico: Guardá informes, sacá fotos periódicas de tu evolución y anotá cómo te sentís. Esa documentación puede ser decisiva si la ART intenta darte el alta antes de que estés realmente recuperado.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-022</p>
<p>¿Qué pasa si la ART me da el alta y sigo con dolor?</p>
<p>En resumen: No la aceptes sin más. Tenés 5 días hábiles para impugnarla ante la Comisión Médica.Si te dieron el alta pero seguís con dolor, limitaciones o secuelas, no des la situación por cerrada. La normativa vigente te da una herramienta concreta: el trámite de disconformidad con el alta, con un plazo perentorio de 5 días hábiles desde la notificación, según la Resolución SRT N.º 5/2026.</p>
<p>1?? Impugná el alta dentro de los 5 días hábiles: es un plazo improrrogable, así que actuá rápido.</p>
<p>2?? Pedí una segunda opinión médica con un profesional de tu confianza.</p>
<p>3?? Reuní pruebas: informes, estudios por imágenes, certificados que respalden tu estado actual.</p>
<p>4?? Iniciá acción judicial si la Comisión Médica no resuelve a tu favor.</p>
<p>📌 Consejo práctico: Firmar el alta no implica renunciar a nada: podés firmarla y de todos modos impugnarla dentro del plazo. Además, el alta no cierra tu derecho a reclamar la indemnización por las secuelas que te queden.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-023</p>
<p>¿Qué es la terapia cognitivo-conductual y cuándo la necesito?</p>
<p>En resumen: Es una terapia psicológica basada en evidencia para cambiar patrones de pensamiento negativos. Muy usada en estrés postraumático y depresión.La terapia cognitivo-conductual (TCC) es un tipo de terapia psicológica que te ayuda a identificar y modificar patrones de pensamiento que afectan tu bienestar emocional. Es una de las herramientas más efectivas para tratar secuelas psicológicas de accidentes laborales, y la ART debe cubrirla si tu médico la indica, conforme al artículo 11 de la LRT.</p>
<p>📌 Útil para depresión asociada a la incapacidad y ansiedad por el futuro laboral.</p>
<p>📌 Ayuda con estrés postraumático: flashbacks, evitación, hipervigilancia.</p>
<p>📌 También se usa en trastornos del sueño derivados del accidente.</p>
<p>📌 Funciona en sesiones periódicas, generalmente semanales.</p>
<p>📌 Consejo práctico: No es un tratamiento de lujo ni opcional: si te la niegan, reclamá ante la Comisión Médica presentando los informes del profesional que la indicó.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-024</p>
<p>¿Cuántas sesiones de kinesiología me corresponden?</p>
<p>En resumen: No hay un número fijo por ley. Las define tu médico según tu lesión, y la ART no puede recortarlas sin justificación.La cantidad de sesiones depende del tipo y la gravedad de tu lesión, tu edad, tu estado de salud y tu respuesta al tratamiento. No hay un número fijado por ley ni por el baremo: es tu médico tratante quien lo determina, y la ART no puede limitarlas por motivos económicos ni sin una justificación médica fundada.</p>
<p>📌 El criterio es siempre clínico: lo que tu lesión necesite, no lo que resulte más barato para la ART.</p>
<p>📌 Si te limitan las sesiones, pedí la razón por escrito.</p>
<p>📌 Podés pedir la intervención de la Comisión Médica si la limitación no tiene sustento médico.</p>
<p>📌 Denunciá ante la SRT si la ART persiste en la negativa.</p>
<p>📌 Consejo práctico: Pedile a tu médico que las indicaciones de cantidad y frecuencia de sesiones queden por escrito en cada informe. Eso te da un respaldo concreto para exigir su cumplimiento.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-025</p>
<p>¿Qué es la electromiografía y para qué sirve?</p>
<p>En resumen: Es un estudio que mide la actividad eléctrica de músculos y nervios, clave para diagnosticar lesiones nerviosas.La electromiografía (EMG) es un estudio diagnóstico que mide la actividad eléctrica de músculos y nervios. Es fundamental para evaluar lesiones del sistema nervioso periférico, como el síndrome del túnel carpiano, neuropatías compresivas o lesiones radiculares. La ART debe cubrirlo si tu médico lo indica, según el artículo 11 de la LRT.</p>
<p>📌 No invasivo: se registra la actividad muscular en reposo y en contracción.</p>
<p>📌 Dura entre 20 y 60 minutos según la zona evaluada.</p>
<p>📌 Clave antes de cirugías que involucran nervios, para planificar mejor la intervención.</p>
<p>📌 Cada vez más relevante para objetivar secuelas frente al nuevo baremo.</p>
<p>📌 Consejo práctico: Con el Baremo 2026 (Decreto 549/2025), objetivar cada secuela con estudios complementarios es más importante que nunca: pedí este estudio si tu médico lo considera necesario para respaldar tu diagnóstico.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-026</p>
<p>¿Puedo hacer deporte durante la rehabilitación?</p>
<p>En resumen: Solo actividades de baja intensidad autorizadas por tu médico. Evitá deportes de contacto o alto impacto.Podés hacer actividad física durante la rehabilitación, pero siempre con autorización y supervisión médica. Tu médico puede habilitar caminata suave, natación ideal porque el agua reduce el impacto articular o estiramientos, según tu lesión. Lo que debés evitar por completo son los deportes de contacto, las actividades de alto impacto y cualquier ejercicio que te genere dolor agudo en la zona lesionada.</p>
<p>📌 Caminata suave en terreno llano, si está autorizada.</p>
<p>📌 Natación: reduce el impacto articular.</p>
<p>📌 Estiramientos suaves y yoga o pilates adaptados, con aval médico.</p>
<p>📌 Evitá deportes de contacto o alto impacto hasta el alta completa.</p>
<p>📌 Consejo práctico: El ejercicio terapéutico forma parte de tu rehabilitación; el deporte recreativo es algo que conviene postergar hasta que tu médico confirme el alta completa. Ante la duda, consultá antes de retomar cualquier actividad.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-027</p>
<p>¿Qué es el programa de reinserción laboral y cómo me ayuda?</p>
<p>En resumen: Es un plan para ayudarte a volver al trabajo después del accidente, con capacitación y adaptación del puesto si tu incapacidad lo requiere.El programa de reinserción laboral busca ayudarte a volver a trabajar en las mejores condiciones posibles cuando tu accidente te dejó una incapacidad que afecta tu capacidad de desempeño. Incluye la evaluación de tu capacidad laboral, capacitación en nuevas tareas si no podés volver a tu puesto anterior, adaptación del puesto de trabajo y seguimiento posterior a la reincorporación. Es tu médico y el equipo evaluador quienes determinan, caso por caso, si tu situación amerita este programa según el grado y el tipo de incapacidad.</p>
<p>📌 Evaluación de capacidad laboral: qué podés hacer y qué no, según tu secuela.</p>
<p>📌 Capacitación en nuevas tareas si tu incapacidad te impide volver a tu puesto anterior.</p>
<p>📌 Adaptación del puesto: modificaciones ergonómicas, herramientas especiales, horarios adaptados.</p>
<p>📌 Seguimiento posterior para asegurar que la reincorporación funcione.</p>
<p>📌 Consejo práctico: Si tu incapacidad afecta seriamente tu puesto habitual y la ART no te ofrece este programa, planteálo expresamente: no siempre lo proponen de oficio, y muchas veces hay que pedirlo.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-028</p>
<p>¿Qué pasa si la ART me manda a un kinesiólogo que no me gusta?</p>
<p>En resumen: Podés pedir un cambio. La ART debe ofrecerte alternativas, y si no las tiene, podés denunciar ante la SRT.Si no estás conforme con el kinesiólogo que te asignó la ART, tenés derecho a pedir un cambio. La relación terapéutica es parte de la efectividad del tratamiento: si no confiás en el profesional, es difícil que el proceso funcione bien.</p>
<p>1?? Pedí por escrito el cambio, explicando los motivos: falta de resultados, mal trato, poca escucha.</p>
<p>2?? La ART debe ofrecerte alternativas concretas entre las cuales elegir.</p>
<p>3?? Si no hay opciones adecuadas, denunciá ante la SRT por su formulario online o línea telefónica.</p>
<p>4?? Mientras tanto, seguí asistiendo a las sesiones para que no usen tu inasistencia en tu contra.</p>
<p>📌 Consejo práctico: Tu recuperación depende de la calidad del vínculo con el profesional. No te quedes con un trato que no te sirve solo por evitar el trámite del cambio: pedilo.</p>
<p>REHABILITACIÓN  ·  rehabilitacion-029</p>
<p>¿Cómo puedo verificar que la ART me está dando la rehabilitación correcta?</p>
<p>En resumen: Pedí informes médicos completos, verificá que coincidan con lo indicado por tu médico y consultá con un especialista si tenés dudas.Para verificar que tu rehabilitación es la que corresponde, pedí informes médicos completos después de cada sesión y evaluación la ART está obligada a dártelos, confirmá que los tratamientos coincidan con lo indicado por tu médico tratante y, ante cualquier duda, consultá con un médico de confianza o con un abogado especialista en accidentes de trabajo.</p>
<p>📌 Pedí informes médicos completos después de cada sesión y evaluación.</p>
<p>📌 Verificá que el tratamiento recibido coincida con lo indicado por tu médico.</p>
<p>📌 Consultá con un médico de confianza si tenés dudas sobre el plan.</p>
<p>📌  Hablá con un abogado especialista para que revise tu caso si algo no cierra.</p>
<p>📌 Consejo práctico: Señales de alerta: menos sesiones de las indicadas, profesionales que no son especialistas, falta de evaluaciones periódicas, presión para aceptar el alta o negativa a darte informes por escrito. Si detectás alguna, reclamá de inmediato ante la ART, la Comisión Médica o la SRT.</p>
<p>D: lesiones-hombro-001</p>
<p>PREGUNTA: ¿Qué lesiones de hombro cubre la ART?</p>
<p>RESPUESTA_CORTA: Cubre rotura de manguito rotador, tendinitis, luxaciones, bursitis, fracturas y otras lesiones de hombro que se originen en el trabajo.</p>
<p>La ART cubre todas las lesiones de hombro que se originen en el trabajo, incluyendo:</p>
<p>📌 Rotura del manguito rotador, parcial o completa.</p>
<p>📌 Tendinitis por esfuerzo repetitivo y bursitis subacromial.</p>
<p>📌 Luxaciones por caídas o golpes, y fracturas de húmero proximal.</p>
<p>📌 Frozen shoulder (capsulitis adhesiva) y síndrome de pinzamiento subacromial.</p>
<p>Desde el 1° de febrero de 2026 rige el Baremo Laboral del Decreto 549/2025, que reemplazó a la tabla que se usaba desde 1996. La diferencia clave: ya no maneja rangos de incapacidad. Cada secuela tiene un porcentaje fijo en la tabla, y recién después se le suma un factor de ponderación según tu edad y el tipo de tarea que hacías (leve 5%, intermedia 10% o alta 20% + entre 2% y 5% por edad). Para la cintura escapular (hombro), el propio decreto fija el tope máximo en 66%  el mismo valor que corresponde a la amputación interescapulotorácica. Es el techo, no lo que cobra cualquier lesión de hombro.</p>
<p>📌 Consejo práctico: guardá toda la documentación médica desde el primer día (resonancia, ecografía, informes del traumatólogo). No dejes pasar el plazo de 2 años para reclamar: corre desde el accidente o desde que el daño se manifestó (Art. 44, Ley 24.557).</p>
<p>PREGUNTA: ¿Cuánto me indemnizan por una rotura de manguito rotador?</p>
<p>RESPUESTA_CORTA: El porcentaje depende de tu secuela puntual según la tabla del Baremo 2026, tu edad y tu salario. Ya no se manejan rangos como &quot;entre 15% y 35%&quot;.</p>
<p>Con el Decreto 549/2025 se terminaron los rangos de incapacidad de la tabla vieja. El nuevo baremo asigna un porcentaje fijo, sin intervalos, para cada secuela puntual, justamente para reducir la discrecionalidad del médico evaluador.</p>
<p>📌 El valor exacto depende de si la rotura fue parcial o completa, si hubo cirugía y qué secuela objetiva quedó (por ejemplo, la limitación de movilidad medida por goniometría).</p>
<p>📌 A ese valor de tabla se le suma el factor de ponderación por edad y tipo de tarea.</p>
<p>📌 Si superás el 50% de incapacidad, corresponde además un adicional por gran invalidez sobre los pisos que fija periódicamente la SRT.</p>
<p>La indemnización de pago único surge de la fórmula del Art. 14, Ley 24.557: 53 x Ingreso Base Mensual x % de incapacidad x (65/tu edad).</p>
<p>Como el número final depende de tu diagnóstico puntual contrastado con la tabla completa, conviene que un perito de parte lo revise antes de firmar nada con la ART.  Si no estás de acuerdo con el porcentaje que te asignaron, podés impugnarlo ante la Comisión Médica Central dentro de los 5 días hábiles de notificado el dictamen (Res. SRT 5/2026).</p>
<p>PREGUNTA: ¿Qué ejercicios debo hacer para recuperar el hombro?</p>
<p>RESPUESTA_CORTA: Los que te indique tu kinesiólogo. Generalmente arrancan con movilidad y progresan a fortalecimiento.</p>
<p>Los ejercicios de rehabilitación del hombro apuntan a recuperar movilidad y fuerza, y siempre los tiene que indicar tu kinesiólogo o traumatólogo según tu lesión puntual:</p>
<p>📌 Movilidad articular: ejercicios pasivos y activos, empezando asistidos y avanzando de a poco.</p>
<p>📌 Estiramientos: sobre todo del pectoral y el dorsal, para ganar flexibilidad.</p>
<p>📌 Fortalecimiento con bandas elásticas: trabajo progresivo del manguito rotador y los estabilizadores.</p>
<p>📌 Reeducación postural: corrige compensaciones que podrían generarte una lesión nueva.</p>
<p>📌 Consejo práctico: nunca hagas estos ejercicios por tu cuenta sin supervisión profesional. Si el dolor aumenta, parás y consultás a tu médico. Las sesiones suelen ser 3 veces por semana durante 2 o 3 meses, y la ART está obligada a cubrirlas.</p>
<p>PREGUNTA: ¿Puedo volver a trabajar con una lesión de hombro?</p>
<p>RESPUESTA_CORTA: Depende de tu tipo de trabajo. Si es físico, tu médico puede indicarte tareas livianas mientras te recuperás.</p>
<p>Podés volver a trabajar después de una lesión de hombro, pero depende de varios factores que tiene que evaluar tu médico:</p>
<p>📌 Trabajo sedentario: en general podés volver antes.</p>
<p>📌 Trabajo físico (cargar peso, movimientos repetitivos del brazo): vas a necesitar más tiempo o tareas adaptadas.</p>
<p>📌 Tareas livianas: administrativas, jornada reducida o prohibición de levantar peso, según indique el médico tratante.</p>
<p>📌 Adaptación del puesto: herramientas ergonómicas, descansos frecuentes, rotación de tareas.</p>
<p>El procedimiento: primero tu médico tratante te da el alta con restricciones; después la Comisión Médica determina el porcentaje de incapacidad permanente si te quedó una secuela. Si tu empleador no te readapta el puesto, podés reclamar ante la SRT.  No vuelvas antes de tiempo: una recaída puede complicar tu salud y tu indemnización.</p>
<p>PREGUNTA: ¿Cuánto tarda en recuperarse una lesión de hombro?</p>
<p>RESPUESTA_CORTA: Desde 3 meses hasta más de un año, según la lesión y si necesitás cirugía.</p>
<p>Los tiempos varían mucho según el tipo y la gravedad de la lesión:</p>
<p>📌 Tendinitis simple: 2-3 meses con kinesiología y medicación.</p>
<p>📌 Rotura parcial del manguito rotador: 3-6 meses, según si el tratamiento es conservador o con cirugía artroscópica.</p>
<p>📌 Rotura completa con cirugía: 6-12 meses, incluyendo la rehabilitación post-operatoria.</p>
<p>📌 Frozen shoulder: puede tardar 12-18 meses, aunque la kinesiología acelera el proceso.</p>
<p>📌 Consejo práctico: la recuperación es gradual y requiere constancia. No te apures a volver antes de tiempo. La ART tiene que cubrir todos los gastos de rehabilitación hasta que estés médicamente estabilizado, momento en el que la Comisión Médica evalúa si te quedó una incapacidad permanente.</p>
<p>PREGUNTA: ¿Qué lesiones de rodilla cubre la ART?</p>
<p>RESPUESTA_CORTA: Rotura de ligamentos, meniscopatía, condromalacia, fracturas y tendinitis de rodilla, entre otras.</p>
<p>La ART cubre todas las lesiones de rodilla que se originen en el trabajo, incluyendo:</p>
<p>📌 Rotura de ligamentos cruzados (anterior o posterior) y de los ligamentos laterales.</p>
<p>📌 Rotura de menisco por torsión o giros bruscos.</p>
<p>📌 Condromalacia rotuliana, fracturas de rótula y tendinitis rotuliana.</p>
<p>📌 Luxación de rótula y lesiones del cartílago articular.</p>
<p>Desde el 1° de febrero de 2026 rige el Baremo Laboral del Decreto 549/2025, que reemplazó a la tabla que se usaba desde 1996. La diferencia clave: ya no maneja rangos de incapacidad. Cada secuela tiene un porcentaje fijo en la tabla, y recién después se le suma un factor de ponderación según tu edad y el tipo de tarea que hacías (leve 5%, intermedia 10% o alta 20% + entre 2% y 5% por edad). La rodilla no tiene un tope propio: forma parte del tope acumulado de miembro inferior. Si el compromiso llega hasta la rodilla (pie, tobillo, pierna y/o rodilla), el baremo lo limita al 55%.</p>
<p>📌 Consejo práctico: los estudios por imágenes (resonancia) y el informe quirúrgico son la prueba clave. No dejes pasar el plazo de 2 años para reclamar: corre desde el accidente o desde que el daño se manifestó (Art. 44, Ley 24.557).</p>
<p>PREGUNTA: ¿Cuánto me indemnizan por una rotura de ligamentos de rodilla?</p>
<p>RESPUESTA_CORTA: El anexo oficial fija valores puntuales y bajos por ligamento: no son los rangos amplios que circulaban con la tabla vieja.</p>
<p>El anexo del Decreto 549/2025 asigna un porcentaje fijo por cada ligamento comprometido, dentro de la Tabla de Lesiones Capsulo-Ligamentarias y Meniscales:</p>
<p>📌 Rotura completa del ligamento cruzado anterior: 7%.</p>
<p>📌 Rotura completa del ligamento cruzado posterior: 4%.</p>
<p>📌 Rotura del ligamento lateral interno o externo: 3% cada uno.</p>
<p>📌 Lesión meniscal operada (meniscectomía o sutura): 4%. No operada, con hipotrofia o bloqueo: 8%.</p>
<p>Estas secuelas, si están en la misma pierna, se suman aritméticamente entre sí (por ejemplo, ligamento cruzado anterior + menisco). La indemnización de pago único surge de la fórmula del Art. 14, Ley 24.557: 53 x Ingreso Base Mensual x % de incapacidad x (65/tu edad). Si no estás de acuerdo con el porcentaje que te asignaron, podés impugnarlo ante la Comisión Médica Central dentro de los 5 días hábiles de notificado el dictamen (Res. SRT 5/2026).</p>
<p>📌 Recordá que a este valor de tabla hay que sumarle el factor de ponderación por edad y actividad  puede representar varios puntos más en tu porcentaje final.</p>
<p>PREGUNTA: ¿Qué es la condromalacia y cómo la tratan?</p>
<p>RESPUESTA_CORTA: Es el desgaste del cartílago de la rodilla, bajo la rótula. Se trata con kinesiología, infiltraciones y, en casos graves, cirugía.</p>
<p>La condromalacia es el desgaste del cartílago articular bajo la rótula. Es muy común en trabajadores que pasan mucho tiempo de pie o hacen movimientos repetitivos de flexión.</p>
<p>📌 Kinesiología: fortalecimiento del cuádriceps y estiramientos. Es la base del tratamiento.</p>
<p>📌 Infiltraciones de ácido hialurónico o plasma rico en plaquetas.</p>
<p>📌 Medicamentos: antiinflamatorios y analgésicos.</p>
<p>📌 Cirugía (artroscopía): en casos graves, cuando el tratamiento conservador no funciona.</p>
<p>📌 Consejo práctico: si te dan el alta médica y te quedaron secuelas objetivables, tenés derecho a que la Comisión Médica evalúe tu porcentaje de incapacidad permanente según la tabla vigente.</p>
<p>PREGUNTA: ¿Puedo caminar después de una cirugía de rodilla?</p>
<p>RESPUESTA_CORTA: Sí, pero con muletas al principio. La rehabilitación te va a ayudar a caminar sin apoyo, de forma progresiva.</p>
<p>La recuperación después de una cirugía de rodilla es un proceso gradual:</p>
<p>📌 Primeras 2-3 semanas: caminás con muletas sin apoyar la pierna operada, con ejercicios de movilidad para evitar rigidez.</p>
<p>📌 1-2 meses: empezás a apoyar progresivamente, según indicación médica.</p>
<p>📌  2-3 meses: caminás sin muletas, con precaución.</p>
<p>📌 3-6 meses: recuperación funcional completa con kinesiología constante.</p>
<p>📌 Consejo práctico: la kinesiología es fundamental y la ART está obligada a cubrirla. No vuelvas a trabajar antes de tiempo: podrías empeorar la lesión y afectar tu porcentaje final de incapacidad.</p>
<p>PREGUNTA: ¿Qué debo evitar después de una lesión de rodilla?</p>
<p>RESPUESTA_CORTA: Deportes de contacto, correr en superficies duras, agacharte con exceso y arrodillarte por mucho tiempo.</p>
<p>Después de una lesión de rodilla, hay actividades que conviene evitar para no recaer:</p>
<p>📌 Deportes de contacto: alto riesgo de re-lesión.</p>
<p>📌 Correr en superficies duras: impacto excesivo sobre la articulación.</p>
<p>📌 Agacharte con exceso o arrodillarte prolongadamente: presión sobre cartílago, meniscos y bursa.</p>
<p>📌 Levantar pesos excesivos: sobrecarga la articulación.</p>
<p>📌 Consejo práctico: usá calzado con buena amortiguación, mantené un peso adecuado y seguí las indicaciones de tu kinesiólogo al pie de la letra. Si la lesión fue laboral, la ART tiene que cubrir tu rehabilitación completa hasta la estabilización médica.</p>
<p>PREGUNTA: ¿Qué lesiones de columna cubre la ART?</p>
<p>RESPUESTA_CORTA: Hernias discales, fracturas vertebrales, esguinces, estenosis y lesiones degenerativas agravadas por el trabajo.</p>
<p>La ART cubre las lesiones de columna que se originen en el trabajo, incluyendo:</p>
<p>📌 Hernias discales (cervicales, dorsales o lumbares), muy comunes por carga de peso.</p>
<p>📌 Fracturas vertebrales por accidentes o compresión.</p>
<p>📌 Esguinces y distensiones musculares.</p>
<p>📌 Estenosis espinal y lesiones degenerativas agravadas por el trabajo.</p>
<p>Desde el 1° de febrero de 2026 rige el Baremo Laboral del Decreto 549/2025, que reemplazó a la tabla que se usaba desde 1996. La diferencia clave: ya no maneja rangos de incapacidad. Cada secuela tiene un porcentaje fijo en la tabla, y recién después se le suma un factor de ponderación según tu edad y el tipo de tarea que hacías (leve 5%, intermedia 10% o alta 20% + entre 2% y 5% por edad). En columna, las secuelas de un mismo sector se suman aritméticamente entre sí, pero sin superar el tope de ese sector: 40% para el sector cervical y 60% para el sector dorsolumbar. Por ejemplo, la hernia de disco operada tiene un valor fijo de 5% en la tabla; una fractura vertebral cervical sin secuelas vale 4%, con secuelas 8% y con pseudoartrosis 12%, mientras que una fractura lumbar sin secuelas vale 8%, con secuelas 16% y con pseudoartrosis 24%.</p>
<p>📌 Un punto importante del nuevo baremo: exige que la secuela esté objetivada con estudios complementarios (resonancia, electromiograma, goniometría). El dolor, por su carácter subjetivo, ya no suma puntos por sí solo  por eso conviene no faltar a ningún control médico ni perder un estudio. No dejes pasar el plazo de 2 años para reclamar: corre desde el accidente o desde que el daño se manifestó (Art. 44, Ley 24.557).</p>
<p>PREGUNTA: ¿Cuánto me indemnizan por una hernia discal lumbar?</p>
<p>RESPUESTA_CORTA: El anexo oficial asigna un valor fijo de 5% a la hernia de disco operada. Puede sumarse la limitación funcional si está objetivada por goniometría.</p>
<p>Este es uno de los cambios más fuertes del Decreto 549/2025 frente a la tabla vieja: la hernia discal operada dejó de tener un rango amplio y pasó a valer 5% fijo en la Tabla de Lesiones Discales y Ligamentarias.</p>
<p>📌 Hernia de disco operada: 5% (valor único del anexo, sin distinguir por nivel).</p>
<p>📌 Si además hay una limitación funcional objetivada por goniometría, esa limitación se pondera aparte y se suma dentro del mismo sector.</p>
<p>📌 Todas las secuelas del sector dorsolumbar se suman aritméticamente, pero sin superar el tope del 60%.</p>
<p>La indemnización de pago único surge de la fórmula del Art. 14, Ley 24.557: 53 x Ingreso Base Mensual x % de incapacidad x (65/tu edad). Si tenés más del 50% de incapacidad corresponde el adicional por gran invalidez.</p>
<p>Es un valor bajo frente a lo que muchos trabajadores esperan, así que conviene que un abogado laboralista revise si en tu caso corresponden factores adicionales.  Si no estás de acuerdo con el porcentaje que te asignaron, podés impugnarlo ante la Comisión Médica Central dentro de los 5 días hábiles de notificado el dictamen (Res. SRT 5/2026).</p>
<p>PREGUNTA: ¿Qué ejercicios son buenos para la columna lesionada?</p>
<p>RESPUESTA_CORTA: Fortalecimiento del core, estiramientos y natación, siempre bajo supervisión médica.</p>
<p>Los ejercicios para la columna lesionada son claves para la recuperación y siempre los tiene que indicar tu kinesiólogo o traumatólogo:</p>
<p>📌 Fortalecimiento del core: planchas suaves y estabilidad abdominal, para proteger la columna lumbar.</p>
<p>📌 Estiramientos lumbares: psoas, piriforme y erectores de la columna.</p>
<p>📌 Caminata: ejercicio de bajo impacto que mejora la circulación y la movilidad.</p>
<p>📌 Natación: ideal porque no genera impacto sobre la columna.</p>
<p>📌 Regla de oro: nunca hagas ejercicios que te causen dolor. La ART tiene que cubrir las sesiones de kinesiología, y una rehabilitación adecuada también influye en cómo queda documentada tu secuela para la Comisión Médica.</p>
<p>PREGUNTA: ¿La ART me cubre una cirugía de columna?</p>
<p>RESPUESTA_CORTA: Sí, si es necesaria por tu lesión laboral. Tiene que cubrir la cirugía, la internación y la rehabilitación posterior.</p>
<p>Si necesitás una cirugía de columna como consecuencia de un accidente de trabajo o una enfermedad profesional, la ART está obligada a cubrirla. Esto incluye:</p>
<p>📌 Hernias discales: discectomía, microdiscectomía o fusión vertebral.</p>
<p>📌 Descompresiones: laminectomía para estenosis espinal.</p>
<p>📌 Fracturas: vertebroplastia, cifoplastia o cirugía abierta.</p>
<p>📌 Gastos cubiertos: internación, honorarios médicos, prótesis, medicamentos y rehabilitación post-operatoria.</p>
<p>Si la ART se niega: presentá el pedido por escrito con la indicación médica; si lo rechazan, reclamá ante la SRT; si tampoco resuelve, queda la vía judicial.  Consejo práctico: no dejes que la ART te niegue un tratamiento indicado por tu médico tratante.</p>
<p>PREGUNTA: ¿Cuánto tarda en recuperarse una lesión de columna?</p>
<p>RESPUESTA_CORTA: Desde 4-8 semanas para un esguince lumbar hasta 6-12 meses si hubo cirugía.</p>
<p>Los tiempos de recuperación varían según la gravedad:</p>
<p>📌 Esguince lumbar: 4-8 semanas con kinesiología y descanso.</p>
<p>📌 Hernia discal sin cirugía: 3-6 meses de tratamiento conservador.</p>
<p>📌 Hernia discal con cirugía: 6-12 meses, incluyendo rehabilitación post-operatoria.</p>
<p>📌 Fractura vertebral: 3-6 meses según el tipo y el tratamiento.</p>
<p>📌 Consejo práctico: la rehabilitación es clave. La ART tiene que cubrir todas las sesiones de kinesiología necesarias. No vuelvas a trabajar antes de tiempo, sobre todo si tu trabajo implica cargar pesos: si te dan el alta y quedaste con secuelas, tenés derecho a la indemnización por incapacidad permanente.</p>
<p>PREGUNTA: ¿Qué lesiones cervicales cubre la ART?</p>
<p>RESPUESTA_CORTA: Cervicalgia, whiplash (latigazo cervical), hernias discales cervicales, tortícolis y fracturas.</p>
<p>La ART cubre las lesiones cervicales que se originen en el trabajo, incluyendo:</p>
<p>📌 Cervicalgia: dolor crónico o agudo en la zona del cuello.</p>
<p>📌 Whiplash (latigazo cervical): muy común en accidentes de tránsito laborales.</p>
<p>📌 Hernias discales cervicales por esfuerzo o traumatismos.</p>
<p>📌 Fracturas vertebrales cervicales por accidentes graves.</p>
<p>El sector cervical de la columna tiene, según el Decreto 549/2025, un tope máximo de 40%: la suma de todas las secuelas cervicales no puede superar ese valor. Una fractura cervical (C3-C7) sin secuelas vale 4% fijo, con secuelas 8%, y con pseudoartrosis 12%.</p>
<p>📌 Si trabajás manejando, cargando peso o con movimientos repetitivos del cuello, estas lesiones son especialmente relevantes. No dejes pasar el plazo de 2 años para reclamar: corre desde el accidente o desde que el daño se manifestó (Art. 44, Ley 24.557).</p>
<p>PREGUNTA: ¿Cuánto me indemnizan por una lesión cervical?</p>
<p>RESPUESTA_CORTA: El baremo asigna un porcentaje fijo por secuela, con un tope del 40% para todo el sector cervical.</p>
<p>El anexo del Decreto 549/2025 ya no trabaja con rangos: cada secuela cervical objetivada tiene un valor puntual en la tabla, dentro del tope del 40% para el sector.</p>
<p>📌 Fractura cervical (C3-C7): 4% sin secuelas, 8% con secuelas, 12% con pseudoartrosis.</p>
<p>📌 Hernia de disco operada: 5% (valor único del anexo, independiente del nivel).</p>
<p>📌 Si tenés más de una secuela en el mismo sector cervical, se suman aritméticamente entre sí, sin superar el 40%.</p>
<p>La indemnización de pago único surge de la fórmula del Art. 14, Ley 24.557: 53 x Ingreso Base Mensual x % de incapacidad x (65/tu edad).</p>
<p>Si tenés dolor crónico, mareos, vértigo o limitación funcional objetivada por goniometría, asegurate de que la Comisión Médica lo tenga en cuenta al calcular tu porcentaje.  Si no estás de acuerdo con el porcentaje que te asignaron, podés impugnarlo ante la Comisión Médica Central dentro de los 5 días hábiles de notificado el dictamen (Res. SRT 5/2026).</p>
<p>PREGUNTA: ¿Qué es el whiplash y cómo se trata?</p>
<p>RESPUESTA_CORTA: Es una lesión por latigazo del cuello, causada por un movimiento brusco. Se trata con kinesiología, medicamentos y calor local.</p>
<p>El whiplash o latigazo cervical es causado por un movimiento brusco del cuello, generalmente por un golpe por detrás (como un accidente de tránsito laboral).</p>
<p>📌 Síntomas: dolor intenso en cuello y nuca, rigidez, cefalea, mareos y, si hay afectación radicular, hormigueo en los brazos.</p>
<p>📌 Kinesiología: la base del tratamiento, con estiramientos y fortalecimiento.</p>
<p>📌 Medicamentos: antiinflamatorios, relajantes musculares y analgésicos.</p>
<p>📌 Collarín cervical: solo de forma temporal, nunca prolongada.</p>
<p>📌 Consejo práctico: la ART tiene que cubrir todo el tratamiento. Si te quedan secuelas objetivables (limitación de movimiento, afectación neurológica), corresponde que la Comisión Médica evalúe tu incapacidad según la tabla vigente.</p>
<p>PREGUNTA: ¿Puedo trabajar con una lesión cervical?</p>
<p>RESPUESTA_CORTA: Depende de tu trabajo. Si no exige esfuerzo del cuello, podés volver con precaución; si manejás o cargás peso, vas a necesitar más tiempo.</p>
<p>Podés trabajar con una lesión cervical, pero depende del tipo de actividad:</p>
<p>📌 Trabajo sedentario: podés volver más rápido, con descansos frecuentes y un reposacabezas ergonómico.</p>
<p>📌 Manejo de vehículos: necesitás más tiempo, porque girar el cuello para los espejos puede empeorar la lesión.</p>
<p>📌 Carga de pesos o movimientos del cuello: vas a necesitar tareas adaptadas o jornada reducida.</p>
<p>El procedimiento: tu médico tratante indica las restricciones, la ART tiene que verificar que se cumplan, y si tu empleador no te readapta, podés reclamar ante la SRT.  No vuelvas antes de tiempo: una recidiva puede ser peor y afectar tu indemnización final.</p>
<p>PREGUNTA: ¿Qué puedo hacer para prevenir lesiones cervicales en el trabajo?</p>
<p>RESPUESTA_CORTA: Mantené buena postura, hacé estiramientos cada hora, ajustá tu escritorio y tomá descansos frecuentes.</p>
<p>Prevenir lesiones cervicales en el trabajo es clave, sobre todo si pasás muchas horas frente a una pantalla:</p>
<p>📌 Buena postura: la cabeza alineada con la columna, sin adelantar el cuello.</p>
<p>📌 Ajustá tu escritorio: la pantalla a la altura de los ojos y a un brazo de distancia.</p>
<p>📌 Estiramientos cada hora: movimientos suaves del cuello hacia los lados, arriba y abajo.</p>
<p>📌 No sostengas el teléfono con el hombro: usá auricular o altavoz.</p>
<p>📌 Consejo práctico: si trabajás en computadora, invertí en un monitor a la altura correcta. Si ya tenés una lesión cervical, avisale a tu empleador para que haga las adaptaciones necesarias en tu puesto.</p>
<p>PREGUNTA: ¿Qué lesiones lumbares cubre la ART?</p>
<p>RESPUESTA_CORTA: Lumbalgia, hernias discales lumbares, ciática, fracturas vertebrales y contracturas musculares.</p>
<p>La ART cubre las lesiones lumbares que se originen en el trabajo, incluyendo:</p>
<p>📌 Lumbago agudo y crónico: dolor intenso en la zona lumbar.</p>
<p>📌 Hernias discales lumbares, muy comunes en trabajadores que cargan pesos.</p>
<p>📌 Ciática: dolor que se irradia por el nervio ciático hasta la pierna.</p>
<p>📌 Fracturas vertebrales lumbares por trauma o compresión.</p>
<p>La zona lumbar forma parte del sector dorsolumbar de la columna, cuyo tope según el Decreto 549/2025 es del 60%. Una fractura de vértebra lumbar (por ejemplo L1) vale 8% fijo sin secuelas, 16% con secuelas y 24% con pseudoartrosis; la hernia de disco operada vale 5% fijo.</p>
<p>📌 Si cargás pesos, mantenés posturas forzadas o hacés movimientos de torsión en tu trabajo, estas lesiones son especialmente frecuentes. No dejes pasar el plazo de 2 años para reclamar: corre desde el accidente o desde que el daño se manifestó (Art. 44, Ley 24.557).</p>
<p>PREGUNTA: ¿Cuánto me indemnizan por una lesión lumbar?</p>
<p>RESPUESTA_CORTA: El baremo asigna un porcentaje fijo por secuela, con un tope del 60% para todo el sector dorsolumbar.</p>
<p>El Decreto 549/2025 fija valores puntuales para cada secuela lumbar, dentro del tope del 60% del sector dorsolumbar:</p>
<p>📌 Fractura vertebral lumbar (L1): 8% sin secuelas, 16% con secuelas, 24% con pseudoartrosis.</p>
<p>📌 Hernia de disco operada: 5% fijo, sin distinción por nivel.</p>
<p>📌 Las secuelas del mismo sector se suman aritméticamente, hasta el tope del 60%.</p>
<p>La indemnización de pago único surge de la fórmula del Art. 14, Ley 24.557: 53 x Ingreso Base Mensual x % de incapacidad x (65/tu edad).</p>
<p>Si tenés dolor crónico, limitación funcional severa o afectación neurológica objetivada, asegurate de que quede bien documentada.  Si no estás de acuerdo con el porcentaje que te asignaron, podés impugnarlo ante la Comisión Médica Central dentro de los 5 días hábiles de notificado el dictamen (Res. SRT 5/2026).</p>
<p>PREGUNTA: ¿Qué ejercicios debo hacer para la columna lumbar?</p>
<p>RESPUESTA_CORTA: Fortalecimiento abdominal, estiramientos lumbares y caminatas suaves, siempre bajo supervisión.</p>
<p>Los ejercicios para la columna lumbar son esenciales para la recuperación y siempre los indica tu kinesiólogo:</p>
<p>📌 Fortalecimiento abdominal: planchas suaves, para estabilizar la zona lumbar.</p>
<p>📌 Estiramientos lumbares: piriforme, psoas y erectores de la columna.</p>
<p>📌 Caminata: 30 minutos diarios mejoran la circulación y reducen el dolor.</p>
<p>📌 Natación: el mejor ejercicio porque no genera impacto sobre la columna.</p>
<p>📌 Consejo práctico: nunca hagas ejercicios que te causen dolor. La ART tiene que cubrir las sesiones de kinesiología, y la rehabilitación adecuada es clave tanto para tu recuperación como para la documentación de tu caso.</p>
<p>PREGUNTA: ¿Puedo levantar pesos después de una lesión lumbar?</p>
<p>RESPUESTA_CORTA: Depende de tu recuperación. Tu médico tiene que autorizarte y hay que tomar precauciones, sobre todo al principio.</p>
<p>Después de una lesión lumbar, levantar pesos requiere extrema precaución:</p>
<p>📌 Al principio: no levantes nada, tu espalda necesita descanso.</p>
<p>📌 Fase intermedia: pesos ligeros, solo si tu médico lo autoriza.</p>
<p>📌 Fase de retorno: peso progresivo, siempre con técnica correcta (agacharte con las rodillas, espalda recta, peso cerca del cuerpo).</p>
<p>📌 Consejo práctico: si tu trabajo implica carga habitual de peso y tenés una lesión lumbar, pedí tareas adaptadas a tu empleador o a la ART. No arriesgues tu recuperación ni tu indemnización volviendo antes de tiempo.</p>
<p>PREGUNTA: ¿Qué es la ciática y cómo se trata?</p>
<p>RESPUESTA_CORTA: Es un dolor que baja por la pierna, por compresión del nervio ciático. Se trata con medicación y kinesiología.</p>
<p>La ciática es un dolor que se irradia desde la columna lumbar a lo largo del nervio ciático, hasta el glúteo, el muslo y a veces el pie.</p>
<p>📌 Causas más comunes: hernia discal que comprime el nervio, estenosis espinal o síndrome del piriforme.</p>
<p>📌 Medicamentos: antiinflamatorios, analgésicos y relajantes musculares.</p>
<p>📌 Kinesiología: estiramientos y fortalecimiento del core.</p>
<p>📌 Infiltraciones epidurales: para reducir la inflamación del nervio, y cirugía en casos graves.</p>
<p>📌 Consejo práctico: si la ciática es secuela de una lesión laboral, la ART tiene que cubrir todo el tratamiento, y si te queda una afectación neurológica objetivada, corresponde que se valore como incapacidad permanente.</p>
<p>PREGUNTA: ¿Qué lesiones de mano cubre la ART?</p>
<p>RESPUESTA_CORTA: Fracturas, tendinitis, síndrome del túnel carpiano, luxaciones y amputaciones parciales de dedos.</p>
<p>La ART cubre todas las lesiones de mano que se originen en el trabajo, incluyendo:</p>
<p>📌 Fracturas de falanges, metacarpianos y huesos del carpo.</p>
<p>📌 Tendinitis por movimientos repetitivos, muy común en trabajadores manuales.</p>
<p>📌 Síndrome del túnel carpiano: compresión del nervio mediano en la muñeca.</p>
<p>📌 Amputaciones parciales o totales de dedos y lesiones de tendones flexores o extensores.</p>
<p>El Decreto 549/2025 fija valores puntuales por amputación: pulgar a nivel de la articulación trapeciometacarpiana 40%, a nivel de la metacarpofalángica 30%, a nivel del pulpejo sin lesión ósea 2%. Índice, mayor, anular o meñique a nivel de la metacarpofalángica: 10% cada uno; a nivel de la falange distal: 3%. La amputación de los 5 dedos (mano completa) vale 50%, que es también el tope máximo para mano y/o muñeca.</p>
<p>📌 La mano es fundamental para casi cualquier trabajo, así que una lesión acá es especialmente relevante. No dejes pasar el plazo de 2 años para reclamar: corre desde el accidente o desde que el daño se manifestó (Art. 44, Ley 24.557).</p>
<p>PREGUNTA: ¿Cuánto me indemnizan por una lesión de mano?</p>
<p>RESPUESTA_CORTA: El baremo fija un porcentaje puntual por hueso o dedo afectado, con un tope del 50% para mano y/o muñeca.</p>
<p>El anexo oficial ya no da rangos: asigna un valor fijo por cada secuela de mano, según el dedo afectado (el pulgar es el más relevante funcionalmente) y el nivel de amputación:</p>
<p>📌 Pulgar: 40% (articulación trapeciometacarpiana), 30% (metacarpofalángica) o 2% (pulpejo, sin lesión ósea).</p>
<p>📌 Índice, mayor, anular o meñique: 10% (metacarpofalángica) o 3% (falange distal), cada uno.</p>
<p>📌 Mano completa (5 dedos): 50%, que es a la vez el tope de todo el sector mano y/o muñeca.</p>
<p>📌 Las secuelas de la misma mano se suman aritméticamente entre sí, sin superar ese tope.</p>
<p>La indemnización de pago único surge de la fórmula del Art. 14, Ley 24.557: 53 x Ingreso Base Mensual x % de incapacidad x (65/tu edad). Si no estás de acuerdo con el porcentaje que te asignaron, podés impugnarlo ante la Comisión Médica Central dentro de los 5 días hábiles de notificado el dictamen (Res. SRT 5/2026).</p>
<p>PREGUNTA: ¿Qué es el síndrome del túnel carpiano?</p>
<p>RESPUESTA_CORTA: Es la compresión del nervio mediano en la muñeca. Causa dolor, hormigueo y debilidad para agarrar objetos.</p>
<p>El síndrome del túnel carpiano es la compresión del nervio mediano a su paso por la muñeca. Es una de las lesiones laborales más comunes en quienes usan mucho las manos.</p>
<p>📌 Dolor nocturno que despierta y obliga a sacudir la mano.</p>
<p>📌 Hormigueo en pulgar, índice, medio y anular; adormecimiento y pérdida de fuerza para agarrar.</p>
<p>📌 Férula nocturna, para mantener la muñeca en posición neutra.</p>
<p>📌 Infiltraciones con corticoides, y cirugía de liberación del nervio mediano si el tratamiento conservador no funciona.</p>
<p>📌 Consejo práctico: la ART tiene que cubrir todo el tratamiento, incluida la cirugía si es necesaria. Si te queda una afectación sensitiva o motora objetivada del nervio mediano, corresponde valorarla como secuela neurológica dentro del baremo.</p>
<p>PREGUNTA: ¿Puedo volver a trabajar después de una lesión de mano?</p>
<p>RESPUESTA_CORTA: Depende de tu trabajo y de tu recuperación. Puede que necesites tareas adaptadas mientras te recuperás.</p>
<p>Podés volver a trabajar después de una lesión de mano, pero según tu tipo de trabajo vas a necesitar adaptaciones:</p>
<p>📌 Tareas adaptadas: si trabajás con las manos, tu médico puede indicar tareas que no requieran esfuerzo de la mano afectada.</p>
<p>📌 Herramientas ergonómicas: teclados especiales, grips adaptados, herramientas con mango más grueso.</p>
<p>📌 Jornada reducida: puede que necesites trabajar menos horas al principio.</p>
<p>El procedimiento: tu médico tratante indica las restricciones, presentás el certificado a tu empleador y a la ART, y si no te readaptan, reclamás ante la SRT.  No vuelvas antes de tiempo: una recidiva puede perjudicar tu salud y tu indemnización.</p>
<p>PREGUNTA: ¿Cómo puedo prevenir lesiones de mano en el trabajo?</p>
<p>RESPUESTA_CORTA: Usá guantes, hacé pausas, mantené buena postura y fortalecé las manos con ejercicios regulares.</p>
<p>Prevenir lesiones de mano en el trabajo es clave, sobre todo en tareas repetitivas o con herramientas:</p>
<p>📌 Guantes protectores: si trabajás con herramientas, materiales cortantes o sustancias químicas.</p>
<p>📌 Pausas cada hora: estirá dedos y muñeca para prevenir la tendinitis.</p>
<p>📌 Buena postura al escribir: la muñeca en posición neutra.</p>
<p>📌 Herramientas ergonómicas: grips antideslizantes y teclados ergonómicos.</p>
<p>📌 Consejo práctico: si tu trabajo implica tareas repetitivas con las manos, tu empleador tiene que darte las condiciones adecuadas para prevenir lesiones. Si igualmente sufrís una lesión, la ART tiene que cubrir el tratamiento completo.</p>
<p>PREGUNTA: ¿Qué lesiones de muñeca cubre la ART?</p>
<p>RESPUESTA_CORTA: Fracturas, esguinces, tendinitis, síndrome del túnel carpiano y lesiones del TFCC.</p>
<p>La ART cubre todas las lesiones de muñeca que se originen en el trabajo, incluyendo:</p>
<p>📌 Fracturas de radio distal y cúbito, muy comunes en caídas.</p>
<p>📌 Esguinces de los ligamentos de la muñeca.</p>
<p>📌 Tendinitis por movimientos repetitivos de flexión y extensión.</p>
<p>📌 Lesiones del TFCC (fibrocartílago triangular), el estabilizador de la muñeca.</p>
<p>La muñeca comparte con la mano el tope acumulado del baremo: 50% para mano y/o muñeca, y 55% si además hay compromiso del antebrazo.</p>
<p>📌 Si trabajás con las manos (herramientas, computadora, manipulación de materiales), estas lesiones son especialmente frecuentes. No dejes pasar el plazo de 2 años para reclamar: corre desde el accidente o desde que el daño se manifestó (Art. 44, Ley 24.557).</p>
<p>PREGUNTA: ¿Cuánto me indemnizan por una fractura de muñeca?</p>
<p>RESPUESTA_CORTA: El porcentaje depende del hueso fracturado y de la secuela objetivada, dentro del tope del 50% para mano y/o muñeca.</p>
<p>El anexo del Decreto 549/2025 asigna un valor fijo por secuela, sin los rangos amplios de la tabla anterior. En fracturas de muñeca, el porcentaje depende de qué hueso se afectó, si hubo cirugía y qué secuela objetiva quedó (limitación de movimiento medida por goniometría, por ejemplo).</p>
<p>📌 Todas las secuelas de la muñeca y la mano, del mismo lado, se suman aritméticamente hasta el tope del 50%.</p>
<p>📌 Con compromiso de antebrazo, el tope sube a 55%.</p>
<p>La indemnización de pago único surge de la fórmula del Art. 14, Ley 24.557: 53 x Ingreso Base Mensual x % de incapacidad x (65/tu edad).</p>
<p>Si quedaste con limitación de movimiento, rigidez o dolor objetivado, asegurate de que la Comisión Médica lo evalúe correctamente.  Si no estás de acuerdo con el porcentaje que te asignaron, podés impugnarlo ante la Comisión Médica Central dentro de los 5 días hábiles de notificado el dictamen (Res. SRT 5/2026).</p>
<p>PREGUNTA: ¿Qué es una lesión del TFCC y cómo se trata?</p>
<p>RESPUESTA_CORTA: Es una lesión del fibrocartílago que estabiliza la muñeca. Se trata con férula, infiltraciones o cirugía artroscópica.</p>
<p>El TFCC (Triangular Fibrocartilage Complex) es una estructura que estabiliza la muñeca y permite la rotación del antebrazo. Una lesión acá puede ser muy incapacitante.</p>
<p>📌 Síntomas: dolor en el lado del meñique, debilidad al girar la muñeca, chasquidos o sensación de inestabilidad.</p>
<p>📌 Férula: inmovilización para permitir la cicatrización.</p>
<p>📌 Infiltraciones: corticoides o plasma rico en plaquetas.</p>
<p>📌 Cirugía artroscópica: en casos graves, cuando el tratamiento conservador no funciona.</p>
<p>📌 Consejo práctico: la ART tiene que cubrir todo el tratamiento, incluida la cirugía artroscópica si es necesaria. Si te queda una secuela objetivada, corresponde valorarla dentro del sector muñeca del baremo.</p>
<p>PREGUNTA: ¿Puedo escribir con una lesión de muñeca?</p>
<p>RESPUESTA_CORTA: Depende de la gravedad. Con férula puede ser difícil, pero hay adaptaciones que te permiten seguir trabajando.</p>
<p>Escribir con una lesión de muñeca puede ser difícil, pero hay adaptaciones que te permiten seguir trabajando:</p>
<p>📌 Teclados ergonómicos: divididos o en ángulo, para reducir la presión sobre la muñeca.</p>
<p>📌 Dictado por voz: software de reconocimiento de voz para escribir sin usar las manos.</p>
<p>📌 Mouse ergonómico: vertical o de bola, que no requiere flexionar la muñeca.</p>
<p>📌 Férula funcional: permite cierto movimiento pero protege la zona.</p>
<p>📌 Consejo práctico: informá a tu empleador sobre tu lesión para que te dé las herramientas adecuadas. Tu médico tiene que indicar las restricciones laborales por escrito.</p>
<p>PREGUNTA: ¿Cómo se trata la tendinitis de muñeca?</p>
<p>RESPUESTA_CORTA: Con descanso, férula, medicamentos, kinesiología y, en casos graves, cirugía.</p>
<p>La tendinitis de muñeca es una inflamación de los tendones que cruzan la articulación. Su tratamiento es progresivo:</p>
<p>📌 Descanso de la zona: si tu trabajo la provoca, pedí tareas alternativas.</p>
<p>📌 Férula: para permitir la cicatrización del tendón.</p>
<p>📌 Medicamentos antiinflamatorios: orales o tópicos.</p>
<p>📌 Kinesiología: estiramientos progresivos y fortalecimiento, que la ART tiene que cubrir.</p>
<p>📌 Consejo práctico: hacé pausas frecuentes, usá herramientas ergonómicas y fortalecé los músculos del antebrazo para prevenir recaídas. Si la tendinitis fue causada por tu trabajo, tenés derecho a que la ART cubra todo el tratamiento.</p>
<p>PREGUNTA: ¿Qué lesiones de codo cubre la ART?</p>
<p>RESPUESTA_CORTA: Epicondilitis, epitrocleítis, fracturas, luxaciones y lesiones del nervio cubital.</p>
<p>La ART cubre todas las lesiones de codo que se originen en el trabajo, incluyendo:</p>
<p>📌 Epicondilitis (codo de tenista): inflamación de los tendones en la parte externa del codo.</p>
<p>📌 Epitrocleítis (codo de golfista): inflamación en la parte interna.</p>
<p>📌 Fracturas de húmero distal, radio o cúbito proximal.</p>
<p>📌 Lesiones del nervio cubital (compresión en el codo) y luxaciones.</p>
<p>El codo forma parte del tope acumulado del miembro superior: mano, muñeca, antebrazo, codo y/o brazo no puede superar el 60%.</p>
<p>📌 Estas lesiones son muy comunes en trabajadores que hacen movimientos repetitivos con el brazo (herramientas, línea de montaje). No dejes pasar el plazo de 2 años para reclamar: corre desde el accidente o desde que el daño se manifestó (Art. 44, Ley 24.557).</p>
<p>PREGUNTA: ¿Cuánto me indemnizan por una lesión de codo?</p>
<p>RESPUESTA_CORTA: El porcentaje depende de la secuela puntual y su objetivación, dentro del tope acumulado del 60% para todo el miembro superior.</p>
<p>El Decreto 549/2025 asigna un valor fijo por secuela de codo, según la gravedad y la limitación funcional objetivada por goniometría:</p>
<p>📌 Las secuelas del mismo brazo (mano, muñeca, antebrazo, codo y/o brazo) se suman aritméticamente, hasta el tope del 60%.</p>
<p>📌 Si tu codo tiene limitación significativa de flexión, extensión o rotación medida por goniometría, eso se refleja en el porcentaje.</p>
<p>La indemnización de pago único surge de la fórmula del Art. 14, Ley 24.557: 53 x Ingreso Base Mensual x % de incapacidad x (65/tu edad).</p>
<p>📌 Si no estás de acuerdo con el porcentaje que te asignaron, podés impugnarlo ante la Comisión Médica Central dentro de los 5 días hábiles de notificado el dictamen (Res. SRT 5/2026).</p>
<p>PREGUNTA: ¿Qué es la epicondilitis y cómo se trata?</p>
<p>RESPUESTA_CORTA: Es la inflamación de los tendones del codo. Se trata con descanso, kinesiología e infiltraciones.</p>
<p>La epicondilitis es la inflamación de los tendones que se insertan en el epicóndilo (parte externa del codo), causada por movimientos repetitivos de extensión de la muñeca y los dedos.</p>
<p>📌 Descanso: evitar la actividad que causa la inflamación, con tareas alternativas si hace falta.</p>
<p>📌 Kinesiología: estiramientos y fortalecimiento excéntrico de los extensores.</p>
<p>📌 Infiltraciones: corticoides en casos que no mejoran con el tratamiento básico.</p>
<p>📌 Ondas de choque: terapia extracorpórea en casos persistentes.</p>
<p>📌 Consejo práctico: hacé estiramientos antes y después del trabajo, usá herramientas ergonómicas y evitá la fuerza excesiva con el brazo. La ART tiene que cubrir todo el tratamiento.</p>
<p>PREGUNTA: ¿Puedo trabajar con una lesión de codo?</p>
<p>RESPUESTA_CORTA: Depende de tu trabajo. Si repetís movimientos con el brazo, puede que necesites tareas adaptadas.</p>
<p>Podés trabajar con una lesión de codo, pero depende del tipo de actividad:</p>
<p>📌 Trabajo sedentario: podés volver más rápido si no requiere esfuerzo del brazo.</p>
<p>📌 Movimientos repetitivos del brazo: vas a necesitar tareas adaptadas, herramientas ergonómicas o reducción de jornada.</p>
<p>📌 Carga de peso con el brazo: debe limitarse o prohibirse temporalmente.</p>
<p>📌 Trabajo con vibración: evitá herramientas que generen vibración en el codo.</p>
<p>El procedimiento: tu médico indica las restricciones por escrito, presentás el certificado a tu empleador y a la ART, y si no te readaptan, reclamás ante la SRT.  No vuelvas antes de tiempo: una recidiva puede perjudicar tu salud y tu indemnización.</p>
<p>PREGUNTA: ¿Cómo puedo prevenir lesiones de codo en el trabajo?</p>
<p>RESPUESTA_CORTA: Hacé pausas, usá herramientas ergonómicas, fortalecé los brazos y mantené buena postura.</p>
<p>Prevenir lesiones de codo en el trabajo es clave, sobre todo si tu actividad implica movimientos repetitivos:</p>
<p>📌 Pausas frecuentes: cada 45-60 minutos, descansá el brazo y estirá el antebrazo.</p>
<p>📌 Herramientas ergonómicas: grips antivibración y mangos acolchados.</p>
<p>📌 Fortalecé los músculos: ejercicios con bandas elásticas para flexores y extensores del antebrazo.</p>
<p>📌 Buena postura: el codo cerca del cuerpo, no extendido o levantado.</p>
<p>📌 Consejo práctico: si tu lesión de codo fue causada por tu trabajo, la ART tiene que cubrir el tratamiento. La prevención es la mejor inversión para no perder capacidad laboral.</p>
<p>PREGUNTA: ¿Qué lesiones de tobillo cubre la ART?</p>
<p>RESPUESTA_CORTA: Esguinces, fracturas, tendinitis, luxaciones y síndrome de túnel tarsiano.</p>
<p>La ART cubre todas las lesiones de tobillo que se originen en el trabajo, incluyendo:</p>
<p>📌 Esguinces: lesiones de los ligamentos, las más comunes en accidentes laborales.</p>
<p>📌 Fracturas de peroné, tibia o astrágalo.</p>
<p>📌 Tendinitis por esfuerzo repetitivo o sobrecarga.</p>
<p>📌 Luxaciones y síndrome de túnel tarsiano (compresión del nervio tibial posterior).</p>
<p>El Decreto 549/2025 fija un tope de 35% para pie y/o tobillo, que sube a 40% si hay compromiso de la pierna. Una fractura de tobillo (cualquiera de los tres maléolos) vale 3% sin secuelas, 6% con secuelas y 9% con pseudoartrosis. La amputación tipo Syme (a nivel del tobillo) vale 35%.</p>
<p>📌 Si trabajás de pie, caminás mucho o manejás maquinaria, estas lesiones son especialmente frecuentes. No dejes pasar el plazo de 2 años para reclamar: corre desde el accidente o desde que el daño se manifestó (Art. 44, Ley 24.557).</p>
<p>PREGUNTA: ¿Cuánto tarda en recuperarse un esguince de tobillo?</p>
<p>RESPUESTA_CORTA: Desde 2 semanas hasta 3 meses, según la gravedad del esguince.</p>
<p>Los tiempos de recuperación varían según el grado del esguince:</p>
<p>📌 Grado I (leve): 2-4 semanas. Ligamentos estirados sin rotura; kinesiología desde el primer día.</p>
<p>📌 Grado II (moderado): 4-8 semanas. Rotura parcial del ligamento; se usa férula o yeso y muletas.</p>
<p>📌 Grado III (grave): 8-12 semanas. Rotura completa; puede requerir cirugía y rehabilitación prolongada.</p>
<p>📌 Aplicá hielo las primeras 48 horas, después calor, con compresión y elevación de la pierna.</p>
<p>📌 Consejo práctico: seguí las indicaciones de tu kinesiólogo al pie de la letra. La ART tiene que cubrir la kinesiología y el tratamiento completo hasta que estés estabilizado.</p>
<p>PREGUNTA: ¿Puedo caminar después de una lesión de tobillo?</p>
<p>RESPUESTA_CORTA: Depende de la gravedad. Con un esguince leve, sí con precaución. Con una fractura, esperá la indicación médica.</p>
<p>Podés caminar después de una lesión de tobillo, pero depende de la gravedad:</p>
<p>📌 Esguince leve: sí, con precaución y calzado adecuado, evitando superficies irregulares.</p>
<p>📌 Esguince moderado o grave: necesitás muletas y no debés apoyar el pie hasta que tu médico lo autorice.</p>
<p>📌 Fractura: esperá la indicación específica; generalmente requiere inmovilización con yeso y muletas.</p>
<p>📌 Consejo práctico: usá calzado con buen soporte de tobillo, evitá superficies resbaladizas y no vuelvas a trabajar antes de tiempo si tu trabajo implica estar de pie o caminar.</p>
<p>PREGUNTA: ¿Cómo puedo prevenir lesiones de tobillo en el trabajo?</p>
<p>RESPUESTA_CORTA: Usá calzado adecuado, mantené el área de trabajo limpia y hacé ejercicios de equilibrio.</p>
<p>Prevenir lesiones de tobillo en el trabajo es clave:</p>
<p>📌 Calzado adecuado: con buen soporte de tobillo, suela antideslizante y amortiguación.</p>
<p>📌 Área de trabajo limpia: piso ordenado, sin cables sueltos ni superficies mojadas.</p>
<p>📌 Ejercicios de equilibrio: pararse en un pie o usar una tabla de equilibrio fortalece los estabilizadores.</p>
<p>📌 Iluminación suficiente para evitar tropiezos.</p>
<p>📌 Consejo práctico: si sufrís una lesión de tobillo en el trabajo, la ART tiene que cubrir el tratamiento completo. La prevención evita lesiones que afectan tu capacidad laboral.</p>
<p>PREGUNTA: ¿Qué lesiones de pie cubre la ART?</p>
<p>RESPUESTA_CORTA: Fracturas, esguinces, fascitis plantar, neuromas y lesiones de tendones.</p>
<p>La ART cubre todas las lesiones de pie que se originen en el trabajo, incluyendo:</p>
<p>📌 Fracturas de metatarsianos por caídas o golpes directos.</p>
<p>📌 Esguinces de la articulación de Lisfranc o de Chopart.</p>
<p>📌 Fascitis plantar: inflamación del tejido de la planta del pie.</p>
<p>📌 Neuromas de Morton y lesiones de tendones (por ejemplo, del tendón de Aquiles).</p>
<p>El Decreto 549/2025 fija el mismo tope que para el tobillo: 35% para pie y/o tobillo. La fractura del primer dedo del pie tiene un tope propio de 12% (amputación a nivel de la falange proximal); para los demás dedos (2°, 3°, 4° o 5°), el tope es 3%.</p>
<p>📌 Si trabajás mucho tiempo de pie o cargás peso, estas lesiones son especialmente frecuentes. No dejes pasar el plazo de 2 años para reclamar: corre desde el accidente o desde que el daño se manifestó (Art. 44, Ley 24.557).</p>
<p>PREGUNTA: ¿Cuánto me indemnizan por una lesión de pie?</p>
<p>RESPUESTA_CORTA: El porcentaje depende del hueso o estructura afectada, dentro del tope del 35% para pie y/o tobillo.</p>
<p>El anexo oficial fija valores puntuales según la estructura del pie afectada:</p>
<p>📌 Primer dedo (fractura, limitación funcional o anquilosis): tope de 12%.</p>
<p>📌 Dedos 2° a 5°: tope de 3% cada uno.</p>
<p>📌 Todas las secuelas del pie se suman aritméticamente, sin superar el tope de 35% del sector pie y/o tobillo.</p>
<p>La indemnización de pago único surge de la fórmula del Art. 14, Ley 24.557: 53 x Ingreso Base Mensual x % de incapacidad x (65/tu edad).</p>
<p>Si quedaste con dolor crónico o dificultad objetivada para caminar, asegurate de que la Comisión Médica lo evalúe bien.  Si no estás de acuerdo con el porcentaje que te asignaron, podés impugnarlo ante la Comisión Médica Central dentro de los 5 días hábiles de notificado el dictamen (Res. SRT 5/2026).</p>
<p>PREGUNTA: ¿Qué es la fascitis plantar y cómo se trata?</p>
<p>RESPUESTA_CORTA: Es la inflamación del tejido de la planta del pie. Causa dolor al caminar y se trata con plantillas y kinesiología.</p>
<p>La fascitis plantar es la inflamación de la fascia plantar, la banda de tejido que va del talón a los dedos. Es muy común en trabajadores que pasan mucho tiempo de pie.</p>
<p>📌 Dolor intenso en el talón al caminar, sobre todo en los primeros pasos del día.</p>
<p>📌 Plantillas ortopédicas personalizadas para aliviar la presión.</p>
<p>📌 Estiramientos de la fascia plantar y el tendón de Aquiles.</p>
<p>📌 Ondas de choque y kinesiología para estimular la cicatrización.</p>
<p>📌 Consejo práctico: la ART tiene que cubrir todo el tratamiento, incluidas las plantillas ortopédicas si tu médico las indica.</p>
<p>PREGUNTA: ¿Puedo trabajar de pie con una lesión de pie?</p>
<p>RESPUESTA_CORTA: Depende. Si tu trabajo exige estar de pie, puede que necesites tareas sentado mientras te recuperás.</p>
<p>Si tu trabajo exige estar de pie de forma permanente y tenés una lesión de pie, vas a necesitar adaptaciones:</p>
<p>📌 Tareas sentado: si es posible, tu empleador tiene que asignarte tareas que permitan estar sentado.</p>
<p>📌 Descansos frecuentes: cada 30-45 minutos, para aliviar la presión sobre el pie.</p>
<p>📌 Plantillas ortopédicas y calzado con buena amortiguación.</p>
<p>El procedimiento: tu médico indica las restricciones, presentás el certificado a tu empleador y a la ART, y si no te readaptan, reclamás ante la SRT.  No vuelvas a trabajar antes de tiempo si tu lesión lo requiere.</p>
<p>PREGUNTA: ¿Qué calzado debo usar para prevenir lesiones de pie?</p>
<p>RESPUESTA_CORTA: Calzado cómodo, con buen soporte y amortiguación. Evitá tacones altos y suelas duras.</p>
<p>Elegir el calzado adecuado es clave para prevenir lesiones de pie en el trabajo:</p>
<p>📌 Cómodo, con espacio para los dedos y buen soporte de arco.</p>
<p>📌 Con amortiguación: suela que absorba el impacto al caminar.</p>
<p>📌 Suela antideslizante, para evitar caídas.</p>
<p>📌 Evitá tacones altos, suelas duras y calzado gastado sin soporte.</p>
<p>📌 Consejo práctico: si trabajás de pie mucho tiempo, invertí en buen calzado. Si igual sufrís una lesión de pie en el trabajo, la ART tiene que cubrir el tratamiento completo.</p>
<p>PREGUNTA: ¿Qué lesiones de cadera cubre la ART?</p>
<p>RESPUESTA_CORTA: Fracturas, luxaciones, bursitis, tendinitis y artrosis de cadera.</p>
<p>La ART cubre todas las lesiones de cadera que se originen en el trabajo, incluyendo:</p>
<p>📌 Fracturas de cuello femoral: muy graves, comunes en caídas laborales.</p>
<p>📌 Luxaciones de cadera por traumatismos intensos.</p>
<p>📌 Bursitis (trocanteritis): inflamación de la bolsa sinovial lateral.</p>
<p>📌 Tendinitis y artrosis de cadera, por desgaste del cartílago articular.</p>
<p>La cadera es la zona con el tope más alto de todo el sistema locomotor: el Decreto 549/2025 fija en 70% el máximo para el miembro inferior completo, equivalente a la desarticulación coxofemoral. Las fracturas de cadera son especialmente graves y suelen requerir cirugía con prótesis.</p>
<p>📌 Si sufriste una lesión de cadera en el trabajo, la ART tiene que cubrir todo el tratamiento. No dejes pasar el plazo de 2 años para reclamar: corre desde el accidente o desde que el daño se manifestó (Art. 44, Ley 24.557).</p>
<p>PREGUNTA: ¿Cuánto me indemnizan por una lesión de cadera?</p>
<p>RESPUESTA_CORTA: El porcentaje depende de la gravedad y de si requirió prótesis, dentro del tope máximo del 70%.</p>
<p>El anexo oficial fija valores puntuales según la secuela de cadera, sin los rangos amplios de la tabla anterior:</p>
<p>📌 Amputación a nivel de la pierna: 40%.</p>
<p>📌 Desarticulación coxofemoral (pérdida completa de la cadera): 70%, el tope máximo para todo el miembro inferior.</p>
<p>📌 Cuando hay compromisos en pie, tobillo, pierna, rodilla y cadera del mismo lado, la suma de todas las secuelas no puede superar ese 70%.</p>
<p>La indemnización de pago único surge de la fórmula del Art. 14, Ley 24.557: 53 x Ingreso Base Mensual x % de incapacidad x (65/tu edad). Si superás el 50% de incapacidad corresponde el adicional por gran invalidez, sobre los pisos que fija periódicamente la SRT.</p>
<p>Las lesiones de cadera están entre las más graves del sistema locomotor.  Si no estás de acuerdo con el porcentaje que te asignaron, podés impugnarlo ante la Comisión Médica Central dentro de los 5 días hábiles de notificado el dictamen (Res. SRT 5/2026).</p>
<p>PREGUNTA: ¿Qué es la bursitis de cadera y cómo se trata?</p>
<p>RESPUESTA_CORTA: Es la inflamación de la bolsa sinovial de la cadera. Causa dolor al dormir de ese lado y al subir escaleras.</p>
<p>La bursitis de cadera (o trocanteritis) es la inflamación de la bolsa sinovial que cubre el trocánter mayor del fémur, en la parte lateral de la cadera.</p>
<p>📌 Dolor lateral que empeora al acostarse del lado afectado.</p>
<p>📌 Dolor al subir escaleras o al caminar.</p>
<p>📌 Medicamentos antiinflamatorios y, si no mejora, infiltraciones de corticoides.</p>
<p>📌 Kinesiología: estiramientos y fortalecimiento de glúteos y abductores.</p>
<p>📌 Consejo práctico: evitá la posición que causa dolor mientras dure el tratamiento. La ART tiene que cubrirlo por completo.</p>
<p>PREGUNTA: ¿Puedo volver a trabajar después de una prótesis de cadera?</p>
<p>RESPUESTA_CORTA: Sí, pero puede que necesites tareas livianas al principio. Tu médico autoriza el regreso cuando estés estabilizado.</p>
<p>Después de una prótesis de cadera, podés volver al trabajo, pero con ciertas adaptaciones:</p>
<p>📌 Tareas livianas: sin esfuerzo físico intenso ni estar mucho tiempo de pie.</p>
<p>📌 Adaptaciones del puesto: silla con soporte lumbar, evitar levantar peso.</p>
<p>📌 Jornada reducida al principio.</p>
<p>📌 Evitar ciertas posiciones: no cruzar las piernas, no agacharte mucho ni girar bruscamente.</p>
<p>📌 Consejo práctico: los plazos típicos van de 2-3 meses (retorno con restricciones) a 6-12 meses (recuperación funcional completa). Tu médico autoriza el regreso cuando estés médicamente estabilizado.</p>
<p>PREGUNTA: ¿Cuánto tarda en recuperarse una cirugía de cadera?</p>
<p>RESPUESTA_CORTA: Entre 3 y 6 meses para la recuperación funcional completa, con rehabilitación intensiva.</p>
<p>La recuperación después de una cirugía de cadera es un proceso gradual:</p>
<p>📌 Primeras 2-4 semanas: caminás con muletas o andador, con ejercicios de movilidad para evitar rigidez.</p>
<p>📌 1-2 meses: caminás sin ayuda, pero con precaución, evitando ciertas posiciones.</p>
<p>📌 2-3 meses: recuperación funcional considerable, volvés a actividades cotidianas.</p>
<p>📌 3-6 meses: recuperación funcional completa con rehabilitación constante.</p>
<p>📌 Consejo práctico: seguí las indicaciones de tu kinesiólogo, no te sientes en sillas bajas ni cruces las piernas. La ART tiene que cubrir la rehabilitación completa hasta la estabilización médica.</p>',
